  const analysisScope = executableWorkspaceJobSchema.safeParse(input.entryJob);
  if (!analysisScope.success) {
    return workspaceExecutionRouteSchema.parse({
      action: "conversation_only",
      analysisScope: null,
      requirements: [],
      reasonCode: "executor_not_released",
      modelRoutingCalls: 0,
