  {id:"MA-15",slug:"memo-editorial-rules",title:"Regras editoriais do memo",product:"Relatório editorial objetivo e reproduzível",templates:["institutional-credit-memo"],method:["Aplicar voz ativa, datas absolutas, siglas abertas, número com fonte e adjetivo quantificado.","Executar lista vigiada de superlativos, linguagem conclusiva e jargão vazio."],verification:["Emitir achado por frase e regra, com localização no artefato.","Bloquear violações materiais; não reescrever fatos para fazê-los parecer melhores."]},
  {id:"MA-16",slug:"memo-boundary",title:"O que o memo não é",product:"Enquadramento issuer-side e fronteira consultiva",templates:["institutional-credit-memo"],method:["Aplicar enquadramento issuer-side: tese, méritos, riscos, estrutura e evidências de forma persuasiva e equilibrada.","Excluir linguagem de parecer de crédito, aprovação, recomendação de investimento, prospecto ou compromisso de capital."],verification:["Executar auditoria de vocabulário e presença do disclaimer vigente.","Exigir revisão jurídica quando o template de fronteira mudar."],legal:true},
  {id:"MA-17",slug:"canonical-clauses",title:"As cláusulas canônicas",product:"Term sheet indicativo completo e versionado",templates:["indicative-term-sheet"],method:["Compilar todas as cláusulas canônicas, incluindo mecânica das garantias, definições de covenants, CPs, eventos, cura, reporting e natureza não vinculante.","Usar defaults da casa e alternativas por perfil sem remover cláusula sem decisão registrada."],verification:["Exigir compatibilidade de dia um e mapa termo para base verde.","Comparar ids, ordem e completude ao template vigente."]},
  {id:"MA-18",slug:"term-basis",title:"A base de cada termo",product:"Mapa interno termo para base",templates:["indicative-term-sheet"],method:["Ligar cada termo a procedimento ES, cálculo, fato ou referência de mercado datada.","Registrar trade-offs e alternativas indicativas para explicação à companhia."],verification:["Exigir cobertura de 100% dos termos materiais.","Atualizar o mapa sempre que o fingerprint do term sheet mudar."]},
  {id:"MA-19",slug:"non-binding-language",title:"Linguagem não vinculante",product:"Validação da linguagem e vigência jurídica do template",templates:["indicative-term-sheet"],method:["Aplicar indicativo, sujeito a diligência, documentação definitiva e aprovações do financiador em todo o documento.","Verificar vigência da revisão jurídica do template."],verification:["Bloquear obrigação de contratar, termo final ou aprovação implícita.","Bloquear template vencido até nova revisão especializada."],legal:true},
  {id:"MA-20",slug:"conditions-precedent",title:"Condições precedentes",product:"Condições com base, responsável e momento",templates:["indicative-term-sheet"],method:["Compilar CPs societárias, de garantia, certidões, seguros, contratos e intercreditor aplicáveis.","Atribuir base, responsável e momento esperado a cada condição."],verification:["Rejeitar CP sem dono, base ou relação com a estrutura.","Não transformar a data room inicial em checklist de closing."]},
