  {id:"MA-22",slug:"anticipated-questions",title:"As perguntas antecipadas",product:"Q&A por arquétipo e categoria",method:["Compilar perguntas recorrentes do arquétipo e das flags do caso, agrupadas por companhia, números, dívida, operação e estrutura.","Preencher somente com resposta suportada; caso contrário registrar não disponível, solicitado ou dependente de confirmação."],verification:["Exigir versão do padrão de perguntas e cobertura das flags materiais.","Pergunta nova recorrente vira proposta versionada de evolução, não resposta inventada."]},
  {id:"MA-23",slug:"sourced-answer",title:"Resposta com fonte",product:"Respostas auditadas ou lacunas explícitas",method:["Ligar cada resposta a marcador de documento, cálculo ou confirmação formal da companhia.","Converter ausência de suporte em lacuna com impacto e próxima solicitação."],verification:["Auditar Q&A pelo mesmo claim registry do memo.","Bloquear resposta de memória ou texto provável sem fonte."]},
