  field("/structure/waterfall/availableCash", "money", "currency_major", "Qual caixa está disponível para a waterfall no período testado?", "How much cash is available for the waterfall in the tested period?", structureWhy.pt, structureWhy.en, 0),
  field("/structure/waterfall/servicingFeeDue", "money", "currency_major", "Qual servicing fee vence no período testado?", "What servicing fee is due in the tested period?", structureWhy.pt, structureWhy.en, 0),
  field("/structure/waterfall/seniorInterestDue", "money", "currency_major", "Quanto de juros sênior vence no período testado?", "How much senior interest is due in the tested period?", structureWhy.pt, structureWhy.en, 0),
  field("/structure/waterfall/seniorPrincipalDue", "money", "currency_major", "Quanto de principal sênior vence no período testado?", "How much senior principal is due in the tested period?", structureWhy.pt, structureWhy.en, 0),
  field("/structure/waterfall/reserveOpening", "money", "currency_major", "Qual é o saldo inicial da reserva no período testado?", "What is the opening reserve balance in the tested period?", structureWhy.pt, structureWhy.en, 0),
  field("/structure/waterfall/mezzanineDue", "money", "currency_major", "Quanto vence para a tranche mezanino no período testado?", "How much is due to the mezzanine tranche in the tested period?", structureWhy.pt, structureWhy.en, 0),
  field("/policy/maxDaysPastDue", "integer", "days", "Qual é o atraso máximo permitido para um recebível elegível?", "What is the maximum days past due for an eligible receivable?", policyWhy.pt, policyWhy.en, 0),
  field("/policy/maxRemainingTermDays", "integer", "days", "Qual é o prazo remanescente máximo permitido, em dias?", "What is the maximum remaining term allowed, in days?", policyWhy.pt, policyWhy.en, 1),
  field("/policy/minSeasoningDays", "integer", "days", "Qual seasoning mínimo deve ser exigido, em dias?", "What minimum seasoning should be required, in days?", policyWhy.pt, policyWhy.en, 0),
  field("/policy/maxSingleDebtorShare", "percentage", "percent_0_100", "Qual é a concentração máxima por devedor? Informe de 0% a 100%.", "What is the maximum single-debtor concentration? Enter 0% to 100%.", policyWhy.pt, policyWhy.en, 0, 100),
  field("/policy/maxDebtorGroupShare", "percentage", "percent_0_100", "Qual é a concentração máxima por grupo econômico? Informe de 0% a 100%.", "What is the maximum economic-group concentration? Enter 0% to 100%.", policyWhy.pt, policyWhy.en, 0, 100),
  field("/policy/minimumEligibleShare", "percentage", "percent_0_100", "Qual percentual mínimo da carteira deve permanecer elegível?", "What minimum share of the pool must remain eligible?", policyWhy.pt, policyWhy.en, 0, 100),
  field("/policy/minimumEvidenceCoverage", "percentage", "percent_0_100", "Qual cobertura documental mínima devemos exigir?", "What minimum evidence coverage should be required?", policyWhy.pt, policyWhy.en, 0, 100),
  field("/policy/minimumRegistrationCoverage", "percentage", "percent_0_100", "Qual cobertura mínima de registro devemos exigir?", "What minimum registration coverage should be required?", policyWhy.pt, policyWhy.en, 0, 100),
  field("/policy/maximumDelinquency30Share", "percentage", "percent_0_100", "Qual limite máximo para atraso acima de 30 dias?", "What is the maximum share over 30 days past due?", policyWhy.pt, policyWhy.en, 0, 100),
  field("/policy/maximumDilutionShare", "percentage", "percent_0_100", "Qual limite máximo de diluição devemos adotar?", "What maximum dilution share should be used?", policyWhy.pt, policyWhy.en, 0, 100),
  field("/policy/maximumRepurchaseShare", "percentage", "percent_0_100", "Qual limite máximo de recompra devemos adotar?", "What maximum repurchase share should be used?", policyWhy.pt, policyWhy.en, 0, 100),
  field("/policy/minimumRecoveryRate", "percentage", "percent_0_100", "Qual recuperação mínima devemos exigir?", "What minimum recovery rate should be required?", policyWhy.pt, policyWhy.en, 0, 100),
  field("/policy/maximumAccountingMismatchShare", "percentage", "percent_0_100", "Qual divergência contábil máxima será tolerada?", "What maximum accounting mismatch should be tolerated?", policyWhy.pt, policyWhy.en, 0, 100),
  field("/policy/maximumCashMismatchShare", "percentage", "percent_0_100", "Qual divergência máxima de caixa será tolerada?", "What maximum cash mismatch should be tolerated?", policyWhy.pt, policyWhy.en, 0, 100),
  field("/policy/minimumMappedCashShare", "percentage", "percent_0_100", "Qual percentual mínimo de caixa deve estar conciliado aos títulos?", "What minimum share of cash must be mapped to receivables?", policyWhy.pt, policyWhy.en, 0, 100),
  field("/policy/minimumLinkedAccountCashShare", "percentage", "percent_0_100", "Qual percentual mínimo de recebimentos deve transitar pela conta vinculada?", "What minimum share of collections must flow through the linked account?", policyWhy.pt, policyWhy.en, 0, 100),
];

const booleanFields: Array<[ReceivablesSupplementFieldPath, string, string]> = [
  ["/policy/requireAssignable", "Devemos exigir que todo recebível elegível seja cedível?", "Must every eligible receivable be assignable?"],
  ["/policy/requireEvidenceVerified", "Devemos exigir lastro verificado para todo recebível elegível?", "Must every eligible receivable have verified evidence?"],
  ["/policy/excludeDisputed", "Recebíveis em disputa devem ser excluídos?", "Should disputed receivables be excluded?"],
  ["/policy/excludeRelatedParties", "Recebíveis de partes relacionadas devem ser excluídos?", "Should related-party receivables be excluded?"],
  ["/policy/excludeEncumbered", "Recebíveis onerados devem ser excluídos?", "Should encumbered receivables be excluded?"],
];

fieldDefinitions.push(
  ...booleanFields.map(([fieldPath, pt, en]) => ({fieldPath, valueKind: "boolean" as const, unit: "boolean" as const, minimum: null, maximum: null, options: [], question: {pt, en}, why: policyWhy})),
  {fieldPath: "/policy/registrationRule", valueKind: "enum", unit: "enum", minimum: null, maximum: null, options: [], question: {pt: "Qual regra de registro deve ser aplicada?", en: "Which registration rule should apply?"}, why: policyWhy},
  {fieldPath: "/policy/allowedDebtorSectors", valueKind: "string_list", unit: "text_list", minimum: null, maximum: null, options: [], question: {pt: "Há setores de devedores permitidos? Separe por vírgulas; deixe ‘todos’ se não houver restrição.", en: "Are there permitted debtor sectors? Separate with commas; enter ‘all’ if unrestricted."}, why: policyWhy},
);

const definitionByPath = new Map(fieldDefinitions.map((definition) => [definition.fieldPath, definition]));

function requirementKey(code: string, sourceDatasetHash: string): string {
  // A response to a different pool must never suppress this pool's diligence.
  // Run IDs and localized prose do not change the economic question identity.
  const identity = createHash("sha256").update(JSON.stringify({sourceDatasetHash, code})).digest("hex");
  return `receivables.r01.evidence.${identity}`;
}

function fieldRequirementKey(path: ReceivablesSupplementFieldPath): string {
  return `receivables.r01.field.${path.slice(1).replaceAll("/", ".").replace(/([a-z])([A-Z])/g, "$1_$2").toLowerCase()}`;
}

function optionsFor(definition: FieldDefinition, locale: "pt-BR" | "en-US") {
  if (definition.valueKind === "boolean") return yesNo(locale);
  if (definition.fieldPath === "/policy/registrationRule") return locale === "en-US"
    ? [{label: "Required", value: "required"}, {label: "Required when applicable", value: "required_when_applicable"}, {label: "Not required", value: "not_required"}]
    : [{label: "Obrigatório", value: "required"}, {label: "Obrigatório quando aplicável", value: "required_when_applicable"}, {label: "Não obrigatório", value: "not_required"}];
  return definition.options;
}

export function buildReceivablesMethodEvidenceRequestProjection(input: {
  projectId: string;
  processingRunId: string;
  locale: "pt-BR" | "en-US";
  readiness: Omit<ReceivablesPoolMethodReadiness, "validatedInput">;
  missingDraftSections?: readonly string[];
  idFactory?: () => string;
}) {
  const english = input.locale === "en-US";
  const idFactory = input.idFactory ?? randomUUID;
  const missing = new Set(input.missingDraftSections ?? []);
  // Suppress only missing-assembly questions already satisfied by the current
  // source-bound draft. Temporal gaps, conflicts and unknown requirements remain.
  const assembledRequirements: Record<string, readonly string[]> = {
    portfolio_lineage_not_assembled: ["titles"],
    cedent_and_servicing_not_evidenced: ["cedent", "evidence.cedentAndServicing"],
    title_legal_controls_not_evidenced: ["titles", "evidence.titleLegalControls"],
    cash_reconciliation_not_evidenced: ["cashReceipts", "evidence.cashReconciliation"],
    accounting_reconciliation_not_evidenced: ["accounting", "evidence.accountingReconciliation"],
  };
  const evidenceGaps = input.readiness.gaps.filter((gap) => {
    if (gap.class === "policy" || gap.class === "structure") return false;
    // Source reading remains blocking without asking for documents already delivered.
    if (gap.code === "support_period:undeclared_recourse_and_debt") return false;
    if (input.missingDraftSections === undefined || gap.class === "conflict") return true;
    const requirements = assembledRequirements[gap.code];
    return requirements === undefined || requirements.some((section) => missing.has(section));
  });
  return {
    schemaVersion: "project-information-request-projection.v1",
    projectId: input.projectId,
    sourceNamespace: "receivables_method_r01_evidence",
    projectionRef: `${input.processingRunId}:R01:evidence:${input.readiness.sourceDatasetHash}:${input.readiness.state}`,
    requests: input.readiness.methodExecutionAllowed ? [] : evidenceGaps.slice(0, 3).map((gap, index) => ({
      id: idFactory(), schemaVersion: "dcm-information-request.v1", projectId: input.projectId,
      requirementKey: requirementKey(gap.code, input.readiness.sourceDatasetHash), question: english ? gap.question.en : gap.question.pt,
      whyItMatters: english ? gap.message.en : gap.message.pt,
      decisionImpact: english ? "Without this evidence, R01 remains blocked and produces no title-level conclusion." : "Sem esta evidência, o R01 permanece bloqueado e não produz conclusão por título.",
      acceptableEvidence: evidenceByDimension[gap.dimensionId][english ? "en" : "pt"], answerKind: "document" as const,
      choices: [], priority: "blocking" as const, informationGain: Number((1 - index * 0.08).toFixed(3)),
      materiality: Number((0.98 - index * 0.04).toFixed(3)), answerability: 0.75, redundancyPenalty: 0, status: "open" as const,
    })),
  };
}

export function buildReceivablesMethodFieldRequestProjection(input: {
  projectId: string;
  processingRunId: string;
  locale: "pt-BR" | "en-US";
  sourceDatasetHash: string;
  activeGroups: Array<"policy" | "structure">;
  missingSections?: readonly string[];
  idFactory?: () => string;
}) {
  const english = input.locale === "en-US";
  const idFactory = input.idFactory ?? randomUUID;
  const explicitMissing = new Set((input.missingSections ?? []).map((item) => `/${item.replaceAll(".", "/")}`));
  const candidates = fieldDefinitions.filter((definition) => {
    const group = definition.fieldPath.startsWith("/policy/") ? "policy" : "structure";
    return input.activeGroups.includes(group) && (explicitMissing.size === 0 || explicitMissing.has(definition.fieldPath));
  }).slice(0, 3);
  return {
    schemaVersion: "project-information-request-projection.v1",
    projectId: input.projectId,
    sourceNamespace: "receivables_method_r01_fields",
    projectionRef: `${input.processingRunId}:R01:fields:${input.sourceDatasetHash}:${candidates.map((item) => item.fieldPath).join(",")}`,
    requests: candidates.map((definition, index) => {
      const options = optionsFor(definition, input.locale);
      const binding = receivablesInformationRequestBindingSchema.parse({
        schemaVersion: "receivables-information-request-binding.v1", methodId: "R01",
        sourceDatasetHash: input.sourceDatasetHash, fieldPath: definition.fieldPath,
        valueKind: definition.valueKind, unit: definition.unit, minimum: definition.minimum,
        maximum: definition.maximum, options,
      });
      return {
        id: idFactory(), schemaVersion: "dcm-information-request.v1", projectId: input.projectId,
        requirementKey: fieldRequirementKey(definition.fieldPath), question: english ? definition.question.en : definition.question.pt,
        whyItMatters: english ? definition.why.en : definition.why.pt,
        decisionImpact: english ? "The confirmed value becomes a traceable model input; changing it creates a new revision." : "O valor confirmado vira input rastreável do modelo; qualquer alteração cria uma nova revisão.",
        acceptableEvidence: evidenceByDimension[definition.fieldPath.startsWith("/policy/") ? "eligibility_policy" : "facility_and_waterfall"][english ? "en" : "pt"],
        answerKind: options.length ? "choice" as const : definition.valueKind === "string_list" ? "text" as const : "number" as const,
        choices: options.map((option) => option.label), priority: "blocking" as const,
        informationGain: Number((1 - index * 0.05).toFixed(3)), materiality: Number((0.98 - index * 0.03).toFixed(3)),
        answerability: 0.95, redundancyPenalty: 0, status: "open" as const, producerBinding: binding,
      };
    }),
  };
}

export function buildReceivablesMethodInformationRequestProjection(input: Parameters<typeof buildReceivablesMethodEvidenceRequestProjection>[0]) {
  return buildReceivablesMethodEvidenceRequestProjection(input);
}

export function receivablesFieldDefinition(path: string): FieldDefinition | null {
  const parsed = receivablesSupplementFieldPathSchema.safeParse(path);
  return parsed.success ? definitionByPath.get(parsed.data) ?? null : null;
}

/** Source diligence and premise collection can progress independently. */
export function buildReceivablesMethodRequestProjections(input: {
  projectId: string;
  processingRunId: string;
  locale: "pt-BR" | "en-US";
  readiness: Omit<ReceivablesPoolMethodReadiness, "validatedInput">;
  missingDraftSections?: readonly string[];
}) {
  const evidence = buildReceivablesMethodEvidenceRequestProjection(input);
  const activeGroups = [...new Set(input.readiness.gaps.flatMap((gap) =>
    gap.class === "policy" ? ["policy" as const] : gap.class === "structure" ? ["structure" as const] : [],
  ))];
  const fields = buildReceivablesMethodFieldRequestProjection({
    projectId: input.projectId, processingRunId: input.processingRunId, locale: input.locale,
    sourceDatasetHash: input.readiness.sourceDatasetHash, activeGroups,
    ...(input.missingDraftSections ? {missingSections: input.missingDraftSections} : {}),
  });
  return [evidence, fields];
}

packages/document-intelligence/src/schem.content:
import {z} from "zod";
import {
  accountingBasisSchema,
  anchorPrecisionSchema,
  documentKindSchema,
  entityRoleSchema,
  entityScopeSchema,
  exceptionOwnerRoleSchema,
  exceptionSeveritySchema,
  exceptionTypeSchema,
  fieldGroupSchema,
  fieldValueTypeSchema,
  informationClassSchema,
  materialitySchema,
  periodKindSchema,
} from "@offroad/credit-ontology";

// ---------------------------------------------------------------------------
// Document layer — the verifiable representation of a document (P1 plan §5.3)
// ---------------------------------------------------------------------------

export const layerKindSchema = z.enum(["pdf", "spreadsheet", "docx", "pptx", "csv", "image"]);
export type LayerKind = z.infer<typeof layerKindSchema>;

const bboxSchema = z.tuple([z.number(), z.number(), z.number(), z.number()]);

export const layerBlockSchema = z.object({
  /** Stable id, e.g. `p12.b3`, `sl4.b1`, `sec2.p7`. */
  id: z.string().min(1),
  kind: z.enum(["text", "heading", "table_row", "caption", "footer", "header", "note", "other"]),
  text: z.string(),
  bbox: bboxSchema.optional(),
});
export type LayerBlock = z.infer<typeof layerBlockSchema>;

export const layerTableCellSchema = z.object({
  /** e.g. `p12.t1.r4.c3` or `sERP.t1.r4.c2` */
  id: z.string().min(1),
  text: z.string(),
  /** Native PDF coordinates; null means an empty clustered slot, not measured geometry. */
  bbox: bboxSchema.nullable().optional(),
  /** Spreadsheet cell reference when the table comes from a sheet (`B14`). */
  ref: z.string().optional(),
});

export const layerTableRowSchema = z.object({
  id: z.string().min(1),
  cells: z.array(layerTableCellSchema),
});

export const layerTableSchema = z.object({
  id: z.string().min(1),
  header: z.array(z.string()).optional(),
  rows: z.array(layerTableRowSchema),
  bbox: bboxSchema.optional(),
});
export type LayerTable = z.infer<typeof layerTableSchema>;

export const layerPageSchema = z.object({
  n: z.number().int().positive(),
  blocks: z.array(layerBlockSchema),
  tables: z.array(layerTableSchema).default([]),
  /** True when the page had no extractable text and was rendered as an image. */
  scanned: z.boolean().default(false),
});
export type LayerPage = z.infer<typeof layerPageSchema>;

export const layerCellSchema = z.object({
  /** A1-style reference (`B14`). */
  ref: z.string().regex(/^[A-Z]{1,3}[1-9]\d{0,6}$/),
  v: z.union([z.string(), z.number(), z.boolean(), z.null()]),
  /** n = number, s = string, b = boolean, d = date, e = error */
  t: z.enum(["n", "s", "b", "d", "e"]),
  f: z.string().optional(),
  fmt: z.string().optional(),
  merged: z.string().optional(),
});
export type LayerCell = z.infer<typeof layerCellSchema>;

export const layerSheetSchema = z.object({
  name: z.string().min(1),
  hidden: z.boolean().default(false),
  cells: z.array(layerCellSchema),
  tables: z.array(layerTableSchema).default([]),
});
export type LayerSheet = z.infer<typeof layerSheetSchema>;

export const layerSectionSchema = z.object({
  id: z.string().min(1),
  heading: z.string().optional(),
  paragraphs: z.array(layerBlockSchema),
  tables: z.array(layerTableSchema).default([]),
});

export type LayerSection = z.infer<typeof layerSectionSchema>;

export const layerSlideSchema = z.object({
  n: z.number().int().positive(),
  blocks: z.array(layerBlockSchema),
  tables: z.array(layerTableSchema).default([]),
  notes: z.string().optional(),
});

export type LayerSlide = z.infer<typeof layerSlideSchema>;

export const documentLayerSchema = z.object({
  documentId: z.string().min(1),
  documentVersion: z.number().int().positive(),
  kind: layerKindSchema,
  pages: z.array(layerPageSchema).optional(),
  sheets: z.array(layerSheetSchema).optional(),
  sections: z.array(layerSectionSchema).optional(),
  slides: z.array(layerSlideSchema).optional(),
  /** Scale declarations found deterministically ("em milhares de reais" → 1000) with where they were seen. */
  scaleDeclarations: z
    .array(z.object({scale: z.number().positive(), where: z.string(), text: z.string()}))
    .default([]),
  stats: z
    .object({
      estimatedTokens: z.number().int().nonnegative().optional(),
      pageCount: z.number().int().nonnegative().optional(),
      sheetCount: z.number().int().nonnegative().optional(),
      slideCount: z.number().int().nonnegative().optional(),
    })
    .default({}),
});
export type DocumentLayer = z.infer<typeof documentLayerSchema>;

// ---------------------------------------------------------------------------
// Document profile — output of stage E1
// ---------------------------------------------------------------------------

export const documentProfileSchema = z.object({
  documentId: z.string().min(1),
  kind: documentKindSchema,
  title: z.string().optional(),
  entityName: z.string().optional(),
  entityRole: entityRoleSchema.optional(),
  entityScope: entityScopeSchema.optional(),
  periodStart: z.iso.date().optional(),
  periodEnd: z.iso.date().optional(),
  fiscalYear: z.number().int().optional(),
  currency: z.string().regex(/^[A-Z]{3}$/).optional(),
  /** Declared scale of the numbers in the document (1, 1000, 1000000). */
  scale: z.number().positive().optional(),
  accountingBasis: accountingBasisSchema.optional(),
  informationClass: informationClassSchema,
  evidenceRank: z.number().int().min(1).max(7),
  language: z.enum(["pt", "en", "other"]).optional(),
  quality: z
    .object({
      isScanned: z.boolean().optional(),
      hasTables: z.boolean().optional(),
      pageCount: z.number().int().optional(),
      sheetCount: z.number().int().optional(),
      alerts: z.array(z.string()).default([]),
    })
    .default({alerts: []}),
  summary: z.object({pt: z.string(), en: z.string()}).optional(),
  confidence: z.number().min(0).max(1),
});
export type DocumentProfile = z.infer<typeof documentProfileSchema>;

// ---------------------------------------------------------------------------
// Extraction — what the model returns (E3) and what the verifier produces
// ---------------------------------------------------------------------------

export const anchorKindSchema = z.enum(["block", "table_row", "table_cell", "sheet_cell", "paragraph", "slide_block", "page", "document"]);
export type AnchorKind = z.infer<typeof anchorKindSchema>;

export const extractionAnchorSchema = z.object({
  kind: anchorKindSchema,
  /** Layer id (`p12.t1.r4.c3`, `sERP!B14`, `sec2.p7`, `sl3.b2`, `p12` for page-only). */
  id: z.string().min(1),
  page: z.number().int().positive().optional(),
  sheet: z.string().optional(),
});
export type ExtractionAnchor = z.infer<typeof extractionAnchorSchema>;

export const extractionPeriodSchema = z.object({
  start: z.iso.date(),
  end: z.iso.date(),
  kind: periodKindSchema,
});

export const extractionEntitySchema = z.object({
  name: z.string().min(1),
  scope: entityScopeSchema,
});

/** One candidate exactly as the model emits it (structured output; no normalized value). */
export const rawExtractionCandidateSchema = z.object({
  field_path: z.string().regex(/^[a-z0-9_.]+$/),
  value_raw: z.string().min(1),
  value_type: fieldValueTypeSchema,
  unit: z.string().optional(),
  scale: z.number().positive().default(1),
  currency: z.string().regex(/^[A-Z]{3}$/).optional(),
  period: extractionPeriodSchema.optional(),
  entity: extractionEntitySchema.optional(),
  information_class: informationClassSchema,
  anchor: extractionAnchorSchema,
  quote: z.string().min(1).max(400),
  confidence: z.number().min(0).max(1),
  notes: z.string().max(400).optional(),
});
export type RawExtractionCandidate = z.infer<typeof rawExtractionCandidateSchema>;

export const extractorOutputSchema = z.object({
  candidates: z.array(rawExtractionCandidateSchema),
  absent_fields: z.array(z.string()).default([]),
  document_alerts: z.array(z.string()).default([]),
});
export type ExtractorOutput = z.infer<typeof extractorOutputSchema>;

export const verifierFlagSchema = z.enum([
  "anchor_missing",
  "quote_not_in_anchor",
  "value_not_in_quote",
  "digits_not_in_anchor",
  "scale_unverified",
  "scale_conflict",
  "period_outside_document",
  "entity_mismatch",
  "field_unknown",
  "value_unparseable",
  "value_type_mismatch",
  "duplicate",
]);
export type VerifierFlag = z.infer<typeof verifierFlagSchema>;

export const verifiedCandidateSchema = rawExtractionCandidateSchema.extend({
  extractor_key: z.string().regex(/^[a-f0-9]{64}$/),
  source_document_id: z.string().min(1),
  document_version: z.number().int().positive(),
  field_group: fieldGroupSchema,
  materiality: materialitySchema,
  anchor_verified: z.boolean(),
  anchor_precision: anchorPrecisionSchema,
  verifier_flags: z.array(verifierFlagSchema),
  /** Decimal string for numbers (already multiplied by scale); ISO date; text; "true"/"false"; JSON array for lists. */
  normalized_value: z.string(),
  /** Additional anchors merged from duplicates. */
  additional_anchors: z.array(extractionAnchorSchema).default([]),
});
export type VerifiedCandidate = z.infer<typeof verifiedCandidateSchema>;

// ---------------------------------------------------------------------------
// Reconciliation exception (E6) — P1 plan §8.4
// ---------------------------------------------------------------------------

export const exceptionEvidenceSideSchema = z.object({
  label: z.string(),
  candidateKeys: z.array(z.string()),
  value: z.string().optional(),
  anchors: z.array(extractionAnchorSchema).default([]),
});

export const reconciliationExceptionSchema = z.object({
  ruleId: z.string(),
  type: exceptionTypeSchema,
  severity: exceptionSeveritySchema,
  title: z.object({pt: z.string(), en: z.string()}),
  description: z.object({pt: z.string(), en: z.string()}),
  fieldPath: z.string().optional(),
  evidence: z.object({left: exceptionEvidenceSideSchema, right: exceptionEvidenceSideSchema.optional()}),
  proposedResolution: z
    .object({winner: z.enum(["left", "right", "none"]), rationale: z.object({pt: z.string(), en: z.string()})})
    .optional(),
  ownerRole: exceptionOwnerRoleSchema,
  impactedOutputs: z.array(z.string()).default([]),
  blocksExternalOutputs: z.boolean().default(false),
});
export type ReconciliationException = z.infer<typeof reconciliationExceptionSchema>;

// ---------------------------------------------------------------------------
// Case brief skeleton (E7) — claims-first; refined in F4
// ---------------------------------------------------------------------------

export const claimSchema = z.object({
  id: z.string().min(1),
  claimType: z.enum(["fact", "calculation", "assumption", "judgment", "external_observation"]),
  text: z.object({pt: z.string(), en: z.string()}),
  supportIds: z.array(z.string()),
  materiality: materialitySchema,
  validationStatus: z.enum(["supported", "unsupported", "contradicted", "stale"]).default("unsupported"),
});
export type Claim = z.infer<typeof claimSchema>;

export const caseBriefSchema = z.object({
  version: z.number().int().positive(),
  sections: z.array(
    z.object({
      key: z.string().min(1),
      title: z.object({pt: z.string(), en: z.string()}),
      claimIds: z.array(z.string()),
    }),
  ),
  claims: z.array(claimSchema),
  openQuestions: z.array(z.object({id: z.string(), text: z.object({pt: z.string(), en: z.string()}), materiality: materialitySchema})).default([]),
});
export type CaseBrief = z.infer<typeof caseBriefSchema>;

packages/document-intelligence/src/gover.content:
import {createHash} from "node:crypto";

import {fileTypeFromBuffer} from "file-type";
import JSZip from "jszip";
import {z} from "zod";
import {inspectPdfStructure} from "./pdf-structure";

export const governedDocumentQuarantineVersion = "governed-document-quarantine.v1";

const sha256Schema = z.string().regex(/^[a-f0-9]{64}$/);
const uuidSchema = z.uuid();
const isoSchema = z.iso.datetime({offset: true});

export const quarantineReasonSchema = z.enum([
  "empty_file",
  "file_size_exceeded",
  "size_mismatch",
  "hash_mismatch",
  "unsupported_type",
  "declared_type_mismatch",
  "extension_type_mismatch",
  "malformed_container",
  "polyglot_content",
  "encrypted_document",
  "archive_entries_exceeded",
  "archive_member_exceeded",
  "archive_total_uncompressed_exceeded",
  "archive_ratio_exceeded",
  "nested_archive",
  "archive_path_unsafe",
  "active_content_inspection_exceeded",
  "active_macro",
  "active_script",
  "embedded_object",
  "external_relationship",
  "external_formula",
  "formula_injection",
  "scanner_unavailable",
  "malware_detected",
]);
export type QuarantineReason = z.infer<typeof quarantineReasonSchema>;

export const documentQuarantinePolicySchema = z.object({
  policyVersion: z.string().trim().min(1).max(120),
  maxFileBytes: z.number().int().positive(),
  maxArchiveEntries: z.number().int().positive(),
  maxArchiveMemberBytes: z.number().int().positive(),
  maxArchiveTotalUncompressedBytes: z.number().int().positive(),
  maxArchiveCompressionRatio: z.number().positive(),
  /** This slice rejects nested archives; recursive inspection is not implemented. */
  maxArchiveDepth: z.literal(0),
  maxActiveContentInspectionBytes: z.number().int().positive(),
  rejectDeclaredTypeMismatch: z.boolean(),
  rejectExtensionTypeMismatch: z.boolean(),
  rejectEncryptedDocuments: z.boolean(),
  rejectMacros: z.boolean(),
  rejectActiveScripts: z.boolean(),
  rejectEmbeddedObjects: z.boolean(),
  rejectExternalRelationships: z.boolean(),
  rejectExternalFormulas: z.boolean(),
  rejectFormulaInjection: z.boolean(),
  allowedMediaTypes: z.array(z.string().trim().min(1)).min(1),
}).strict();
export type DocumentQuarantinePolicy = z.infer<typeof documentQuarantinePolicySchema>;

export const defaultDocumentQuarantinePolicy: Readonly<DocumentQuarantinePolicy> = deepFreeze(documentQuarantinePolicySchema.parse({
  policyVersion: "offroad.document-quarantine.2026-09-16.v2",
  maxFileBytes: 50 * 1024 * 1024,
  maxArchiveEntries: 5_000,
  maxArchiveMemberBytes: 200 * 1024 * 1024,
  maxArchiveTotalUncompressedBytes: 512 * 1024 * 1024,
  maxArchiveCompressionRatio: 250,
  maxArchiveDepth: 0,
  maxActiveContentInspectionBytes: 8 * 1024 * 1024,
  rejectDeclaredTypeMismatch: true,
  rejectExtensionTypeMismatch: true,
  rejectEncryptedDocuments: true,
  rejectMacros: true,
  rejectActiveScripts: true,
  rejectEmbeddedObjects: true,
  rejectExternalRelationships: true,
  rejectExternalFormulas: true,
  rejectFormulaInjection: true,
  allowedMediaTypes: [
    "application/pdf",
    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    "application/vnd.openxmlformats-officedocument.presentationml.presentation",
    "text/plain",
    "text/csv",
    "image/png",
    "image/jpeg",
    "image/tiff",
    "application/zip",
  ],
}));

/** Machine-readable honesty boundary for the pure contract in this package. */
export const governedDocumentQuarantineRuntimeBoundary = deepFreeze({
  maturity: "code_complete_candidate",
  exposure: "internal_shadow",
  parserAuthorization: "clean_receipt_required",
  blockers: [
    "append_only_receipt_persistence",
    "atomic_compare_and_swap",
    "immutable_storage_version_binding",
    "scanner_version_and_signature_attestation",
    "runtime_task_isolation",
    "runtime_egress_enforcement",
    "complete_nested_container_detection",
    "staging_adversarial_validation",
  ],
} as const);

export const quarantineDocumentBindingSchema = z.object({
  organizationId: uuidSchema,
  sourceDocumentId: uuidSchema,
  documentVersion: z.number().int().positive(),
  expectedSha256: sha256Schema,
  expectedByteSize: z.number().int().nonnegative(),
  originalName: z.string().trim().min(1).max(1_024),
  declaredMediaType: z.string().trim().min(1).max(255).nullable(),
  operationId: uuidSchema,
}).strict();
export type QuarantineDocumentBinding = z.infer<typeof quarantineDocumentBindingSchema>;

export type GovernedMalwareScanner = Readonly<{
  scannerId: string;
  engineVersion: string | null;
  signatureSetVersion: string | null;
  scan(bytes: Uint8Array): Promise<Readonly<{verdict: "clean" | "infected"; signature?: string}>>;
}>;

const detectedContentSchema = z.object({
  mediaType: z.string().min(1),
  extension: z.string(),
  container: z.enum(["none", "pdf", "zip", "ooxml", "cfb", "text", "image", "other"]),
  archiveEntries: z.number().int().nonnegative(),
  archiveCompressedBytes: z.number().int().nonnegative(),
  archiveUncompressedBytes: z.number().int().nonnegative(),
  archiveMaxDepth: z.number().int().nonnegative(),
  activeContent: z.array(z.enum(["macro", "script", "embedded_object", "external_relationship", "external_formula", "formula_injection"])),
}).strict();

export const documentQuarantineReceiptSchema = z.object({
  schemaVersion: z.literal(governedDocumentQuarantineVersion),
  receiptId: z.string().regex(/^sha256:[a-f0-9]{64}$/),
  receiptFingerprint: sha256Schema,
  organizationId: uuidSchema,
  sourceDocumentId: uuidSchema,
  documentVersion: z.number().int().positive(),
  operationId: uuidSchema,
  expectedSha256: sha256Schema,
  observedSha256: sha256Schema,
  expectedByteSize: z.number().int().nonnegative(),
  observedByteSize: z.number().int().nonnegative(),
  originalName: z.string().min(1),
  declaredMediaType: z.string().nullable(),
  detected: detectedContentSchema.nullable(),
  scanner: z.object({
    scannerId: z.string().min(1),
    engineVersion: z.string().nullable(),
    signatureSetVersion: z.string().nullable(),
    verdict: z.enum(["clean", "infected", "unavailable"]),
    malwareSignature: z.string().min(1).nullable(),
  }).strict(),
  policyVersion: z.string().min(1),
  policyFingerprint: sha256Schema,
  verdict: z.enum(["clean", "rejected"]),
  reasons: z.array(quarantineReasonSchema),
  retryable: z.boolean(),
  transitions: z.tuple([
    z.object({state: z.literal("quarantined"), at: isoSchema}).strict(),
    z.object({state: z.literal("scanning"), at: isoSchema}).strict(),
    z.object({state: z.enum(["clean", "rejected"]), at: isoSchema}).strict(),
  ]),
}).strict();
export type DocumentQuarantineReceipt = z.infer<typeof documentQuarantineReceiptSchema>;

export type AuthorizedParserInput = Readonly<{
  bytes: Uint8Array;
  organizationId: string;
  sourceDocumentId: string;
  documentVersion: number;
  operationId: string;
  originalName: string;
  declaredMediaType: string | null;
  detectedMediaType: string;
  detectedExtension: string;
  observedSha256: string;
  observedByteSize: number;
}>;

export class GovernedDocumentQuarantineError extends Error {
  constructor(readonly code: "receipt_invalid" | "receipt_not_clean" | "binding_mismatch" | "bytes_changed") {
    super(code);
    this.name = "GovernedDocumentQuarantineError";
  }
}

export async function quarantineDocument(input: {
  bytes: Uint8Array;
  binding: QuarantineDocumentBinding;
  scanner: GovernedMalwareScanner | null;
  policy?: DocumentQuarantinePolicy;
  now?: () => string;
}): Promise<DocumentQuarantineReceipt> {
  const binding = quarantineDocumentBindingSchema.parse(structuredClone(input.binding));
  const policy = documentQuarantinePolicySchema.parse(structuredClone(input.policy ?? defaultDocumentQuarantinePolicy));
  const now = input.now ?? (() => new Date().toISOString());
  const quarantinedAt = checkedTimestamp(now());
  const scanningAt = checkedTimestamp(now());
  const immutableBytes = Uint8Array.from(input.bytes);
  const observedByteSize = immutableBytes.byteLength;
  const observedSha256 = sha256(immutableBytes);
  const reasons = new Set<QuarantineReason>();

  if (observedByteSize === 0) reasons.add("empty_file");
  if (observedByteSize > policy.maxFileBytes) reasons.add("file_size_exceeded");
  if (observedByteSize !== binding.expectedByteSize) reasons.add("size_mismatch");
  if (observedSha256 !== binding.expectedSha256) reasons.add("hash_mismatch");

  let scannerResult: DocumentQuarantineReceipt["scanner"] = {
    scannerId: input.scanner?.scannerId ?? "none",
    engineVersion: input.scanner?.engineVersion ?? null,
    signatureSetVersion: input.scanner?.signatureSetVersion ?? null,
    verdict: "unavailable",
    malwareSignature: null,
  };

  if (reasons.size === 0 && input.scanner) {
    try {
      // The scanner is an external boundary and must never receive the canonical byte snapshot.
      // A buggy or compromised adapter may mutate its input after declaring it clean; give it a
      // disposable copy and revalidate the untouched snapshot before container inspection.
      const result = await input.scanner.scan(Uint8Array.from(immutableBytes));
      scannerResult = {
        scannerId: input.scanner.scannerId,
        engineVersion: input.scanner.engineVersion,
        signatureSetVersion: input.scanner.signatureSetVersion,
        verdict: result.verdict,
        malwareSignature: result.signature ?? null,
      };
      if (result.verdict === "infected") reasons.add("malware_detected");
    } catch {
      reasons.add("scanner_unavailable");
    }
  } else if (reasons.size === 0) {
    reasons.add("scanner_unavailable");
  }

  if (immutableBytes.byteLength !== observedByteSize || observedByteSize !== binding.expectedByteSize) reasons.add("size_mismatch");
  if (sha256(immutableBytes) !== observedSha256 || observedSha256 !== binding.expectedSha256) reasons.add("hash_mismatch");

  // Container detection can invoke complex archive code. It is deliberately sequenced after a
  // clean malware verdict; before that point the gate does only byte count and SHA-256.
  let detected: z.infer<typeof detectedContentSchema> | null = null;
  if (reasons.size === 0 && scannerResult.verdict === "clean") {
    try {
      const inspection = await inspectDocumentBytes(immutableBytes, binding, policy);
      detected = inspection.detected;
      for (const reason of inspection.reasons) reasons.add(reason);
    } catch {
      // A detector/parser crash is itself a malformed input verdict. The gate must still emit a
      // durable rejection receipt; throwing here would leave the document stuck in `scanning`.
      reasons.add("malformed_container");
    }
  }

  const completedAt = checkedTimestamp(now());
  if (Date.parse(scanningAt) < Date.parse(quarantinedAt) || Date.parse(completedAt) < Date.parse(scanningAt)) {
    throw new GovernedDocumentQuarantineError("receipt_invalid");
  }

  const orderedReasons = [...reasons].sort();
  const verdict = orderedReasons.length === 0 && scannerResult.verdict === "clean" ? "clean" : "rejected";
  const policyFingerprint = fingerprint(policy);
  const receiptIdentity = {
    schemaVersion: governedDocumentQuarantineVersion,
    organizationId: binding.organizationId,
    sourceDocumentId: binding.sourceDocumentId,
    documentVersion: binding.documentVersion,
    operationId: binding.operationId,
    expectedSha256: binding.expectedSha256,
    observedSha256,
    expectedByteSize: binding.expectedByteSize,
    observedByteSize,
    originalName: binding.originalName,
    declaredMediaType: binding.declaredMediaType,
    detected,
    scanner: scannerResult,
    policyVersion: policy.policyVersion,
    policyFingerprint,
    verdict,
    reasons: orderedReasons,
    retryable: orderedReasons.length === 1 && orderedReasons[0] === "scanner_unavailable",
    transitions: [
      {state: "quarantined", at: quarantinedAt},
      {state: "scanning", at: scanningAt},
      {state: verdict, at: completedAt},
    ],
  } as const;
  // This ID identifies the exact immutable receipt, not merely a job or an input. Including every
  // binding field, the observed bytes, policy, scanner outcome and timestamps prevents two
  // materially different receipts from colliding under a retry of the same operation.
  const receiptId = `sha256:${fingerprint(receiptIdentity)}`;
  const body = {
    ...receiptIdentity,
    receiptId,
  } as const;
  const receipt = documentQuarantineReceiptSchema.parse({...body, receiptFingerprint: fingerprint(body)});
  return deepFreeze(receipt);
}

export function authorizeParserInput(input: {
  receipt: DocumentQuarantineReceipt;
  binding: QuarantineDocumentBinding;
  bytes: Uint8Array;
  policy?: DocumentQuarantinePolicy;
}): AuthorizedParserInput {
  const receipt = documentQuarantineReceiptSchema.parse(structuredClone(input.receipt));
  const {receiptFingerprint: _fingerprint, ...body} = receipt;
  if (fingerprint(body) !== receipt.receiptFingerprint) throw new GovernedDocumentQuarantineError("receipt_invalid");
  const {receiptId: _receiptId, ...receiptIdentity} = body;
  if (`sha256:${fingerprint(receiptIdentity)}` !== receipt.receiptId) throw new GovernedDocumentQuarantineError("receipt_invalid");
  if (receipt.verdict !== "clean" || receipt.scanner.verdict !== "clean" || receipt.reasons.length > 0) {
    throw new GovernedDocumentQuarantineError("receipt_not_clean");
  }
  const binding = quarantineDocumentBindingSchema.parse(input.binding);
  if (
    receipt.organizationId !== binding.organizationId
    || receipt.sourceDocumentId !== binding.sourceDocumentId
    || receipt.documentVersion !== binding.documentVersion
    || receipt.operationId !== binding.operationId
    || receipt.expectedSha256 !== binding.expectedSha256
    || receipt.expectedByteSize !== binding.expectedByteSize
    || receipt.originalName !== binding.originalName
    || receipt.declaredMediaType !== binding.declaredMediaType
  ) throw new GovernedDocumentQuarantineError("binding_mismatch");

  const policy = documentQuarantinePolicySchema.parse(input.policy ?? defaultDocumentQuarantinePolicy);
  if (receipt.policyVersion !== policy.policyVersion || receipt.policyFingerprint !== fingerprint(policy)) {
    throw new GovernedDocumentQuarantineError("binding_mismatch");
  }

  const current = Uint8Array.from(input.bytes);
  if (current.byteLength !== receipt.observedByteSize || sha256(current) !== receipt.observedSha256) {
    throw new GovernedDocumentQuarantineError("bytes_changed");
  }
  if (!receipt.detected) throw new GovernedDocumentQuarantineError("receipt_invalid");
  return Object.freeze({
    bytes: current,
    organizationId: receipt.organizationId,
    sourceDocumentId: receipt.sourceDocumentId,
    documentVersion: receipt.documentVersion,
    operationId: receipt.operationId,
    originalName: receipt.originalName,
    declaredMediaType: receipt.declaredMediaType,
    detectedMediaType: receipt.detected.mediaType,
    detectedExtension: receipt.detected.extension,
    observedSha256: receipt.observedSha256,
    observedByteSize: receipt.observedByteSize,
  });
}

async function inspectDocumentBytes(
  bytes: Uint8Array,
  binding: QuarantineDocumentBinding,
  policy: DocumentQuarantinePolicy,
): Promise<{detected: z.infer<typeof detectedContentSchema>; reasons: QuarantineReason[]}> {
  const sniffed = await fileTypeFromBuffer(bytes);
  const fileExtension = extensionOf(binding.originalName);
  let mediaType = sniffed?.mime ?? "application/octet-stream";
  let extension = sniffed?.ext ?? fileExtension;
  let container: z.infer<typeof detectedContentSchema>["container"] = "other";
  let archiveEntries = 0;
  let archiveCompressedBytes = 0;
  let archiveUncompressedBytes = 0;
  let archiveMaxDepth = 0;
  const activeContent = new Set<z.infer<typeof detectedContentSchema>["activeContent"][number]>();
  const reasons = new Set<QuarantineReason>();

  if (!sniffed && looksTextual(bytes)) {
    mediaType = fileExtension === "txt" ? "text/plain" : "text/csv";
    extension = fileExtension;
    container = "text";
    if (policy.rejectFormulaInjection && hasFormulaInjection(new TextDecoder("utf-8", {fatal: false}).decode(bytes))) {
      activeContent.add("formula_injection");
      reasons.add("formula_injection");
    }
  } else if (mediaType === "application/pdf") {
    container = "pdf";
    const ascii = latin1(bytes);
    if (!ascii.startsWith("%PDF-") || !/%%EOF\s*$/.test(ascii.slice(-8_192))) reasons.add("malformed_container");
    const structure = await inspectPdfStructure(bytes, policy.maxActiveContentInspectionBytes);
    if (structure.limited) reasons.add("active_content_inspection_exceeded");
    if (structure.malformed) reasons.add("malformed_container");
    if (policy.rejectEncryptedDocuments && structure.encrypted) reasons.add("encrypted_document");
    if (structure.script) {
      activeContent.add("script");
      if (policy.rejectActiveScripts) reasons.add("active_script");
    }
    if (structure.embedded) {
      activeContent.add("embedded_object");
      if (policy.rejectEmbeddedObjects) reasons.add("embedded_object");
    }
    if (indexOfBytes(bytes, [0x50, 0x4b, 0x03, 0x04], 5) >= 0) reasons.add("polyglot_content");
  } else if (mediaType === "application/zip") {
    container = "zip";
    try {
      const zip = await JSZip.loadAsync(bytes);
      const entries = Object.values(zip.files);
      archiveEntries = entries.length;
      if (entries.length > policy.maxArchiveEntries) reasons.add("archive_entries_exceeded");
      for (const entry of entries) {
        if (entry.unsafeOriginalName && !archivePathSafe(entry.unsafeOriginalName)) reasons.add("archive_path_unsafe");
        const sizes = (entry as unknown as {_data?: {compressedSize?: number; uncompressedSize?: number}})._data;
        const compressed = sizes?.compressedSize ?? 0;
        const uncompressed = sizes?.uncompressedSize ?? 0;
        archiveCompressedBytes += compressed;
        archiveUncompressedBytes += uncompressed;
        if (uncompressed > policy.maxArchiveMemberBytes) reasons.add("archive_member_exceeded");
        const depth = archiveDepth(entry.name);
        archiveMaxDepth = Math.max(archiveMaxDepth, depth);
        if (depth > policy.maxArchiveDepth) reasons.add("nested_archive");
      }
      if (archiveUncompressedBytes > policy.maxArchiveTotalUncompressedBytes) reasons.add("archive_total_uncompressed_exceeded");
      if (archiveCompressedBytes > 0 && archiveUncompressedBytes / archiveCompressedBytes > policy.maxArchiveCompressionRatio) reasons.add("archive_ratio_exceeded");

      const names = entries.map((entry) => entry.name.replaceAll("\\", "/").toLowerCase());
      const ooxmlKind = names.includes("word/document.xml") ? "docx"
        : names.includes("xl/workbook.xml") ? "xlsx"
          : names.includes("ppt/presentation.xml") ? "pptx"
            : null;
      if (ooxmlKind) {
        container = "ooxml";
        mediaType = ooxmlKind === "docx"
          ? "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
          : ooxmlKind === "xlsx"
            ? "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
            : "application/vnd.openxmlformats-officedocument.presentationml.presentation";
        extension = ooxmlKind;
      } else if (!entries.filter((entry) => !entry.dir).every((entry) => entry.name.toLowerCase().endsWith(".xml"))) {
        reasons.add("unsupported_type");
      }

      if (names.some((name) => /(?:^|\/)(?:vbaproject\.bin|macros?\/|_vba_project)/.test(name))) {
        activeContent.add("macro");
        if (policy.rejectMacros) reasons.add("active_macro");
      }
      if (names.some((name) => /\/(?:embeddings|activex)\//.test(name) || /oleobject/.test(name))) {
        activeContent.add("embedded_object");
        if (policy.rejectEmbeddedObjects) reasons.add("embedded_object");
      }

      const declaredLimitFailure = [...reasons].some((reason) => reason.startsWith("archive_") || reason === "nested_archive");
      if (!declaredLimitFailure) {
        let actualTotal = 0;
        for (const entry of entries) {
          if (entry.dir) continue;
          const lower = entry.name.toLowerCase();
          const capture = lower.endsWith(".rels") || /^xl\/worksheets\/.*\.xml$/.test(lower);
          try {
            const result = await readZipEntryBounded(
              entry,
              policy.maxArchiveMemberBytes,
              policy.maxArchiveTotalUncompressedBytes - actualTotal,
              capture ? policy.maxActiveContentInspectionBytes : 0,
            );
            actualTotal += result.bytes;
            if (archiveMagic(result.prefix)) {
              archiveMaxDepth = Math.max(archiveMaxDepth, 1);
              reasons.add("nested_archive");
              break;
            }
            if (!result.source) continue;
            if (lower.endsWith(".rels") && /TargetMode\s*=\s*["']External["']/i.test(result.source)) {
              activeContent.add("external_relationship");
              if (policy.rejectExternalRelationships) reasons.add("external_relationship");
            }
            if (/^xl\/worksheets\/.*\.xml$/.test(lower) && hasExternalFormula(result.source)) {
              activeContent.add("external_formula");
              if (policy.rejectExternalFormulas) reasons.add("external_formula");
            }
          } catch (error) {
            if (error instanceof ArchiveBoundError) {
              reasons.add(error.reason);
              break;
            }
            else throw error;
          }
        }
      }
    } catch {
      reasons.add("malformed_container");
    }
  } else if (mediaType === "application/x-cfb") {
    container = "cfb";
    const markerText = latin1(bytes) + new TextDecoder("utf-16le", {fatal: false}).decode(bytes);
    if (/(?:_VBA_PROJECT|VBA|Macros)/i.test(markerText)) {
      activeContent.add("macro");
      if (policy.rejectMacros) reasons.add("active_macro");
    }
  } else if (mediaType.startsWith("image/")) container = "image";

  if (!policy.allowedMediaTypes.includes(mediaType)) reasons.add("unsupported_type");
  const declared = canonicalMediaType(binding.declaredMediaType);
  if (policy.rejectDeclaredTypeMismatch && declared && !mediaTypesCompatible(declared, mediaType)) reasons.add("declared_type_mismatch");
  if (policy.rejectExtensionTypeMismatch && fileExtension && !extensionCompatible(fileExtension, extension, mediaType)) reasons.add("extension_type_mismatch");

  return {
    detected: detectedContentSchema.parse({
      mediaType,
      extension,
      container,
      archiveEntries,
      archiveCompressedBytes,
      archiveUncompressedBytes,
      archiveMaxDepth,
      activeContent: [...activeContent].sort(),
    }),
    reasons: [...reasons].sort(),
  };
}

function canonicalMediaType(value: string | null): string | null {
  if (!value) return null;
  const normalized = value.toLowerCase().split(";", 1)[0]?.trim() ?? "";
  if (normalized === "application/csv" || normalized === "text/comma-separated-values") return "text/csv";
  if (normalized === "application/x-pdf") return "application/pdf";
  if (normalized === "image/jpg") return "image/jpeg";
  return normalized;
}

function mediaTypesCompatible(left: string, right: string): boolean {
  if (left === right) return true;
  const zipAliases = new Set(["application/zip", "application/x-zip-compressed"]);
  return zipAliases.has(left) && zipAliases.has(right);
}

const extensionMediaTypes: Readonly<Record<string, readonly string[]>> = {
  pdf: ["application/pdf"],
  xlsx: ["application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"],
  docx: ["application/vnd.openxmlformats-officedocument.wordprocessingml.document"],
  pptx: ["application/vnd.openxmlformats-officedocument.presentationml.presentation"],
  xls: ["application/vnd.ms-excel", "application/x-cfb"],
  xlsb: ["application/vnd.ms-excel.sheet.binary.macroenabled.12", "application/x-cfb"],
  doc: ["application/msword", "application/x-cfb"],
  ppt: ["application/vnd.ms-powerpoint", "application/x-cfb"],
  csv: ["text/csv"], tsv: ["text/csv"], txt: ["text/plain"], prn: ["text/csv"],
  png: ["image/png"], jpg: ["image/jpeg"], jpeg: ["image/jpeg"], tif: ["image/tiff"], tiff: ["image/tiff"],
  zip: ["application/zip"],
};

function extensionCompatible(fileExtension: string, detectedExtension: string, mediaType: string): boolean {
  const expected = extensionMediaTypes[fileExtension];
  if (expected) return expected.includes(mediaType);
  return fileExtension === detectedExtension;
}

function extensionOf(name: string): string {
  const part = name.split(".").pop();
  return part && part !== name ? part.toLowerCase() : "";
}

function looksTextual(bytes: Uint8Array): boolean {
  if (bytes.byteLength === 0) return false;
  const sample = bytes.subarray(0, Math.min(bytes.byteLength, 32_768));
  let controls = 0;
  for (const byte of sample) if (byte === 0 || (byte < 0x09) || (byte > 0x0d && byte < 0x20)) controls += 1;
  return controls / sample.byteLength < 0.01;
}

function hasFormulaInjection(source: string): boolean {
  return source.split(/\r?\n/).some((line) => line.split(/[;,\t]/).some((cell) => /^[\s"']*[=+@]/.test(cell) || /^[\s"']*-[A-Za-z(]/.test(cell)));
}

function hasExternalFormula(source: string): boolean {
  const formulae = [...source.matchAll(/<(?:\w+:)?f(?:\s[^>]*)?>([\s\S]*?)<\/(?:\w+:)?f>/gi)].map((match) => match[1] ?? "");
  return formulae.some((formula) => /(?:\[[^\]]+\]|https?:\/\/|file:\/\/|WEBSERVICE\s*\(|HYPERLINK\s*\(|DDE\s*\()/i.test(formula));
}

function archiveDepth(name: string): number {
  return /\.(?:zip|zipx|jar|7z|rar|gz|tgz|bz2|tbz|tbz2|xz|txz|tar)$/i.test(name) ? 1 : 0;
}

function archivePathSafe(name: string): boolean {
  return !name.startsWith("/")
    && !name.includes("\\")
    && !name.split("/").some((part) => part === "" || part === "." || part === "..");
}

class ArchiveBoundError extends Error {
  constructor(readonly reason: "archive_member_exceeded" | "archive_total_uncompressed_exceeded" | "active_content_inspection_exceeded") {
    super(reason);
    this.name = "ArchiveBoundError";
  }
}

async function readZipEntryBounded(
  entry: JSZip.JSZipObject,
  maxMemberBytes: number,
  maxRemainingTotalBytes: number,
  captureLimit: number,
): Promise<{bytes: number; source: string | null; prefix: Uint8Array}> {
  const stream = entry.nodeStream("nodebuffer");
  const captured: Buffer[] = [];
  const prefix: number[] = [];
  let bytes = 0;
  return new Promise((resolve, reject) => {
    stream.on("data", (chunk: Buffer | Uint8Array | string) => {
      const body = typeof chunk === "string" ? Buffer.from(chunk) : Buffer.from(chunk);
      bytes += body.byteLength;
      for (const byte of body.subarray(0, Math.max(0, 8 - prefix.length))) prefix.push(byte);
      if (bytes > maxMemberBytes) {
        (stream as NodeJS.ReadableStream & {destroy?: () => void}).destroy?.();
        reject(new ArchiveBoundError("archive_member_exceeded"));
        return;
      }
      if (bytes > maxRemainingTotalBytes) {
        (stream as NodeJS.ReadableStream & {destroy?: () => void}).destroy?.();
        reject(new ArchiveBoundError("archive_total_uncompressed_exceeded"));
        return;
      }
      if (captureLimit > 0) {
        if (bytes > captureLimit) {
          (stream as NodeJS.ReadableStream & {destroy?: () => void}).destroy?.();
          reject(new ArchiveBoundError("active_content_inspection_exceeded"));
          return;
        }
        captured.push(body);
      }
    });
    stream.on("error", reject);
    stream.on("end", () => resolve({
      bytes,
      source: captureLimit > 0 ? Buffer.concat(captured).toString("utf8") : null,
      prefix: Uint8Array.from(prefix),
    }));
  });
}

function archiveMagic(prefix: Uint8Array): boolean {
  return (
    startsWith(prefix, [0x50, 0x4b, 0x03, 0x04])
    || startsWith(prefix, [0x1f, 0x8b])
    || startsWith(prefix, [0x52, 0x61, 0x72, 0x21, 0x1a, 0x07])
    || startsWith(prefix, [0x37, 0x7a, 0xbc, 0xaf, 0x27, 0x1c])
    || startsWith(prefix, [0x42, 0x5a, 0x68])
    || startsWith(prefix, [0xfd, 0x37, 0x7a, 0x58, 0x5a, 0x00])
  );
}

function startsWith(bytes: Uint8Array, prefix: readonly number[]): boolean {
  return prefix.every((byte, index) => bytes[index] === byte);
}

function latin1(bytes: Uint8Array): string {
  return new TextDecoder("latin1", {fatal: false}).decode(bytes);
}

function indexOfBytes(bytes: Uint8Array, needle: readonly number[], start = 0): number {
  outer: for (let i = start; i <= bytes.length - needle.length; i += 1) {
    for (let j = 0; j < needle.length; j += 1) if (bytes[i + j] !== needle[j]) continue outer;
    return i;
  }
  return -1;
}

function checkedTimestamp(value: string): string {
  return isoSchema.parse(value);
}

function sha256(bytes: Uint8Array): string {
  return createHash("sha256").update(bytes).digest("hex");
}

function fingerprint(value: unknown): string {
  return sha256(new TextEncoder().encode(stableJson(value)));
}

function stableJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(stableJson).join(",")}]`;
  if (value && typeof value === "object") {
    return `{${Object.entries(value as Record<string, unknown>)
      .filter(([, entry]) => entry !== undefined)
      .sort(([left], [right]) => left.localeCompare(right))
      .map(([key, entry]) => `${JSON.stringify(key)}:${stableJson(entry)}`)
      .join(",")}}`;
  }
  return JSON.stringify(value) ?? "null";
}

function deepFreeze<T>(value: T): T {
  if (value && typeof value === "object") {
    Object.freeze(value);
    for (const child of Object.values(value as Record<string, unknown>)) deepFreeze(child);
  }
  return value;
}

