import Decimal from "decimal.js";

Decimal.set({precision: 40, rounding: Decimal.ROUND_HALF_UP, toExpNeg: -30, toExpPos: 30});

/**
 * Canonical text normalization used by every containment check:
 * NFKC → lower-case → strip diacritics → unify spaces/dashes → collapse whitespace.
 * Numbers keep their separators so "185.400" ≠ "185400" (exactness is checked
 * separately through digit sequences).
 */
export function normalizeText(value: string): string {
  return value
    .normalize("NFKD")
    .toLowerCase()
    .replace(/\p{M}/gu, "")
    .replace(/[   ]/g, " ")
    .replace(/[‐-―−]/g, "-")
    .replace(/[“”„]/g, '"')
    .replace(/[‘’]/g, "'")
    .replace(/\s+/g, " ")
    .trim();
}

/** Digits only (used to check that a number was not altered by re-formatting). */
export function digitSequence(value: string): string {
  return value.replace(/\D+/g, "");
}

export function containsNormalized(haystack: string, needle: string): boolean {
  const h = normalizeText(haystack);
  const n = normalizeText(needle);
  if (n.length === 0) return false;
  return h.includes(n);
}

const wordScales: Array<[RegExp, number]> = [
  [/\b(bilh(ao|oes)|bilhao|bilhoes|bi|billion|billions|bn)\b/i, 1_000_000_000],
  [/\b(milh(ao|oes)|milhao|milhoes|mi|mm|million|millions|mn)\b/i, 1_000_000],
  [/\b(mil|thousand|thousands|k)\b/i, 1_000],
];

export type ParsedNumber = {
  value: Decimal;
  negative: boolean;
  /** Multiplier implied by a word in the raw text ("54 milhões" → 1e6), null when absent. */
  detectedScale: number | null;
  isPercent: boolean;
};

/**
 * Parses numbers as they appear in Brazilian and international financial
 * documents: `185.400`, `185.400,50`, `1,234.5`, `(1.234)`, `-1.234`,
 * `R$ 54 milhões`, `12,5%`, `3,2x`. Returns null when no number is present.
 * `localeHint` only breaks the ambiguous single-separator case (`1.234`).
 */
export function parseNumber(raw: string, localeHint: "pt-BR" | "en-US" = "pt-BR"): ParsedNumber | null {
  const cleaned = raw.normalize("NFKC").replace(/[   ]/g, " ").trim();
  if (!/\d/.test(cleaned)) return null;

  const isPercent = /%/.test(cleaned);
  let detectedScale: number | null = null;
  for (const [pattern, scale] of wordScales) {
    if (pattern.test(stripDiacritics(cleaned))) {
      detectedScale = scale;
      break;
    }
  }

  const parenthesized = /^\s*\(.*\)\s*$/.test(cleaned) || /\(\s*[\d.,]+\s*\)/.test(cleaned);
  // A multiplier suffix ("4,0x", "3.0 x") is a unit, the way "%" is; the digits are the value.
  const match = /[-−–]?\s?\d[\d.,]*/.exec(cleaned.replace(/\(([^)]*)\)/g, "$1").replace(/(\d)\s?x\b/i, "$1"));
  if (!match) return null;
  let token = match[0].replace(/\s+/g, "").replace(/[.,]+$/, "");
  let negative = parenthesized || /^[-−–]/.test(token) || /^\s*[-−–]/.test(cleaned);
  token = token.replace(/^[-−–]/, "");
  // A trailing minus ("1.234-") is used by some ERPs.
  if (/[-−–]\s*$/.test(cleaned) && !/[a-zA-Z%]/.test(cleaned)) negative = true;

  const dots = (token.match(/\./g) ?? []).length;
  const commas = (token.match(/,/g) ?? []).length;
  let integerPart = token;
  let fractionPart = "";

  if (dots > 0 && commas > 0) {
    const lastDot = token.lastIndexOf(".");
    const lastComma = token.lastIndexOf(",");
    const decimalSeparator = lastDot > lastComma ? "." : ",";
    const [i, f = ""] = splitLast(token, decimalSeparator);
    integerPart = i.replace(/[.,]/g, "");
    fractionPart = f;
  } else if (dots > 0 || commas > 0) {
    const separator = dots > 0 ? "." : ",";
    const count = dots > 0 ? dots : commas;
    const [i, f = ""] = splitLast(token, separator);
    // "0.181" is never zero thousand one hundred and eighty-one: a leading lone zero makes the
    // separator decimal in any locale. Aurora's customer sheet measured the alternative: every
    // share came back a hundred times too large.
    const leadingZero = /^0$/.test(i);
    const looksLikeThousands = !leadingZero && (count > 1 || (f.length === 3 && (separator === "." ? localeHint === "pt-BR" : localeHint === "en-US")));
    if (looksLikeThousands) {
      integerPart = token.replace(/[.,]/g, "");
      fractionPart = "";
    } else {
      integerPart = i.replace(/[.,]/g, "");
      fractionPart = f;
    }
  }

  if (!/^\d+$/.test(integerPart) || (fractionPart && !/^\d+$/.test(fractionPart))) return null;
  const magnitude = new Decimal(fractionPart ? `${integerPart}.${fractionPart}` : integerPart);
  return {value: negative ? magnitude.negated() : magnitude, negative, detectedScale, isPercent};
}

function splitLast(token: string, separator: string): [string, string] {
  const index = token.lastIndexOf(separator);
  return [token.slice(0, index), token.slice(index + 1)];
}

function stripDiacritics(value: string): string {
  return value.normalize("NFKD").replace(/\p{M}/gu, "");
}

const monthTokens: Record<string, number> = {
  jan: 1, fev: 2, feb: 2, mar: 3, abr: 4, apr: 4, mai: 5, may: 5, jun: 6, jul: 7, ago: 8, aug: 8, set: 9, sep: 9, out: 10, oct: 10, nov: 11, dez: 12, dec: 12,
};

/**
 * Parses dates in the shapes seen in documents: `2025-12-31`, `31/12/2025`,
 * `31.12.2025`, `dez/25`, `dezembro de 2025` (→ last day of month), `07/2026`
 * (→ last day of month). Returns an ISO date or null.
 */
export function parseDate(raw: string): string | null {
  const value = normalizeText(raw);
  let m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (m) return isoIfValid(Number(m[1]), Number(m[2]), Number(m[3]));
  m = /^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})$/.exec(value);
  if (m) return isoIfValid(Number(m[3]), Number(m[2]), Number(m[1]));
  m = /^(\d{1,2})[/.-](\d{4})$/.exec(value);
  if (m) return endOfMonth(Number(m[2]), Number(m[1]));
  m = /^([a-z]{3})[a-z]*[ /.-]*(?:de )?(\d{2}|\d{4})$/.exec(value);
  if (m) {
    const month = monthTokens[m[1] as keyof typeof monthTokens];
    if (!month) return null;
    const year = m[2]!.length === 2 ? 2000 + Number(m[2]) : Number(m[2]);
    return endOfMonth(year, month);
  }
  m = /^(\d{1,2}) de ([a-z]+) de (\d{4})$/.exec(value);
  if (m) {
    const month = monthTokens[m[2]!.slice(0, 3) as keyof typeof monthTokens];
    if (!month) return null;
    return isoIfValid(Number(m[3]), month, Number(m[1]));
  }
  return null;
}

function endOfMonth(year: number, month: number): string | null {
  if (month < 1 || month > 12) return null;
  const day = new Date(Date.UTC(year, month, 0)).getUTCDate();
  return isoIfValid(year, month, day);
}

function isoIfValid(year: number, month: number, day: number): string | null {
  if (month < 1 || month > 12 || day < 1) return null;
  const last = new Date(Date.UTC(year, month, 0)).getUTCDate();
  if (day > last) return null;
  return `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
}

export function parseBoolean(raw: string): boolean | null {
  const value = normalizeText(raw);
  if (["sim", "yes", "true", "verdadeiro", "s", "y", "x", "conciliado", "reconciled"].includes(value)) return true;
  if (["nao", "no", "false", "falso", "n", "nao conciliado", "not reconciled"].includes(value)) return false;
  return null;
}

export function parseList(raw: string): string[] {
  const parts = raw
    .split(/[;\n]|,(?=\s*[A-ZÁÉÍÓÚÂÊÔÃÕÇ])/)
    .map((item) => item.trim())
    .filter((item) => item.length > 0);
  // Portuguese closes an enumeration with "e", not a comma: "Franca, Araraquara e São Carlos"
  // is three items. Only the final part of an already-plural list is split, so a lone name
  // that happens to contain "e" ("Compra e Venda Ltda") is never torn apart.
  if (parts.length >= 2) {
    const last = parts[parts.length - 1] ?? "";
    // Tokenize once: overlapping wildcard/whitespace groups backtrack quadratically
    // on long OCR whitespace. Keep the original spacing inside each resulting name.
    for (const token of last.matchAll(/\S+/g)) {
      if (token[0] !== "e" || token.index === 0 || token.index + 1 === last.length) continue;
      parts.splice(parts.length - 1, 1, last.slice(0, token.index).trim(), last.slice(token.index + 1).trim());
      break;
    }
  }
  return parts;
}

packages/document-intelligence/src/layer.content:
import type {AnchorPrecision} from "@offroad/credit-ontology";
import type {DocumentLayer, LayerTable} from "./schemas";

export type IndexedAnchor = {
  id: string;
  precision: AnchorPrecision;
  text: string;
  page?: number;
  sheet?: string;
  /** Text of the enclosing page/sheet/section/slide — used for scale/period cues. */
  containerId?: string;
};

export type LayerIndex = {
  byId: Map<string, IndexedAnchor>;
  documentId: string;
  documentVersion: number;
};

/**
 * Builds the id → text/precision index used by the verifier. Ids are stable per
 * document version and follow the conventions of P1 plan §5.3.
 */
export function indexLayer(layer: DocumentLayer): LayerIndex {
  const byId = new Map<string, IndexedAnchor>();
  const put = (anchor: IndexedAnchor) => {
    if (byId.has(anchor.id)) throw new Error(`duplicate layer id: ${anchor.id}`);
    byId.set(anchor.id, anchor);
  };

  for (const page of layer.pages ?? []) {
    const pageId = `p${page.n}`;
    const blockTexts: string[] = [];
    for (const block of page.blocks) {
      put({id: block.id, precision: "block", text: block.text, page: page.n, containerId: pageId});
      blockTexts.push(block.text);
    }
    for (const table of page.tables) blockTexts.push(...indexTable(table, put, {page: page.n, containerId: pageId}));
    put({id: pageId, precision: "page", text: blockTexts.join("\n"), page: page.n});
  }

  for (const sheet of layer.sheets ?? []) {
    const sheetId = `s${sheet.name}`;
    const texts: string[] = [];
    for (const cell of sheet.cells) {
      const text = cell.v === null ? "" : String(cell.v);
      put({id: `${sheetId}!${cell.ref}`, precision: "cell", text, sheet: sheet.name, containerId: sheetId});
      if (text) texts.push(text);
    }
    for (const table of sheet.tables) texts.push(...indexTable(table, put, {sheet: sheet.name, containerId: sheetId}));
    put({id: sheetId, precision: "page", text: texts.join("\n"), sheet: sheet.name});
  }

  for (const section of layer.sections ?? []) {
    const texts: string[] = [];
    if (section.heading) texts.push(section.heading);
    for (const paragraph of section.paragraphs) {
      put({id: paragraph.id, precision: "block", text: paragraph.text, containerId: section.id});
      texts.push(paragraph.text);
    }
    for (const table of section.tables) texts.push(...indexTable(table, put, {containerId: section.id}));
    put({id: section.id, precision: "page", text: texts.join("\n")});
  }

  for (const slide of layer.slides ?? []) {
    const slideId = `sl${slide.n}`;
    const texts: string[] = [];
    for (const block of slide.blocks) {
      put({id: block.id, precision: "block", text: block.text, containerId: slideId});
      texts.push(block.text);
    }
    for (const table of slide.tables) texts.push(...indexTable(table, put, {containerId: slideId}));
    if (slide.notes) texts.push(slide.notes);
    put({id: slideId, precision: "page", text: texts.join("\n")});
  }

  const everything = [...byId.values()].filter((a) => a.precision === "page").map((a) => a.text);
  put({id: "document", precision: "document", text: everything.join("\n")});

  return {byId, documentId: layer.documentId, documentVersion: layer.documentVersion};
}

function indexTable(table: LayerTable, put: (anchor: IndexedAnchor) => void, context: {page?: number; sheet?: string; containerId?: string}): string[] {
  const rowTexts: string[] = [];
  for (const row of table.rows) {
    const cellTexts: string[] = [];
    for (const cell of row.cells) {
      put({id: cell.id, precision: "cell", text: cell.text, ...context});
      cellTexts.push(cell.text);
    }
    const rowText = cellTexts.join(" | ");
    put({id: row.id, precision: "row", text: rowText, ...context});
    rowTexts.push(rowText);
  }
  const header = table.header ? [table.header.join(" | ")] : [];
  put({id: table.id, precision: "block", text: [...header, ...rowTexts].join("\n"), ...context});
  return [...header, ...rowTexts];
}

export function lookupAnchor(index: LayerIndex, id: string): IndexedAnchor | undefined {
  return index.byId.get(id);
}

packages/receivables-analysis/src/schema.content:
import {z} from "zod";

export const receivablesAnalysisVersion = "2026.08.24-v1" as const;

export const moneySchema = z.string().regex(/^\d+(?:\.\d+)?$/);
export const rateSchema = z.string().regex(/^\d+(?:\.\d+)?$/).refine((value) => Number(value) >= 0 && Number(value) <= 1, "rate must be between zero and one");

export const receivableSchema = z.object({
  id: z.string().min(1),
  debtorId: z.string().min(1),
  debtorGroupId: z.string().min(1).optional(),
  debtorSector: z.string().min(1),
  originDate: z.iso.date(),
  dueDate: z.iso.date(),
  originalAmount: moneySchema,
  outstandingBalance: moneySchema,
  paidAmount: moneySchema.default("0"),
  collectedInPeriod: moneySchema.default("0"),
  defaultedBalance: moneySchema.default("0"),
  recoveredInPeriod: moneySchema.default("0"),
  dilutionInPeriod: moneySchema.default("0"),
  repurchasedInPeriod: moneySchema.default("0"),
  substitutedInPeriod: moneySchema.default("0"),
  assignable: z.boolean(),
  evidenceVerified: z.boolean(),
  registration: z.enum(["registered", "not_required", "missing", "conflict"]),
  encumbrance: z.enum(["free", "pledged", "assigned", "unknown"]),
  disputed: z.boolean().default(false),
  relatedParty: z.boolean().default(false),
  sourceDocumentId: z.string().min(1),
  sourceAnchor: z.string().min(1),
  anchorVerified: z.boolean(),
}).superRefine((item, context) => {
  const original = Number(item.originalAmount);
  const outstanding = Number(item.outstandingBalance);
  const paid = Number(item.paidAmount);
  const defaulted = Number(item.defaultedBalance);
  if (original < 0 || outstanding < 0 || paid < 0 || defaulted < 0) context.addIssue({code: "custom", message: "monetary balances cannot be negative"});
  if (original <= 0) context.addIssue({code: "custom", path: ["originalAmount"], message: "original amount must be positive"});
  if (outstanding > original) context.addIssue({code: "custom", path: ["outstandingBalance"], message: "outstanding balance cannot exceed original amount"});
  if (defaulted > outstanding) context.addIssue({code: "custom", path: ["defaultedBalance"], message: "defaulted balance cannot exceed outstanding balance"});
  if (item.dueDate < item.originDate) context.addIssue({code: "custom", path: ["dueDate"], message: "due date cannot precede origin date"});
});
export type Receivable = z.infer<typeof receivableSchema>;

export const cashReceiptSchema = z.object({
  id: z.string().min(1),
  receivedAt: z.iso.date(),
  amount: moneySchema,
  receivableId: z.string().min(1).nullable(),
  debtorId: z.string().min(1).nullable(),
  linkedAccount: z.boolean(),
  duplicateOf: z.string().min(1).nullable().default(null),
  sourceDocumentId: z.string().min(1),
  sourceAnchor: z.string().min(1),
  anchorVerified: z.boolean(),
}).superRefine((receipt, context) => {
  if (Number(receipt.amount) <= 0) context.addIssue({code: "custom", path: ["amount"], message: "cash receipt amount must be positive"});
});
export type CashReceipt = z.infer<typeof cashReceiptSchema>;

export const eligibilityPolicySchema = z.object({
  maxDaysPastDue: z.number().int().nonnegative(),
  maxRemainingTermDays: z.number().int().positive(),
  minSeasoningDays: z.number().int().nonnegative(),
  requireAssignable: z.boolean(),
  requireEvidenceVerified: z.boolean(),
  registrationRule: z.enum(["required", "required_when_applicable", "not_required"]),
  excludeDisputed: z.boolean(),
  excludeRelatedParties: z.boolean(),
  excludeEncumbered: z.boolean(),
  allowedDebtorSectors: z.array(z.string().min(1)).default([]),
  maxSingleDebtorShare: rateSchema,
  maxDebtorGroupShare: rateSchema,
  minimumEligibleShare: rateSchema,
  minimumEvidenceCoverage: rateSchema,
  minimumRegistrationCoverage: rateSchema,
  maximumDelinquency30Share: rateSchema,
  maximumDilutionShare: rateSchema,
  maximumRepurchaseShare: rateSchema,
  minimumRecoveryRate: rateSchema,
  maximumAccountingMismatchShare: rateSchema,
  maximumCashMismatchShare: rateSchema,
  minimumMappedCashShare: rateSchema,
  minimumLinkedAccountCashShare: rateSchema,
});
export type EligibilityPolicy = z.infer<typeof eligibilityPolicySchema>;

export const receivablesStructureSchema = z.object({
  requestedFacility: moneySchema.refine((value) => Number(value) > 0, "requested facility must be positive"),
  advanceRate: rateSchema,
  requiredOvercollateralization: z.string().regex(/^\d+(?:\.\d+)?$/).refine((value) => Number(value) >= 1, "overcollateralization must be at least one"),
  requiredSubordinationRate: rateSchema,
  actualSeniorAmount: moneySchema,
  actualMezzanineAmount: moneySchema.default("0"),
  actualSubordinatedAmount: moneySchema,
  reserveRate: rateSchema,
  waterfall: z.object({
    availableCash: moneySchema,
    servicingFeeDue: moneySchema,
    seniorInterestDue: moneySchema,
    seniorPrincipalDue: moneySchema,
    reserveOpening: moneySchema,
    mezzanineDue: moneySchema.default("0"),
  }),
}).superRefine((structure, context) => {
  const capital = Number(structure.actualSeniorAmount) + Number(structure.actualMezzanineAmount) + Number(structure.actualSubordinatedAmount);
  if (capital <= 0) context.addIssue({code: "custom", message: "actual capital stack must be positive"});
});
export type ReceivablesStructure = z.infer<typeof receivablesStructureSchema>;

export const receivablesCaseSchema = z.object({
  schemaVersion: z.literal(receivablesAnalysisVersion),
  id: z.string().regex(/^[a-z0-9][a-z0-9-]{2,99}$/),
  referenceDate: z.iso.date(),
  cedent: z.object({
    id: z.string().min(1),
    legalName: z.string().min(2),
    servicingRole: z.enum(["cedent", "third_party", "shared"]),
  }),
  portfolio: z.array(receivableSchema).min(1),
  cashReceipts: z.array(cashReceiptSchema),
  accounting: z.object({
    grossReceivablesBalance: moneySchema,
    allowanceBalance: moneySchema,
    reportedCollectionsInPeriod: moneySchema,
  }),
  policy: eligibilityPolicySchema,
  structure: receivablesStructureSchema,
}).superRefine((input, context) => {
  if (Number(input.accounting.allowanceBalance) > Number(input.accounting.grossReceivablesBalance)) {
    context.addIssue({code: "custom", path: ["accounting", "allowanceBalance"], message: "allowance cannot exceed gross receivables"});
  }
  const receivableIds = new Set<string>();
  const receivableAnchors = new Set<string>();
  const debtorGroups = new Map<string, string>();
  for (const [index, item] of input.portfolio.entries()) {
    if (receivableIds.has(item.id)) context.addIssue({code: "custom", path: ["portfolio", index, "id"], message: "receivable id must be unique"});
    receivableIds.add(item.id);
    const anchor = `${item.sourceDocumentId}:${item.sourceAnchor}`;
    if (receivableAnchors.has(anchor)) context.addIssue({code: "custom", path: ["portfolio", index, "sourceAnchor"], message: "receivable source anchor must identify one row"});
    receivableAnchors.add(anchor);
    const group = item.debtorGroupId ?? item.debtorId;
    const priorGroup = debtorGroups.get(item.debtorId);
    if (priorGroup !== undefined && priorGroup !== group) context.addIssue({code: "custom", path: ["portfolio", index, "debtorGroupId"], message: "one debtor cannot belong to multiple economic groups in the same snapshot"});
    debtorGroups.set(item.debtorId, group);
  }
  const receiptIds = new Set<string>();
  const receiptAnchors = new Set<string>();
  for (const [index, receipt] of input.cashReceipts.entries()) {
    if (receiptIds.has(receipt.id)) context.addIssue({code: "custom", path: ["cashReceipts", index, "id"], message: "cash receipt id must be unique"});
    receiptIds.add(receipt.id);
    const anchor = `${receipt.sourceDocumentId}:${receipt.sourceAnchor}`;
    if (receiptAnchors.has(anchor)) context.addIssue({code: "custom", path: ["cashReceipts", index, "sourceAnchor"], message: "cash receipt source anchor must identify one row"});
    receiptAnchors.add(anchor);
  }
  for (const [index, receipt] of input.cashReceipts.entries()) {
    if (receipt.duplicateOf === receipt.id) context.addIssue({code: "custom", path: ["cashReceipts", index, "duplicateOf"], message: "a cash receipt cannot duplicate itself"});
    if (receipt.duplicateOf !== null && !receiptIds.has(receipt.duplicateOf)) context.addIssue({code: "custom", path: ["cashReceipts", index, "duplicateOf"], message: "duplicate receipt must reference another receipt in the snapshot"});
  }
});
export type ReceivablesCase = z.infer<typeof receivablesCaseSchema>;

export type EligibilityReason =
  | "zero_balance"
  | "defaulted"
  | "past_due"
  | "remaining_term"
  | "seasoning"
  | "not_assignable"
  | "evidence_unverified"
  | "anchor_unverified"
  | "registration_missing"
  | "registration_conflict"
  | "encumbered"
  | "disputed"
  | "related_party"
  | "sector_outside_policy";

export type ReceivablesDecision = "ready_for_structuring" | "needs_remediation" | "not_viable";

