import Decimal from "decimal.js";
import {
  calculateReceivablesEligibilityAllocation,
  calculateReceivablesProviderAllocation,
  type AssertionProvenance,
  type ReceivableEligibilityClassification,
  type ReceivablesEligibilityAllocation,
  type ReceivablesProviderAllocationEnvelope,
  type ReceivablesUniverse,
} from "@offroad/financial-core";
import {
  type ReceivablesPolicyRule,
  type ReceivablesProviderCriterionId,
  type ResolvedReceivablesMandateCriterion,
  type ResolvedReceivablesProviderMandate,
} from "@offroad/fund-mandate";

import type {ReceivablesPhaseTwoReport, ReceivablesRouteEligibilityStatus} from "./phase-two";

export const receivablesPhaseTwoBReportVersion = "2026.08.27-v1";

export type ReceivablesProviderMetric = {
  value: string;
  provenance: AssertionProvenance;
};

export type ReceivablesProviderMetricSet = {
  currency: string;
  requestedAmount: ReceivablesProviderMetric;
  weightedAverageTermDays?: ReceivablesProviderMetric;
  historyMonths?: ReceivablesProviderMetric;
  pastDueOver30Ratio?: ReceivablesProviderMetric;
  pastDueOver90Ratio?: ReceivablesProviderMetric;
  dilutionRatio?: ReceivablesProviderMetric;
  adjustedLossRatio?: ReceivablesProviderMetric;
  singleObligorRatio?: ReceivablesProviderMetric;
  topTenObligorRatio?: ReceivablesProviderMetric;
};

export type ReceivablesProviderCriterionResult = {
  criterionId: ReceivablesProviderCriterionId;
  status: "pass" | "fail" | "condition" | "not_evaluated";
  hard: boolean;
  reason: string;
  caseProvenance?: AssertionProvenance;
  mandateSourceId?: string;
};

export type ReceivablesProviderFitStatus =
  | "live_appetite_confirmed"
  | "policy_fit_confirmed"
  | "conditionally_eligible"
  | "not_evaluated"
  | "ineligible";

export type ReceivablesProviderFitResult = {
  mandateId: string;
  providerId: string;
  providerLegalName: string;
  providerKind: ResolvedReceivablesProviderMandate["providerKind"];
  programId: string;
  programName: string;
  mandateVersion: number;
  status: ReceivablesProviderFitStatus;
  compatibleRouteIds: readonly string[];
  routeStatuses: readonly {routeId: string; status: ReceivablesRouteEligibilityStatus}[];
  criterionResults: readonly ReceivablesProviderCriterionResult[];
  portfolioAllocation: ReceivablesEligibilityAllocation | null;
  allocationEnvelope: ReceivablesProviderAllocationEnvelope | null;
  marketConfirmation: {
    liveAppetite: {current: boolean; confirmed: boolean; sourceId: string} | null;
    availableCapacity: {current: boolean; confirmed: boolean; sourceId: string} | null;
  };
  blockers: readonly string[];
  conditions: readonly string[];
};

export type ReceivablesPhaseTwoBInput = {
  phaseTwoA: ReceivablesPhaseTwoReport;
  universe: ReceivablesUniverse;
  asOf: string;
  metrics: ReceivablesProviderMetricSet;
  mandates: readonly ResolvedReceivablesProviderMandate[];
  titleClassificationsByProgram?: Readonly<Record<string, readonly ReceivableEligibilityClassification[] | undefined>>;
};

export type ReceivablesPhaseTwoBReport = {
  version: typeof receivablesPhaseTwoBReportVersion;
  analysisLayer: "deterministic_provider_mandate_fit";
  asOf: string;
  universe: ReceivablesPhaseTwoReport["universe"];
  providers: readonly ReceivablesProviderFitResult[];
  summary: {
    screened: number;
    liveAppetiteConfirmed: number;
    policyFitConfirmed: number;
    conditional: number;
    notEvaluated: number;
    ineligible: number;
  };
  quality: {status: "complete_for_internal_shortlist" | "incomplete"; blockers: readonly string[]; warnings: readonly string[]};
  boundaries: {
    buyerMandateMatched: boolean;
    internalShortlistAllowed: boolean;
    companyFacingRecommendationAllowed: false;
    externalDirectionAllowed: false;
    qualifiedIntroductionAllowed: false;
    creditApprovalExpressed: false;
  };
};

type NumericRule = ResolvedReceivablesMandateCriterion<ReceivablesPolicyRule<string>> | null;

function decimal(value: string, label: string): Decimal {
  const parsed = new Decimal(value);
  if (!parsed.isFinite() || parsed.isNegative()) throw new RangeError(`${label} must be a non-negative decimal`);
  return parsed;
}

function metricUsable(metric: ReceivablesProviderMetric | undefined): metric is ReceivablesProviderMetric {
  return Boolean(metric && metric.provenance.kind !== "estimated");
}

function sourceUsable<T>(criterion: ResolvedReceivablesMandateCriterion<T> | null): criterion is ResolvedReceivablesMandateCriterion<T> {
  return Boolean(criterion?.decisionUseAllowed);
}

function result(
  criterionId: ReceivablesProviderCriterionId,
  status: ReceivablesProviderCriterionResult["status"],
  hard: boolean,
  reason: string,
  criterion?: ResolvedReceivablesMandateCriterion<unknown> | null,
  metric?: ReceivablesProviderMetric,
): ReceivablesProviderCriterionResult {
  return {
    criterionId,
    status,
    hard,
    reason,
    ...(metric ? {caseProvenance: metric.provenance} : {}),
    ...(criterion ? {mandateSourceId: criterion.accepted.sourceId} : {}),
  };
}

function evaluateMaximum(
  criterionId: ReceivablesProviderCriterionId,
  criterion: NumericRule,
  metric: ReceivablesProviderMetric | undefined,
): ReceivablesProviderCriterionResult {
  if (!sourceUsable(criterion)) return result(criterionId, "not_evaluated", true, "Política ausente, vencida ou sem fonte utilizável.", criterion);
  if (criterion.divergent) return result(criterionId, "condition", true, "As fontes do mandato divergem e exigem reconfirmação.", criterion);
  const rule = criterion.value;
  if (rule.mode === "no_restriction") return result(criterionId, "pass", true, "O programa confirmou não aplicar este limite.", criterion);
  if (rule.mode === "case_by_case") return result(criterionId, "condition", true, rule.note, criterion);
  if (!metricUsable(metric)) return result(criterionId, "not_evaluated", true, "Métrica do caso ausente ou apenas estimada.", criterion, metric);
  const passes = decimal(metric.value, criterionId).lte(decimal(rule.value, criterionId));
  return result(criterionId, passes ? "pass" : "fail", true, passes ? "Métrica dentro do máximo confirmado." : "Métrica acima do máximo confirmado.", criterion, metric);
}

function evaluateMinimum(
  criterionId: ReceivablesProviderCriterionId,
  criterion: NumericRule,
  metric: ReceivablesProviderMetric | undefined,
): ReceivablesProviderCriterionResult {
  if (!sourceUsable(criterion)) return result(criterionId, "not_evaluated", true, "Política ausente, vencida ou sem fonte utilizável.", criterion);
  if (criterion.divergent) return result(criterionId, "condition", true, "As fontes do mandato divergem e exigem reconfirmação.", criterion);
  const rule = criterion.value;
  if (rule.mode === "no_restriction") return result(criterionId, "pass", true, "O programa confirmou não aplicar este mínimo.", criterion);
  if (rule.mode === "case_by_case") return result(criterionId, "condition", true, rule.note, criterion);
  if (!metricUsable(metric)) return result(criterionId, "not_evaluated", true, "Métrica do caso ausente ou apenas estimada.", criterion, metric);
  const passes = decimal(metric.value, criterionId).gte(decimal(rule.value, criterionId));
  return result(criterionId, passes ? "pass" : "fail", true, passes ? "Métrica acima do mínimo confirmado." : "Métrica abaixo do mínimo confirmado.", criterion, metric);
}

function evaluateRange(
  criterionId: "ticket" | "weighted_average_term_days",
  criterion: ResolvedReceivablesMandateCriterion<ReceivablesPolicyRule<{min: string; max: string}>> | null,
  metric: ReceivablesProviderMetric | undefined,
): ReceivablesProviderCriterionResult {
  if (!sourceUsable(criterion)) return result(criterionId, "not_evaluated", true, "Política ausente, vencida ou sem fonte utilizável.", criterion);
  if (criterion.divergent) return result(criterionId, "condition", true, "As fontes do mandato divergem e exigem reconfirmação.", criterion);
  const rule = criterion.value;
  if (rule.mode === "no_restriction") return result(criterionId, "pass", true, "O programa confirmou não aplicar esta faixa.", criterion);
  if (rule.mode === "case_by_case") return result(criterionId, "condition", true, rule.note, criterion);
  if (!metricUsable(metric)) return result(criterionId, "not_evaluated", true, "Métrica do caso ausente ou apenas estimada.", criterion, metric);
  const value = decimal(metric.value, criterionId);
  const min = decimal(rule.value.min, criterionId);
  const max = decimal(rule.value.max, criterionId);
  if (value.lt(min)) return result(criterionId, "fail", true, "A operação está abaixo do menor ticket ou prazo confirmado.", criterion, metric);
  if (value.gt(max)) {
    return result(
      criterionId,
      criterionId === "ticket" ? "pass" : "fail",
      true,
      criterionId === "ticket"
        ? "O pedido excede o cheque individual. O programa continua compatível até seu limite e pode integrar uma estrutura com mais de um financiador."
        : "O prazo está acima do máximo confirmado.",
      criterion,
      metric,
    );
  }
  return result(criterionId, "pass", true, "Métrica dentro da faixa confirmada.", criterion, metric);
}

function evaluateProvider(
  input: ReceivablesPhaseTwoBInput,
  mandate: ResolvedReceivablesProviderMandate,
): ReceivablesProviderFitResult {
  const routeStatuses = input.phaseTwoA.routes
    .filter((route) => mandate.eligibleRoutes?.value.includes(route.routeId))
    .map((route) => ({routeId: route.routeId, status: route.status}));
  const compatibleRouteIds = routeStatuses
    .filter((route) => route.status === "technically_eligible" || route.status === "conditionally_eligible")
    .map((route) => route.routeId);
  const criteria: ReceivablesProviderCriterionResult[] = [];
  if (!sourceUsable(mandate.eligibleRoutes)) {
    criteria.push(result("eligible_routes", "not_evaluated", true, "Rotas do programa ausentes, vencidas ou sem fonte utilizável.", mandate.eligibleRoutes));
  } else if (routeStatuses.length === 0 || routeStatuses.every((route) => route.status === "ineligible")) {
    criteria.push(result("eligible_routes", "fail", true, "Nenhuma rota do programa é tecnicamente compatível com o caso.", mandate.eligibleRoutes));
  } else if (routeStatuses.every((route) => route.status === "not_evaluated")) {
    criteria.push(result("eligible_routes", "not_evaluated", true, "As rotas declaradas ainda não puderam ser avaliadas tecnicamente.", mandate.eligibleRoutes));
  } else if (routeStatuses.some((route) => route.status === "technically_eligible")) {
    criteria.push(result("eligible_routes", "pass", true, "Ao menos uma rota declarada é tecnicamente elegível.", mandate.eligibleRoutes));
  } else {
    criteria.push(result("eligible_routes", "condition", true, "A rota compatível ainda possui pendências remediáveis.", mandate.eligibleRoutes));
  }

  if (!sourceUsable(mandate.currencies)) {
    criteria.push(result("currencies", "not_evaluated", true, "Moedas do programa ausentes, vencidas ou sem fonte utilizável.", mandate.currencies));
  } else {
    criteria.push(result("currencies", mandate.currencies.value.includes(input.metrics.currency) ? "pass" : "fail", true, mandate.currencies.value.includes(input.metrics.currency) ? "Moeda aceita pelo programa." : "Moeda fora da política confirmada.", mandate.currencies));
  }
  criteria.push(evaluateRange("ticket", mandate.ticket, input.metrics.requestedAmount));
  criteria.push(evaluateRange("weighted_average_term_days", mandate.weightedAverageTermDays, input.metrics.weightedAverageTermDays));
  const historyMetric = input.metrics.historyMonths;
  if (!sourceUsable(mandate.minimumHistoryMonths)) {
    criteria.push(result("minimum_history_months", "not_evaluated", true, "Histórico mínimo ausente, vencido ou sem fonte utilizável.", mandate.minimumHistoryMonths));
  } else if (mandate.minimumHistoryMonths.value.mode === "no_restriction") {
    criteria.push(result("minimum_history_months", "pass", true, "O programa confirmou não aplicar histórico mínimo.", mandate.minimumHistoryMonths));
  } else if (mandate.minimumHistoryMonths.value.mode === "case_by_case") {
    criteria.push(result("minimum_history_months", "condition", true, mandate.minimumHistoryMonths.value.note, mandate.minimumHistoryMonths));
  } else if (!metricUsable(historyMetric)) {
    criteria.push(result("minimum_history_months", "not_evaluated", true, "Histórico do caso ausente ou apenas estimado.", mandate.minimumHistoryMonths, historyMetric));
  } else {
    criteria.push(result("minimum_history_months", decimal(historyMetric.value, "minimum_history_months").gte(mandate.minimumHistoryMonths.value.value) ? "pass" : "fail", true, "Histórico comparado ao mínimo confirmado.", mandate.minimumHistoryMonths, historyMetric));
  }
  criteria.push(evaluateMaximum("maximum_past_due_over_30_ratio", mandate.maximumPastDueOver30Ratio, input.metrics.pastDueOver30Ratio));
  criteria.push(evaluateMaximum("maximum_past_due_over_90_ratio", mandate.maximumPastDueOver90Ratio, input.metrics.pastDueOver90Ratio));
  criteria.push(evaluateMaximum("maximum_dilution_ratio", mandate.maximumDilutionRatio, input.metrics.dilutionRatio));
  criteria.push(evaluateMaximum("maximum_adjusted_loss_ratio", mandate.maximumAdjustedLossRatio, input.metrics.adjustedLossRatio));
  criteria.push(evaluateMaximum("maximum_single_obligor_ratio", mandate.maximumSingleObligorRatio, input.metrics.singleObligorRatio));
  criteria.push(evaluateMaximum("maximum_top_ten_obligor_ratio", mandate.maximumTopTenObligorRatio, input.metrics.topTenObligorRatio));

  const classifications = input.titleClassificationsByProgram?.[mandate.programId];
  const portfolioAllocation = classifications === undefined ? null : calculateReceivablesEligibilityAllocation({
    universe: input.universe,
    datasetHash: input.phaseTwoA.universe.datasetHash,
    classifications,
  });
  const eligibleMetric: ReceivablesProviderMetric | undefined = portfolioAllocation ? {
    value: portfolioAllocation.amounts.eligible,
    provenance: {
      kind: "measured",
      datasetHash: portfolioAllocation.provenance.datasetHash,
      anchors: input.universe.receivables.filter((title) => title.status === "open").map((title) => title.source),
      universe: portfolioAllocation.provenance.universeId,
      reportingDate: input.universe.dates.reportingDate,
      inclusions: portfolioAllocation.provenance.inclusions,
      exclusions: portfolioAllocation.provenance.exclusions,
      formula: {id: "receivables_provider_title_allocation", version: portfolioAllocation.version},
      numerator: "open value classified as eligible for this provider program",
      denominator: "open receivables value",
      unit: input.universe.currency,
    },
  } : undefined;
  criteria.push(evaluateMinimum("minimum_eligible_portfolio_amount", mandate.minimumEligiblePortfolioAmount, eligibleMetric));

  const policyCriteria = criteria;
  const policyFailed = policyCriteria.some((criterion) => criterion.status === "fail");
  const policyUnknown = policyCriteria.some((criterion) => criterion.status === "not_evaluated" && criterion.hard);
  const policyConditional = policyCriteria.some((criterion) => criterion.status === "condition");
  const appetiteCurrent = sourceUsable(mandate.liveAppetite) && mandate.liveAppetite.confirmed && !mandate.liveAppetite.divergent;
  const capacityCurrent = sourceUsable(mandate.availableCapacity) && mandate.availableCapacity.confirmed && !mandate.availableCapacity.divergent;
  const appetiteOpen = appetiteCurrent && mandate.liveAppetite?.value === true;
  const capacity = capacityCurrent ? mandate.availableCapacity?.value : null;
  let allocationEnvelope: ReceivablesProviderAllocationEnvelope | null = null;
  if (portfolioAllocation && capacity && mandate.ticket?.value.mode === "threshold") {
    allocationEnvelope = calculateReceivablesProviderAllocation({
      requestedAmount: input.metrics.requestedAmount.value,
      ticketMinimum: mandate.ticket.value.value.min,
      ticketMaximum: mandate.ticket.value.value.max,
      availableCapacity: capacity,
      eligiblePortfolioAmount: portfolioAllocation.amounts.eligible,
      conditionalPortfolioAmount: portfolioAllocation.amounts.conditional,
    });
  }
  const allocationDependsOnConditional = Boolean(
    allocationEnvelope
    && !allocationEnvelope.minimumTicketMet
    && allocationEnvelope.minimumTicketMetIncludingConditional,
  );
  const liveConfirmed = appetiteOpen && capacityCurrent && Boolean(allocationEnvelope?.minimumTicketMet);
  const status: ReceivablesProviderFitStatus = policyFailed
    ? "ineligible"
    : policyUnknown
      ? "not_evaluated"
      : policyConditional || allocationDependsOnConditional
        ? "conditionally_eligible"
        : liveConfirmed
          ? "live_appetite_confirmed"
          : "policy_fit_confirmed";
  const blockers = [
    ...policyCriteria.filter((criterion) => criterion.status === "fail").map((criterion) => `criterion:${criterion.criterionId}:failed`),
    ...policyCriteria.filter((criterion) => criterion.status === "not_evaluated" && criterion.hard).map((criterion) => `criterion:${criterion.criterionId}:not_evaluated`),
    ...(!appetiteCurrent ? ["live_appetite_not_current_and_confirmed"] : mandate.liveAppetite?.value === false ? ["provider_not_accepting_new_transactions"] : []),
    ...(!capacityCurrent ? ["available_capacity_not_current_and_confirmed"] : []),
    ...(allocationEnvelope && !allocationEnvelope.minimumTicketMet ? ["confirmed_allocation_below_minimum_ticket"] : []),
  ];
  const conditions = [
    ...policyCriteria.filter((criterion) => criterion.status === "condition").map((criterion) => `criterion:${criterion.criterionId}:condition`),
    ...(allocationEnvelope && !allocationEnvelope.wholeRequestCovered ? ["provider_covers_part_of_request_only"] : []),
    ...(allocationDependsOnConditional ? ["minimum_ticket_depends_on_conditional_titles"] : []),
  ];
  return {
    mandateId: mandate.mandateId,
    providerId: mandate.providerId,
    providerLegalName: mandate.providerLegalName,
    providerKind: mandate.providerKind,
    programId: mandate.programId,
    programName: mandate.programName,
    mandateVersion: mandate.version,
    status,
    compatibleRouteIds,
    routeStatuses,
    criterionResults: criteria,
    portfolioAllocation,
    allocationEnvelope,
    marketConfirmation: {
      liveAppetite: mandate.liveAppetite ? {
        current: mandate.liveAppetite.current,
        confirmed: mandate.liveAppetite.confirmed,
        sourceId: mandate.liveAppetite.accepted.sourceId,
      } : null,
      availableCapacity: mandate.availableCapacity ? {
        current: mandate.availableCapacity.current,
        confirmed: mandate.availableCapacity.confirmed,
        sourceId: mandate.availableCapacity.accepted.sourceId,
      } : null,
    },
    blockers,
    conditions,
  };
}

export function analyzeReceivablesPhaseTwoB(input: ReceivablesPhaseTwoBInput): ReceivablesPhaseTwoBReport {
  if (input.phaseTwoA.universe.id !== input.universe.id) throw new RangeError("Phase 2B universe does not match Phase 2A");
  if (input.metrics.requestedAmount.provenance.kind !== "measured") {
    throw new RangeError("Phase 2B requested amount must be measured");
  }
  if (input.phaseTwoA.universe.datasetHash !== input.metrics.requestedAmount.provenance.datasetHash) {
    throw new RangeError("Phase 2B metric dataset does not match Phase 2A");
  }
  if (input.phaseTwoA.universe.reportingDate !== input.universe.dates.reportingDate) throw new RangeError("Phase 2B reporting date does not match Phase 2A");
  const ids = new Set<string>();
  const programIds = new Set<string>();
  for (const mandate of input.mandates) {
    if (ids.has(mandate.mandateId)) throw new RangeError(`duplicate receivables mandate: ${mandate.mandateId}`);
    ids.add(mandate.mandateId);
    if (programIds.has(mandate.programId)) throw new RangeError(`duplicate active receivables program: ${mandate.programId}`);
    programIds.add(mandate.programId);
    if (mandate.asOf !== input.asOf) throw new RangeError(`mandate ${mandate.mandateId} was not resolved at the report as-of date`);
  }
  const providers = input.mandates.map((mandate) => evaluateProvider(input, mandate));
  const counts = (status: ReceivablesProviderFitStatus) => providers.filter((provider) => provider.status === status).length;
  const live = counts("live_appetite_confirmed");
  const policy = counts("policy_fit_confirmed");
  const blockers = providers.flatMap((provider) => provider.blockers.map((blocker) => `program:${provider.programId}:${blocker}`));
  const warnings = providers.flatMap((provider) => provider.conditions.map((condition) => `program:${provider.programId}:${condition}`));
  return {
    version: receivablesPhaseTwoBReportVersion,
    analysisLayer: "deterministic_provider_mandate_fit",
    asOf: input.asOf,
    universe: input.phaseTwoA.universe,
    providers,
    summary: {
      screened: providers.length,
      liveAppetiteConfirmed: live,
      policyFitConfirmed: policy,
      conditional: counts("conditionally_eligible"),
      notEvaluated: counts("not_evaluated"),
      ineligible: counts("ineligible"),
    },
    quality: {status: live > 0 ? "complete_for_internal_shortlist" : "incomplete", blockers, warnings},
    boundaries: {
      buyerMandateMatched: live + policy > 0,
      internalShortlistAllowed: live > 0,
      companyFacingRecommendationAllowed: false,
      externalDirectionAllowed: false,
      qualifiedIntroductionAllowed: false,
      creditApprovalExpressed: false,
    },
  };
}

packages/receivables-analysis/src/method.content:
import {createHash} from "node:crypto";

import {z} from "zod";

import {eligibilityPolicySchema, receivablesStructureSchema} from "./schema";
import {
  receivablesCashSupplementSchema,
  receivablesMethodEvidenceReferenceSchema,
  receivablesMethodEvidenceSectionSchema,
  receivablesPoolInputSupplementSchema,
  receivablesPoolInputSupplementVersion,
  receivablesTitleSupplementSchema,
  type ReceivablesPoolInputSupplement,
} from "./method-assembly";

export const receivablesSupplementDraftVersion = "2026.09.07-v1" as const;
export const receivablesSupplementPatchVersion = "2026.09.07-v1" as const;

const sha256Schema = z.string().regex(/^[a-f0-9]{64}$/);
const cedentSchema = receivablesPoolInputSupplementSchema.shape.cedent;
const accountingSchema = receivablesPoolInputSupplementSchema.shape.accounting;
const findingResolutionSchema = receivablesPoolInputSupplementSchema.shape.findingResolutions.element;

const supplementFieldPaths = [
  "/policy/maxDaysPastDue", "/policy/maxRemainingTermDays", "/policy/minSeasoningDays",
  "/policy/requireAssignable", "/policy/requireEvidenceVerified", "/policy/registrationRule",
  "/policy/excludeDisputed", "/policy/excludeRelatedParties", "/policy/excludeEncumbered",
  "/policy/allowedDebtorSectors", "/policy/maxSingleDebtorShare", "/policy/maxDebtorGroupShare",
  "/policy/minimumEligibleShare", "/policy/minimumEvidenceCoverage", "/policy/minimumRegistrationCoverage",
  "/policy/maximumDelinquency30Share", "/policy/maximumDilutionShare", "/policy/maximumRepurchaseShare",
  "/policy/minimumRecoveryRate", "/policy/maximumAccountingMismatchShare", "/policy/maximumCashMismatchShare",
  "/policy/minimumMappedCashShare", "/policy/minimumLinkedAccountCashShare",
  "/structure/requestedFacility", "/structure/advanceRate", "/structure/requiredOvercollateralization",
  "/structure/requiredSubordinationRate", "/structure/actualSeniorAmount", "/structure/actualMezzanineAmount",
  "/structure/actualSubordinatedAmount", "/structure/reserveRate",
  "/structure/waterfall/availableCash", "/structure/waterfall/servicingFeeDue",
  "/structure/waterfall/seniorInterestDue", "/structure/waterfall/seniorPrincipalDue",
  "/structure/waterfall/reserveOpening", "/structure/waterfall/mezzanineDue",
] as const;
export const receivablesSupplementFieldPathSchema = z.enum(supplementFieldPaths);
export type ReceivablesSupplementFieldPath = z.infer<typeof receivablesSupplementFieldPathSchema>;

const policyFieldSchemas = eligibilityPolicySchema.shape as Record<string, z.ZodType>;
const structureFieldSchemas = receivablesStructureSchema.shape as Record<string, z.ZodType>;
const waterfallFieldSchemas = receivablesStructureSchema.shape.waterfall.shape as Record<string, z.ZodType>;

function fieldValueSchema(path: ReceivablesSupplementFieldPath): z.ZodType {
  const parts = path.split("/").filter(Boolean);
  const schema = parts[0] === "policy"
    ? policyFieldSchemas[parts[1]!]
    : parts[1] === "waterfall"
    ? waterfallFieldSchemas[parts[2]!]
    : structureFieldSchemas[parts[1]!];
  if (!schema) throw new Error(`receivables_supplement_field_schema_missing:${path}`);
  return schema;
}

function stableJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(stableJson).join(",")}]`;
  if (value !== null && typeof value === "object") {
    return `{${Object.entries(value as Record<string, unknown>)
      .sort(([left], [right]) => left.localeCompare(right))
      .map(([key, nested]) => `${JSON.stringify(key)}:${stableJson(nested)}`)
      .join(",")}}`;
  }
  return JSON.stringify(value);
}

function fingerprint(value: unknown): string {
  return createHash("sha256").update(stableJson(value)).digest("hex");
}

function sectionPatch<T extends z.ZodType>(schema: T) {
  return z.object({
    value: schema,
    supersedesFingerprint: sha256Schema.optional(),
  }).strict();
}

const fieldPatchSchema = z.object({
  path: receivablesSupplementFieldPathSchema,
  value: z.unknown(),
  supersedesFingerprint: sha256Schema.optional(),
}).strict().superRefine((field, context) => {
  const parsed = fieldValueSchema(field.path).safeParse(field.value);
  if (!parsed.success) context.addIssue({code: "custom", path: ["value"], message: `invalid value for ${field.path}`});
});

const evidencePatchSchema = z.object({
  cedentAndServicing: receivablesMethodEvidenceSectionSchema.optional(),
  titleLegalControls: receivablesMethodEvidenceSectionSchema.optional(),
  performanceHistory: receivablesMethodEvidenceSectionSchema.optional(),
  cashReconciliation: receivablesMethodEvidenceSectionSchema.optional(),
  accountingReconciliation: receivablesMethodEvidenceSectionSchema.optional(),
  eligibilityPolicy: receivablesMethodEvidenceSectionSchema.optional(),
  facilityAndWaterfall: receivablesMethodEvidenceSectionSchema.optional(),
}).strict();

export const receivablesSupplementPatchSchema = z.object({
  schemaVersion: z.literal(receivablesSupplementPatchVersion),
  patchId: z.string().min(1).max(160),
  sourceDatasetHash: sha256Schema,
  suppliedBy: z.object({
    actorType: z.enum(["document_worker", "user", "system"]),
    actorId: z.string().min(1),
    suppliedAt: z.string().datetime({offset: true}),
    evidence: z.array(receivablesMethodEvidenceReferenceSchema).min(1),
  }).strict(),
  sections: z.object({
    cedent: sectionPatch(cedentSchema).optional(),
    titles: sectionPatch(z.array(receivablesTitleSupplementSchema).min(1)).optional(),
    cashReceipts: sectionPatch(z.array(receivablesCashSupplementSchema)).optional(),
    accounting: sectionPatch(accountingSchema).optional(),
    policy: sectionPatch(eligibilityPolicySchema).optional(),
    structure: sectionPatch(receivablesStructureSchema).optional(),
    findingResolutions: sectionPatch(z.array(findingResolutionSchema)).optional(),
  }).strict(),
  fields: z.array(fieldPatchSchema).max(supplementFieldPaths.length).default([]),
  evidence: evidencePatchSchema,
}).strict().superRefine((patch, context) => {
  const has = (key: keyof typeof patch.evidence) => patch.evidence[key] !== undefined;
  const requireEvidence = (condition: boolean, keys: (keyof typeof patch.evidence)[], path: string) => {
    if (condition && keys.some((key) => !has(key))) {
      context.addIssue({code: "custom", path: ["evidence", path], message: `section ${path} requires its governed evidence`});
    }
  };
  requireEvidence(Boolean(patch.sections.cedent), ["cedentAndServicing"], "cedentAndServicing");
  requireEvidence(Boolean(patch.sections.titles), ["titleLegalControls", "performanceHistory"], "titleLegalControls");
  requireEvidence(Boolean(patch.sections.cashReceipts), ["cashReconciliation"], "cashReconciliation");
  requireEvidence(Boolean(patch.sections.accounting), ["accountingReconciliation"], "accountingReconciliation");
  requireEvidence(Boolean(patch.sections.policy), ["eligibilityPolicy"], "eligibilityPolicy");
  requireEvidence(Boolean(patch.sections.structure), ["facilityAndWaterfall"], "facilityAndWaterfall");
  requireEvidence(patch.fields.some((field) => field.path.startsWith("/policy/")), ["eligibilityPolicy"], "eligibilityPolicy");
  requireEvidence(patch.fields.some((field) => field.path.startsWith("/structure/")), ["facilityAndWaterfall"], "facilityAndWaterfall");
  if (new Set(patch.fields.map((field) => field.path)).size !== patch.fields.length) {
    context.addIssue({code: "custom", path: ["fields"], message: "one value per field path is allowed in a patch"});
  }
  if (Object.keys(patch.sections).length === 0 && patch.fields.length === 0) {
    context.addIssue({code: "custom", path: ["sections"], message: "a patch must contribute at least one section"});
  }
});
export type ReceivablesSupplementPatch = z.infer<typeof receivablesSupplementPatchSchema>;

const sectionNames = ["cedent", "titles", "cashReceipts", "accounting", "policy", "structure", "findingResolutions"] as const;
type SectionName = typeof sectionNames[number];

const storedSectionSchema = z.object({
  value: z.unknown(),
  fingerprint: sha256Schema,
  patchIds: z.array(z.string().min(1)).min(1),
  sources: z.array(receivablesMethodEvidenceReferenceSchema).min(1),
}).strict();

export const receivablesSupplementDraftSchema = z.object({
  schemaVersion: z.literal(receivablesSupplementDraftVersion),
  sourceDatasetHash: sha256Schema,
  revision: z.number().int().nonnegative(),
  appliedPatchIds: z.array(z.string().min(1)),
  sections: z.object({
    cedent: storedSectionSchema.optional(),
    titles: storedSectionSchema.optional(),
    cashReceipts: storedSectionSchema.optional(),
    accounting: storedSectionSchema.optional(),
    policy: storedSectionSchema.optional(),
    structure: storedSectionSchema.optional(),
    findingResolutions: storedSectionSchema.optional(),
  }).strict(),
  fields: z.partialRecord(receivablesSupplementFieldPathSchema, storedSectionSchema).default({}),
  evidence: evidencePatchSchema,
  conflicts: z.array(z.object({
    id: sha256Schema,
    section: z.union([z.enum(sectionNames), receivablesSupplementFieldPathSchema]),
    status: z.enum(["open", "resolved"]),
    existingFingerprint: sha256Schema,
    incomingFingerprint: sha256Schema,
    incomingPatchId: z.string().min(1),
    resolvedByPatchId: z.string().min(1).nullable(),
  }).strict()),
}).strict();
export type ReceivablesSupplementDraft = z.infer<typeof receivablesSupplementDraftSchema>;

export function newReceivablesSupplementDraft(sourceDatasetHash: string): ReceivablesSupplementDraft {
  return receivablesSupplementDraftSchema.parse({
    schemaVersion: receivablesSupplementDraftVersion,
    sourceDatasetHash,
    revision: 0,
    appliedPatchIds: [],
    sections: {},
    fields: {},
    evidence: {},
    conflicts: [],
  });
}

function mergeEvidence(
  current: ReceivablesSupplementDraft["evidence"],
  incoming: ReceivablesSupplementPatch["evidence"],
): ReceivablesSupplementDraft["evidence"] {
  const merged: Record<string, unknown> = {...current};
  for (const [key, references] of Object.entries(incoming)) {
    const existing = (current as Record<string, unknown>)[key];
    const combined = [...(Array.isArray(existing) ? existing : []), ...(references ?? [])];
    merged[key] = [...new Map(combined.map((reference) => [stableJson(reference), reference])).values()]
      .sort((left, right) => stableJson(left).localeCompare(stableJson(right)));
  }
  return evidencePatchSchema.parse(merged);
}

/**
 * Applies sparse document or conversation facts without last-write-wins. A changed value becomes
 * an open conflict unless the patch names the exact fingerprint it supersedes. This lets a later
 * chat turn correct a premise while preserving who changed what and why.
 */
export function applyReceivablesSupplementPatch(input: {
  draft: unknown;
  patch: unknown;
}): ReceivablesSupplementDraft {
  const draft = receivablesSupplementDraftSchema.parse(input.draft);
  const patch = receivablesSupplementPatchSchema.parse(input.patch);
  if (patch.sourceDatasetHash !== draft.sourceDatasetHash) throw new Error("receivables_supplement_patch_dataset_mismatch");
  if (draft.appliedPatchIds.includes(patch.patchId)) return draft;

  const next = structuredClone(draft);
  next.revision += 1;
  next.appliedPatchIds.push(patch.patchId);
  next.appliedPatchIds.sort();
  next.evidence = mergeEvidence(next.evidence, patch.evidence);

  for (const section of sectionNames) {
    const incoming = patch.sections[section];
    if (!incoming) continue;
    if ((section === "policy" || section === "structure")
      && Object.keys(next.fields).some((path) => path.startsWith(`/${section}/`))) {
      throw new Error(`receivables_supplement_${section}_has_incremental_fields`);
    }
    const incomingFingerprint = fingerprint(incoming.value);
    const existing = next.sections[section];
    if (!existing) {
      next.sections[section] = {
        value: incoming.value,
        fingerprint: incomingFingerprint,
        patchIds: [patch.patchId],
        sources: patch.suppliedBy.evidence,
      };
      continue;
    }
    if (existing.fingerprint === incomingFingerprint) {
      existing.patchIds = [...new Set([...existing.patchIds, patch.patchId])].sort();
      existing.sources = [...new Map([...existing.sources, ...patch.suppliedBy.evidence]
        .map((reference) => [stableJson(reference), reference])).values()]
        .sort((left, right) => stableJson(left).localeCompare(stableJson(right)));
      continue;
    }
    if (incoming.supersedesFingerprint === existing.fingerprint) {
      next.sections[section] = {
        value: incoming.value,
        fingerprint: incomingFingerprint,
        patchIds: [patch.patchId],
        sources: patch.suppliedBy.evidence,
      };
      next.conflicts = next.conflicts.map((conflict) => conflict.section === section && conflict.status === "open"
        ? {...conflict, status: "resolved" as const, resolvedByPatchId: patch.patchId}
        : conflict);
      continue;
    }
    const conflictId = fingerprint({section, existing: existing.fingerprint, incoming: incomingFingerprint, patchId: patch.patchId});
    if (!next.conflicts.some((conflict) => conflict.id === conflictId)) {
      next.conflicts.push({
        id: conflictId,
        section,
        status: "open",
        existingFingerprint: existing.fingerprint,
        incomingFingerprint,
        incomingPatchId: patch.patchId,
        resolvedByPatchId: null,
      });
    }
  }
  for (const incoming of patch.fields) {
    const section = incoming.path.startsWith("/policy/") ? "policy" : "structure";
    if (next.sections[section]) throw new Error(`receivables_supplement_${section}_already_complete`);
    const incomingFingerprint = fingerprint(incoming.value);
    const existing = next.fields[incoming.path];
    if (!existing) {
      next.fields[incoming.path] = {
        value: incoming.value,
        fingerprint: incomingFingerprint,
        patchIds: [patch.patchId],
        sources: patch.suppliedBy.evidence,
      };
      continue;
    }
    if (existing.fingerprint === incomingFingerprint) {
      existing.patchIds = [...new Set([...existing.patchIds, patch.patchId])].sort();
      existing.sources = [...new Map([...existing.sources, ...patch.suppliedBy.evidence]
        .map((reference) => [stableJson(reference), reference])).values()]
        .sort((left, right) => stableJson(left).localeCompare(stableJson(right)));
      continue;
    }
    if (incoming.supersedesFingerprint === existing.fingerprint) {
      next.fields[incoming.path] = {
        value: incoming.value,
        fingerprint: incomingFingerprint,
        patchIds: [patch.patchId],
        sources: patch.suppliedBy.evidence,
      };
      next.conflicts = next.conflicts.map((conflict) => conflict.section === incoming.path && conflict.status === "open"
        ? {...conflict, status: "resolved" as const, resolvedByPatchId: patch.patchId}
        : conflict);
      continue;
    }
    const conflictId = fingerprint({section: incoming.path, existing: existing.fingerprint, incoming: incomingFingerprint, patchId: patch.patchId});
    if (!next.conflicts.some((conflict) => conflict.id === conflictId)) {
      next.conflicts.push({
        id: conflictId,
        section: incoming.path,
        status: "open",
        existingFingerprint: existing.fingerprint,
        incomingFingerprint,
        incomingPatchId: patch.patchId,
        resolvedByPatchId: null,
      });
    }
  }
  next.conflicts.sort((left, right) => left.id.localeCompare(right.id));
  return receivablesSupplementDraftSchema.parse(next);
}

export type ReceivablesSupplementDraftStatus = {
  state: "complete" | "incomplete" | "conflicted";
  missingSections: readonly string[];
  openConflictIds: readonly string[];
  supplement: ReceivablesPoolInputSupplement | null;
};

function incrementalGroup(draft: ReceivablesSupplementDraft, group: "policy" | "structure"): Record<string, unknown> {
  const value: Record<string, unknown> = {};
  for (const [path, field] of Object.entries(draft.fields)) {
    if (!path.startsWith(`/${group}/`) || !field) continue;
    const parts = path.split("/").filter(Boolean).slice(1);
    if (group === "structure" && parts[0] === "waterfall") {
      const waterfall = value.waterfall && typeof value.waterfall === "object" && !Array.isArray(value.waterfall)
        ? value.waterfall as Record<string, unknown>
        : {};
      waterfall[parts[1]!] = field.value;
      value.waterfall = waterfall;
    } else {
      value[parts[0]!] = field.value;
    }
  }
  return value;
}

function missingPaths(prefix: string, result: z.ZodSafeParseError<unknown>): string[] {
  return [...new Set(result.error.issues.map((issue) => `${prefix}.${issue.path.join(".") || "required"}`))].sort();
}

export function compileReceivablesSupplementDraft(input: unknown): ReceivablesSupplementDraftStatus {
  const draft = receivablesSupplementDraftSchema.parse(input);
  const openConflictIds = draft.conflicts.filter((conflict) => conflict.status === "open").map((conflict) => conflict.id).sort();
  const requiredSections: SectionName[] = ["cedent", "titles", "cashReceipts", "accounting"];
  const missingSections: string[] = requiredSections.filter((section) => !draft.sections[section]);
  const policy = eligibilityPolicySchema.safeParse(draft.sections.policy?.value ?? incrementalGroup(draft, "policy"));
  const structure = receivablesStructureSchema.safeParse(draft.sections.structure?.value ?? incrementalGroup(draft, "structure"));
  if (!policy.success) missingSections.push(...missingPaths("policy", policy));
  if (!structure.success) missingSections.push(...missingPaths("structure", structure));
  const requiredEvidence = [
    "cedentAndServicing", "titleLegalControls", "performanceHistory", "cashReconciliation",
    "accountingReconciliation", "eligibilityPolicy", "facilityAndWaterfall",
  ] as const;
  missingSections.push(...requiredEvidence.filter((section) => !draft.evidence[section]).map((section) => `evidence.${section}`));
  const uniqueMissingSections = [...new Set(missingSections)].sort();
  if (openConflictIds.length > 0) return {state: "conflicted", missingSections: uniqueMissingSections, openConflictIds, supplement: null};
  if (uniqueMissingSections.length > 0) return {state: "incomplete", missingSections: uniqueMissingSections, openConflictIds, supplement: null};

  const supplement = receivablesPoolInputSupplementSchema.parse({
    schemaVersion: receivablesPoolInputSupplementVersion,
    sourceDatasetHash: draft.sourceDatasetHash,
    cedent: draft.sections.cedent!.value,
    titles: draft.sections.titles!.value,
    cashReceipts: draft.sections.cashReceipts!.value,
    accounting: draft.sections.accounting!.value,
    policy: policy.success ? policy.data : null,
    structure: structure.success ? structure.data : null,
    evidence: draft.evidence,
    findingResolutions: draft.sections.findingResolutions?.value ?? [],
  });
  return {state: "complete", missingSections: [], openConflictIds: [], supplement};
}

packages/receivables-analysis/src/phase-.content:
import {
  calculateAdjustedDebtBridge,
  calculateDynamicReceivablesMetrics,
  calculateImplicitAdvanceRate,
  calculateSingleMaturityReceivablesProposal,
  calculateStaticReceivablesMetrics,
  type AdjustedDebtBridge,
  type AdjustedDebtBridgeInput,
  type DynamicReceivablesMetrics,
  type GovernedRateAssumption,
  type ImplicitAdvanceRate,
  type IsoDate,
  type ReceivablesUniverse,
  type SingleMaturityReceivablesProposal,
  type SingleMaturityReceivablesProposalInput,
  type StaticReceivablesMetrics,
} from "@offroad/financial-core";

export const receivablesPhaseOneReportVersion = "2026.08.27-v1";

type CanonicalContextFields = "reportingDate" | "universeId" | "datasetHash" | "currency";

export type ReceivablesPhaseOneProposalInput = {
  id: string;
  proposal: Omit<SingleMaturityReceivablesProposalInput, CanonicalContextFields>;
};

export type ReceivablesPhaseOneAdvanceRateInput = {
  periodStart: IsoDate;
  expectedDilution?: GovernedRateAssumption;
  expectedLossRate?: GovernedRateAssumption;
  dilutionStressMultiplier?: GovernedRateAssumption;
  lossStressMultiplier?: GovernedRateAssumption;
  operationalReserve?: GovernedRateAssumption;
  additionalReserves?: readonly GovernedRateAssumption[];
};

export type ReceivablesPhaseOneInput = {
  universe: ReceivablesUniverse;
  datasetHash: string;
  limitations?: readonly string[];
  adjustedDebt?: Omit<AdjustedDebtBridgeInput, CanonicalContextFields>;
  proposals?: readonly ReceivablesPhaseOneProposalInput[];
  advanceRate?: ReceivablesPhaseOneAdvanceRateInput;
};

export type ReceivablesPhaseOneProposalResult = {
  id: string;
  result: SingleMaturityReceivablesProposal;
};

export type ReceivablesPhaseOneReport = {
  version: typeof receivablesPhaseOneReportVersion;
  analysisLayer: "deterministic_math_and_provenance";
  universe: {
    id: string;
    datasetHash: string;
    currency: string;
    reportingDate: IsoDate;
    latestOriginationDate: IsoDate;
    dataStartDate: IsoDate;
    dataEndDate: IsoDate;
  };
  staticMetrics: StaticReceivablesMetrics;
  dynamicMetrics: DynamicReceivablesMetrics;
  adjustedDebt: AdjustedDebtBridge | null;
  proposals: readonly ReceivablesPhaseOneProposalResult[];
  implicitAdvanceRate: ImplicitAdvanceRate | null;
  quality: {
    status: "complete_for_phase_one" | "incomplete";
    blockers: readonly string[];
    warnings: readonly string[];
    limitations: readonly string[];
  };
  boundaries: {
    externalDirectionAllowed: false;
    buyerRecommendationAllowed: false;
    qualifiedIntroductionAllowed: false;
    creditApprovalExpressed: false;
  };
};

function unique(values: readonly string[]): string[] {
  return [...new Set(values.filter((value) => value.length > 0))].sort();
}

export function analyzeReceivablesPhaseOne(input: ReceivablesPhaseOneInput): ReceivablesPhaseOneReport {
  const {universe, datasetHash} = input;
  const staticMetrics = calculateStaticReceivablesMetrics(universe, {datasetHash});
  const dynamicMetrics = calculateDynamicReceivablesMetrics(universe, {datasetHash});
  const adjustedDebt = input.adjustedDebt === undefined
    ? null
    : calculateAdjustedDebtBridge({
      ...input.adjustedDebt,
      reportingDate: universe.dates.reportingDate,
      universeId: universe.id,
      datasetHash,
      currency: universe.currency,
    });

  const proposalIds = new Set<string>();
  const proposals = (input.proposals ?? []).map(({id, proposal}) => {
    if (proposalIds.has(id)) throw new RangeError(`duplicate proposal id: ${id}`);
    proposalIds.add(id);
    return {
      id,
      result: calculateSingleMaturityReceivablesProposal({
        ...proposal,
        reportingDate: universe.dates.reportingDate,
        universeId: universe.id,
        datasetHash,
        currency: universe.currency,
      }),
    };
  });

  const advanceInput = input.advanceRate;
  const implicitAdvanceRate = advanceInput === undefined
    ? null
    : calculateImplicitAdvanceRate({
      reportingDate: universe.dates.reportingDate,
      periodStart: advanceInput.periodStart,
      universeId: universe.id,
      ...(advanceInput.expectedDilution === undefined ? {} : {expectedDilution: advanceInput.expectedDilution}),
      ...(advanceInput.expectedLossRate === undefined ? {} : {expectedLossRate: advanceInput.expectedLossRate}),
      ...(advanceInput.dilutionStressMultiplier === undefined ? {} : {dilutionStressMultiplier: advanceInput.dilutionStressMultiplier}),
      ...(advanceInput.lossStressMultiplier === undefined ? {} : {lossStressMultiplier: advanceInput.lossStressMultiplier}),
      ...(advanceInput.operationalReserve === undefined ? {} : {operationalReserve: advanceInput.operationalReserve}),
      ...(advanceInput.additionalReserves === undefined ? {} : {additionalReserves: advanceInput.additionalReserves}),
    });

  const blockers: string[] = [];
  for (const [event, coverage] of Object.entries(universe.eventCoverage)) {
    if (coverage.status !== "complete") blockers.push(`coverage:${event}:${coverage.status}`);
  }
  if (dynamicMetrics.rollRates.status !== "measured") blockers.push("metric:roll_rates:not_evaluable");
  if (dynamicMetrics.vintages.status !== "measured") blockers.push("metric:vintages:not_evaluable");
  const requiredDynamicMetrics = [
    dynamicMetrics.dilution.shareOfOrigination,
    dynamicMetrics.repurchaseAndLoss.repurchaseShareOfAssigned,
    dynamicMetrics.repurchaseAndLoss.finalWrittenOffShare,
    dynamicMetrics.repurchaseAndLoss.adjustedLossShare,
    dynamicMetrics.punctualSettlement.punctualByCount,
    dynamicMetrics.punctualSettlement.punctualByValue,
    dynamicMetrics.extensions.extendedTitleShare,
    dynamicMetrics.extensions.extendedFaceShare,
    dynamicMetrics.extensions.weightedExtensionDays,
  ];
  for (const metric of requiredDynamicMetrics) {
    if (metric.status !== "measured") blockers.push(`metric:${metric.id}:not_evaluable`);
  }
  if (adjustedDebt === null) blockers.push("adjusted_debt_bridge_not_provided");
  if (proposals.length === 0) blockers.push("financing_proposal_not_provided");
  for (const proposal of proposals) {
    if (proposal.result.cet.status !== "calculated_complete") blockers.push(`proposal:${proposal.id}:complete_cet_not_available`);
  }
  if (implicitAdvanceRate === null) blockers.push("advance_rate_scenario_not_provided");
  else if (implicitAdvanceRate.status !== "calculated") blockers.push("advance_rate_not_evaluable");

  const warnings = unique([
    ...staticMetrics.quality.warnings,
    ...dynamicMetrics.quality.warnings,
    ...(adjustedDebt?.quality.warnings ?? []),
    ...proposals.flatMap((proposal) => proposal.result.cet.quality.warnings.map((warning) => `proposal:${proposal.id}:${warning}`)),
    ...(implicitAdvanceRate?.quality.warnings ?? []),
  ]);
  const coverageLimitations = Object.entries(universe.eventCoverage).flatMap(([event, coverage]) => [
    ...(coverage.status === "complete" ? [] : [`${event}_coverage_${coverage.status}`]),
    ...coverage.limitations.map((limitation) => `${event}:${limitation}`),
  ]);
  const limitations = unique([...(input.limitations ?? []), ...coverageLimitations]);

  return {
    version: receivablesPhaseOneReportVersion,
    analysisLayer: "deterministic_math_and_provenance",
    universe: {
      id: universe.id,
      datasetHash,
      currency: universe.currency,
      reportingDate: universe.dates.reportingDate,
      latestOriginationDate: universe.dates.latestOriginationDate,
      dataStartDate: universe.dates.dataStartDate,
      dataEndDate: universe.dates.dataEndDate,
    },
    staticMetrics,
    dynamicMetrics,
    adjustedDebt,
    proposals,
    implicitAdvanceRate,
    quality: {
      status: blockers.length === 0 ? "complete_for_phase_one" : "incomplete",
      blockers: unique(blockers),
      warnings,
      limitations,
    },
    boundaries: {
      externalDirectionAllowed: false,
      buyerRecommendationAllowed: false,
      qualifiedIntroductionAllowed: false,
      creditApprovalExpressed: false,
    },
  };
}

packages/receivables-analysis/src/underw.content:
import {createHash} from "node:crypto";

import {z} from "zod";

import {analyzeReceivables} from "./analyze";
import {buildReceivablesHistoryCoverage, receivablesHistoryCoverageSchema, receivablesEconomicConventionsSchema, receivablesEconomicConventions} from "./history-coverage";
import {receivablesCaseSchema} from "./schema";

export const receivablesPoolUnderwritingVersion = "2026.09.06-v1" as const;
// Version the additive output projection separately from the unchanged economic method.
const underwritingProjectionVersion = "receivables-underwriting-coverage.v1" as const;

const currencySchema = z.enum(["BRL", "USD"]);

export const receivablesPoolUnderwritingInputSchema = z.object({
  currency: currencySchema,
  case: receivablesCaseSchema,
}).strict();
export type ReceivablesPoolUnderwritingInput = z.input<typeof receivablesPoolUnderwritingInputSchema>;

const sha256Schema = z.string().regex(/^[a-f0-9]{64}$/);
const metricMoneySchema = z.string().regex(/^-?\d+(?:\.\d+)?$/);
const eligibilityReasonSchema = z.enum([
  "zero_balance", "defaulted", "past_due", "remaining_term", "seasoning",
  "not_assignable", "evidence_unverified", "anchor_unverified", "registration_missing",
  "registration_conflict", "encumbered", "disputed", "related_party", "sector_outside_policy",
]);

/** Exact result contract consumed by the internal dispatcher and artifact gates. */
export const receivablesPoolUnderwritingSchema = z.object({
  schema_version: z.literal("method.underwrite-receivables-pool.v1"),
  state: z.enum(["ready_for_structuring", "needs_remediation", "not_viable"]),
  case_id: z.string().min(1),
  reference_date: z.iso.date(),
  currency: currencySchema,
  portfolio_summary: z.object({
    receivableCount: z.number().int().nonnegative(),
    debtorCount: z.number().int().nonnegative(),
    debtorGroupCount: z.number().int().nonnegative(),
    totalOutstanding: metricMoneySchema,
    preliminaryEligibleBalance: metricMoneySchema,
    concentrationAdjustedEligibleBalance: metricMoneySchema,
    eligibleShare: metricMoneySchema,
    weightedAverageRemainingDays: metricMoneySchema,
    topDebtorShare: metricMoneySchema,
    topFiveDebtorShare: metricMoneySchema,
    topGroupShare: metricMoneySchema,
    debtorHerfindahl: metricMoneySchema,
  }).strict(),
  eligibility: z.array(z.object({
    receivableId: z.string().min(1), debtorId: z.string().min(1), debtorGroupId: z.string().min(1),
    balance: metricMoneySchema, daysPastDue: z.number().int().nonnegative(),
    seasoningDays: z.number().int().nonnegative(), remainingTermDays: z.number().int().nonnegative(),
    eligible: z.boolean(), reasons: z.array(eligibilityReasonSchema),
  }).strict()),
  aging: z.object({
    current: metricMoneySchema, days_1_30: metricMoneySchema, days_31_60: metricMoneySchema,
    days_61_90: metricMoneySchema, days_91_plus: metricMoneySchema,
  }).strict(),
  performance: z.object({
    delinquency1Share: metricMoneySchema, delinquency30Share: metricMoneySchema,
    delinquency90Share: metricMoneySchema, grossDefaultRate: metricMoneySchema,
    netLossRate: metricMoneySchema, recoveryRate: metricMoneySchema, dilutionRate: metricMoneySchema,
    repurchaseRate: metricMoneySchema, substitutionRate: metricMoneySchema,
  }).strict(),
  // Legacy results omit these fields; absence never asserts complete history.
  history_coverage: receivablesHistoryCoverageSchema.optional(),
  economic_conventions: receivablesEconomicConventionsSchema.optional(),
  evidence_coverage: z.object({
    verifiedBalanceShare: metricMoneySchema, anchoredBalanceShare: metricMoneySchema,
    registrationCoverageShare: metricMoneySchema, assignableBalanceShare: metricMoneySchema,
    freeBalanceShare: metricMoneySchema,
  }).strict(),
  reconciliation: z.object({
    tapeToAccounting: reconciliationLineSchema(),
    tapeCollectionsToAccounting: z.object({
      tape: metricMoneySchema, reported: metricMoneySchema, difference: metricMoneySchema,
      differenceShare: metricMoneySchema, status: z.enum(["tied", "outside_tolerance"]),
    }).strict(),
    collectionsToCash: z.object({
      reported: metricMoneySchema, cash: metricMoneySchema, difference: metricMoneySchema,
      differenceShare: metricMoneySchema, status: z.enum(["tied", "outside_tolerance"]),
    }).strict(),
    cashControls: z.object({
      mappedShare: metricMoneySchema, linkedAccountShare: metricMoneySchema,
      duplicateReceiptIds: z.array(z.string()), unanchoredReceiptIds: z.array(z.string()),
      unknownMappingReceiptIds: z.array(z.string()),
    }).strict(),
  }).strict(),
  borrowing_base: z.object({
    requestedFacility: metricMoneySchema, maximumByAdvanceRate: metricMoneySchema,
    maximumByOvercollateralization: metricMoneySchema, supportedFacility: metricMoneySchema,
    overcollateralizationAtRequest: metricMoneySchema, requiredOvercollateralization: metricMoneySchema,
    actualSubordinationRate: metricMoneySchema, requiredSubordinationRate: metricMoneySchema,
    reserveTarget: metricMoneySchema,
  }).strict(),
  waterfall: z.array(z.object({
    priority: z.number().int().positive(), item: z.string().min(1), due: metricMoneySchema,
    paid: metricMoneySchema, shortfall: metricMoneySchema,
  }).strict()),
  triggers: z.array(z.object({
    id: z.string().min(1), actual: metricMoneySchema, threshold: metricMoneySchema,
    comparison: z.enum(["maximum", "minimum"]), status: z.enum(["within_limit", "breached"]),
    consequence: z.enum(["block", "remediate"]),
  }).strict()),
  gaps: z.array(z.object({
    code: z.string().min(1), severity: z.enum(["blocking", "material", "attention"]),
    scope: z.enum(["portfolio", "cedent", "obligor", "servicing", "structure"]),
    message: z.object({pt: z.string(), en: z.string()}).strict(), evidenceIds: z.array(z.string()),
  }).strict()),
  decision_boundary: z.object({
    status: z.enum(["ready_for_structuring", "needs_remediation", "not_viable"]),
    blockingCodes: z.array(z.string()), remediationCodes: z.array(z.string()),
    refusalCodes: z.array(z.string()), externalDirectionAllowed: z.literal(false),
  }).strict(),
  trace: z.object({
    projection_version: z.literal(underwritingProjectionVersion).optional(),
    method_version: z.literal(receivablesPoolUnderwritingVersion),
    engine_version: z.literal("2026.08.24-v1"), input_fingerprint: sha256Schema,
    output_fingerprint: sha256Schema, policy: receivablesCaseSchema.shape.policy,
    source_rows: z.array(z.object({
      receivable_id: z.string().min(1), document_id: z.string().min(1), anchor: z.string().min(1),
    }).strict()),
    cash_rows: z.array(z.object({
      receipt_id: z.string().min(1), document_id: z.string().min(1), anchor: z.string().min(1),
    }).strict()),
  }).strict(),
}).strict();
export type ReceivablesPoolUnderwriting = z.infer<typeof receivablesPoolUnderwritingSchema>;

function reconciliationLineSchema() {
  return z.object({
    tape: metricMoneySchema, accounting: metricMoneySchema, difference: metricMoneySchema,
    differenceShare: metricMoneySchema, status: z.enum(["tied", "outside_tolerance"]),
  }).strict();
}

/**
 * Produces the governed method result for a receivables pool. The model never calculates an
 * eligibility amount, concentration cap, borrowing base, trigger or waterfall. It supplies no
 * missing policy either: every threshold is part of the validated input and is echoed in trace.
 */
export function underwriteReceivablesPool(raw: ReceivablesPoolUnderwritingInput): ReceivablesPoolUnderwriting {
  const input = receivablesPoolUnderwritingInputSchema.parse(raw);
  const analysis = analyzeReceivables(input.case);
  const sourceRows = input.case.portfolio
    .map((row) => ({receivable_id: row.id, document_id: row.sourceDocumentId, anchor: row.sourceAnchor}))
    .sort((left, right) => left.receivable_id.localeCompare(right.receivable_id));
  const cashRows = input.case.cashReceipts
    .map((row) => ({receipt_id: row.id, document_id: row.sourceDocumentId, anchor: row.sourceAnchor}))
    .sort((left, right) => left.receipt_id.localeCompare(right.receipt_id));
  const canonicalInput = {
    currency: input.currency,
    case: {
      ...input.case,
      portfolio: [...input.case.portfolio].sort((left, right) => left.id.localeCompare(right.id)),
      cashReceipts: [...input.case.cashReceipts].sort((left, right) => left.id.localeCompare(right.id)),
    },
  };
  const resultWithoutTrace = {
    schema_version: "method.underwrite-receivables-pool.v1" as const,
    state: analysis.decision.status,
    case_id: analysis.caseId,
    reference_date: input.case.referenceDate,
    currency: input.currency,
    portfolio_summary: analysis.metrics.portfolio,
    eligibility: [...analysis.analyzedReceivables].sort((left, right) => left.receivableId.localeCompare(right.receivableId)),
    aging: analysis.metrics.aging,
    performance: analysis.metrics.performance,
    history_coverage: buildReceivablesHistoryCoverage(analysis.dynamicMetrics),
    economic_conventions: receivablesEconomicConventions,
    evidence_coverage: analysis.metrics.evidence,
    reconciliation: analysis.reconciliation,
    borrowing_base: {
      requestedFacility: analysis.structure.requestedFacility,
      maximumByAdvanceRate: analysis.structure.maximumByAdvanceRate,
      maximumByOvercollateralization: analysis.structure.maximumByOvercollateralization,
      supportedFacility: analysis.structure.supportedFacility,
      overcollateralizationAtRequest: analysis.structure.overcollateralizationAtRequest,
      requiredOvercollateralization: analysis.structure.requiredOvercollateralization,
      actualSubordinationRate: analysis.structure.actualSubordinationRate,
      requiredSubordinationRate: analysis.structure.requiredSubordinationRate,
      reserveTarget: analysis.structure.reserveTarget,
    },
    waterfall: [...analysis.structure.waterfall].sort((left, right) => left.priority - right.priority),
    triggers: [...analysis.triggers].sort((left, right) => left.id.localeCompare(right.id)),
    gaps: [...analysis.gaps].sort((left, right) => left.code.localeCompare(right.code)),
    decision_boundary: analysis.decision,
  };
  const inputFingerprint = hash(canonicalInput);
  const outputFingerprint = hash({
    ...resultWithoutTrace,
    projection_version: underwritingProjectionVersion,
    method_version: receivablesPoolUnderwritingVersion,
    engine_version: analysis.version,
    input_fingerprint: inputFingerprint,
    policy: input.case.policy,
    source_rows: sourceRows,
    cash_rows: cashRows,
  });
  return receivablesPoolUnderwritingSchema.parse({
    ...resultWithoutTrace,
    trace: {
      projection_version: underwritingProjectionVersion,
      method_version: receivablesPoolUnderwritingVersion,
      engine_version: analysis.version,
      input_fingerprint: inputFingerprint,
      output_fingerprint: outputFingerprint,
      policy: input.case.policy,
      source_rows: sourceRows,
      cash_rows: cashRows,
    },
  });
}

function hash(value: unknown): string {
  return createHash("sha256").update(stableJson(value)).digest("hex");
}

function stableJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(stableJson).join(",")}]`;
  if (value !== null && typeof value === "object") {
    const record = value as Record<string, unknown>;
    return `{${Object.keys(record).sort().map((key) => `${JSON.stringify(key)}:${stableJson(record[key])}`).join(",")}}`;
  }
  return JSON.stringify(value);
}

packages/receivables-analysis/src/contra.content:
import type {AssertionProvenance} from "@offroad/financial-core";

import type {ReceivablesEligibilityFact} from "./phase-two";

export const receivablesContractFactResolutionVersion = "2026.08.28-v1";

export type ReceivablesFactScope = {
  kind: "portfolio" | "title" | "obligor" | "contract" | "company" | "operational_process";
  id?: string;
};

export type ReceivablesFactCoverage = {
  status: "complete" | "partial";
  coveredCount?: number;
  totalCount?: number;
};

export type ReceivablesFactObservation = {
  id: string;
  factId: string;
  state: "true" | "false";
  scope: ReceivablesFactScope;
  coverage: ReceivablesFactCoverage;
  observedAt: string;
  validUntil?: string;
  sourceId: string;
  sourceLabel: string;
  sourceOwner: string;
  explanation: string;
  provenance: AssertionProvenance;
};

export type ReceivablesFactResolutionDefinitionInput = {
  id: string;
  safeState: "true" | "false";
  safeCoverage: "complete";
  adverseHandling: "complete_only" | "any_confirmed_observation";
  unresolvedRequest: string;
};

export type ReceivablesFactObservationDisposition = {
  observationId: string;
  factId: string;
  decisionUseAllowed: boolean;
  reason: "accepted" | "estimated" | "stale" | "partial_safe_evidence" | "partial_adverse_evidence";
};

export type ReceivablesFactConflict = {
  factId: string;
  observationIds: readonly string[];
  reason: "current_material_evidence_disagrees";
};

export type ReceivablesFactResolutionReport = {
  version: typeof receivablesContractFactResolutionVersion;
  asOf: string;
  facts: readonly ReceivablesEligibilityFact[];
  dispositions: readonly ReceivablesFactObservationDisposition[];
  conflicts: readonly ReceivablesFactConflict[];
  unresolvedRequirements: readonly {factId: string; request: string}[];
  quality: {
    status: "complete_for_route_facts" | "incomplete";
    blockers: readonly string[];
  };
};

function dateTime(value: string, endOfDay = false): number {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) throw new RangeError(`invalid fact observation date: ${value}`);
  const parsed = Date.parse(`${value}T${endOfDay ? "23:59:59.999" : "00:00:00.000"}Z`);
  if (!Number.isFinite(parsed) || new Date(parsed).toISOString().slice(0, 10) !== value) {
    throw new RangeError(`invalid fact observation date: ${value}`);
  }
  return parsed;
}

function assertNonEmpty(value: string, label: string, observationId: string): void {
  if (value.trim().length === 0) throw new RangeError(`${label} is required for fact observation: ${observationId}`);
}

function assertCoverage(observation: ReceivablesFactObservation): void {
  const {coveredCount, totalCount, status} = observation.coverage;
  if ((coveredCount === undefined) !== (totalCount === undefined)) {
    throw new RangeError(`fact observation coverage counts must be supplied together: ${observation.id}`);
  }
  if (coveredCount === undefined || totalCount === undefined) return;
  if (!Number.isInteger(coveredCount) || !Number.isInteger(totalCount) || coveredCount < 0 || totalCount <= 0 || coveredCount > totalCount) {
    throw new RangeError(`invalid fact observation coverage: ${observation.id}`);
  }
  if (status === "complete" && coveredCount !== totalCount) {
    throw new RangeError(`complete fact observation must cover the full universe: ${observation.id}`);
  }
  if (status === "partial" && coveredCount >= totalCount) {
    throw new RangeError(`partial fact observation cannot cover the full universe: ${observation.id}`);
  }
}

function newest(observations: readonly ReceivablesFactObservation[]): ReceivablesFactObservation | undefined {
  return [...observations].sort((left, right) =>
    dateTime(right.observedAt) - dateTime(left.observedAt) || left.id.localeCompare(right.id))[0];
}

/**
 * Resolves evidence observations into the coarse facts consumed by route eligibility.
 * No missing observation and no favourable sample can become a route-level assertion.
 */
export function resolveReceivablesContractFacts(input: {
  asOf: string;
  definitions: readonly ReceivablesFactResolutionDefinitionInput[];
  observations: readonly ReceivablesFactObservation[];
}): ReceivablesFactResolutionReport {
  const asOfTime = dateTime(input.asOf);
  const definitions = new Map<string, ReceivablesFactResolutionDefinitionInput>();
  for (const definition of input.definitions) {
    if (definitions.has(definition.id)) throw new RangeError(`duplicate receivables fact definition: ${definition.id}`);
    assertNonEmpty(definition.id, "fact definition id", definition.id);
    assertNonEmpty(definition.unresolvedRequest, "unresolved request", definition.id);
    definitions.set(definition.id, definition);
  }

  const observationIds = new Set<string>();
  for (const observation of input.observations) {
    assertNonEmpty(observation.id, "observation id", observation.id);
    if (observationIds.has(observation.id)) throw new RangeError(`duplicate receivables fact observation: ${observation.id}`);
    observationIds.add(observation.id);
    if (!definitions.has(observation.factId)) throw new RangeError(`unknown receivables fact observation: ${observation.factId}`);
    assertNonEmpty(observation.sourceId, "source id", observation.id);
    assertNonEmpty(observation.sourceLabel, "source label", observation.id);
    assertNonEmpty(observation.sourceOwner, "source owner", observation.id);
    assertNonEmpty(observation.explanation, "explanation", observation.id);
    if (observation.scope.kind !== "portfolio" && !observation.scope.id?.trim()) {
      throw new RangeError(`scoped fact observation requires a scope id: ${observation.id}`);
    }
    assertCoverage(observation);
    const observedAt = dateTime(observation.observedAt);
    if (observedAt > asOfTime) throw new RangeError(`future fact observation: ${observation.id}`);
    if (observation.validUntil && dateTime(observation.validUntil, true) < observedAt) {
      throw new RangeError(`fact observation expires before it is observed: ${observation.id}`);
    }
  }

  const dispositions: ReceivablesFactObservationDisposition[] = [];
  const conflicts: ReceivablesFactConflict[] = [];
  const facts: ReceivablesEligibilityFact[] = [];
  const unresolvedRequirements: {factId: string; request: string}[] = [];

  for (const definition of [...definitions.values()].sort((left, right) => left.id.localeCompare(right.id))) {
    const candidates = input.observations.filter((observation) => observation.factId === definition.id);
    const decisive: ReceivablesFactObservation[] = [];
    for (const observation of candidates) {
      const stale = observation.validUntil !== undefined && dateTime(observation.validUntil, true) < asOfTime;
      const adverse = observation.state !== definition.safeState;
      let reason: ReceivablesFactObservationDisposition["reason"] = "accepted";
      if (observation.provenance.kind === "estimated") reason = "estimated";
      else if (stale) reason = "stale";
      else if (observation.coverage.status === "partial" && !adverse) reason = "partial_safe_evidence";
      else if (observation.coverage.status === "partial" && definition.adverseHandling === "complete_only") reason = "partial_adverse_evidence";
      if (reason === "accepted") decisive.push(observation);
      dispositions.push({observationId: observation.id, factId: definition.id, decisionUseAllowed: reason === "accepted", reason});
    }

    const safe = decisive.filter((observation) => observation.state === definition.safeState);
    const adverse = decisive.filter((observation) => observation.state !== definition.safeState);
    if (safe.length > 0 && adverse.length > 0) {
      const ids = [...safe, ...adverse].map((observation) => observation.id).sort();
      conflicts.push({factId: definition.id, observationIds: ids, reason: "current_material_evidence_disagrees"});
      facts.push({id: definition.id, state: "unknown", explanation: "Evidências materiais vigentes divergem e precisam ser reconciliadas."});
      unresolvedRequirements.push({factId: definition.id, request: definition.unresolvedRequest});
      continue;
    }

    const accepted = newest(safe.length > 0 ? safe : adverse);
    if (!accepted) {
      facts.push({id: definition.id, state: "unknown", explanation: "O fato ainda não foi comprovado para o universo relevante."});
      unresolvedRequirements.push({factId: definition.id, request: definition.unresolvedRequest});
      continue;
    }
    facts.push({id: definition.id, state: accepted.state, explanation: accepted.explanation, provenance: accepted.provenance});
  }

  const blockers = [
    ...conflicts.map((conflict) => `fact:${conflict.factId}:conflicting_evidence`),
    ...unresolvedRequirements.map((requirement) => `fact:${requirement.factId}:not_evaluated`),
  ].sort();
  return {
    version: receivablesContractFactResolutionVersion,
    asOf: input.asOf,
    facts,
    dispositions: dispositions.sort((left, right) => left.observationId.localeCompare(right.observationId)),
    conflicts,
    unresolvedRequirements,
    quality: {status: blockers.length === 0 ? "complete_for_route_facts" : "incomplete", blockers},
  };
}

packages/receivables-analysis/src/suppor.content:
import type {SourceAnchor} from "@offroad/financial-core";

export type ReceivablesSupportPeriodEntry = {
  id: string;
  detectorId: string;
  sourceId: string;
  sourceLabel: string;
  sourceHash: string;
  anchor: SourceAnchor;
  dateKind: "stock_as_of" | "flow_interval" | "event_timestamp" | "event_date";
  requiresSourceReview?: true | undefined;
  scopeAmbiguous?: true | undefined;
  amountStatus?: "provided" | "missing" | "invalid" | undefined;
  rawDate: string | null;
  startDate: string | null;
  endDate: string | null;
  qualification: "included" | "subsequent" | "missing" | "invalid" | "overlaps_cutoff";
};

export type ReceivablesSupportPeriodAssessment = {
  schemaVersion: "receivables-support-periods.v1";
  reportingDate: string;
  dateComparisonPolicy: "source_local_calendar_date";
  entries: readonly ReceivablesSupportPeriodEntry[];
};

export function supportCalendarDate(raw: string): string | null {
  const value = /^\d{2}\/\d{2}\/\d{4}$/.test(raw)
    ? `${raw.slice(6)}-${raw.slice(3, 5)}-${raw.slice(0, 2)}` : raw;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const date = new Date(`${value}T00:00:00Z`);
  return Number.isFinite(date.valueOf()) && date.toISOString().slice(0, 10) === value ? value : null;
}

/** Dates are source dates, never upload dates. Timestamps retain their explicit local offset date. */
export function qualifySupportPeriod(
  raw: string | null | undefined,
  kind: ReceivablesSupportPeriodEntry["dateKind"],
  cutoff: string,
): Pick<ReceivablesSupportPeriodEntry, "rawDate" | "startDate" | "endDate" | "qualification"> {
  if (!supportCalendarDate(cutoff) || cutoff.includes("/")) throw new RangeError("support reporting cutoff must be a real ISO calendar date");
  const rawDate = raw?.trim() || null;
  if (!rawDate) return {rawDate, startDate: null, endDate: null, qualification: "missing"};
  let startDate: string | null = null;
  let endDate: string | null = null;
  if (kind === "flow_interval" && /^\d{2}\/\d{4}$/.test(rawDate)) {
    startDate = supportCalendarDate(`${rawDate.slice(3)}-${rawDate.slice(0, 2)}-01`);
    if (startDate) {
      const date = new Date(`${startDate}T00:00:00Z`);
      date.setUTCMonth(date.getUTCMonth() + 1, 0);
      endDate = date.toISOString().slice(0, 10);
    }
  } else if (kind === "event_timestamp") {
    if (/^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|[+-](?:(?:0\d|1[0-3]):[0-5]\d|14:00))$/.test(rawDate)) {
      startDate = supportCalendarDate(rawDate.slice(0, 10));
      endDate = startDate;
    }
  } else if (kind !== "flow_interval") {
    startDate = supportCalendarDate(rawDate);
    endDate = startDate;
  }
  const qualification = !startDate || !endDate ? "invalid"
    : startDate > cutoff ? "subsequent"
      : endDate > cutoff ? "overlaps_cutoff" : "included";
  return {rawDate, startDate, endDate, qualification};
}

export function supportPeriodBlocks(entry: ReceivablesSupportPeriodEntry): boolean {
  return entry.requiresSourceReview === true || entry.scopeAmbiguous === true
    || (entry.qualification !== "subsequent" && (entry.amountStatus === "missing" || entry.amountStatus === "invalid"))
    || (entry.qualification !== "included" && entry.qualification !== "subsequent");
}

packages/receivables-analysis/src/balanc.content:
import {z} from "zod";
import type {ReceivablesEvidenceDocument, ReceivablesEvidenceTableRow} from "./raw-detection";

const anchorSchema = z.object({
  id: z.string().min(1).max(1024), text: z.string().max(512), truncated: z.literal(true).optional(),
  bbox: z.tuple([z.number().finite(), z.number().finite(), z.number().finite(), z.number().finite()]).nullable().optional(),
});
const roleSchema = z.enum(["closing_balance", "opening_balance", "debit", "credit", "outstanding_balance"]);
const contextKindSchema = z.enum(["period", "as_of", "issued_at", "entity", "perimeter", "unit"]);

/** These are source observations, never accepted facts or authority to calculate. */
export const balanceSourceProposalSchema = z.object({
  id: z.string().min(1), sourceId: z.string().min(1), sourceLabel: z.string().min(1),
  sourceHash: z.string().regex(/^[a-f0-9]{64}$/), documentVersion: z.number().int().positive().nullable(),
  containerId: z.string().min(1), page: z.number().int().positive().optional(), sheet: z.string().optional(),
  reviewState: z.literal("proposed"), calculationUse: z.literal("not_permitted"),
  columns: z.array(z.object({role: roleSchema, header: anchorSchema})).min(1).max(16),
  context: z.array(z.object({kind: contextKindSchema, anchor: anchorSchema})).max(32),
  rows: z.array(z.object({id: z.string().min(1), cells: z.array(anchorSchema).max(16)})).max(12),
  issues: z.array(z.enum(["review_required", "source_version_missing", "entity_not_identified", "perimeter_not_identified", "unit_not_identified", "economic_date_not_identified", "multiple_economic_date_references", "multiple_balance_columns", "column_geometry_unavailable", "source_context_unanchored", "source_rows_truncated", "source_context_truncated", "source_cells_truncated", "source_text_truncated"])),
});
export type BalanceSourceProposal = z.infer<typeof balanceSourceProposalSchema>;
export const balanceSourceAssessmentSchema = z.object({
  schemaVersion: z.literal("balance-source-proposals.v1"),
  reportingDate: z.iso.date(),
  proposals: z.array(balanceSourceProposalSchema).max(16),
  issues: z.array(z.literal("assessment_limit_reached")).max(1),
});
export type BalanceSourceAssessment = z.infer<typeof balanceSourceAssessmentSchema>;

const fold = (text: string) => text.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/\s+/g, " ").trim();
const roles = new Map<string, z.infer<typeof roleSchema>>([
  ["saldo atual", "closing_balance"], ["saldo final", "closing_balance"], ["closing balance", "closing_balance"],
  ["saldo anterior", "opening_balance"], ["opening balance", "opening_balance"],
  ["debito", "debit"], ["debitos", "debit"], ["debit", "debit"],
  ["credito", "credit"], ["creditos", "credit"], ["credit", "credit"],
  ["saldo devedor", "outstanding_balance"], ["outstanding balance", "outstanding_balance"],
]);
type SourceText = {id?: string | undefined; text: string; bbox?: readonly [number, number, number, number] | null | undefined};
const anchor = (cell: SourceText & {id: string}): z.infer<typeof anchorSchema> => ({
  id: cell.id, text: cell.text.slice(0, 512), ...(cell.text.length > 512 ? {truncated: true as const} : {}),
  ...(cell.bbox === undefined ? {} : {bbox: cell.bbox === null ? null : [...cell.bbox] as [number, number, number, number]}),
});

function contextKinds(text: string): z.infer<typeof contextKindSchema>[] {
  const value = fold(text);
  return [
    ...(/\bperiodo\b|\bperiod\b/.test(value) ? ["period" as const] : []),
    ...(/\bdata[- ]?base\b|\bbase\s*:?\s*\d|\bas of\b/.test(value) ? ["as_of" as const] : []),
    ...(/\bemissao\b|\bemitido\b|\bissued\b/.test(value) ? ["issued_at" as const] : []),
    ...(/\bcnpj\b|\btax id\b/.test(value) ? ["entity" as const] : []),
    ...(/\bconsolidado\b|\bindividual\b|\bcontroladora\b|\bconsolidated\b|\bstandalone\b/.test(value) ? ["perimeter" as const] : []),
    ...(/\br\$|\breais\b|\bbrl\b|\busd\b|\beur\b|\bmilhares\b|\bthousands\b/.test(value) ? ["unit" as const] : []),
  ];
}

/**
 * Preserve all relevant competing declarations in their own source container. In
 * particular, issue date is not reporting date and an entity name is not a perimeter.
 * No cell is assigned to a balance column until a separate governed review exists.
 */
export function proposeBalanceSources(documents: readonly ReceivablesEvidenceDocument[], reportingDate: string): BalanceSourceAssessment {
  const proposals: BalanceSourceProposal[] = [];
  let limitReached = false;
  let payloadBytes = 0;
  for (const document of [...documents].sort((a, b) => a.id.localeCompare(b.id))) {
    if (limitReached) break;
    const add = (containerId: string, rows: readonly ReceivablesEvidenceTableRow[], context: readonly SourceText[], location: {page?: number; sheet?: string}) => {
      for (let index = 0; index < rows.length; index += 1) {
        if (limitReached) break;
        const header = rows[index]!;
        const allColumns = header.cells.flatMap((cell) => {
          const role = roles.get(fold(cell.text));
          return role ? [{role, header: anchor(cell)}] : [];
        });
        if (!allColumns.some((column) => column.role === "closing_balance" || column.role === "outstanding_balance")) continue;
        if (proposals.length >= 16) { limitReached = true; break; }
        const columns = allColumns.slice(0, 16);
        // A repeated header starts a new candidate; never inherit it across pages/tables.
        let end = index + 1;
        while (end < rows.length && !rows[end]!.cells.some((cell) => {
          const role = roles.get(fold(cell.text));
          return role === "closing_balance" || role === "outstanding_balance";
        })) end += 1;
        // Bound the scan itself, not only its output: repeated headers cannot multiply
        // an entire sheet prefix. Omitted context is explicit and never authorizes use.
        const contextTexts: SourceText[] = context.slice(0, 64);
        let contextTruncated = context.length > 64;
        let visited = 0;
        contextScan: for (let rowIndex = 0; rowIndex <= index; rowIndex += 1) {
          for (const cell of rows[rowIndex]!.cells) {
            if (visited >= 128) { contextTruncated = true; break contextScan; }
            contextTexts.push(cell); visited += 1;
          }
        }
        const observed = contextTexts.flatMap((cell) => cell.id ? contextKinds(cell.text).map((kind) => ({kind, anchor: anchor({...cell, id: cell.id!})})) : []);
        const unique = new Map(observed.map((item) => [`${item.kind}:${item.anchor.id}`, item]));
        const allContexts = [...unique.values()].sort((a, b) => a.kind.localeCompare(b.kind) || a.anchor.id.localeCompare(b.anchor.id));
        const contexts = allContexts.slice(0, 32);
        const has = (kind: z.infer<typeof contextKindSchema>) => contexts.some((item) => item.kind === kind);
        const issues: BalanceSourceProposal["issues"] = ["review_required"];
        if (!document.layer.documentVersion) issues.push("source_version_missing");
        if (!has("entity")) issues.push("entity_not_identified");
        if (!has("perimeter")) issues.push("perimeter_not_identified");
        if (!has("unit")) issues.push("unit_not_identified");
        const economic = contexts.filter((item) => item.kind === "period" || item.kind === "as_of");
        if (economic.length === 0) issues.push("economic_date_not_identified");
        if (economic.length > 1) issues.push("multiple_economic_date_references");
        if (new Set(columns.map((item) => item.role)).size !== columns.length) issues.push("multiple_balance_columns");
        if (location.page !== undefined && columns.some((column) => !column.header.bbox)) issues.push("column_geometry_unavailable");
        if (contextTexts.some((cell) => !cell.id && contextKinds(cell.text).length > 0)) issues.push("source_context_unanchored");
        const sourceRows = rows.slice(index + 1, end);
        if (contextTruncated || allContexts.length > 32) issues.push("source_context_truncated");
        if (allColumns.length > 16 || sourceRows.slice(0, 12).some((row) => row.cells.length > 16)) issues.push("source_cells_truncated");
        if ([...columns.map((column) => column.header), ...contexts.map((item) => item.anchor)].some((item) => item.truncated) || sourceRows.slice(0, 12).some((row) => row.cells.slice(0, 16).some((cell) => cell.text.length > 512))) issues.push("source_text_truncated");
        if (sourceRows.length > 12) issues.push("source_rows_truncated");
        const proposal: BalanceSourceProposal = {
          id: `${document.id}:${containerId}:${header.id}`, sourceId: document.id, sourceLabel: document.fileName,
          sourceHash: document.fileHash, documentVersion: document.layer.documentVersion ?? null, containerId, ...location,
          reviewState: "proposed", calculationUse: "not_permitted", columns, context: contexts,
          rows: sourceRows.slice(0, 12).map((row) => ({id: row.id, cells: row.cells.slice(0, 16).map(anchor)})), issues,
        };
        const bytes = new TextEncoder().encode(JSON.stringify(proposal)).byteLength;
        if (payloadBytes + bytes > 250_000) { limitReached = true; break; }
        payloadBytes += bytes; proposals.push(proposal);
      }
    };
    for (const page of document.layer.pages ?? []) {
      for (const table of page.tables) {
        // A container without a stable anchor cannot become a proposal.
        if (!table.id || !page.n) continue;
        add(table.id, table.rows, page.blocks, {page: page.n});
      }
    }
    for (const sheet of document.layer.sheets ?? []) {
      const grouped = new Map<number, {id: string; text: string; column: string}[]>();
      for (const cell of sheet.cells) {
        const match = /^([A-Z]{1,3})([1-9]\d{0,6})$/.exec(cell.ref);
        if (!match) continue;
        const row = Number(match[2]);
        if (!Number.isSafeInteger(row)) continue;
        const entries = grouped.get(row) ?? [];
        entries.push({id: `s${sheet.name}!${cell.ref}`, text: String(cell.v ?? ""), column: match[1]!});
        grouped.set(row, entries);
      }
      const ordinal = (column: string) => [...column].reduce((n, character) => n * 26 + character.charCodeAt(0) - 64, 0);
      const rows = [...grouped].sort(([a], [b]) => a - b).map(([n, cells]) => ({id: `s${sheet.name}!row${n}`, cells: cells.sort((a, b) => ordinal(a.column) - ordinal(b.column))}));
      add(`s${sheet.name}`, rows, [], {sheet: sheet.name});
    }
  }
  return balanceSourceAssessmentSchema.parse({schemaVersion: "balance-source-proposals.v1", reportingDate, proposals, issues: limitReached ? ["assessment_limit_reached"] : []});
}

