import {fingerprintJson} from "@offroad/case-understanding";
import {z} from "zod";

import {professionalFunctionSchema} from "./professional-functions";
import {executableWorkspaceJobSchema} from "./workspace-jobs";

export const specializationDimensionSchema = z.enum([
  "core",
  "economic_situation",
  "capital_objective",
  "instrument",
  "sector",
  "analysis_domain",
  "professional_function",
  "jurisdiction",
  "market_execution",
]);
export type SpecializationDimension = z.infer<typeof specializationDimensionSchema>;

export const coverageDomainSchema = z.enum([
  "company_and_business_model",
  "sector_and_competitive_position",
  "historical_financials",
  "earnings_quality",
  "cash_conversion_and_working_capital",
  "liquidity_and_debt_schedule",
  "leverage_and_debt_service",
  "covenants",
  "collateral_and_security",
  "receivables_inventory_or_contracts",
  "business_plan_and_sources_uses",
  "downside_and_sensitivities",
  "legal_tax_and_regulatory",
  "capital_alternatives",
  "structure_and_terms",
  "market_pricing_and_precedents",
  "capital_provider_fit",
  "execution_timeline_and_contingency",
  "materials_and_cross_consistency",
]);
export type CoverageDomain = z.infer<typeof coverageDomainSchema>;

const coverageMaterialitySchema = z.enum(["blocking", "high", "medium", "low"]);
const coverageMaterialityRank: Readonly<Record<z.infer<typeof coverageMaterialitySchema>, number>> = {
  blocking: 4,
  high: 3,
  medium: 2,
  low: 1,
};

export const coverageRequirementDefinitionSchema = z.object({
  key: z.string().regex(/^[a-z0-9_.-]{3,120}$/),
  domain: coverageDomainSchema,
  label: z.string().trim().min(3).max(240),
  questionAnswered: z.string().trim().min(5).max(1_000),
  decisionImpacts: z.array(z.string().trim().min(3).max(500)).min(1).max(20),
  acceptableEvidence: z.array(z.string().trim().min(2).max(240)).max(20).default([]),
  materiality: coverageMaterialitySchema,
});
export type CoverageRequirementDefinition = z.infer<typeof coverageRequirementDefinitionSchema>;

export const depthPackManifestSchema = z.object({
  schemaVersion: z.literal("dcm-depth-pack.v1"),
  id: z.string().regex(/^[a-z0-9_.-]{3,120}$/),
  version: z.string().regex(/^\d{4}[.]\d{2}[.]\d{2}-v\d+$/),
  owner: z.string().trim().min(3).max(200),
  dimension: specializationDimensionSchema,
  activationKeys: z.array(z.string().trim().min(2).max(160)).min(1).max(50),
  supportedJobs: z.array(executableWorkspaceJobSchema).min(1),
  professionalFunctions: z.array(professionalFunctionSchema).max(28).default([]),
  requirements: z.array(coverageRequirementDefinitionSchema).min(1).max(200),
  procedureIds: z.array(z.string().regex(/^[A-Z]{1,4}-[A-Z0-9.-]{1,40}$/)).min(1).max(200),
  calculationPolicy: z.enum(["required", "conditional", "not_applicable"]),
  calculationIds: z.array(z.string().regex(/^[a-z0-9_.-]{3,120}$/)).max(100).default([]),
  calculationRationale: z.string().trim().min(5).max(500),
  structureTermKeys: z.array(z.string().regex(/^[a-z0-9_.-]{3,120}$/)).max(100).default([]),
  marketCriterionKeys: z.array(z.string().regex(/^[a-z0-9_.-]{3,120}$/)).max(100).default([]),
  disconfirmers: z.array(z.string().trim().min(5).max(500)).min(1).max(100),
  qualityGateIds: z.array(z.string().regex(/^[a-z0-9_.-]{3,120}$/)).min(1).max(100),
  goldCaseIds: z.array(z.string().regex(/^[a-z0-9_.-]{3,160}$/)).max(100).default([]),
  adversarialCaseIds: z.array(z.string().regex(/^[a-z0-9_.-]{3,160}$/)).max(100).default([]),
  generalistBenchmarkIds: z.array(z.string().regex(/^[a-z0-9_.-]{3,160}$/)).max(100).default([]),
  dependsOn: z.array(z.string().regex(/^[a-z0-9_.-]{3,120}$/)).max(30).default([]),
  incompatibleWith: z.array(z.string().regex(/^[a-z0-9_.-]{3,120}$/)).max(30).default([]),
  maturity: z.enum(["specified", "implemented", "tested", "production"]),
  reviewedBy: z.string().trim().min(3).max(200).nullable().default(null),
  reviewedAt: z.iso.datetime().nullable().default(null),
}).superRefine((pack, context) => {
  const duplicateRequirement = pack.requirements.find((requirement, index) =>
    pack.requirements.findIndex((candidate) => candidate.key === requirement.key) !== index
  );
  if (duplicateRequirement) {
    context.addIssue({code: "custom", path: ["requirements"], message: `duplicate requirement ${duplicateRequirement.key}`});
  }
  if (pack.calculationPolicy === "required" && pack.calculationIds.length === 0) {
    context.addIssue({code: "custom", path: ["calculationIds"], message: "required calculation policy needs a deterministic calculation"});
  }
  if (pack.maturity === "production") {
    if (pack.goldCaseIds.length < 2) {
      context.addIssue({code: "custom", path: ["goldCaseIds"], message: "production packs require at least two gold cases"});
    }
    if (pack.adversarialCaseIds.length < 1) {
      context.addIssue({code: "custom", path: ["adversarialCaseIds"], message: "production packs require adversarial coverage"});
    }
    if (pack.generalistBenchmarkIds.length < 1) {
      context.addIssue({code: "custom", path: ["generalistBenchmarkIds"], message: "production packs require a benchmark against the best available generalist model"});
    }
    if (!pack.reviewedBy || !pack.reviewedAt) {
      context.addIssue({code: "custom", path: ["reviewedBy"], message: "production packs require documented expert review"});
    }
  }
});
export type DepthPackManifest = z.infer<typeof depthPackManifestSchema>;

export const compiledCoverageRequirementSchema = coverageRequirementDefinitionSchema.extend({
  sourcePackIds: z.array(z.string().regex(/^[a-z0-9_.-]{3,120}$/)).min(1),
});

export const compiledSpecializationProfileSchema = z.object({
  schemaVersion: z.literal("dcm-specialization-profile.v1"),
  packIds: z.array(z.string()).min(1),
  activatedDimensions: z.array(z.object({
    dimension: specializationDimensionSchema,
    packIds: z.array(z.string()).min(1),
  })).min(1),
  requirements: z.array(compiledCoverageRequirementSchema).min(1),
  procedureIds: z.array(z.string()).min(1),
  calculationIds: z.array(z.string()),
  structureTermKeys: z.array(z.string()),
  marketCriterionKeys: z.array(z.string()),
  disconfirmers: z.array(z.string()).min(1),
  qualityGateIds: z.array(z.string()).min(1),
  minimumMaturity: z.enum(["specified", "implemented", "tested", "production"]),
  fingerprint: z.string().regex(/^[a-f0-9]{64}$/),
});
export type CompiledSpecializationProfile = z.infer<typeof compiledSpecializationProfileSchema>;

const dimensionOrder = specializationDimensionSchema.options;
const maturityOrder = ["specified", "implemented", "tested", "production"] as const;

function uniqueSorted(values: readonly string[]): string[] {
  return [...new Set(values)].sort();
}

/**
 * Composes independent depth packs. It intentionally does not create a bespoke implementation for
 * combinations such as `retail + refinance + debenture`: those cases are compiled from reusable,
 * reviewable packs and retain the lineage of every contributed rule.
 */
export function composeDepthPacks(rawPacks: readonly DepthPackManifest[]): CompiledSpecializationProfile {
  const packs = rawPacks.map((pack) => depthPackManifestSchema.parse(pack));
  if (!packs.some((pack) => pack.dimension === "core")) throw new Error("a core DCM pack is required");
  const byId = new Map(packs.map((pack) => [pack.id, pack]));
  if (byId.size !== packs.length) throw new Error("depth pack ids must be unique");
  for (const pack of packs) {
    for (const dependency of pack.dependsOn) {
      if (!byId.has(dependency)) throw new Error(`${pack.id} requires missing pack ${dependency}`);
    }
    for (const incompatible of pack.incompatibleWith) {
      if (byId.has(incompatible)) throw new Error(`${pack.id} is incompatible with ${incompatible}`);
    }
  }

  const requirementMap = new Map<string, z.infer<typeof compiledCoverageRequirementSchema>>();
  for (const pack of packs) {
    for (const requirement of pack.requirements) {
      const existing = requirementMap.get(requirement.key);
      if (!existing) {
        requirementMap.set(requirement.key, {...requirement, sourcePackIds: [pack.id]});
        continue;
      }
      if (existing.domain !== requirement.domain || existing.label !== requirement.label) {
        throw new Error(`conflicting definition for coverage requirement ${requirement.key}`);
      }
      requirementMap.set(requirement.key, {
        ...existing,
        questionAnswered: existing.questionAnswered === requirement.questionAnswered
          ? existing.questionAnswered
          : `${existing.questionAnswered} / ${requirement.questionAnswered}`,
        decisionImpacts: uniqueSorted([...existing.decisionImpacts, ...requirement.decisionImpacts]),
        acceptableEvidence: uniqueSorted([...existing.acceptableEvidence, ...requirement.acceptableEvidence]),
        materiality: coverageMaterialityRank[requirement.materiality] > coverageMaterialityRank[existing.materiality]
          ? requirement.materiality
          : existing.materiality,
        sourcePackIds: uniqueSorted([...existing.sourcePackIds, pack.id]),
      });
    }
  }

  const sortedPacks = [...packs].sort((left, right) =>
    dimensionOrder.indexOf(left.dimension) - dimensionOrder.indexOf(right.dimension)
      || left.id.localeCompare(right.id)
  );
  const payload = {
    schemaVersion: "dcm-specialization-profile.v1" as const,
    packIds: sortedPacks.map((pack) => pack.id),
    activatedDimensions: dimensionOrder.flatMap((dimension) => {
      const packIds = sortedPacks.filter((pack) => pack.dimension === dimension).map((pack) => pack.id);
      return packIds.length ? [{dimension, packIds}] : [];
    }),
    requirements: [...requirementMap.values()].sort((left, right) => left.key.localeCompare(right.key)),
    procedureIds: uniqueSorted(packs.flatMap((pack) => pack.procedureIds)),
    calculationIds: uniqueSorted(packs.flatMap((pack) => pack.calculationIds)),
    structureTermKeys: uniqueSorted(packs.flatMap((pack) => pack.structureTermKeys)),
    marketCriterionKeys: uniqueSorted(packs.flatMap((pack) => pack.marketCriterionKeys)),
    disconfirmers: uniqueSorted(packs.flatMap((pack) => pack.disconfirmers)),
    qualityGateIds: uniqueSorted(packs.flatMap((pack) => pack.qualityGateIds)),
    minimumMaturity: maturityOrder[Math.min(...packs.map((pack) => maturityOrder.indexOf(pack.maturity)))]!,
  };
  return compiledSpecializationProfileSchema.parse({...payload, fingerprint: fingerprintJson(payload)});
}

export const coverageAssessmentStatusSchema = z.enum([
  "not_examined",
  "insufficient_evidence",
  "covered",
  "conflicting",
  "not_applicable",
  "deferred",
]);
export type CoverageAssessmentStatus = z.infer<typeof coverageAssessmentStatusSchema>;

export const coverageAssessmentSchema = z.object({
  requirementKey: z.string().regex(/^[a-z0-9_.-]{3,120}$/),
  status: coverageAssessmentStatusSchema,
  evidenceRefs: z.array(z.string().trim().min(1).max(300)).max(100).default([]),
  rationale: z.string().trim().min(3).max(1_000).nullable().default(null),
  assessedAt: z.iso.datetime().nullable().default(null),
}).superRefine((assessment, context) => {
  if (assessment.status === "covered" && assessment.evidenceRefs.length === 0) {
    context.addIssue({code: "custom", path: ["evidenceRefs"], message: "covered dimensions require evidence"});
  }
  if (["insufficient_evidence", "conflicting", "not_applicable", "deferred"].includes(assessment.status)
      && !assessment.rationale) {
    context.addIssue({code: "custom", path: ["rationale"], message: "this status requires an explicit rationale"});
  }
});
export type CoverageAssessment = z.infer<typeof coverageAssessmentSchema>;

export const decisionCoverageMapSchema = z.object({
  schemaVersion: z.literal("dcm-decision-coverage-map.v1"),
  specializationFingerprint: z.string().regex(/^[a-f0-9]{64}$/),
  dimensions: z.array(compiledCoverageRequirementSchema.extend({
    status: coverageAssessmentStatusSchema,
    evidenceRefs: z.array(z.string()),
    rationale: z.string().nullable(),
    assessedAt: z.iso.datetime().nullable(),
  })).min(1),
  blockingKeys: z.array(z.string()),
  unexaminedKeys: z.array(z.string()),
  disclosedGapKeys: z.array(z.string()),
  decisionReady: z.boolean(),
  complete: z.boolean(),
});
export type DecisionCoverageMap = z.infer<typeof decisionCoverageMapSchema>;

export function buildDecisionCoverageMap(
  profile: CompiledSpecializationProfile,
  rawAssessments: readonly CoverageAssessment[],
): DecisionCoverageMap {
  const assessments = rawAssessments.map((assessment) => coverageAssessmentSchema.parse(assessment));
  const assessmentByKey = new Map(assessments.map((assessment) => [assessment.requirementKey, assessment]));
  if (assessmentByKey.size !== assessments.length) throw new Error("coverage assessments must be unique by requirement");
  for (const key of assessmentByKey.keys()) {
    if (!profile.requirements.some((requirement) => requirement.key === key)) {
      throw new Error(`assessment references unknown coverage requirement ${key}`);
    }
  }
  const dimensions = profile.requirements.map((requirement) => {
    const assessment = assessmentByKey.get(requirement.key) ?? {
      requirementKey: requirement.key,
      status: "not_examined" as const,
      evidenceRefs: [],
      rationale: null,
      assessedAt: null,
    };
    return {...requirement, ...assessment};
  });
  const unresolved = new Set(["not_examined", "insufficient_evidence", "conflicting", "deferred"]);
  const blockingKeys = dimensions
    .filter((dimension) => dimension.materiality === "blocking" && unresolved.has(dimension.status))
    .map((dimension) => dimension.key);
  const unexaminedKeys = dimensions.filter((dimension) => dimension.status === "not_examined").map((dimension) => dimension.key);
  const disclosedGapKeys = dimensions
    .filter((dimension) => ["insufficient_evidence", "conflicting", "deferred"].includes(dimension.status))
    .map((dimension) => dimension.key);
  return decisionCoverageMapSchema.parse({
    schemaVersion: "dcm-decision-coverage-map.v1",
    specializationFingerprint: profile.fingerprint,
    dimensions,
    blockingKeys,
    unexaminedKeys,
    disclosedGapKeys,
    decisionReady: blockingKeys.length === 0,
    complete: dimensions.every((dimension) => ["covered", "not_applicable"].includes(dimension.status)),
  });
}

packages/agent-contracts/src/decision-va.content:
import {z} from "zod";

export const decisionValueKindSchema = z.enum([
  "non_obvious_insight_found",
  "material_error_avoided",
  "structure_changed",
  "pitch_improved",
  "time_saved",
  "mandate_supported",
  "execution_path_improved",
  "better_capital_provider_identified",
]);
export type DecisionValueKind = z.infer<typeof decisionValueKindSchema>;

/**
 * Product value is recorded as an observation, not asserted by the model. Estimated outcomes stay
 * visibly separate from user-confirmed or externally observed outcomes.
 */
export const decisionValueObservationSchema = z.object({
  schemaVersion: z.literal("dcm-decision-value.v1"),
  kind: decisionValueKindSchema,
  description: z.string().trim().min(5).max(1_000),
  measurement: z.object({
    basis: z.enum(["user_confirmed", "externally_observed", "measured_by_system", "estimated"]),
    baseline: z.string().trim().min(1).max(500).nullable().default(null),
    result: z.string().trim().min(1).max(500),
    unit: z.string().trim().min(1).max(80).nullable().default(null),
  }),
  evidenceRefs: z.array(z.string().trim().min(1).max(300)).min(1).max(50),
  attributionConfidence: z.enum(["low", "medium", "high"]),
  recordedAt: z.iso.datetime(),
});
export type DecisionValueObservation = z.infer<typeof decisionValueObservationSchema>;

export const domainSurvivalCriterionSchema = z.enum([
  "coverage_completeness",
  "evidence_traceability",
  "deterministic_reconciliation",
  "domain_specific_depth",
  "non_obvious_insight",
  "alternative_discrimination",
  "structure_term_completeness",
  "market_match_discrimination",
  "decision_impact",
]);

export const domainSurvivalCheckSchema = z.object({
  criterion: domainSurvivalCriterionSchema,
  required: z.boolean(),
  status: z.enum(["passed", "failed", "not_applicable"]),
  evidenceRefs: z.array(z.string().trim().min(1).max(300)).max(50).default([]),
  rationale: z.string().trim().min(5).max(1_000),
}).superRefine((check, context) => {
  if (check.required && check.status === "not_applicable") {
    context.addIssue({code: "custom", path: ["status"], message: "a required survival criterion cannot be not applicable"});
  }
  if (check.status === "passed" && check.evidenceRefs.length === 0) {
    context.addIssue({code: "custom", path: ["evidenceRefs"], message: "a passed survival criterion requires evidence"});
  }
});
export type DomainSurvivalCheck = z.infer<typeof domainSurvivalCheckSchema>;

export const domainSurvivalAssessmentSchema = z.object({
  schemaVersion: z.literal("dcm-domain-survival-assessment.v1"),
  baseline: z.literal("best_available_generalist_model"),
  checks: z.array(domainSurvivalCheckSchema).min(1),
  valueObservations: z.array(decisionValueObservationSchema).max(100).default([]),
  survives: z.boolean(),
  failureReasons: z.array(z.string()).default([]),
});
export type DomainSurvivalAssessment = z.infer<typeof domainSurvivalAssessmentSchema>;

export function assessDomainSurvival(input: {
  checks: readonly DomainSurvivalCheck[];
  valueObservations?: readonly DecisionValueObservation[];
}): DomainSurvivalAssessment {
  const checks = input.checks.map((check) => domainSurvivalCheckSchema.parse(check));
  const criteria = checks.map((check) => check.criterion);
  if (new Set(criteria).size !== criteria.length) throw new Error("survival criteria must be unique");
  const requiredFailures = checks.filter((check) => check.required && check.status !== "passed");
  const observations = [...(input.valueObservations ?? [])].map((observation) => decisionValueObservationSchema.parse(observation));
  const supportedValue = observations.some((observation) =>
    observation.measurement.basis !== "estimated" && observation.attributionConfidence !== "low"
  );
  const failureReasons = [
    ...requiredFailures.map((check) => `required criterion failed: ${check.criterion}`),
    ...(supportedValue ? [] : ["no materially supported decision-value observation"]),
  ];
  return domainSurvivalAssessmentSchema.parse({
    schemaVersion: "dcm-domain-survival-assessment.v1",
    baseline: "best_available_generalist_model",
    checks,
    valueObservations: observations,
    survives: failureReasons.length === 0,
    failureReasons,
  });
}

packages/agent-contracts/src/intent-enve.content:
import {z} from "zod";

import {dcmWorkEffectSchema, type DcmWorkEffect} from "./work-system";

/**
 * Intent Envelope v1: the unit of routing decided in ADR 0021 and shaped by the architecture
 * review of 4 September 2026. It has two layers on purpose.
 *
 * The routing core is what a classifier can infer from a message with confidence and what is
 * enough to discover the initial work. The governed execution context is everything else the
 * work needs. Part of it comes from the system and the model never writes it: what the caller
 * may do, which evidence regime applies, which organization and documents exist. Part of it can
 * be inferred but has to be confirmed when it is material, because jurisdiction, as-of date
 * and currency are often exactly the ambiguity that changes an analysis.
 *
 * Nothing here is a runtime router yet. The production router stays untouched until the
 * envelope has proven composite intent, correction and abstention in shadow.
 */

export const intentFieldStateSchema = z.enum([
  "explicit",
  "inferred",
  "system",
  "reused_confirmed",
  "ambiguous",
  "unknown",
  "not_applicable",
]);
export type IntentFieldState = z.infer<typeof intentFieldStateSchema>;

/** The nine primary works the router chooses among. Compositions are built on top of them. */
export const primaryWorkSchema = z.enum([
  "find_and_organize",
  "extract_and_reconcile",
  "understand",
  "analyze",
  "model",
  "capital_strategy",
  "read_documents",
  "market",
  "capital_match",
]);
export type PrimaryWork = z.infer<typeof primaryWorkSchema>;

export const intentDepthSchema = z.enum(["point", "preliminary", "institutional"]);
export const intentOutputFormSchema = z.enum(["chat", "artifact", "file"]);
export const intentContinuitySchema = z.enum(["new", "refresh", "monitor", "comparison", "resume"]);
export const workResponsibilitySchema = z.enum([
  "producer",
  "coordinator",
  "reviewer",
  "decision_maker",
  "sponsor",
  "recipient",
  "external_authorizer",
]);
export type WorkResponsibility = z.infer<typeof workResponsibilitySchema>;

export const intentObjectKindSchema = z.enum([
  "organization",
  "user",
  "company",
  "project",
  "operation",
  "instrument",
  "document",
  "claim",
  "model",
  "asset_or_pool",
  "scenario",
  "alternative",
  "material",
  "market",
  "provider",
  "mandate",
  "process",
  "decision",
]);

/**
 * One routing turn can carry at most this many independently referable objects. The classifier,
 * semantic compiler and persisted envelope all consume this constant so no layer can silently
 * drop objects to satisfy a narrower downstream schema.
 */
export const intentObjectCardinalityLimit = 24;

export const evidenceRegimeSchema = z.enum(["unresolved", "public", "private_authorized", "hybrid", "received"]);
export type EvidenceRegime = z.infer<typeof evidenceRegimeSchema>;
export const authorityGrantSchema = z.enum(["read", "modify", "approve_internal", "share", "introduce"]);
export type AuthorityGrant = z.infer<typeof authorityGrantSchema>;
export const canonicalIntentActionSchema = z.enum([
  "find_and_organize", "extract_and_reconcile", "understand", "answer", "analyze", "model",
  "diagnose", "compare", "structure", "read_document", "prepare_meeting", "prepare_material",
  "review", "prepare_decision", "evaluate", "map_market", "identify_capital", "introduce",
  "monitor", "manage_work",
]);
export type CanonicalIntentAction = z.infer<typeof canonicalIntentActionSchema>;

export const intentDecisionTypeSchema = z.enum(["none", "capital", "credit", "material", "market", "external", "workflow", "document"]);
export type IntentDecisionType = z.infer<typeof intentDecisionTypeSchema>;
export const intentAudienceTypeSchema = z.enum(["self", "internal_senior", "company_management", "board_or_committee", "capital_provider", "market", "unspecified"]);
export type IntentAudienceType = z.infer<typeof intentAudienceTypeSchema>;
export const intentObjectSlotKeySchema = z.enum([
  "entity", "subject", "amount", "currency", "percentage", "basis_points", "ratio",
  "indexer", "tenor_months", "page_count", "count", "cadence",
]);
export type IntentObjectSlotKey = z.infer<typeof intentObjectSlotKeySchema>;

const inferable = <T extends z.ZodTypeAny>(value: T) => z.object({
  value,
  state: intentFieldStateSchema,
  /** 0 to 1. Required whenever the state is inferred or ambiguous. */
  confidence: z.number().min(0).max(1).optional(),
  /** Where the inference came from, so it stays corrigible. Never a document value. */
  basis: z.string().max(300).optional(),
}).superRefine((field, ctx) => {
  if ((field.state === "inferred" || field.state === "ambiguous") && field.confidence === undefined) {
    ctx.addIssue({code: z.ZodIssueCode.custom, message: "an inferred or ambiguous field carries a confidence"});
  }
});

/** A field only the control plane may fill. Its state is always `system`. */
const systemProvided = <T extends z.ZodTypeAny>(value: T) => z.object({value, state: z.literal("system")});

export const routingCoreSchema = z.object({
  action: inferable(z.array(z.string().min(1).max(60)).min(1).max(8)),
  object: inferable(z.array(z.object({
    kind: intentObjectKindSchema,
    reference: z.string().max(200).optional(),
  })).min(1).max(intentObjectCardinalityLimit)),
  desiredOutcome: inferable(z.string().min(1).max(300)),
  decision: inferable(z.string().max(300).nullable()),
  audience: inferable(z.array(z.string().min(1).max(80)).min(1).max(6)),
  depth: inferable(intentDepthSchema),
  continuity: inferable(intentContinuitySchema),
  workResponsibility: inferable(z.array(workResponsibilitySchema).min(1).max(4)),
});
export type RoutingCore = z.infer<typeof routingCoreSchema>;

export const governedExecutionContextSchema = z.object({
  evidenceRegime: systemProvided(evidenceRegimeSchema),
  authority: systemProvided(z.array(authorityGrantSchema)),
  organizationId: systemProvided(z.string().uuid()),
  projectId: systemProvided(z.string().uuid().nullable()),
  availableDocumentIds: systemProvided(z.array(z.string().uuid()).max(500)),
  jurisdiction: inferable(z.array(z.string().min(2).max(8)).max(4)),
  asOfDate: inferable(z.string().regex(/^\d{4}-\d{2}-\d{2}$/).nullable()),
  currency: inferable(z.string().length(3).nullable()),
  deadline: inferable(z.string().max(80).nullable()),
  sponsorInstruction: inferable(z.string().max(500).nullable()),
  constraints: inferable(z.array(z.string().max(200)).max(20)),
  language: inferable(z.enum(["pt-BR", "en-US"])),
  urgency: inferable(z.enum(["now", "today", "this_week", "ongoing"]).nullable()),
  availableInputs: inferable(z.array(z.string().max(120)).max(40)),
});
export type GovernedExecutionContext = z.infer<typeof governedExecutionContextSchema>;

export const namedCompositionKeys = [
  "find_and_organize_information",
  "extract_and_reconcile_data",
  "understand_company_sector_asset",
  "answer_a_question",
  "analyze_performance_and_credit",
  "build_or_review_model",
  "diagnose_capital_structure",
  "develop_alternatives",
  "design_indicative_structure",
  "read_contract_covenant_waterfall",
  "prepare_meeting",
  "prepare_material",
  "review_work",
  "prepare_decision",
  "evaluate_received_opportunity",
  "map_market_and_precedents",
  "identify_capital",
  "introduce",
  "monitor",
  "manage_work",
] as const;
export const namedCompositionSchema = z.enum(namedCompositionKeys);
export type NamedComposition = z.infer<typeof namedCompositionSchema>;

export type NamedCompositionPolicy = {
  atlas: `I${string}`;
  canonicalAction: CanonicalIntentAction;
  primaryWorks: readonly [PrimaryWork, ...PrimaryWork[]];
  primaryWorkVariants?: readonly [{
    when: "documents_present";
    primaryWorks: readonly [PrimaryWork, ...PrimaryWork[]];
  }];
  depth: z.infer<typeof intentDepthSchema>;
  workResponsibilities: readonly [WorkResponsibility, ...WorkResponsibility[]];
  effect: DcmWorkEffect;
  classifierGuidance: string;
};

/**
 * Single executable policy for the twenty Atlas families. Schema validation, classifier
 * canonicalization, system stamping and eval fingerprints all consume this object. Adding a
 * second composition table anywhere else is a policy fork and must fail review.
 */
export const namedCompositions = {
  find_and_organize_information: {atlas: "I01", canonicalAction: "find_and_organize", primaryWorks: ["find_and_organize"], depth: "preliminary", workResponsibilities: ["producer"], effect: "none", classifierGuidance: "collect or organize information without analysis"},
  extract_and_reconcile_data: {atlas: "I02", canonicalAction: "extract_and_reconcile", primaryWorks: ["extract_and_reconcile"], depth: "institutional", workResponsibilities: ["producer"], effect: "none", classifierGuidance: "extract, spread, reconcile or explain discrepancies in supplied data"},
  understand_company_sector_asset: {atlas: "I03", canonicalAction: "understand", primaryWorks: ["understand"], depth: "preliminary", workResponsibilities: ["producer"], effect: "none", classifierGuidance: "understand a company, sector or asset without a narrower requested outcome"},
  answer_a_question: {atlas: "I04", canonicalAction: "answer", primaryWorks: ["extract_and_reconcile"], depth: "point", workResponsibilities: ["producer"], effect: "none", classifierGuidance: "explain or trace a bounded fact, number or instrument question"},
  analyze_performance_and_credit: {atlas: "I05", canonicalAction: "analyze", primaryWorks: ["analyze", "model"], depth: "preliminary", workResponsibilities: ["producer"], effect: "none", classifierGuidance: "analyze financial performance, credit risk, covenant headroom or downside"},
  build_or_review_model: {atlas: "I06", canonicalAction: "model", primaryWorks: ["model"], depth: "institutional", workResponsibilities: ["producer"], effect: "none", classifierGuidance: "build, audit or change assumptions in a financial model"},
  diagnose_capital_structure: {atlas: "I07", canonicalAction: "diagnose", primaryWorks: ["capital_strategy", "analyze", "model"], depth: "institutional", workResponsibilities: ["producer"], effect: "none", classifierGuidance: "diagnose debt, liquidity, maturities, repricing or capital structure"},
  develop_alternatives: {atlas: "I08", canonicalAction: "compare", primaryWorks: ["capital_strategy", "analyze", "model"], depth: "preliminary", workResponsibilities: ["producer"], effect: "none", classifierGuidance: "develop or compare capital alternatives without selecting final terms"},
  design_indicative_structure: {atlas: "I09", canonicalAction: "structure", primaryWorks: ["capital_strategy", "analyze"], primaryWorkVariants: [{when: "documents_present", primaryWorks: ["extract_and_reconcile", "capital_strategy", "analyze"]}], depth: "institutional", workResponsibilities: ["producer", "coordinator"], effect: "none", classifierGuidance: "design an indicative debt or receivables structure; supplied documents must be extracted and reconciled first"},
  read_contract_covenant_waterfall: {atlas: "I10", canonicalAction: "read_document", primaryWorks: ["read_documents", "analyze"], depth: "institutional", workResponsibilities: ["producer"], effect: "none", classifierGuidance: "read or test a contract, covenant clause, formula or payment waterfall"},
  prepare_meeting: {atlas: "I11", canonicalAction: "prepare_meeting", primaryWorks: ["understand", "capital_strategy", "model"], depth: "preliminary", workResponsibilities: ["producer", "coordinator"], effect: "none", classifierGuidance: "prepare for a client or management meeting; understanding precedes strategy and modelling, including financing meetings"},
  prepare_material: {atlas: "I12", canonicalAction: "prepare_material", primaryWorks: ["capital_strategy", "analyze", "model"], depth: "institutional", workResponsibilities: ["producer", "coordinator"], effect: "none", classifierGuidance: "produce an explicitly requested deck, memo, spreadsheet or other material"},
  review_work: {atlas: "I13", canonicalAction: "review", primaryWorks: ["analyze"], depth: "institutional", workResponsibilities: ["producer", "reviewer"], effect: "none", classifierGuidance: "challenge, critique or quality-review existing work"},
  prepare_decision: {atlas: "I14", canonicalAction: "prepare_decision", primaryWorks: ["capital_strategy", "analyze", "model"], depth: "institutional", workResponsibilities: ["producer", "sponsor"], effect: "none", classifierGuidance: "prepare a recommendation or decision for a board or committee"},
  evaluate_received_opportunity: {atlas: "I15", canonicalAction: "evaluate", primaryWorks: ["analyze", "read_documents"], depth: "preliminary", workResponsibilities: ["producer", "reviewer"], effect: "none", classifierGuidance: "screen a received investment or financing opportunity"},
  map_market_and_precedents: {atlas: "I16", canonicalAction: "map_market", primaryWorks: ["market"], depth: "preliminary", workResponsibilities: ["producer"], effect: "none", classifierGuidance: "map current market terms, pricing, comparables or precedents"},
  identify_capital: {atlas: "I17", canonicalAction: "identify_capital", primaryWorks: ["capital_match", "market"], depth: "preliminary", workResponsibilities: ["producer", "coordinator"], effect: "none", classifierGuidance: "identify or shortlist suitable capital providers without contacting them"},
  introduce: {atlas: "I18", canonicalAction: "introduce", primaryWorks: ["capital_match"], depth: "institutional", workResponsibilities: ["coordinator"], effect: "external", classifierGuidance: "send, connect or introduce an opportunity to an external party"},
  monitor: {atlas: "I19", canonicalAction: "monitor", primaryWorks: ["find_and_organize", "extract_and_reconcile", "analyze"], depth: "preliminary", workResponsibilities: ["producer"], effect: "none", classifierGuidance: "monitor recurring changes and alert on a defined condition"},
  manage_work: {atlas: "I20", canonicalAction: "manage_work", primaryWorks: ["find_and_organize"], depth: "point", workResponsibilities: ["coordinator"], effect: "propose_state", classifierGuidance: "manage project status, versions, open work or comments"},
} as const satisfies Record<NamedComposition, NamedCompositionPolicy>;

export function compositionPolicy(composition: NamedComposition): NamedCompositionPolicy {
  return namedCompositions[composition];
}

export function resolveCompositionPrimaryWorks(
  composition: NamedComposition,
  context: {documentsPresent: boolean},
): readonly [PrimaryWork, ...PrimaryWork[]] {
  const policy = compositionPolicy(composition);
  const variant = context.documentsPresent ? policy.primaryWorkVariants?.find(({when}) => when === "documents_present") : undefined;
  return variant?.primaryWorks ?? policy.primaryWorks;
}

export function intentCompositionPolicyPrompt(): string {
  return namedCompositionKeys.map((composition) => {
    const policy = compositionPolicy(composition);
    const variants = policy.primaryWorkVariants?.map(({when, primaryWorks}) => `; when ${when}: ${primaryWorks.join(" -> ")}`).join("") ?? "";
    return `- ${composition}: ${policy.classifierGuidance}; works: ${policy.primaryWorks.join(" -> ")}${variants}; depth: ${policy.depth}`;
  }).join("\n");
}

const sameOrderedValues = <T extends string>(actual: readonly T[], expected: readonly T[]): boolean =>
  actual.length === expected.length && actual.every((value, index) => value === expected[index]);
const assertsRoutedMeaning = (state: IntentFieldState): boolean => state === "explicit" || state === "inferred" || state === "system" || state === "reused_confirmed";

export const intentEnvelopeSchema = z.object({
  schemaVersion: z.literal("intent-envelope.v1"),
  routingCore: routingCoreSchema,
  executionContext: governedExecutionContextSchema,
  /** One to three primary works, the first being the one the plan starts from. */
  primaryWorks: z.array(z.object({work: primaryWorkSchema, confidence: z.number().min(0).max(1)})).min(1).max(3),
  /** A named composition when one applies. Unknown strings are rejected at the boundary. */
  composition: namedCompositionSchema.nullable(),
  effect: dcmWorkEffectSchema,
  createdAt: z.string().datetime({offset: true}),
}).superRefine((envelope, ctx) => {
  if (envelope.composition === null) {
    const checks: Array<[boolean, (string | number)[], string]> = [
      [envelope.effect === "none", ["effect"], "an unnamed route can have no committed or external effect"],
      [!envelope.routingCore.action.value.includes("introduce"), ["routingCore", "action"], "an unnamed route cannot introduce externally"],
      [!envelope.routingCore.workResponsibility.value.includes("external_authorizer"), ["routingCore", "workResponsibility"], "an unnamed route cannot claim external authorization"],
    ];
    for (const [valid, path, message] of checks) if (!valid) ctx.addIssue({code: z.ZodIssueCode.custom, path, message});
    return;
  }
  const policy = compositionPolicy(envelope.composition);
  const works = envelope.primaryWorks.map(({work}) => work);
  const expectedWorks = resolveCompositionPrimaryWorks(envelope.composition, {
    documentsPresent: envelope.executionContext.availableDocumentIds.value.length > 0,
  });
  if (!sameOrderedValues(works, expectedWorks)) {
    ctx.addIssue({code: z.ZodIssueCode.custom, path: ["primaryWorks"], message: "primary works must match the canonical composition policy"});
  }
  if (!sameOrderedValues(envelope.routingCore.action.value, [policy.canonicalAction])) {
    ctx.addIssue({code: z.ZodIssueCode.custom, path: ["routingCore", "action"], message: "action must match the canonical composition policy"});
  }
  if (!assertsRoutedMeaning(envelope.routingCore.action.state)) {
    ctx.addIssue({code: z.ZodIssueCode.custom, path: ["routingCore", "action", "state"], message: "a routed action has an asserted state"});
  }
  if (!assertsRoutedMeaning(envelope.routingCore.object.state)) {
    ctx.addIssue({code: z.ZodIssueCode.custom, path: ["routingCore", "object", "state"], message: "routed objects have an asserted state"});
  }
  if (envelope.routingCore.decision.value !== null && !assertsRoutedMeaning(envelope.routingCore.decision.state)) {
    ctx.addIssue({code: z.ZodIssueCode.custom, path: ["routingCore", "decision", "state"], message: "a routed decision has an asserted state"});
  }
  if (!(envelope.routingCore.audience.value.length === 1 && envelope.routingCore.audience.value[0] === "unspecified")
    && !assertsRoutedMeaning(envelope.routingCore.audience.state)) {
    ctx.addIssue({code: z.ZodIssueCode.custom, path: ["routingCore", "audience", "state"], message: "a routed audience has an asserted state"});
  }
  if (envelope.routingCore.depth.value !== policy.depth) {
    ctx.addIssue({code: z.ZodIssueCode.custom, path: ["routingCore", "depth"], message: "depth must match the canonical composition policy"});
  }
  if (!sameOrderedValues(envelope.routingCore.workResponsibility.value, policy.workResponsibilities)) {
    ctx.addIssue({code: z.ZodIssueCode.custom, path: ["routingCore", "workResponsibility"], message: "responsibilities must match the canonical composition policy"});
  }
  if (envelope.effect !== policy.effect) {
    ctx.addIssue({code: z.ZodIssueCode.custom, path: ["effect"], message: "effect must match the canonical composition policy"});
  }
});
export type IntentEnvelope = z.infer<typeof intentEnvelopeSchema>;

/**
 * The fields the model may never fill. A classifier output that marks any of them as inferred
 * is rejected before it reaches a plan.
 */
export function systemFieldViolations(envelope: IntentEnvelope): string[] {
  const context = envelope.executionContext;
  const violations: string[] = [];
  for (const [key, field] of Object.entries({
    evidenceRegime: context.evidenceRegime,
    authority: context.authority,
    organizationId: context.organizationId,
    projectId: context.projectId,
    availableDocumentIds: context.availableDocumentIds,
  })) {
    if (field.state !== "system") violations.push(key);
  }
  return violations;
}

/**
 * Whether a field that can be inferred still needs the person before the work relies on it:
 * only when it is material to the decision and was not stated or confirmed.
 */
export function needsConfirmation(field: {state: IntentFieldState; confidence?: number}, material: boolean): boolean {
  if (!material) return false;
  if (field.state === "explicit" || field.state === "reused_confirmed" || field.state === "system") return false;
  return true;
}

packages/agent-contracts/src/intent-clas.content:
import {z} from "zod";

import {
  intentContinuitySchema,
  canonicalIntentActionSchema,
  intentAudienceTypeSchema,
  intentDecisionTypeSchema,
  intentDepthSchema,
  intentObjectCardinalityLimit,
  intentObjectKindSchema,
  intentObjectSlotKeySchema,
  compositionPolicy,
  intentCompositionPolicyPrompt,
  namedCompositionSchema,
  primaryWorkSchema,
  resolveCompositionPrimaryWorks,
  workResponsibilitySchema,
  type NamedComposition,
} from "./intent-envelope";

export const intentClassifierInputSchema = z.object({
  locale: z.enum(["pt-BR", "en-US"]),
  latestUserMessage: z.string().min(1),
  recentConversation: z.array(z.object({role: z.string().min(1), content: z.string()})).max(8),
  entryJob: z.string().nullable(),
  documentCount: z.number().int().nonnegative(),
});
export type IntentClassifierInput = z.infer<typeof intentClassifierInputSchema>;

/** Parse once before JSON serialization so runtime and evals send the same bounded shape. */
export function buildIntentClassifierInput(input: unknown): IntentClassifierInput {
  return intentClassifierInputSchema.parse(input);
}

/**
 * The exact model-written portion of an Intent Envelope. It lives beside the envelope contract
 * so the worker and the gold gate cannot silently test different prompts or schemas.
 *
 * This schema is intentionally more permissive than the persisted envelope: prompted JSON is
 * not grammar-bound. The worker clamps strings and lists and stamps authority, evidence and
 * tenant fields from the control plane before persistence.
 */
const inferredClassifierField = <T extends z.ZodTypeAny>(value: T) => z.object({
  value,
  state: z.enum(["explicit", "inferred", "ambiguous", "unknown", "not_applicable"]),
  confidence: z.number().min(0).max(1).nullish(),
  basis: z.string().max(200).nullish(),
});

const classifierObjectSlotsSchema = z.array(z.object({
  key: intentObjectSlotKeySchema,
  value: z.string().min(1).max(200),
})).max(12).superRefine((slots, ctx) => {
  const keys = new Set<string>();
  for (const [index, slot] of slots.entries()) {
    if (keys.has(slot.key)) ctx.addIssue({code: z.ZodIssueCode.custom, path: [index, "key"], message: "slot keys are unique within an object"});
    keys.add(slot.key);
  }
});

const classifierObjectInstancesSchema = z.array(z.object({
  id: z.string().regex(/^object-[1-9]\d*$/),
  ordinal: z.number().int().min(1).max(intentObjectCardinalityLimit),
  kind: intentObjectKindSchema,
  slots: classifierObjectSlotsSchema,
}).strict()).max(intentObjectCardinalityLimit).superRefine((objects, ctx) => {
  const ids = new Set<string>();
  const ordinals = new Set<number>();
  for (const [index, object] of objects.entries()) {
    if (ids.has(object.id)) ctx.addIssue({code: z.ZodIssueCode.custom, path: [index, "id"], message: "object ids are unique"});
    if (ordinals.has(object.ordinal)) ctx.addIssue({code: z.ZodIssueCode.custom, path: [index, "ordinal"], message: "object ordinals are unique"});
    if (object.id !== `object-${object.ordinal}`) {
      ctx.addIssue({code: z.ZodIssueCode.custom, path: [index, "id"], message: "object id matches its ordinal"});
    }
    ids.add(object.id);
    ordinals.add(object.ordinal);
  }
  const ordered = [...ordinals].sort((left, right) => left - right);
  if (ordered.some((ordinal, index) => ordinal !== index + 1)) {
    ctx.addIssue({code: z.ZodIssueCode.custom, message: "object ordinals are contiguous from one"});
  }
});

export const intentClassifierOutputSchema = z.object({
  routingCore: z.object({
    // Empty lists are representable at the model boundary so an honest abstention is valid JSON.
    // `canonicalizeIntentClassifierOutput` then supplies a fail-closed envelope shape; the
    // persisted contract remains strict and never accepts an empty routing core.
    action: inferredClassifierField(z.array(canonicalIntentActionSchema).max(1)),
    object: inferredClassifierField(classifierObjectInstancesSchema),
    decisionType: inferredClassifierField(intentDecisionTypeSchema),
    audienceType: inferredClassifierField(intentAudienceTypeSchema),
    depth: inferredClassifierField(intentDepthSchema),
    continuity: inferredClassifierField(intentContinuitySchema),
    workResponsibility: inferredClassifierField(z.array(workResponsibilitySchema).max(8)),
  }).strict(),
  inferableContext: z.object({
    jurisdiction: inferredClassifierField(z.array(z.string().min(1).max(40)).max(8)),
    asOfDate: inferredClassifierField(z.string().max(40).nullable()),
    currency: inferredClassifierField(z.string().max(12).nullable()),
    deadline: inferredClassifierField(z.string().max(300).nullable()),
    sponsorInstruction: inferredClassifierField(z.string().max(2_000).nullable()),
    constraints: inferredClassifierField(z.array(z.string().max(600)).max(40)),
    urgency: inferredClassifierField(z.enum(["now", "today", "this_week", "ongoing"]).nullable()),
    availableInputs: inferredClassifierField(z.array(z.string().max(400)).max(80)),
  }),
  primaryWorks: z.array(z.object({work: primaryWorkSchema, confidence: z.number().min(0).max(1)})).max(6),
  composition: namedCompositionSchema.nullable(),
  /** The one question the classifier would ask first, if it were allowed to ask. */
  firstQuestion: z.string().max(600).nullable(),
  abstain: z.boolean(),
  abstainReason: z.string().max(600).nullable(),
}).strict();
export type IntentClassifierOutput = z.infer<typeof intentClassifierOutputSchema>;

const abstentionQuestion = (locale: IntentClassifierInput["locale"]): string => locale === "pt-BR"
  ? "Qual material, documento ou assunto você quer que eu examine, e qual resultado você espera?"
  : "Which material, document or subject should I examine, and what result do you expect?";

const normalizeForPolicy = (value: string): string => value
  .normalize("NFKD")
  .replace(/[\u0300-\u036f]/g, "")
  .toLocaleLowerCase("pt-BR")
  // Expand common English negative contractions before cue polarity is evaluated. Curly
  // apostrophes survive NFKD, so both forms are intentional.
  .replace(/\b(?:don['’]t|doesn['’]t|didn['’]t|won['’]t|wouldn['’]t|shouldn['’]t|can['’]t|cannot|couldn['’]t|isn['’]t|aren['’]t|wasn['’]t|weren['’]t|haven['’]t|hasn['’]t|hadn['’]t)\b/g, " not ");

/** A deterministic override is allowed only for an affirmative cue in its own clause. */
function hasAffirmedCue(text: string, cue: RegExp): boolean {
  const flags = cue.flags.includes("g") ? cue.flags : `${cue.flags}g`;
  for (const match of text.matchAll(new RegExp(cue.source, flags))) {
    const before = text.slice(Math.max(0, (match.index ?? 0) - 100), match.index ?? 0);
    const after = text.slice((match.index ?? 0) + match[0].length, (match.index ?? 0) + match[0].length + 100);
    const clause = before.split(/[.;!?\x0a]|\b(?:mas|porem|contudo|apenas|somente|but|however|only)\b/).at(-1) ?? "";
    const rejectedAfterQuestion = /^[^.;!\x0a]{0,80}\?\s*(?:nao|not|no)\b/.test(after);
    if (!/\b(nao|not|sem|without|nunca|jamais|never|evite|evitar|avoid)\b/.test(clause) && !rejectedAfterQuestion) return true;
  }
  return false;
}

/** External side effects require a direct user command, never mere lexical co-occurrence. */
function hasExplicitExternalOutreach(text: string): boolean {
  const courtesy = /^(?:(?:ja|agora|por favor|please)\s+)*/;
  const imperative = /(?:envie|manda|mande|compartilhe|conecte|introduza|apresente|send|share|connect|introduce|faca a introducao|make the introduction)\b/;
  const modalCommand = /(?:(?:pode|podem|can you|quero que|vamos)\s+)(?:envie|enviar|manda|mande|mandar|compartilhe|compartilhar|conecte|conectar|introduza|introduzir|apresente|apresentar|send|share|connect|introduce|faca a introducao|make the introduction)\b/;
  const directCommand = new RegExp(`${courtesy.source}(?:${imperative.source}|${modalCommand.source})`);
  const rejected = /\b(?:nao|not|sem|without|nunca|jamais|never|evite|evitar|avoid|proibid[oa]|forbidden|not allowed|fora de questao|nem pensar|de jeito nenhum|absolutely not|definitely not)\b/;
  const command = text.match(directCommand);
  if (!command || rejected.test(text)) return false;
  const modalAtStart = /^(?:(?:ja|agora|por favor|please)\s+)*(?:pode|podem|can you|quero que|vamos)\s+/;
  if (text.endsWith("?") && !modalAtStart.test(text)) return false;

  // External effects use a closed grammar for the complete clause: command, bounded direct
  // object, destination preposition and provider. This prevents a leading word such as "send"
  // in a label or explanation from combining with "investors" later in the sentence.
  const remainder = text.slice(command[0].length).trim();
  const routed = remainder.match(/^(?:(?:this|that|these|those|isso|isto)|(?:a|o|as|os|esse|essa|este|esta|da|do|das|dos|the)\s+[a-z0-9_-]+)\s+(?:a|ao|aos|para|to)\s+(?:(?:os|as|the|tres|three|\d+)\s+)?(fundos?|investidores?|financiadores?|bancos?|lenders?|investors?|providers?)(.*)$/);
  if (!routed) return false;

  // Once the provider target is named, only a bounded fit/selection qualifier and terminal
  // punctuation may follow. Any answer, predicate, retraction or other prose fails closed.
  const tail = routed[2]!.trim();
  return /^(?:(?:selecionad[oa]s?|aderentes?|compativeis?|selected|best[- ]?fit)|(?:de|of)\s+(?:credito|credit)|(?:com|with)\s+(?:(?:a|the)\s+)?(?:melhor|best)\s+(?:aderencia|fit)|que\s+(?:(?:voce|you)\s+)?(?:achar|considerar|find|consider)\s+(?:mais\s+|most\s+)?(?:aderentes?|compativeis?|best[- ]?fit)|que\s+(?:tiverem|tenham|have)\s+fit)?[.!?]?$/.test(tail);
}

/** Classify one affirmative, user-authored clause. Cross-clause noun/verb joins are forbidden. */
function explicitCompositionForClause(input: IntentClassifierInput, text: string): NamedComposition | null {
  const hasPrior = input.recentConversation.length > 0;
  const material = /\b(material|deck|pitch|memo|one[- ]?pager|apresentacao|presentation|paginas?|pages?|planilha|spreadsheet)\b/.test(text);
  const meeting = /\b(reuniao|meeting|conversa|conversation)\b/.test(text);
  const materialTransition = hasPrior && /\b(gostei|selecion\w*|escolh\w*|vamos preparar|prepare the material|liked|selected|chosen)\b/.test(text);
  const specifiedMaterial = /\b(\d+|tres|three)\s*(paginas?|pages?)\b/.test(text)
    || /\b(deck|memo|one[- ]?pager|planilha|spreadsheet)\b/.test(text);
  const materialCreation = hasAffirmedCue(text, /\b(produz\w*|prepar\w*|cri\w*|monte|montar|gere|gerar|build|create|produce|prepare|draft|generate)\b/);

  const negatedMaterial = /\b(sem|nao|not|without)\s+(?:produz\w*|faz\w*|cri\w*|prepar\w*|create)?\s*(?:o\s+|um\s+)?(?:material|deck|pitch|memo|arquivo|file)\b/.test(text)
    || /\b(?:material|deck|pitch|memo|arquivo|file)\b[^.;!\x0a]{0,60}\?\s*(?:nao|not|no)\b/.test(text);
  const externalOutreach = hasExplicitExternalOutreach(text);

  if (hasAffirmedCue(text, /\b(ajust\w*|alter\w*|atualiz\w*|recalcul\w*|change|update|recalculate)\b/)
    && /\b(cenario|scenario|premissa|assumption|cdi|taxa|rate|prazo|term|spread|modelo|model)\b/.test(text)) return "build_or_review_model";
  if (hasAffirmedCue(text, /\b(de onde saiu|qual a origem|como chegou|where did|how did)\b/)
    || (hasAffirmedCue(text, /\b(por que|why)\b/) && /\b(alavancagem|leverage|numero|number|indicador|metric)\b/.test(text))) return "answer_a_question";
  if (hasAffirmedCue(text, /\b(diferenca|difference|como funciona|how does|explique|explain|o que e|what is)\b/)
    && /\b(debenture|fidc|ccb|bond|loan|instrumento|instrument)\b/.test(text)) return "answer_a_question";
  if (hasAffirmedCue(text, /\b(construa|construir|monte|montar|revise|revisar|build|review|audit)\b/)
    && /\b(modelo|model|forecast|projecao|projection)\b/.test(text)) return "build_or_review_model";
  if (/\b(covenant|headroom)\b/.test(text) && hasAffirmedCue(text, /\b(aguenta|suporta|holds?|cobertura|coverage)\b/)) return "analyze_performance_and_credit";
  if (/\b(covenant|headroom|folga)\b/.test(text) && hasAffirmedCue(text, /\b(teste|testar|analise|analisar|teste?\b|holds?)\b/)
    && !/\b(clausula|clause|formula|waterfall)\b/.test(text)) return "analyze_performance_and_credit";
  if (hasAffirmedCue(text, /\b(leia|ler|analise|analisar|teste|testar|read|analy[sz]e|test)\b/)
    && /\b(contrato|contract|clausula|clause|covenant|waterfall|escritura|indenture)\b/.test(text)) return "read_contract_covenant_waterfall";
  if (hasAffirmedCue(text, /\b(so organiza|apenas organiza|organize only|no analysis|sem analise)\b/)) return "find_and_organize_information";
  if (hasAffirmedCue(text, /\b(extraia|extrair|concilie|conciliar|reconcilie|reconciliar|extract|reconcile|spreading)\b/)) return "extract_and_reconcile_data";
  if (hasAffirmedCue(text, /\b(o que falta|onde paramos|organize o projeto|incorpore os comentarios|what is missing|where did we stop|organize the project|incorporate the comments)\b/)) return "manage_work";
  if (externalOutreach) return "introduce";
  if (hasAffirmedCue(text, /\b(quem financiaria|quais fundos|matching|capital aderente|who would finance|which funds|find capital)\b/)
    || hasAffirmedCue(text, /\bidentifi\w*\b[^.;!\x0a]{0,60}\b(investidores?|fundos?|financiadores?|investors?|funds?|lenders?|providers?)\b/)) return "identify_capital";
  if (hasAffirmedCue(text, /\b(monitor\w*|acompanh\w*|avise quando|todo trimestre|track|alert me|quarterly)\b/)) return "monitor";
  if (hasAffirmedCue(text, /\b(mapeie|mapear|levante|pesquise|map|research|como esta|how is)\b[^.;!\x0a]{0,60}\b(mercado|emissoes|comparaveis|precedentes|pricing|spread|market|issuances|comparables|precedents)\b/)
    || hasAffirmedCue(text, /\b(comparaveis|precedentes|condicoes de mercado|pricing|comparables|precedents|market conditions)\b/)) return "map_market_and_precedents";
  if (/\b(conselh\w*|board|comite\w*|committee)\b/.test(text)
    && hasAffirmedCue(text, /\b(decis\w*|discut\w*|avali\w*|alternativ\w*|recomend\w*|prepar\w*|decision)\b/)) return "prepare_decision";
  if (hasAffirmedCue(text, /\b(revise|revisar|review|critique|criticar|cetico|skeptical|controle de qualidade|quality control)\b/)) return "review_work";
  if (material && !negatedMaterial && ((specifiedMaterial && materialCreation) || materialTransition)) return "prepare_material";
  if (material && meeting) return "prepare_meeting";
  if (hasAffirmedCue(text, /\b(recebi|recebemos|received)\b/) && /\b(proposta|deal|oportunidade|opportunity|term sheet)\b/.test(text)) return "evaluate_received_opportunity";
  if (hasAffirmedCue(text, /\b(estruture|estruturar|desenhe|desenhar|structure|design)\b/)
    && /\b(operacao|operation|recebiveis|receivables|divida|debt|term sheet)\b/.test(text)) return "design_indicative_structure";
  if (hasAffirmedCue(text, /\b(compare|comparar|avalie|avaliar|explore|explorar|compare|evaluate|explore)\b[^.;!\x0a]{0,60}\b(alternativas|opcoes|caminhos|alternatives|options|paths)\b/)) return "develop_alternatives";
  if (hasAffirmedCue(text, /\b(diagnostique|diagnosticar|diagnose)\b/)
    || hasAffirmedCue(text, /\b(vencimentos|maturity|liquidez|liquidity|estrutura de capital|capital structure|refinanc|repricing)\b/)) return "diagnose_capital_structure";
  if (hasAffirmedCue(text, /\b(qualidade de credito|credit quality|risco de credito|credit risk|desempenho financeiro|financial performance)\b/)) return "analyze_performance_and_credit";
  if (hasAffirmedCue(text, /\b(entender|entenda|compreender|understand|explique|explain)\b/)) return "understand_company_sector_asset";
  if (hasAffirmedCue(text, /\b(levante|localize|ache|baixe|organize|atualize|find|locate|download|organize|update)\b/)) return "find_and_organize_information";
  return null;
}

/**
 * High-precision deterministic overrides are intentionally narrower than the model. We remove
 * quoted/reported source text, rejected rhetorical questions and negative clauses, then accept an
 * override only when every remaining actionable clause agrees. A conflicting or incomplete turn
 * stays with the semantic model instead of being guessed from isolated keywords.
 */
function explicitComposition(input: IntentClassifierInput): NamedComposition | null {
  const containsQuotedContent = /["'“”‘’]/.test(input.latestUserMessage);
  const normalized = normalizeForPolicy(input.latestUserMessage)
    .replace(/"[^"]*"|'[^']*'|“[^”]*”|‘[^’]*’/g, " ")
    .replace(/\b(?:source text|source|texto fonte|noticia|documento|contrato)\b[^.;!\x0a]{0,80}\b(?:says?|said|diz|disse|contem a frase)\b[^.;!\x0a]*/g, " ")
    .replace(/(?:^|[.;!\x0a])\s*[^?]{0,180}\?\s*(?:nao|not|no|nem pensar|de jeito nenhum|absolutely not|definitely not)\b[^.;!\x0a]*/g, " ");
  const clauses = normalized
    // Keep question marks inside a clause. `Can you send this?` remains an explicit request,
    // while `Send this? I refuse` reaches the closed external grammar as one rejected clause.
    .split(/[.;!\x0a]|\b(?:mas|porem|contudo|but|however)\b/)
    .map((clause) => clause.trim())
    .filter(Boolean);
  const affirmativeClauses = clauses
    .filter((clause) => !/\b(nao|not|sem|without|nunca|jamais|never|evite|evitar|avoid)\b/.test(clause));
  const exclusive = affirmativeClauses.filter((clause) => /^(?:apenas|somente|so|only|just)\b/.test(clause));
  const candidates = (exclusive.length > 0 ? exclusive : affirmativeClauses)
    .map((clause) => explicitCompositionForClause(input, clause))
    .filter((composition): composition is NamedComposition => composition !== null);
  const unique = [...new Set(candidates)];
  if (unique.length === 1 && unique[0] === "introduce") {
    // Quoted content may be a source instruction, a retraction or an emphasized refusal. The
    // classifier is not an authorization boundary, so any quotation makes external intent
    // ambiguous and must be confirmed through a governed path.
    if (containsQuotedContent) return null;
    const commandIndex = clauses.findIndex(hasExplicitExternalOutreach);
    // Once an external command appears, any later authored clause makes its final polarity
    // unresolved. Fail closed instead of discarding a retraction as an "irrelevant" clause.
    if (commandIndex < 0 || clauses.slice(commandIndex + 1).some(Boolean)) return null;
  }
  return unique.length === 1 ? unique[0]! : null;
}

/** Requests that explicitly delegate the missing objective, fabricate evidence or route by title. */
function requiresObjectiveClarification(input: IntentClassifierInput): boolean {
  const text = normalizeForPolicy(input.latestUserMessage);
  const asksToFabricate = /\b(invente|inventar|fabrique|fabricar|invent|fabricate|make up)\b/.test(text)
    && /\b(companhia|empresa|company|documentos?|documents?|evidencias?|evidence)\b/.test(text);
  const asksToGuessObjective = /\b(conclua|descubra|adivinhe|infira|guess|infer|determine)\b/.test(text)
    && /\b(qual operacao|o que eu quero|meu objetivo|which operation|what i want|my objective)\b/.test(text);
  const routesByTitleOnly = /\b(normalmente|padrao|tipic[oa]|normally|standard|typical)\b/.test(text)
    && /\b(cargo|posicao|funcao|managing director|diretor|analista|banker|role|position|title)\b/.test(text)
    && !/\b(companhia|empresa|company|contrato|contract|modelo|model|operacao|operation|material|documento|document|mercado|market)\b/.test(text);
  return asksToFabricate || asksToGuessObjective || routesByTitleOnly;
}

const policyField = <T>(value: T, composition: NamedComposition) => ({
  value,
  state: "inferred" as const,
  confidence: 0.99,
  basis: `deterministic policy for ${composition}`,
});

function policyContinuity(
  composition: NamedComposition,
  output: IntentClassifierOutput,
  input: IntentClassifierInput,
): IntentClassifierOutput["routingCore"]["continuity"] {
  const text = normalizeForPolicy(input.latestUserMessage);
  if (composition === "monitor") return policyField("monitor" as const, composition);
  if (/\b(esquece|ignora|novo trabalho|forget|ignore|new task)\b/.test(text)) return policyField("new" as const, composition);
  if (composition === "build_or_review_model"
    && /\b(ajusta|altera|atualiza|recalcula|change|update|recalculate)\b/.test(text)) return policyField("refresh" as const, composition);
  if (input.recentConversation.length === 0) return policyField("new" as const, composition);
  if (input.recentConversation.length > 0 && [
    "answer_a_question", "review_work", "prepare_material", "prepare_decision", "introduce", "map_market_and_precedents",
  ].includes(composition)) return policyField("resume" as const, composition);
  return output.routingCore.continuity;
}

/**
 * Decision domain is a workflow axis, not a second model-authored description of the request.
 * Most compositions determine it completely. The few polymorphic families use only the current
 * request and governed active context; a job title never changes the domain.
 */
function policyDecisionType(
  composition: NamedComposition,
  input: IntentClassifierInput,
): IntentClassifierOutput["routingCore"]["decisionType"] {
  // Policy fields may be derived from the current user instruction or from a separately
  // governed active-work projection. Free-form conversation history is neither: assistant prose
  // can describe hypothetical domains and old user turns can have been superseded. Until the
  // governed projection is wired into this contract, current-turn evidence is the only safe
  // lexical source for polymorphic decision families.
  const text = normalizeForPolicy(input.latestUserMessage);
  const fixed: Partial<Record<NamedComposition, IntentClassifierOutput["routingCore"]["decisionType"]["value"]>> = {
    find_and_organize_information: "none",
    understand_company_sector_asset: "none",
    answer_a_question: "none",
    extract_and_reconcile_data: "document",
    read_contract_covenant_waterfall: "document",
    analyze_performance_and_credit: "credit",
    evaluate_received_opportunity: "credit",
    diagnose_capital_structure: "capital",
    develop_alternatives: "capital",
    design_indicative_structure: "capital",
    prepare_meeting: "capital",
    prepare_material: "material",
    prepare_decision: "capital",
    map_market_and_precedents: "market",
    identify_capital: "market",
    introduce: "external",
    manage_work: "workflow",
  };
  let value = fixed[composition];
  if (!value && composition === "monitor") {
    value = /\b(mercado|emiss\w*|spread|market|issuance|pricing)\b/.test(text) ? "market" : "credit";
  }
  if (!value && composition === "build_or_review_model") {
    const updatesCapitalScenario = /\b(ajust\w*|alter\w*|atualiz\w*|recalcul\w*|change|update|recalculate)\b/.test(normalizeForPolicy(input.latestUserMessage))
      && /\b(cenario|scenario|taxa|rate|prazo|tenor|cdi|indexador|indexer)\b/.test(normalizeForPolicy(input.latestUserMessage));
    value = updatesCapitalScenario ? "capital" : "credit";
  }
  if (!value && composition === "review_work") {
    value = /\b(estrutura de capital|capital structure|refinanc|alongamento|emissao|issuance)\b/.test(text)
      ? "capital"
      : /\b(contrato|contract|documento|document|clausula|clause)\b/.test(text) ? "document" : "credit";
  }
  value ??= "none";
  return value === "none"
    ? {value, state: "not_applicable", confidence: null, basis: `deterministic policy for ${composition}`}
    : policyField(value, composition);
}

/** Audience means the consumer or external counterparty of this work, never the subject analysed. */
function policyAudienceType(
  composition: NamedComposition,
  input: IntentClassifierInput,
): IntentClassifierOutput["routingCore"]["audienceType"] {
  const current = normalizeForPolicy(input.latestUserMessage);
  // Only user-authored history is a permissible fallback. Assistant prose is never evidence of
  // the requested audience. A governed active-work context will eventually replace this fallback.
  const userHistory = normalizeForPolicy(input.recentConversation
    .filter(({role}) => role === "user")
    .map(({content}) => content)
    .join("\n"));
  const replacesBoardContext = /\b(esquece|ignora|forget|ignore)\b[^.\n]{0,40}\b(conselh\w*|board|comite\w*|committee)\b/.test(current);

  // An audience named in the current instruction always wins over composition defaults. This
  // matters for requests such as "build the model for my VP" and "shortlist lenders for my VP".
  if (!replacesBoardContext && /\b(conselh\w*|board|comite\w*|committee)\b/.test(current)) {
    return policyField("board_or_committee" as const, composition);
  }
  if (/\b(?:(?:para|pro|ao|a|for|to)\s+)?(?:o|a|the)?\s*(?:meu|minha|my)\s+(vp|pm|diretor|director|managing director|chefe|head)\b/.test(current)) {
    return policyField("internal_senior" as const, composition);
  }
  if (/\b(?:para|pro|ao|aos|for|to)\s+(?:(?:o|a|os|as|the)\s+)?(?:cfo|tesouraria|treasury|companhia|cliente|client|management)\b/.test(current)
    || (composition === "prepare_meeting" && /\b(?:com|with)\s+(?:(?:o|a|the)\s+)?(?:cfo|tesouraria|treasury|companhia|cliente|client|management)\b/.test(current))) {
    return policyField("company_management" as const, composition);
  }
  if (/\b(?:para|aos|for|to)\s+(?:(?:os|as|the)\s+)?(?:fundos?|investidores?|financiadores?|bancos?|lenders?|investors?|providers?)\b/.test(current)) {
    return policyField("capital_provider" as const, composition);
  }

  // User-authored history can preserve an audience only when the current turn does not replace it.
  if (!replacesBoardContext && /\b(conselh\w*|board|comite\w*|committee)\b/.test(userHistory)) {
    return policyField("board_or_committee" as const, composition);
  }
  if (/\b(meu|minha|my)\s+(vp|pm|diretor|director|managing director|chefe|head)\b/.test(userHistory)) {
    return policyField("internal_senior" as const, composition);
  }

  // Composition defaults apply only after explicit/current and user-history evidence.
  if (composition === "identify_capital" || composition === "introduce") {
    return policyField("capital_provider" as const, composition);
  }
  return policyField("self" as const, composition);
}

function policyQuestion(
  composition: NamedComposition,
  output: IntentClassifierOutput,
  input: IntentClassifierInput,
): string | null {
  if (composition === "introduce") return input.locale === "pt-BR"
    ? "Você confirma a autorização para compartilhar externamente e qual estrutura ou termos devem orientar o envio?"
    : "Do you confirm authorization to share externally, and which structure or terms should govern the outreach?";
  if (composition === "prepare_material") {
    const text = normalizeForPolicy(input.latestUserMessage);
    const destinationIsExplicit = /\b(interno|interna|internal|cliente|client[- ]?ready|companhia|board|conselho|comite|committee)\b/.test(text);
    if (!destinationIsExplicit) return input.locale === "pt-BR"
      ? "Esse material deve ir diretamente à companhia ou ao cliente, ou primeiro passar por revisão interna?"
      : "Should this material go directly to the company or client, or first go through internal review?";
  }
  if (composition === "prepare_meeting" && output.firstQuestion) {
    const question = normalizeForPolicy(output.firstQuestion);
    const changesAngle = /\b(angulo|tese|alternativa|angle|thesis)\b/.test(question);
    const changesForm = /\b(formato|material|paginas?|deck|memo|format|pages?)\b/.test(question);
    return changesAngle && changesForm ? output.firstQuestion : null;
  }
  // Evidence gaps belong to the selected executor's coverage map, not to routing.
  return null;
}

/**
 * Turns semantic reading into a stable workflow identity. The model reads the turn; finite policy
 * derives plan-driving fields from the named composition and explicit control cues. This keeps
 * prose flexible while composition, order, depth and responsibilities are versioned and testable.
 */
export function canonicalizeIntentClassifierOutput(
  output: IntentClassifierOutput,
  inputOrLocale: IntentClassifierInput | IntentClassifierInput["locale"],
): IntentClassifierOutput {
  const input: IntentClassifierInput = typeof inputOrLocale === "string"
    ? {locale: inputOrLocale, latestUserMessage: "", recentConversation: [], entryJob: null, documentCount: 0}
    : inputOrLocale;
  const locale = input.locale;
  const explicit = explicitComposition(input);
  const composition = explicit ?? output.composition;
  const core = output.routingCore;
  const assertsMeaning = (state: typeof core.action.state) => state === "explicit" || state === "inferred";
  const unresolvedSemantics = core.object.value.length === 0
    || !assertsMeaning(core.object.state)
    || (explicit === null && (core.action.value.length !== 1 || !assertsMeaning(core.action.state)))
    || (core.decisionType.value !== "none" && !assertsMeaning(core.decisionType.state))
    || (core.audienceType.value !== "unspecified" && !assertsMeaning(core.audienceType.state));
  const mustAbstain = requiresObjectiveClarification(input)
    || composition === null
    || (composition === "introduce" && explicit !== "introduce")
    || unresolvedSemantics
    || (output.abstain && explicit === null);

  if (!mustAbstain) {
    const policy = compositionPolicy(composition);
    const primaryWorks = resolveCompositionPrimaryWorks(composition, {
      documentsPresent: input.documentCount > 0,
    });
    return intentClassifierOutputSchema.parse({
      routingCore: {
        ...output.routingCore,
        action: policyField([policy.canonicalAction], composition),
        object: output.routingCore.object.value.length > 0 ? output.routingCore.object : {value: [{id: "object-1", ordinal: 1, kind: "process", slots: []}], state: "unknown", confidence: null, basis: null},
        decisionType: policyDecisionType(composition, input),
        audienceType: policyAudienceType(composition, input),
        depth: policyField(policy.depth, composition),
        continuity: policyContinuity(composition, output, input),
        workResponsibility: policyField([...policy.workResponsibilities], composition),
      },
      inferableContext: output.inferableContext,
      primaryWorks: primaryWorks.map((work) => ({work, confidence: 0.99})),
      composition,
      firstQuestion: policyQuestion(composition, output, input),
      abstain: false,
      abstainReason: null,
    });
  }

  const modelQuestion = output.firstQuestion?.trim() || "";
  const asksOutcome = /\b(resultado|objetivo|espera|precisa|result|outcome|expect)\b/.test(normalizeForPolicy(modelQuestion));
  const question = modelQuestion
    ? `${modelQuestion}${asksOutcome ? "" : (locale === "pt-BR" ? " E qual resultado você espera?" : " And what result do you expect?")}`
    : abstentionQuestion(locale);

  return intentClassifierOutputSchema.parse({
    routingCore: {
      ...output.routingCore,
      action: {value: ["understand"], state: "unknown", confidence: null, basis: null},
      object: {value: [{id: "object-1", ordinal: 1, kind: "document", slots: []}], state: "unknown", confidence: null, basis: null},
      decisionType: {value: "none", state: "not_applicable", confidence: null, basis: null},
      audienceType: {value: "unspecified", state: "unknown", confidence: null, basis: null},
      depth: {value: "point", state: "unknown", confidence: null, basis: null},
      continuity: {value: "new", state: "unknown", confidence: null, basis: null},
      workResponsibility: {value: ["producer"], state: "unknown", confidence: null, basis: null},
    },
    inferableContext: output.inferableContext,
    primaryWorks: [{work: "understand", confidence: 0}],
    composition: null,
    firstQuestion: question.slice(0, 600),
    abstain: true,
    abstainReason: output.abstainReason?.trim() || (locale === "pt-BR"
      ? "O objeto e o resultado esperado ainda não estão identificados."
      : "The object and expected result are not identified yet."),
  });
}

/** Stable production classifier instructions, shared verbatim by runtime and gold gate. */
export const INTENT_CLASSIFIER_SYSTEM = `You classify one turn of a debt capital markets conversation into an intent envelope. You do
not answer the request and you do not plan or execute the work.

Fill only what the turn, the recent conversation and the listed inputs support. Every field carries
a state and a confidence: "explicit" when the person said it, "inferred" when it follows from what
they said, "ambiguous" when two readings remain, "unknown" when nothing supports a value. Never
guess authority, evidence regime, permissions or documents: they are not yours to fill.

Use only the canonical enums and codes in the schema. "action" contains exactly one canonical
action when the request is understood. "decisionType" and "audienceType" classify the decision and
audience without narrative prose. Objects are distinct instances with stable "object-N" ids,
one-based contiguous ordinals and canonical slots. Order objects by first material appearance in
the current message, then append objects resolved only from recent conversation in their first
historical appearance order; if two objects first appear together, use the schema enum order.
Never return free-form desired-outcome, decision or audience narratives. Use "entity" only for a
named or identifier-specific entity and "subject" for a generic category or qualitative subject.
Normalize amounts to base units, currencies to ISO-4217, percentages to fractional decimal text
without a percent sign (12% is "0.12"), ratios to decimal multiples (4.7x is "4.7"), indexers to
their uppercase code, basis-point changes to integer text, tenor to months, page/count values to
integer text, and cadence to a stable English code such as "weekly" or "quarterly". Do not split
one object across multiple instances.

Choose the composition that names the requested outcome, not an intermediate step. The complete
composition and ordered-work policy below is generated from the same executable policy used by
canonicalization, envelope validation, runtime stamping and fingerprints:
${intentCompositionPolicyPrompt()}

The requested outcome wins over an intermediate task: a board discussion remains prepare_decision
even though diagnosis is required; an explicit request to produce the selected material remains
prepare_material even when the file will be used in a meeting. A follow-up such as "revise isso"
uses the recent conversation to resolve "isso"; do not abstain merely because it is a pronoun.

Work responsibility describes the person's role in this work, never their job title: producer,
coordinator, reviewer, decision_maker, sponsor, recipient, external_authorizer.
Producer applies when the person asks the system to create or analyse. Reviewer applies when they
ask for a challenge or review. Coordinator applies when they orchestrate a structure, process or
capital outreach. Decision_maker applies when they own the choice being prepared; sponsor applies
when they own the broader programme. Multiple responsibilities may apply.
Never infer decision_maker or external_authorizer from a banker, analyst, advisor or investor job
title. A person preparing client work is normally producer and coordinator; the client owns the
capital decision. A person screening received material can be both producer and reviewer.

Depth: point only for a bounded factual question or a truly context-free request; preliminary for
early exploration, triage or idea generation; institutional for an existing deliverable, decision,
full structure or model update. Continuity: use resume for a follow-up that continues prior work,
refresh for an assumption or data update, monitor for recurring surveillance, comparison for an
explicit comparison, and new when there is no prior work or the person explicitly replaces the
prior objective.

If the turn is too ambiguous to identify the referenced object and desired outcome, set abstain to
true, composition to null and ask one question that identifies both. If one answer would change the
work family, ordering, audience or deliverable, put that single question in firstQuestion.
A firstQuestion does not mean abstention. When a named composition is identifiable, set abstain to
false, select it and ask the question while work begins. A sponsor asking for meeting preparation
is prepare_meeting even when the thesis angle or output format still needs confirmation.
Questions about missing evidence belong to the downstream coverage engine, not here, unless the
missing fact changes the workflow itself. For a point explanation, explicit model update, review,
collection-only request, market query or bounded covenant analysis, leave firstQuestion null.
Do not abstain merely because evidence, assumptions, thesis angle or format is incomplete when the
subject and requested outcome family are already clear. Ask here when the answer changes the
workflow or external effect: internal review versus client-ready material, thesis angle plus output
form for an underspecified sponsor assignment, or authorization and selected structure before an
external introduction. Evidence such as a receivables tape, budget, debt schedule, mandate or capex
amount is requested later by coverage and is not a router question.
Return the requested JSON only.`;

packages/agent-contracts/src/semantic-ob.content:
import {fingerprintJson} from "@offroad/case-understanding";
import {z} from "zod";

import {
  intentObjectCardinalityLimit,
  intentObjectKindSchema,
  intentObjectSlotKeySchema,
  type IntentObjectSlotKey,
} from "./intent-envelope";
import {intentClassifierOutputSchema, type IntentClassifierOutput} from "./intent-classifier";

const nonEmpty = z.string().trim().min(1);
const stableId = z.string().trim().min(1).max(200).regex(/^[A-Za-z0-9][A-Za-z0-9_.:-]*$/);

const canonicalObjectSlotSchema = z.object({
  key: intentObjectSlotKeySchema,
  value: nonEmpty.max(200),
}).strict();

const SLOT_COMPATIBILITY: Record<z.infer<typeof intentObjectKindSchema>, ReadonlySet<IntentObjectSlotKey>> = {
  organization: new Set(["entity", "subject"]),
  user: new Set(["entity", "subject"]),
  company: new Set(["entity", "subject"]),
  project: new Set(["entity", "subject"]),
  operation: new Set(["entity", "subject", "amount", "currency", "percentage", "basis_points", "ratio", "indexer", "tenor_months"]),
  instrument: new Set(["entity", "subject", "amount", "currency", "percentage", "basis_points", "ratio", "indexer", "tenor_months"]),
  document: new Set(["entity", "subject", "count"]),
  claim: new Set(["subject", "amount", "currency", "percentage", "basis_points", "ratio", "indexer", "tenor_months", "count", "cadence"]),
  model: new Set(["entity", "subject"]),
  asset_or_pool: new Set(["entity", "subject", "amount", "currency", "count"]),
  scenario: new Set(["subject", "amount", "currency", "percentage", "basis_points", "ratio", "indexer", "tenor_months", "cadence"]),
  alternative: new Set(["entity", "subject", "amount", "currency", "percentage", "basis_points", "ratio", "indexer", "tenor_months"]),
  material: new Set(["entity", "subject", "page_count", "count"]),
  market: new Set(["entity", "subject", "percentage", "basis_points", "ratio", "indexer", "tenor_months", "cadence"]),
  provider: new Set(["entity", "subject", "count"]),
  mandate: new Set(["entity", "subject", "amount", "currency", "percentage", "basis_points", "ratio", "indexer", "tenor_months"]),
  process: new Set(["entity", "subject", "count", "cadence"]),
  decision: new Set(["entity", "subject"]),
};

function validateSlotsForKind(
  kind: z.infer<typeof intentObjectKindSchema>,
  slots: readonly z.infer<typeof canonicalObjectSlotSchema>[],
  ctx: z.RefinementCtx,
  path: PropertyKey[] = [],
): void {
  for (const [index, slot] of slots.entries()) {
    if (!SLOT_COMPATIBILITY[kind].has(slot.key)) {
      ctx.addIssue({code: "custom", path: [...path, index, "key"], message: `${slot.key} is not valid for ${kind}`});
    }
  }
}

const canonicalObjectSlotsSchema = z.array(canonicalObjectSlotSchema).min(1).max(12).superRefine((slots, ctx) => {
  const keys = new Set<string>();
  for (const [index, slot] of slots.entries()) {
    if (keys.has(slot.key)) {
      ctx.addIssue({code: "custom", path: [index, "key"], message: "slot keys are unique within an object"});
    }
    keys.add(slot.key);
  }
  const headCount = Number(keys.has("entity")) + Number(keys.has("subject"));
  if (headCount !== 1) ctx.addIssue({code: "custom", message: "an object has exactly one entity or subject head"});
});

const governedObjectiveRevisionSchema = z.object({
  id: stableId,
  revision: z.number().int().positive(),
  fingerprint: z.string().regex(/^[a-f0-9]{64}$/),
  label: nonEmpty.max(2_000),
}).strict();

const governedSourceManifestSchema = z.object({
  id: stableId,
  fingerprint: z.string().regex(/^[a-f0-9]{64}$/),
  documentIds: z.array(z.uuid()).max(500),
  evidenceObjectIds: z.array(stableId).max(500),
}).strict().superRefine((manifest, ctx) => {
  if (new Set(manifest.documentIds).size !== manifest.documentIds.length) {
    ctx.addIssue({code: "custom", path: ["documentIds"], message: "source-manifest document ids are unique"});
  }
  if (new Set(manifest.evidenceObjectIds).size !== manifest.evidenceObjectIds.length) {
    ctx.addIssue({code: "custom", path: ["evidenceObjectIds"], message: "source-manifest evidence object ids are unique"});
  }
});

/**
 * A context object is admitted by the control plane, never inferred by the extractor. The source
 * ids point to the governed object/evidence registry that established it. This gives follow-up
 * turns a compact work memory without turning prior assistant prose into evidence.
 */
export const activeWorkContextObjectSchema = z.object({
  id: stableId,
  ordinal: z.number().int().min(1).max(500),
  kind: intentObjectKindSchema,
  slots: canonicalObjectSlotsSchema,
  label: nonEmpty.max(200),
  governance: z.object({
    state: z.enum(["user_confirmed", "system_resolved"]),
    sourceIds: z.array(stableId).min(1).max(50),
  }).strict(),
}).strict().superRefine((object, ctx) => validateSlotsForKind(object.kind, object.slots, ctx, ["slots"]));

export const activeWorkContextSchema = z.object({
  schemaVersion: z.literal("active-work-context.v2"),
  contextId: stableId,
  organizationId: z.uuid(),
  projectId: z.uuid(),
  revision: z.number().int().positive(),
  state: z.enum(["active", "paused"]),
  objective: governedObjectiveRevisionSchema,
  sourceManifest: governedSourceManifestSchema,
  objects: z.array(activeWorkContextObjectSchema).max(500),
}).strict().superRefine((context, ctx) => {
  if (context.revision !== context.objective.revision) {
    ctx.addIssue({code: "custom", path: ["revision"], message: "context revision is the bound objective revision"});
  }
  if (!context.sourceManifest.evidenceObjectIds.includes(context.projectId)
    || !context.sourceManifest.evidenceObjectIds.includes(context.objective.id)) {
    ctx.addIssue({code: "custom", path: ["sourceManifest", "evidenceObjectIds"], message: "source manifest binds the project and objective revision"});
  }
  const allowedSources = new Set([
    context.sourceManifest.id,
    ...context.sourceManifest.documentIds,
    ...context.sourceManifest.evidenceObjectIds,
  ]);
  const ids = new Set<string>();
  const ordinals = new Set<number>();
  for (const [index, object] of context.objects.entries()) {
    if (ids.has(object.id)) ctx.addIssue({code: "custom", path: ["objects", index, "id"], message: "context object ids are unique"});
    if (ordinals.has(object.ordinal)) ctx.addIssue({code: "custom", path: ["objects", index, "ordinal"], message: "context object ordinals are unique"});
    ids.add(object.id);
    ordinals.add(object.ordinal);
    for (const [sourceIndex, sourceId] of object.governance.sourceIds.entries()) {
      if (!allowedSources.has(sourceId)) {
        ctx.addIssue({code: "custom", path: ["objects", index, "governance", "sourceIds", sourceIndex], message: "context object source belongs to the governed source manifest"});
      }
    }
  }
});
export type ActiveWorkContext = z.infer<typeof activeWorkContextSchema>;

const recentMessageSchema = z.object({
  role: z.enum(["user", "assistant"]),
  content: z.string().max(20_000),
}).strict();

export const semanticObjectExtractorInputSchema = z.object({
  locale: z.enum(["pt-BR", "en-US"]),
  latestUserMessage: nonEmpty.max(20_000),
  recentConversation: z.array(recentMessageSchema).max(8),
  activeWorkContext: activeWorkContextSchema.nullable(),
}).strict();
export type SemanticObjectExtractorInput = z.infer<typeof semanticObjectExtractorInputSchema>;

/** Parse once before JSON serialization so runtime and evals send the same bounded shape. */
export function buildSemanticObjectExtractorInput(input: SemanticObjectExtractorInput): SemanticObjectExtractorInput {
  return semanticObjectExtractorInputSchema.parse(input);
}

/** Text spans use JavaScript UTF-16 offsets, matching String.slice in runtime and evals. */
export const semanticTextSpanSchema = z.object({
  source: z.enum(["latest_user_message", "recent_user_message"]),
  messageIndex: z.number().int().min(0).max(7).nullable(),
  start: z.number().int().nonnegative(),
  end: z.number().int().positive(),
  text: nonEmpty.max(600),
}).strict().superRefine((span, ctx) => {
  if (span.end <= span.start) ctx.addIssue({code: "custom", path: ["end"], message: "span end is greater than start"});
  if (span.source === "latest_user_message" && span.messageIndex !== null) {
    ctx.addIssue({code: "custom", path: ["messageIndex"], message: "latest message spans have a null messageIndex"});
  }
  if (span.source === "recent_user_message" && span.messageIndex === null) {
    ctx.addIssue({code: "custom", path: ["messageIndex"], message: "recent message spans identify their input array index"});
  }
});
export type SemanticTextSpan = z.infer<typeof semanticTextSpanSchema>;

const headCandidateSchema = z.object({
  key: z.enum(["entity", "subject"]),
  span: semanticTextSpanSchema,
}).strict();

const modifierCandidateSchema = z.object({
  key: z.enum([
    "amount", "currency", "percentage", "basis_points", "ratio", "indexer",
    "tenor_months", "page_count", "count", "cadence",
  ]),
  span: semanticTextSpanSchema,
}).strict();

const semanticObjectCandidateSchema = z.object({
  candidateId: z.string().regex(/^candidate-[1-9]\d*$/),
  kind: intentObjectKindSchema,
  head: headCandidateSchema,
  modifiers: z.array(modifierCandidateSchema).max(10),
}).strict().superRefine((candidate, ctx) => {
  const keys = new Set<string>();
  for (const [index, modifier] of candidate.modifiers.entries()) {
    if (keys.has(modifier.key)) {
      ctx.addIssue({code: "custom", path: ["modifiers", index, "key"], message: "modifier keys are unique within an object"});
    }
    keys.add(modifier.key);
  }
});

const activeContextReferenceSchema = z.object({
  contextObjectId: stableId,
  trigger: semanticTextSpanSchema,
}).strict();

const unresolvedReferenceSchema = z.object({
  span: semanticTextSpanSchema,
  reason: z.enum(["no_governed_match", "multiple_governed_matches", "missing_referent"]),
}).strict();

const excludedSpanSchema = z.object({
  span: semanticTextSpanSchema,
  reason: z.enum(["deadline_or_date", "quoted_example", "negated_request", "non_object_metadata"]),
}).strict();

const excludedSemanticHeadSpanSchema = z.object({
  span: semanticTextSpanSchema,
  reason: z.enum(["quoted_example", "negated_request", "non_object_metadata"]),
}).strict();

/**
 * Model-written extractor output. It carries raw, attributable spans only. Canonical values,
 * final ids, ordering, context imports, completeness and fingerprints are code-owned.
 */
export const semanticObjectExtractorOutputSchema = z.object({
  objects: z.array(semanticObjectCandidateSchema).max(intentObjectCardinalityLimit),
  activeContextReferences: z.array(activeContextReferenceSchema).max(intentObjectCardinalityLimit),
  unresolvedReferences: z.array(unresolvedReferenceSchema).max(12),
  excludedQuantitativeSpans: z.array(excludedSpanSchema).max(24),
  /** Explicitly accounts for a detected non-numeric head that is not an active object. */
  excludedSemanticHeadSpans: z.array(excludedSemanticHeadSpanSchema).max(24).default([]),
}).strict().superRefine((output, ctx) => {
  const candidateIds = new Set<string>();
  for (const [index, object] of output.objects.entries()) {
    if (candidateIds.has(object.candidateId)) {
      ctx.addIssue({code: "custom", path: ["objects", index, "candidateId"], message: "candidate ids are unique"});
    }
    candidateIds.add(object.candidateId);
  }
  const contextIds = new Set<string>();
  for (const [index, reference] of output.activeContextReferences.entries()) {
    if (contextIds.has(reference.contextObjectId)) {
      ctx.addIssue({code: "custom", path: ["activeContextReferences", index, "contextObjectId"], message: "a context object is referenced at most once"});
    }
    contextIds.add(reference.contextObjectId);
  }
});
export type SemanticObjectExtractorOutput = z.infer<typeof semanticObjectExtractorOutputSchema>;

export const normalizedSemanticObjectSchema = z.object({
  id: z.string().regex(/^object-[1-9]\d*$/),
  ordinal: z.number().int().positive(),
  kind: intentObjectKindSchema,
  slots: canonicalObjectSlotsSchema,
  source: z.discriminatedUnion("type", [
    z.object({type: z.literal("text"), spans: z.array(semanticTextSpanSchema).min(1).max(12)}).strict(),
    z.object({type: z.literal("active_work_context"), contextId: stableId, contextRevision: z.number().int().positive(), contextObjectId: stableId, trigger: semanticTextSpanSchema}).strict(),
  ]),
}).strict().superRefine((object, ctx) => validateSlotsForKind(object.kind, object.slots, ctx, ["slots"]));
export type NormalizedSemanticObject = z.infer<typeof normalizedSemanticObjectSchema>;

const coverageIssueSchema = z.object({
  code: z.enum([
    "invalid_source_span", "assistant_text_is_not_evidence", "unknown_context_object",
    "context_not_active", "unresolved_reference", "uncovered_quantitative_mention",
    "invalid_slot_for_kind", "normalization_failed", "duplicate_atomic_object",
    "no_semantic_object",
    "invalid_exclusion_reason",
    "historical_text_is_not_governed_context",
    "uncovered_semantic_head",
    "explicit_semantic_head_marked_unresolved",
    "merged_semantic_heads",
    "semantic_head_multiply_claimed",
    "object_cardinality_exceeded",
  ]),
  severity: z.enum(["error", "warning"]),
  detail: nonEmpty.max(600),
}).strict();

export const semanticObjectCompilationSchema = z.object({
  schemaVersion: z.literal("semantic-object-compilation.v1"),
  status: z.enum(["complete", "incomplete", "rejected"]),
  // Diagnostic objects preserve the complete bounded provider response even when the combined
  // text + context cardinality exceeds the accepted per-turn limit. usableObjects stays empty.
  objects: z.array(normalizedSemanticObjectSchema).max(intentObjectCardinalityLimit * 2),
  usableObjects: z.array(normalizedSemanticObjectSchema).max(intentObjectCardinalityLimit),
  coverage: z.object({
    sourceSpansChecked: z.number().int().nonnegative(),
    quantitativeMentions: z.number().int().nonnegative(),
    quantitativeMentionsCovered: z.number().int().nonnegative(),
    semanticHeadMentions: z.number().int().nonnegative(),
    semanticHeadMentionsCovered: z.number().int().nonnegative(),
    activeContextReferencesChecked: z.number().int().nonnegative(),
    issues: z.array(coverageIssueSchema).max(200),
  }).strict(),
  fingerprint: z.string().regex(/^[a-f0-9]{64}$/),
}).strict().superRefine((compilation, ctx) => {
  const {fingerprint, ...body} = compilation;
  if (fingerprintJson(body) !== fingerprint) {
    ctx.addIssue({code: "custom", path: ["fingerprint"], message: "compilation fingerprint matches its complete canonical body"});
  }
  for (const [index, object] of compilation.objects.entries()) {
    if (object.ordinal !== index + 1 || object.id !== `object-${index + 1}`) {
      ctx.addIssue({code: "custom", path: ["objects", index], message: "final object ids and ordinals are contiguous in canonical order"});
    }
  }
  const errorCount = compilation.coverage.issues.filter(({severity}) => severity === "error").length;
  if (compilation.coverage.quantitativeMentionsCovered > compilation.coverage.quantitativeMentions) {
    ctx.addIssue({code: "custom", path: ["coverage", "quantitativeMentionsCovered"], message: "covered quantitative mentions cannot exceed detected mentions"});
  }
  if (compilation.coverage.semanticHeadMentionsCovered > compilation.coverage.semanticHeadMentions) {
    ctx.addIssue({code: "custom", path: ["coverage", "semanticHeadMentionsCovered"], message: "covered semantic heads cannot exceed detected heads"});
  }
  if (compilation.status === "complete") {
    if (compilation.objects.length === 0 || errorCount > 0
      || fingerprintJson(compilation.usableObjects) !== fingerprintJson(compilation.objects)) {
      ctx.addIssue({code: "custom", path: ["status"], message: "complete compilation has objects, no errors and exposes exactly those objects as usable"});
    }
  } else if (compilation.usableObjects.length > 0) {
    ctx.addIssue({code: "custom", path: ["usableObjects"], message: "incomplete or rejected compilation exposes no usable objects"});
  }
});
export type SemanticObjectCompilation = z.infer<typeof semanticObjectCompilationSchema>;

export const SEMANTIC_OBJECT_KIND_DEFINITIONS = {
  organization: "the institution or legal organization represented by a person; not the operating company being analysed",
  user: "a specific person whose identity or own profile is itself the subject",
  company: "the operating company, issuer, borrower, sponsor or acquisition target under examination",
  project: "the persistent workspace or named project that contains work over time; not a financing transaction",
  operation: "a financing, transaction, acquisition, expansion or other bounded economic undertaking",
  instrument: "a debt security, facility, loan, covenant or named financing instrument",
  document: "one document, file, filing, spreadsheet or explicitly grouped document class",
  claim: "one proposition, metric, risk, discrepancy or condition that can be tested independently",
  model: "a financial model, forecast, calculation model or sensitivity model",
  asset_or_pool: "an asset, collateral package, receivables pool or other identifiable economic pool",
  scenario: "one coherent assumption set or requested change to variables",
  alternative: "one independently selectable strategic, capital or financing alternative",
  material: "a requested deliverable such as a deck, memo, pitch, spreadsheet or analysis pack",
  market: "a sector, market, pricing environment, comparable universe or precedent set",
  provider: "an investor, lender, bank, fund or other potential capital provider",
  mandate: "an investment, credit or financing mandate and its eligibility criteria",
  process: "a meeting, monitoring routine, workstream, status or recurring operating process",
  decision: "an explicit choice, approval, recommendation or decision question to be prepared",
} as const satisfies Record<z.infer<typeof intentObjectKindSchema>, string>;

export const SEMANTIC_OBJECT_NORMALIZATION_CONTRACT = `
- Text offsets are JavaScript UTF-16 offsets and every span must reproduce source.slice(start, end) exactly.
- "entity" is only a proper name or identifier-specific entity. A generic class, topic or quality uses "subject".
- Amounts are base-unit integer decimal text; currency is ISO-4217; percentages are fractional decimal text;
  basis points are integer text; ratios are decimal multiples; indexers are uppercase canonical codes;
  tenor is integer months; page_count and count are integer text; cadence is one of daily, weekly,
  monthly, quarterly, semiannual, annual or one_time.
- The model returns raw spans, never its own converted number. Code performs and verifies normalization.
- No unsupported derivation: a normalized modifier must be directly stated in its attributed span.
`.trim();

const objectDefinitionsPrompt = Object.entries(SEMANTIC_OBJECT_KIND_DEFINITIONS)
  .map(([kind, definition]) => `- ${kind}: ${definition}`)
  .join("\n");

/** Stable prompt for a bounded second pass; it never routes, plans, answers or executes. */
export const SEMANTIC_OBJECT_EXTRACTOR_SYSTEM = `You extract the semantic objects referenced by one user turn. You do not
classify intent, answer, plan, infer authority, retrieve evidence or execute work.

Kinds:
${objectDefinitionsPrompt}

Atomic reference rule:
- Return one object for every independently referable semantic head. Do not merge a company, operation,
  material, claim, model, instrument, scenario, alternative, document or provider into one object.
- A list of alternatives produces one alternative object per named option. Separately named documents
  produce separate document objects. A plural document class is one object; attach count only when the
  number is explicit. Quantitative modifiers remain on the one head they modify.
- Do not split one head into separate objects merely because it has multiple modifiers.
- The accepted turn cardinality is ${intentObjectCardinalityLimit} text objects plus governed references
  combined. If the turn contains more, return every attributable candidate so code can mark the turn
  incomplete; never silently truncate, merge or choose a preferred subset.

Attribution and order:
- Every new object has one exact head span and zero or more exact modifier spans from user-authored text.
  Never cite assistant text. Use UTF-16 offsets matching JavaScript String.slice.
- New object candidates and context-reference triggers must cite the latest user message. Earlier
  conversation is interpretation-only: it can help detect that a reference is unresolved, but it can
  never promote historical prose into an object or provide an evidence span.
- activeWorkContext is control-plane-governed memory. When the turn refers to one of those objects, return
  its id in activeContextReferences with the textual trigger. Do not copy or rewrite that context object.
  Context references are appended after text objects by code.
- If a pronoun or ellipsis has no unique governed referent, declare it in unresolvedReferences.
- A non-numeric head detected in the turn must be represented by one atomic object, declared unresolved,
  or placed in excludedSemanticHeadSpans with an exact, supported reason. Never omit it silently.

Head and modifier rules:
- entity is only a proper name or identifier-specific entity; generic classes and qualitative subjects use subject.
- The head span is the shortest source phrase that still identifies the object. A modifier span may overlap
  its head span when a phrase such as "R$ 50 milhões" supplies both amount and currency.
- Exclude dates, deadlines, quoted examples, negated requests and other non-object numeric metadata only by
  listing their exact span and a permitted reason. Never hide an uncertain object as excluded metadata.

Normalization contract (performed by code, included here so spans carry sufficient evidence):
${SEMANTIC_OBJECT_NORMALIZATION_CONTRACT}

Return the requested JSON only.`;

const WORD_NUMBERS: Record<string, number> = {
  zero: 0, um: 1, uma: 1, one: 1, dois: 2, duas: 2, two: 2, tres: 3, three: 3,
  quatro: 4, four: 4, cinco: 5, five: 5, seis: 6, six: 6, sete: 7, seven: 7,
  oito: 8, eight: 8, nove: 9, nine: 9, dez: 10, ten: 10, onze: 11, eleven: 11,
  doze: 12, twelve: 12,
};

const normalizeSearchText = (value: string): string => value
  .normalize("NFKD")
  .replace(/[\u0300-\u036f]/g, "")
  .toLocaleLowerCase("pt-BR")
  .replace(/\s+/g, " ")
  .trim();

const normalizeLexical = (value: string): string => value.normalize("NFKC").replace(/\s+/g, " ").trim();

function parseNumberToken(raw: string): number | null {
  const text = normalizeSearchText(raw);
  for (const [word, number] of Object.entries(WORD_NUMBERS)) {
    if (new RegExp(`\\b${word}\\b`).test(text)) return number;
  }
  const match = text.match(/[-+]?\d[\d.,]*/);
  if (!match) return null;
  let token = match[0]!;
  const comma = token.lastIndexOf(",");
  const dot = token.lastIndexOf(".");
  if (comma >= 0 && dot >= 0) {
    token = comma > dot ? token.replace(/\./g, "").replace(",", ".") : token.replace(/,/g, "");
  } else if (comma >= 0) {
    const decimals = token.length - comma - 1;
    token = decimals === 3 ? token.replace(/,/g, "") : token.replace(",", ".");
  } else if (dot >= 0) {
    const decimals = token.length - dot - 1;
    if (decimals === 3 && /^\d{1,3}(?:\.\d{3})+$/.test(token)) token = token.replace(/\./g, "");
  }
  const value = Number(token);
  return Number.isFinite(value) ? value : null;
}

const canonicalDecimal = (value: number): string => {
  if (Object.is(value, -0)) return "0";
  return Number.isInteger(value) ? String(value) : String(Number(value.toFixed(12)));
};

function magnitude(raw: string): number {
  const text = normalizeSearchText(raw);
  if (/\b(bilhao|bilhoes|billion|bn)\b/.test(text)) return 1_000_000_000;
  if (/\b(milhao|milhoes|million|mn|mm)\b/.test(text)) return 1_000_000;
  if (/\b(mil|thousand|k)\b/.test(text)) return 1_000;
  return 1;
}

const CANONICAL_HEAD_ALIASES: Partial<Record<z.infer<typeof intentObjectKindSchema>, Readonly<Record<string, string>>>> = {
  claim: {folga: "headroom"},
  operation: {case: "operação"},
  provider: {fundos: "investidores"},
};

function normalizeSlotValue(key: IntentObjectSlotKey, raw: string, kind?: z.infer<typeof intentObjectKindSchema>): string | null {
  const text = normalizeSearchText(raw);
  if (key === "entity" || key === "subject") return (kind ? CANONICAL_HEAD_ALIASES[kind]?.[text] : undefined) ?? normalizeLexical(raw);
  if (key === "currency") {
    if (/\bbrl\b|r\$|\breais?\b/.test(text)) return "BRL";
    if (/\busd\b|us\$|u\$|\bdolares?\b|\bdollars?\b/.test(text)) return "USD";
    if (/\beur\b|€|\beuros?\b/.test(text)) return "EUR";
    const code = raw.match(/\b[A-Za-z]{3}\b/)?.[0]?.toUpperCase();
    return code ?? null;
  }
  if (key === "indexer") {
    const indexer = text.match(/\b(cdi|ipca|selic|sofr|libor|igpm|igp-m|tjlp|tr)\b/)?.[1];
    return indexer ? indexer.replace("igp-m", "igpm").toUpperCase() : null;
  }
  if (key === "cadence") {
    if (/\b(diari[oa]|diariamente|daily)\b/.test(text)) return "daily";
    if (/\b(semanal|semanalmente|toda semana|weekly)\b/.test(text)) return "weekly";
    if (/\b(mensal|mensalmente|todo mes|monthly)\b/.test(text)) return "monthly";
    if (/\b(trimestral|trimestralmente|todo trimestre|quarterly)\b/.test(text)) return "quarterly";
    if (/\b(semestral|semestralmente|semiannual|semi-annual)\b/.test(text)) return "semiannual";
    if (/\b(anual|anualmente|todo ano|annual|annually|yearly)\b/.test(text)) return "annual";
    if (/\b(uma vez|pontual|one[- ]?time)\b/.test(text)) return "one_time";
    return null;
  }
  const number = parseNumberToken(raw);
  if (number === null) return null;
  if (key === "amount") return canonicalDecimal(number * magnitude(raw));
  if (key === "percentage") return /%|\bpercent(?:age)?\b|\bpor cento\b/.test(text) ? canonicalDecimal(number / 100) : null;
  if (key === "basis_points") return /\bbps?\b|\bbasis points?\b|\bpontos?-base\b/.test(text) && Number.isInteger(number) ? String(number) : null;
  if (key === "page_count") return /\bpaginas?\b|\bpages?\b/.test(text) && Number.isInteger(number) ? String(number) : null;
  if (key === "count") {
    return Number.isInteger(number) ? String(number) : null;
  }
  if (key === "ratio") return /x\b|\bvezes\b|\bmultiples?\b/.test(text) ? canonicalDecimal(number) : null;
  if (key === "tenor_months") {
    if (/\b(ano|anos|year|years)\b/.test(text)) return canonicalDecimal(number * 12);
    if (/\b(mes|meses|month|months)\b/.test(text)) return canonicalDecimal(number);
    return null;
  }
  return null;
}

function sourceText(input: SemanticObjectExtractorInput, span: SemanticTextSpan): string | null {
  if (span.source === "latest_user_message") return input.latestUserMessage;
  const message = span.messageIndex === null ? undefined : input.recentConversation[span.messageIndex];
  return message?.role === "user" ? message.content : null;
}

function validateSpan(input: SemanticObjectExtractorInput, span: SemanticTextSpan): "valid" | "assistant" | "invalid" {
  if (span.source === "recent_user_message" && span.messageIndex !== null
    && input.recentConversation[span.messageIndex]?.role === "assistant") return "assistant";
  const source = sourceText(input, span);
  if (source === null || span.end > source.length) return "invalid";
  return source.slice(span.start, span.end) === span.text ? "valid" : "invalid";
}

function exclusionIsSupported(input: SemanticObjectExtractorInput, excluded: z.infer<typeof excludedSpanSchema>): boolean {
  const source = sourceText(input, excluded.span);
  if (source === null) return false;
  const normalized = normalizeSearchText(excluded.span.text);
  if (excluded.reason === "deadline_or_date") {
    return /\b\d{1,2}[/-]\d{1,2}(?:[/-]\d{2,4})?\b|\b\d{4}-\d{2}-\d{2}\b|\b(?:hoje|amanha|today|tomorrow)\b/.test(normalized);
  }
  if (excluded.reason === "quoted_example") {
    const before = source.slice(0, excluded.span.start);
    const after = source.slice(excluded.span.end);
    const quotePairs: Array<[string, string]> = [["\"", "\""], ["'", "'"], ["“", "”"], ["‘", "’"]];
    return quotePairs.some(([open, close]) => {
      if (open === close) return before.split(open).length % 2 === 0 && after.indexOf(close) >= 0;
      return before.lastIndexOf(open) > before.lastIndexOf(close) && after.indexOf(close) >= 0;
    });
  }
  if (excluded.reason === "negated_request") {
    const window = normalizeSearchText(source.slice(Math.max(0, excluded.span.start - 100), excluded.span.start));
    return /\b(?:nao|sem|nunca|jamais|evite|not|without|never|avoid)\b/.test(window);
  }
  // Non-object metadata is deliberately narrow; business quantities cannot be hidden here.
  const surrounding = normalizeSearchText(source.slice(Math.max(0, excluded.span.start - 40), Math.min(source.length, excluded.span.end + 20)));
  return /\b(?:versao|version|turno|turn|tentativa|attempt|item|passo|step)\s*(?:n(?:o|umber)?\.?\s*)?\d+\b/.test(surrounding);
}

type QuantityMention = {source: SemanticTextSpan["source"]; messageIndex: number | null; start: number; end: number; text: string};

type SemanticHeadMention = {
  source: "latest_user_message";
  messageIndex: null;
  start: number;
  end: number;
  text: string;
  expectedKind: z.infer<typeof intentObjectKindSchema> | null;
};

/**
 * Independent, code-owned coverage vocabulary for the domain heads that materially change a
 * credit-work route. It is deliberately not used to create objects or infer their meaning. Its
 * only authority is negative: a detected head that the model omitted or merged blocks use.
 */
const SEMANTIC_HEAD_PATTERNS: readonly {
  kind: z.infer<typeof intentObjectKindSchema>;
  pattern: RegExp;
}[] = [
  {kind: "operation", pattern: /\b(?:operaç(?:ão|ões)|operac(?:ao|oes)|transaç(?:ão|ões)|transac(?:ao|oes)|captaç(?:ão|ões)|captac(?:ao|oes)|financiamento|refinanciamento|aquisiç(?:ão|ões)|aquisic(?:ao|oes)|expans(?:ão|ões)|expans(?:ao|oes))\b/giu},
  {kind: "material", pattern: /\b(?:memo|memorando|deck|apresentaç(?:ão|ões)|apresentac(?:ao|oes)|pitch|teaser|cim|term[ -]?sheet|planilha|spreadsheet|relat(?:ó|o)rio|report|one[ -]?pager|material|materiais)\b/giu},
  {kind: "instrument", pattern: /\b(?:debênture|debentures?|ccb|cri|cra|fidc|bond|bonds|loan|facility|empréstimo|emprestimo|nota comercial|commercial paper|project finance|acquisition finance)\b/giu},
  {kind: "document", pattern: /\b(?:documento|documentos|arquivo|arquivos|balanço|balanco|balancete|contrato|escritura|waiver)\b/giu},
  {kind: "model", pattern: /\b(?:modelo financeiro|financial model|projeç(?:ão|ões)|projec(?:ao|oes)|forecast|sensibilidade|sensitivity)\b/giu},
  {kind: "asset_or_pool", pattern: /\b(?:recebíveis|recebiveis|carteira|pool|garantia|garantias|colateral|collateral|ativo|ativos)\b/giu},
  {kind: "scenario", pattern: /\b(?:cenário|cenarios?|cenario|scenario|downside|upside|stress case|caso de estresse)\b/giu},
  {kind: "alternative", pattern: /\b(?:alternativa|alternativas|opç(?:ão|ões)|opc(?:ao|oes))\b/giu},
  {kind: "market", pattern: /\b(?:mercado|market|setor|sector|comparáveis|comparaveis|comparables|precedentes|precedents)\b/giu},
  {kind: "provider", pattern: /\b(?:investidor|investidores|financiador|financiadores|lender|lenders|fundo|fundos|banco|bancos|provider|providers)\b/giu},
  {kind: "mandate", pattern: /\b(?:mandato|mandate|política de investimento|politica de investimento|investment policy)\b/giu},
  {kind: "decision", pattern: /\b(?:decisão|decisao|decision|aprovação|aprovacao|approval)\b/giu},
];

const INTRODUCED_ENTITY_PATTERN = /\b(?:a|o|as|os|da|do|das|dos|na|no|nas|nos|com\s+a|com\s+o|sobre\s+a|sobre\s+o|empresa|companhia|banco|gestora|fundo|at|from|for|with|company|bank|fund)\s+([\p{Lu}][\p{L}\p{N}&.-]*(?:\s+(?:(?:d[aeo]s?|e|and|of)\s+)?[\p{Lu}][\p{L}\p{N}&.-]*){0,4})\b/gu;
const ENTITY_HEAD_STOP = new Set([
  "vp", "md", "cfo", "ceo", "dcm", "ib", "ri", "board",
  // Jurisdictions are classifier context, not named semantic objects merely because Portuguese
  // places them after a preposition.
  "brasil", "brazil", "eua", "usa", "us", "estados unidos", "united states", "latam", "america latina", "europa", "europe",
]);

function governedEntityMentions(input: SemanticObjectExtractorInput): SemanticHeadMention[] {
  const text = input.latestUserMessage;
  const matches: SemanticHeadMention[] = [];
  for (const match of text.matchAll(INTRODUCED_ENTITY_PATTERN)) {
    const entity = match[1]!;
    if (ENTITY_HEAD_STOP.has(normalizeSearchText(entity))) continue;
    const start = match.index! + match[0].lastIndexOf(entity);
    matches.push({source: "latest_user_message", messageIndex: null, start, end: start + entity.length, text: entity, expectedKind: null});
  }
  for (const object of input.activeWorkContext?.objects ?? []) {
    const entity = object.slots.find(({key}) => key === "entity")?.value;
    if (!entity) continue;
    let start = text.toLocaleLowerCase(input.locale).indexOf(entity.toLocaleLowerCase(input.locale));
    while (start >= 0) {
      matches.push({source: "latest_user_message", messageIndex: null, start, end: start + entity.length, text: text.slice(start, start + entity.length), expectedKind: object.kind});
      start = text.toLocaleLowerCase(input.locale).indexOf(entity.toLocaleLowerCase(input.locale), start + entity.length);
    }
  }
  return matches;
}

function isProfessionalSelfDescriptionHead(text: string, mention: SemanticHeadMention): boolean {
  if (mention.expectedKind !== "provider") return false;
  const prefix = normalizeSearchText(text.slice(Math.max(0, mention.start - 80), mention.start));
  return /\b(?:sou|trabalho|atuo|meu cargo|my role|i work|i am)\b[^.!?]{0,60}$/.test(prefix);
}

function isExplicitlyIdentifiableHead(text: string, mention: SemanticHeadMention): boolean {
  if (mention.expectedKind === null) return true;
  const prefix = normalizeSearchText(text.slice(Math.max(0, mention.start - 24), mention.start));
  // "qual operação eu quero" names a missing class, not a resolvable operation instance.
  return !/\b(?:qual|quais|que|which|what)\s*$/.test(prefix);
}

function semanticHeadMentions(input: SemanticObjectExtractorInput): SemanticHeadMention[] {
  const text = input.latestUserMessage;
  const mentions: SemanticHeadMention[] = SEMANTIC_HEAD_PATTERNS.flatMap(({kind, pattern}) =>
    [...text.matchAll(new RegExp(pattern.source, pattern.flags))].map((match) => ({
      source: "latest_user_message" as const,
      messageIndex: null,
      start: match.index!, end: match.index! + match[0].length, text: match[0], expectedKind: kind,
    })).filter((mention) => !isProfessionalSelfDescriptionHead(text, mention)),
  );
  mentions.push(...governedEntityMentions(input));
  const ordered = mentions.sort((left, right) => left.start - right.start || right.end - left.end);
  const unique: SemanticHeadMention[] = [];
  for (const mention of ordered) {
    const duplicate = unique.find((existing) => existing.start === mention.start && existing.end === mention.end);
    if (duplicate) {
      if (duplicate.expectedKind === null && mention.expectedKind !== null) duplicate.expectedKind = mention.expectedKind;
      continue;
    }
    // A capitalized proper-name heuristic must not create a second head over a more specific
    // domain phrase (for example, "Project Finance").
    if (mention.expectedKind === null && unique.some((existing) => overlaps(existing, mention))) continue;
    unique.push(mention);
  }
  const sorted = unique.sort((left, right) => left.start - right.start || right.end - left.end);
  const coalesced: SemanticHeadMention[] = [];
  for (let index = 0; index < sorted.length; index += 1) {
    const current = sorted[index]!;
    const next = sorted[index + 1];
    // A proper name that contains a domain class is one referent ("Banco ABC"), even when the
    // independent named-entity pass and the domain vocabulary start at the same byte. Preserve
    // the code-owned domain kind and the widest attributable span.
    if (next && overlaps(current, next)
      && current.start <= next.start && current.end >= next.end
      && current.expectedKind === null && next.expectedKind !== null) {
      coalesced.push({...next, start: current.start, end: current.end, text: text.slice(current.start, current.end)});
      index += 1;
      continue;
    }
    if (next && overlaps(current, next)
      && current.expectedKind !== null && current.expectedKind === next.expectedKind) {
      coalesced.push({
        ...current,
        start: Math.min(current.start, next.start),
        end: Math.max(current.end, next.end),
        text: text.slice(Math.min(current.start, next.start), Math.max(current.end, next.end)),
      });
      index += 1;
      continue;
    }
    // A provider class immediately followed by its proper name is one referent, not two heads:
    // "banco JP Morgan" / "fundo Prisma Capital". This coalescing is deliberately narrow so
    // independent heads such as "Camil ... memo ... operação" remain separate.
    if (current.expectedKind === "provider" && next?.expectedKind === null
      && /^\s+$/u.test(text.slice(current.end, next.start))) {
      coalesced.push({...current, end: next.end, text: text.slice(current.start, next.end)});
      index += 1;
      continue;
    }
    // "precedentes e condições de mercado" names one market comparison set. This narrow
    // coalescer does not join repeated alternatives, instruments or other independently
    // selectable objects merely because they share a kind.
    if (current.expectedKind === "market" && next?.expectedKind === "market"
      && /^\s+(?:e|and)\s+(?:condiç(?:ão|ões)|condic(?:ao|oes)|conditions?)\s+(?:de|do|da|of)\s+$/iu.test(text.slice(current.end, next.start))) {
      coalesced.push({...current, end: next.end, text: text.slice(current.start, next.end)});
      index += 1;
      continue;
    }
    coalesced.push(current);
  }
  return coalesced;
}

const QUANTITY_PATTERN = /(?:\b(?:R\$|US\$|U\$|BRL|USD|EUR)\s*\d[\d.,]*(?:\s*(?:mil|milh(?:ao|oes)|million|billion|mn|bn|k))?|\b\d[\d.,]*\s*(?:%|bps?\b|basis points?\b|x\b|vezes\b|anos?\b|years?\b|mes(?:es)?\b|months?\b|paginas?\b|pages?\b)|\b(?:um|uma|dois|duas|tres|three|quatro|four|cinco|five|seis|six|sete|seven|oito|eight|nove|nine|dez|ten|onze|eleven|doze|twelve)\s+(?:anos?|years?|mes(?:es)?|months?|paginas?|pages?|planilhas?|spreadsheets?|fundos?|funds?)\b)/giu;

function quantityMentions(input: SemanticObjectExtractorInput, usedRecentMessageIndexes: ReadonlySet<number>): QuantityMention[] {
  const sources: Array<{source: QuantityMention["source"]; messageIndex: number | null; text: string}> = [
    {source: "latest_user_message", messageIndex: null, text: input.latestUserMessage},
    ...input.recentConversation.map((message, messageIndex) => ({source: "recent_user_message" as const, messageIndex, text: message.content}))
      .filter(({messageIndex}) => usedRecentMessageIndexes.has(messageIndex) && input.recentConversation[messageIndex]?.role === "user"),
  ];
  return sources.flatMap(({source, messageIndex, text}) => [...text.matchAll(QUANTITY_PATTERN)].map((match) => ({
    source, messageIndex, start: match.index!, end: match.index! + match[0].length, text: match[0],
  })));
}

const overlaps = (left: {source: string; messageIndex: number | null; start: number; end: number}, right: {source: string; messageIndex: number | null; start: number; end: number}): boolean =>
  left.source === right.source && left.messageIndex === right.messageIndex && left.start < right.end && right.start < left.end;

const sourceRank = (input: SemanticObjectExtractorInput, span: SemanticTextSpan): number => span.source === "latest_user_message"
  ? 0
  : 1 + (input.recentConversation.length - 1 - (span.messageIndex ?? 0));

function compareTextCandidates(input: SemanticObjectExtractorInput, left: z.infer<typeof semanticObjectCandidateSchema>, right: z.infer<typeof semanticObjectCandidateSchema>): number {
  const rank = sourceRank(input, left.head.span) - sourceRank(input, right.head.span);
  if (rank !== 0) return rank;
  if (left.head.span.start !== right.head.span.start) return left.head.span.start - right.head.span.start;
  const kind = intentObjectKindSchema.options.indexOf(left.kind) - intentObjectKindSchema.options.indexOf(right.kind);
  return kind !== 0 ? kind : left.candidateId.localeCompare(right.candidateId);
}

function addIssue(issues: z.infer<typeof coverageIssueSchema>[], code: z.infer<typeof coverageIssueSchema>["code"], detail: string, severity: "error" | "warning" = "error"): void {
  issues.push({code, severity, detail: detail.slice(0, 600)});
}

/**
 * Converts attributable candidates into canonical object instances. Any structural, source,
 * normalization or coverage error fails closed: diagnostic objects remain visible, but
 * usableObjects is empty until the complete extraction passes.
 */
export function compileSemanticObjects(
  rawInput: SemanticObjectExtractorInput,
  rawOutput: z.input<typeof semanticObjectExtractorOutputSchema>,
): SemanticObjectCompilation {
  const input = semanticObjectExtractorInputSchema.parse(rawInput);
  const output = semanticObjectExtractorOutputSchema.parse(rawOutput);
  const issues: z.infer<typeof coverageIssueSchema>[] = [];
  let sourceSpansChecked = 0;
  let activeContextReferencesChecked = 0;
  const normalized: Array<Omit<NormalizedSemanticObject, "id" | "ordinal">> = [];
  const modifierSpans: SemanticTextSpan[] = [];
  const acceptedHeads: Array<{span: SemanticTextSpan; kind: z.infer<typeof intentObjectKindSchema>}> = [];
  const usedRecentMessageIndexes = new Set<number>();

  for (const candidate of [...output.objects].sort((left, right) => compareTextCandidates(input, left, right))) {
    const spans = [candidate.head.span, ...candidate.modifiers.map(({span}) => span)];
    for (const span of spans) if (span.source === "recent_user_message" && span.messageIndex !== null) usedRecentMessageIndexes.add(span.messageIndex);
    let candidateValid = true;
    for (const span of spans) {
      sourceSpansChecked += 1;
      const validity = validateSpan(input, span);
      if (validity === "assistant") {
        addIssue(issues, "assistant_text_is_not_evidence", `${candidate.candidateId} cites assistant message ${span.messageIndex}`);
        candidateValid = false;
      } else if (validity === "invalid") {
        addIssue(issues, "invalid_source_span", `${candidate.candidateId} has a span that does not reproduce its source: ${span.text}`);
        candidateValid = false;
      } else if (span.source !== "latest_user_message") {
        addIssue(issues, "historical_text_is_not_governed_context", `${candidate.candidateId} attempts to promote historical user text: ${span.text}`);
        candidateValid = false;
      }
    }
    const slotCandidates = [{key: candidate.head.key as IntentObjectSlotKey, span: candidate.head.span}, ...candidate.modifiers];
    const slots: Array<{key: IntentObjectSlotKey; value: string}> = [];
    for (const slot of slotCandidates) {
      if (!SLOT_COMPATIBILITY[candidate.kind].has(slot.key)) {
        addIssue(issues, "invalid_slot_for_kind", `${slot.key} is not valid for ${candidate.kind}`);
        candidateValid = false;
        continue;
      }
      const value = normalizeSlotValue(slot.key, slot.span.text, candidate.kind);
      if (value === null) {
        addIssue(issues, "normalization_failed", `${slot.key} could not be normalized from: ${slot.span.text}`);
        candidateValid = false;
        continue;
      }
      slots.push({key: slot.key, value});
      if (slot.key !== "entity" && slot.key !== "subject") modifierSpans.push(slot.span);
    }
    if (candidateValid) {
      acceptedHeads.push({span: candidate.head.span, kind: candidate.kind});
      normalized.push({
        kind: candidate.kind,
        slots: slots.sort((left, right) => intentObjectSlotKeySchema.options.indexOf(left.key) - intentObjectSlotKeySchema.options.indexOf(right.key)),
        source: {type: "text", spans},
      });
    }
  }

  const context = input.activeWorkContext;
  const contextOrdinal = new Map(context?.objects.map((object) => [object.id, object.ordinal]) ?? []);
  const contextReferences = [...output.activeContextReferences].sort((left, right) =>
    (contextOrdinal.get(left.contextObjectId) ?? Number.MAX_SAFE_INTEGER) - (contextOrdinal.get(right.contextObjectId) ?? Number.MAX_SAFE_INTEGER)
      || left.contextObjectId.localeCompare(right.contextObjectId));
  for (const reference of contextReferences) {
    activeContextReferencesChecked += 1;
    sourceSpansChecked += 1;
    const validity = validateSpan(input, reference.trigger);
    if (validity === "assistant") addIssue(issues, "assistant_text_is_not_evidence", `context trigger cites assistant message ${reference.trigger.messageIndex}`);
    else if (validity === "invalid") addIssue(issues, "invalid_source_span", `context trigger does not reproduce its source: ${reference.trigger.text}`);
    else if (reference.trigger.source !== "latest_user_message") addIssue(issues, "historical_text_is_not_governed_context", `context trigger must be in the current turn: ${reference.trigger.text}`);
    if (!context) {
      addIssue(issues, "unknown_context_object", `no active work context contains ${reference.contextObjectId}`);
      continue;
    }
    if (context.state !== "active") {
      addIssue(issues, "context_not_active", `context ${context.contextId} is ${context.state}`);
      continue;
    }
    const object = context.objects.find(({id}) => id === reference.contextObjectId);
    if (!object) {
      addIssue(issues, "unknown_context_object", `${reference.contextObjectId} is not in governed context ${context.contextId}`);
      continue;
    }
    if (validity !== "valid" || reference.trigger.source !== "latest_user_message") continue;
    normalized.push({
      kind: object.kind,
      slots: [...object.slots].sort((left, right) => intentObjectSlotKeySchema.options.indexOf(left.key) - intentObjectSlotKeySchema.options.indexOf(right.key)),
      source: {type: "active_work_context", contextId: context.contextId, contextRevision: context.revision, contextObjectId: object.id, trigger: reference.trigger},
    });
  }

  for (const unresolved of output.unresolvedReferences) {
    sourceSpansChecked += 1;
    const validity = validateSpan(input, unresolved.span);
    if (validity === "assistant") addIssue(issues, "assistant_text_is_not_evidence", `unresolved reference cites assistant message ${unresolved.span.messageIndex}`);
    else if (validity === "invalid") addIssue(issues, "invalid_source_span", `unresolved reference span does not reproduce its source: ${unresolved.span.text}`);
    else if (unresolved.span.source !== "latest_user_message") addIssue(issues, "historical_text_is_not_governed_context", `unresolved reference must be attributable to the current turn: ${unresolved.span.text}`);
    addIssue(issues, "unresolved_reference", `${unresolved.reason}: ${unresolved.span.text}`);
  }

  const excluded = output.excludedQuantitativeSpans.filter((entry) => {
    const {span} = entry;
    sourceSpansChecked += 1;
    const validity = validateSpan(input, span);
    if (validity === "valid" && span.source === "latest_user_message" && exclusionIsSupported(input, entry)) return true;
    if (validity === "valid") {
      addIssue(issues, span.source === "latest_user_message" ? "invalid_exclusion_reason" : "historical_text_is_not_governed_context", `${entry.reason} is not supported by its source context: ${span.text}`);
      return false;
    }
    addIssue(issues, validity === "assistant" ? "assistant_text_is_not_evidence" : "invalid_source_span", `excluded span is not valid user evidence: ${span.text}`);
    return false;
  });

  const semanticExclusions = output.excludedSemanticHeadSpans.filter((entry) => {
    sourceSpansChecked += 1;
    const validity = validateSpan(input, entry.span);
    if (validity === "valid" && entry.span.source === "latest_user_message" && exclusionIsSupported(input, entry)) return true;
    if (validity === "valid") {
      addIssue(issues, entry.span.source === "latest_user_message" ? "invalid_exclusion_reason" : "historical_text_is_not_governed_context", `${entry.reason} is not supported by its source context: ${entry.span.text}`);
      return false;
    }
    addIssue(issues, validity === "assistant" ? "assistant_text_is_not_evidence" : "invalid_source_span", `excluded semantic head is not valid user evidence: ${entry.span.text}`);
    return false;
  });

  const quantities = quantityMentions(input, usedRecentMessageIndexes);
  let quantitativeMentionsCovered = 0;
  for (const quantity of quantities) {
    const covered = modifierSpans.some((span) => overlaps(quantity, span))
      || excluded.some(({span}) => overlaps(quantity, span));
    if (covered) quantitativeMentionsCovered += 1;
    else addIssue(issues, "uncovered_quantitative_mention", `${quantity.text} at ${quantity.source}:${quantity.messageIndex ?? "latest"}:${quantity.start}`);
  }

  const heads = semanticHeadMentions(input);
  let semanticHeadMentionsCovered = 0;
  for (const head of heads) {
    const claimingHeads = acceptedHeads.filter(({span}) => overlaps(head, span));
    const unresolvedHead = output.unresolvedReferences.some(({span}) => span.source === "latest_user_message" && overlaps(head, span));
    const explicitlyAccounted = unresolvedHead || semanticExclusions.some(({span}) => overlaps(head, span));
    if (claimingHeads.length === 1 || explicitlyAccounted) semanticHeadMentionsCovered += 1;
    if (unresolvedHead && isExplicitlyIdentifiableHead(input.latestUserMessage, head)) {
      addIssue(issues, "explicit_semantic_head_marked_unresolved", `${head.expectedKind ?? "named_entity"}:${head.text} is explicitly identifiable in the current turn`);
    }
    if (claimingHeads.length === 0 && !explicitlyAccounted) {
      addIssue(issues, "uncovered_semantic_head", `${head.expectedKind ?? "named_entity"}:${head.text} at latest:${head.start}`);
    } else if (claimingHeads.length > 1) {
      addIssue(issues, "semantic_head_multiply_claimed", `${head.text} is claimed by ${claimingHeads.length} object heads`);
    }
  }
  for (const {span: candidateHead} of acceptedHeads) {
    const claimed = heads.filter((head) => overlaps(head, candidateHead));
    if (claimed.length > 1) {
      addIssue(issues, "merged_semantic_heads", `${candidateHead.text} merges independently detected heads: ${claimed.map(({text}) => text).join(" | ")}`);
    }
  }

  const seenAtomicObjects = new Set<string>();
  for (const object of normalized) {
    const identity = fingerprintJson({kind: object.kind, slots: object.slots, source: object.source});
    if (seenAtomicObjects.has(identity)) addIssue(issues, "duplicate_atomic_object", `${object.kind} is duplicated with the same source and slots`);
    seenAtomicObjects.add(identity);
  }
  if (normalized.length > intentObjectCardinalityLimit) {
    addIssue(issues, "object_cardinality_exceeded", `${normalized.length} objects exceed the per-turn limit of ${intentObjectCardinalityLimit}`);
  }
  if (normalized.length === 0) addIssue(issues, "no_semantic_object", "the extraction did not establish any attributable semantic object");

  const objects = normalized.map((object, index) => normalizedSemanticObjectSchema.parse({
    ...object, id: `object-${index + 1}`, ordinal: index + 1,
  }));
  const hasStructuralError = issues.some(({code, severity}) => severity === "error"
    && code !== "unresolved_reference" && code !== "uncovered_quantitative_mention"
    && code !== "uncovered_semantic_head" && code !== "object_cardinality_exceeded"
    && code !== "no_semantic_object");
  const status = hasStructuralError ? "rejected" as const : issues.some(({severity}) => severity === "error") ? "incomplete" as const : "complete" as const;
  const body = {
    schemaVersion: "semantic-object-compilation.v1" as const,
    status,
    objects,
    usableObjects: status === "complete" ? objects : [],
    coverage: {
      sourceSpansChecked,
      quantitativeMentions: quantities.length,
      quantitativeMentionsCovered,
      semanticHeadMentions: heads.length,
      semanticHeadMentionsCovered,
      activeContextReferencesChecked,
      issues,
    },
  };
  return semanticObjectCompilationSchema.parse({...body, fingerprint: fingerprintJson(body)});
}

/**
 * Content-free acceptance result for a model gateway. JSON shape is only the first boundary: an
 * extractor attempt is successful only when deterministic source, normalization and coverage
 * compilation is complete. Stable codes let the gateway repair/fallback without echoing customer
 * text into prompts or telemetry.
 */
export function validateSemanticObjectOutput(
  input: SemanticObjectExtractorInput,
  output: SemanticObjectExtractorOutput,
): {accepted: true} | {accepted: false; issues: Array<{path: string; code: string; message: string}>} {
  const compilation = compileSemanticObjects(input, output);
  if (compilation.status === "complete") return {accepted: true};
  // An extractor may legitimately establish that the current turn has no attributable object
  // or that its reference cannot be resolved from governed work memory. That is a successful,
  // fail-closed abstention, not malformed provider output and therefore must not consume a repair
  // or provider fallback. Coverage omissions, invalid spans, cardinality breaches and every
  // structural rejection remain validation failures.
  const honestAbstentionCodes = new Set(["unresolved_reference", "no_semantic_object"]);
  if (compilation.status === "incomplete"
    && compilation.coverage.issues.length > 0
    && compilation.coverage.issues.every(({code}) => honestAbstentionCodes.has(code))) {
    return {accepted: true};
  }
  const issues = compilation.coverage.issues.slice(0, 12).map((issue, index) => ({
    path: `coverage.issues.${index}`,
    code: issue.code,
    message: `Deterministic semantic-object validation failed: ${issue.code}.`,
  }));
  return {
    accepted: false,
    issues: issues.length > 0 ? issues : [{
      path: "coverage",
      code: "semantic_object_coverage_incomplete",
      message: "Deterministic semantic-object coverage is incomplete.",
    }],
  };
}

/**
 * Pure orchestration seam for the gateway/worker. The classifier remains responsible for intent;
 * this function replaces only its object field after independent semantic compilation. An
 * incomplete or rejected extraction clears asserted object meaning so canonicalization abstains
 * rather than falling back to the classifier's bundled object guess.
 */
export function applySemanticObjectCompilation(
  rawIntent: IntentClassifierOutput,
  rawCompilation: SemanticObjectCompilation,
): IntentClassifierOutput {
  const intent = intentClassifierOutputSchema.parse(rawIntent);
  const compilation = semanticObjectCompilationSchema.parse(rawCompilation);
  if (compilation.status !== "complete" || compilation.usableObjects.length === 0) {
    return intentClassifierOutputSchema.parse({
      ...intent,
      routingCore: {
        ...intent.routingCore,
        object: {
          value: [], state: "unknown", confidence: null,
          basis: `semantic object compilation ${compilation.status}:${compilation.fingerprint.slice(0, 16)}`,
        },
      },
      abstain: true,
      abstainReason: "semantic_object_coverage_incomplete",
    });
  }
  return intentClassifierOutputSchema.parse({
    ...intent,
    routingCore: {
      ...intent.routingCore,
      object: {
        value: compilation.usableObjects.map(({id, ordinal, kind, slots}) => ({id, ordinal, kind, slots})),
        ...(compilation.usableObjects.every(({source}) => source.type === "text")
          ? {
              state: "explicit" as const,
              confidence: null,
              basis: `attributable current-turn semantic object compilation:${compilation.fingerprint.slice(0, 16)}`,
            }
          : {
              state: "inferred" as const,
              // A verified span proves attribution, not that a pronoun-to-context match is certain.
              // Preserve the router's calibrated uncertainty and cap it below certainty.
              confidence: Math.min(intent.routingCore.object.confidence ?? 0.5, 0.95),
              basis: `governed context reference semantic object compilation:${compilation.fingerprint.slice(0, 16)}`,
            }),
      },
    },
  });
}

