/**
 * Financial definitions (Blueprint §15.2). Definitions are parameters of a
 * transaction, never hidden constants: the financial-core receives them
 * explicitly and records the definition id + version in every calculation trace.
 * The platform never suggests a single universal EBITDA/CFADS/DSCR exists.
 */
export type FinancialDefinition = {
  id: string;
  version: string;
  labels: {pt: string; en: string};
  /** Human-readable formula using account codes / metric ids. */
  formula: string;
  inputs: string[];
  notes: {pt: string; en: string};
};

export const financialDefinitions: readonly FinancialDefinition[] = [
  {
    id: "adjusted_ebitda",
    version: "v1",
    labels: {pt: "EBITDA ajustado", en: "Adjusted EBITDA"},
    formula: "is_ebitda + approved_nonrecurring_expenses - nonrecurring_income - unsupported_or_low_confidence_addbacks",
    inputs: ["is_ebitda", "approved_nonrecurring_expenses", "nonrecurring_income", "unsupported_or_low_confidence_addbacks"],
    notes: {
      pt: "Cada ajuste é aprovado individualmente com fonte; add-backs sem suporte não entram.",
      en: "Each adjustment is approved individually with a source; unsupported add-backs are excluded.",
    },
  },
  {
    id: "cfads",
    version: "v1",
    labels: {pt: "CFADS", en: "CFADS"},
    formula: "adjusted_ebitda - taxes_paid - maintenance_capex - normalized_working_capital_investment - fixed_charges_not_yet_reflected +/- approved_cash_adjustments",
    inputs: ["adjusted_ebitda", "taxes_paid", "maintenance_capex", "normalized_working_capital_investment", "fixed_charges_not_yet_reflected", "approved_cash_adjustments"],
    notes: {
      pt: "Capex de manutenção e capital de giro normalizado são premissas explícitas por transação.",
      en: "Maintenance capex and normalized working capital are explicit per-transaction assumptions.",
    },
  },
  {
    id: "dscr",
    version: "v1",
    labels: {pt: "DSCR", en: "DSCR"},
    formula: "cfads / scheduled_cash_debt_service",
    inputs: ["cfads", "scheduled_cash_debt_service"],
    notes: {pt: "Serviço da dívida em caixa programado (principal + juros) do período.", en: "Scheduled cash debt service (principal + interest) for the period."},
  },
  {
    id: "interest_coverage",
    version: "v1",
    labels: {pt: "Cobertura de juros", en: "Interest coverage"},
    formula: "selected_earnings_measure / cash_interest_paid",
    inputs: ["selected_earnings_measure", "cash_interest_paid"],
    notes: {pt: "A medida de resultado (EBITDA, EBITDA ajustado, EBIT) é escolhida por transação.", en: "The earnings measure (EBITDA, adjusted EBITDA, EBIT) is chosen per transaction."},
  },
  {
    id: "collateral_coverage",
    version: "v1",
    labels: {pt: "Cobertura de garantias", en: "Collateral coverage"},
    formula: "eligible_value_after_haircut / secured_exposure",
    inputs: ["eligible_value_after_haircut", "secured_exposure"],
    notes: {pt: "Haircuts vêm da política vigente e ficam registrados por ativo.", en: "Haircuts come from the current policy and are recorded per asset."},
  },
  {
    id: "net_debt",
    version: "v1",
    labels: {pt: "Dívida líquida", en: "Net debt"},
    formula: "gross_debt - cash - short_term_investments",
    inputs: ["gross_debt", "cash", "short_term_investments"],
    notes: {pt: "Aplicações restritas podem ser excluídas por decisão registrada.", en: "Restricted investments may be excluded by a recorded decision."},
  },
  {
    id: "leverage",
    version: "v1",
    labels: {pt: "Alavancagem", en: "Leverage"},
    formula: "net_debt / adjusted_ebitda_ltm",
    inputs: ["net_debt", "adjusted_ebitda_ltm"],
    notes: {pt: "LTM sempre derivado (anual anterior + YTD atual − YTD anterior).", en: "LTM is always derived (prior annual + current YTD − prior YTD)."},
  },
];

export const financialDefinitionMap: ReadonlyMap<string, FinancialDefinition> = new Map(financialDefinitions.map((d) => [d.id, d]));

export function financialDefinition(id: string): FinancialDefinition {
  const found = financialDefinitionMap.get(id);
  if (!found) throw new Error(`unknown financial definition: ${id}`);
  return found;
}

packages/credit-ontology/src/jurisdictio.content:
import {z} from "zod";

/**
 * Language and jurisdiction are independent dimensions.
 *
 * A project may be operated in Portuguese while analysing US debt, or compiled in English from
 * Brazilian source documents. Evidence always preserves its original language; translations are
 * attributed projections and never replace the source. Cross-border concept bridges state the
 * quality of the relationship instead of pretending that two legal instruments are identical.
 */
export const advisorLocaleSchema = z.enum(["pt-BR", "en-US"]);
export type AdvisorLocale = z.infer<typeof advisorLocaleSchema>;

export const debtJurisdictionSchema = z.enum(["BR", "US"]);
export type DebtJurisdiction = z.infer<typeof debtJurisdictionSchema>;

export const sourceLanguageSchema = z.enum(["pt-BR", "en-US", "mixed", "other"]);
export type SourceLanguage = z.infer<typeof sourceLanguageSchema>;

export const outputLanguageModeSchema = z.enum(["pt-BR", "en-US", "bilingual"]);
export type OutputLanguageMode = z.infer<typeof outputLanguageModeSchema>;

export const accountingFrameworkSchema = z.enum([
  "br_gaap_cpc_ifrs",
  "ifrs",
  "us_gaap",
  "other",
  "unknown",
]);
export type AccountingFramework = z.infer<typeof accountingFrameworkSchema>;

export const debtJurisdictionProfileSchema = z.object({
  primary: debtJurisdictionSchema,
  relevant: z.array(debtJurisdictionSchema).min(1).max(2),
  crossBorder: z.boolean(),
  reportingFrameworks: z.array(accountingFrameworkSchema).min(1).max(4),
  currencies: z.array(z.enum(["BRL", "USD", "other"])).min(1).max(3),
}).superRefine((value, context) => {
  if (new Set(value.relevant).size !== value.relevant.length) {
    context.addIssue({code: "custom", path: ["relevant"], message: "relevant jurisdictions must be unique"});
  }
  if (!value.relevant.includes(value.primary)) {
    context.addIssue({code: "custom", path: ["relevant"], message: "primary jurisdiction must be relevant"});
  }
  if (value.crossBorder !== (value.relevant.length > 1)) {
    context.addIssue({code: "custom", path: ["crossBorder"], message: "crossBorder must reflect the jurisdiction set"});
  }
});
export type DebtJurisdictionProfile = z.infer<typeof debtJurisdictionProfileSchema>;

export const advisorLanguagePolicySchema = z.object({
  workingLocale: advisorLocaleSchema,
  sourceLanguages: z.array(sourceLanguageSchema).min(1).max(4),
  outputMode: outputLanguageModeSchema,
  allowLanguageSwitch: z.literal(true),
  preserveOriginalEvidence: z.literal(true),
  instantWorkingTranslation: z.literal(true),
  reviewedExternalMaterials: z.literal(true),
});
export type AdvisorLanguagePolicy = z.infer<typeof advisorLanguagePolicySchema>;

export const evidenceTranslationSchema = z.object({
  locale: advisorLocaleSchema,
  text: z.string().trim().min(1).max(20_000),
  status: z.enum(["machine_draft", "reviewed", "approved"]),
  modelOrReviewer: z.string().trim().min(1).max(240),
  sourceFingerprint: z.string().regex(/^[0-9a-f]{64}$/),
});

export const localizedEvidenceTextSchema = z.object({
  sourceText: z.string().trim().min(1).max(20_000),
  sourceLanguage: sourceLanguageSchema,
  sourceRef: z.string().trim().min(1).max(500),
  sourceFingerprint: z.string().regex(/^[0-9a-f]{64}$/),
  translations: z.array(evidenceTranslationSchema).max(2).default([]),
}).superRefine((value, context) => {
  const locales = new Set<string>();
  value.translations.forEach((translation, index) => {
    if (translation.sourceFingerprint !== value.sourceFingerprint) {
      context.addIssue({code: "custom", path: ["translations", index, "sourceFingerprint"], message: "translation must point to the original evidence fingerprint"});
    }
    if (locales.has(translation.locale)) {
      context.addIssue({code: "custom", path: ["translations", index, "locale"], message: "translation locale must be unique"});
    }
    locales.add(translation.locale);
  });
});
export type LocalizedEvidenceText = z.infer<typeof localizedEvidenceTextSchema>;

export const jurisdictionConceptBridgeSchema = z.object({
  canonicalConceptId: z.string().regex(/^[a-z0-9_.-]{3,120}$/),
  fromJurisdiction: debtJurisdictionSchema,
  fromTerm: z.string().trim().min(1).max(240),
  toJurisdiction: debtJurisdictionSchema,
  toTerm: z.string().trim().min(1).max(240).nullable(),
  relationship: z.enum(["exact", "functional", "partial", "no_direct_equivalent"]),
  caveats: z.array(z.string().trim().min(1).max(1_000)).min(1).max(12),
  asOfDate: z.iso.date(),
  sourceRefs: z.array(z.string().trim().min(1).max(500)).min(1).max(20),
}).superRefine((value, context) => {
  if (value.fromJurisdiction === value.toJurisdiction) {
    context.addIssue({code: "custom", path: ["toJurisdiction"], message: "a bridge must cross jurisdictions"});
  }
  if (value.relationship === "no_direct_equivalent" && value.toTerm !== null) {
    context.addIssue({code: "custom", path: ["toTerm"], message: "no direct equivalent cannot name an equivalent term"});
  }
  if (value.relationship !== "no_direct_equivalent" && value.toTerm === null) {
    context.addIssue({code: "custom", path: ["toTerm"], message: "mapped relationships require a target term"});
  }
});
export type JurisdictionConceptBridge = z.infer<typeof jurisdictionConceptBridgeSchema>;

export const debtKnowledgeLayerSchema = z.enum([
  "universal_debt_core",
  "br_debt",
  "us_debt",
  "br_us_bridge",
  "sector",
  "instrument",
  "market_current",
]);

export const debtKnowledgePackRequirementSchema = z.object({
  id: z.string().regex(/^[a-z0-9_.-]{3,120}$/),
  layer: debtKnowledgeLayerSchema,
  jurisdictions: z.array(debtJurisdictionSchema).max(2),
  supportedLocales: z.array(advisorLocaleSchema).min(2).max(2),
  responsibilities: z.array(z.string().trim().min(3).max(500)).min(1).max(20),
  requiresDatedSources: z.boolean(),
});
export type DebtKnowledgePackRequirement = z.infer<typeof debtKnowledgePackRequirementSchema>;

export const debtKnowledgeFreshnessSchema = z.enum([
  "foundational",
  "accounting",
  "regulatory",
  "market_terms",
  "transaction_comparable",
  "lender_mandate",
]);
export type DebtKnowledgeFreshness = z.infer<typeof debtKnowledgeFreshnessSchema>;

export const debtKnowledgeAccessSchema = z.enum([
  "public",
  "house_private",
  "organization_private",
  "project_private",
]);
export type DebtKnowledgeAccess = z.infer<typeof debtKnowledgeAccessSchema>;

export const debtKnowledgeRecordSchema = z.object({
  id: z.string().regex(/^[a-z0-9_.-]{3,160}$/),
  canonicalConceptId: z.string().regex(/^[a-z0-9_.-]{3,120}$/),
  layer: debtKnowledgeLayerSchema,
  jurisdictions: z.array(debtJurisdictionSchema).max(2),
  language: sourceLanguageSchema,
  title: z.string().trim().min(3).max(500),
  content: z.string().trim().min(3).max(100_000),
  source: z.object({
    ref: z.string().trim().min(1).max(1_000),
    publisher: z.string().trim().min(1).max(500),
    type: z.enum([
      "law_or_regulation",
      "accounting_standard",
      "company_filing",
      "transaction_document",
      "market_data",
      "authoritative_reference",
      "house_observation",
    ]),
    publishedAt: z.iso.datetime().optional(),
    effectiveFrom: z.iso.date().optional(),
    retrievedAt: z.iso.datetime(),
  }),
  asOfDate: z.iso.date(),
  validUntil: z.iso.date().optional(),
  freshness: debtKnowledgeFreshnessSchema,
  version: z.string().trim().min(1).max(120),
  status: z.enum(["draft", "reviewed", "approved", "deprecated"]),
  access: debtKnowledgeAccessSchema,
  reuseScope: z.enum(["global", "organization", "project"]),
  sourceFingerprint: z.string().regex(/^[0-9a-f]{64}$/),
  reviewedAt: z.iso.datetime().optional(),
}).superRefine((value, context) => {
  const expectedJurisdictions: Partial<Record<z.infer<typeof debtKnowledgeLayerSchema>, DebtJurisdiction[]>> = {
    br_debt: ["BR"],
    us_debt: ["US"],
    br_us_bridge: ["BR", "US"],
  };
  const expected = expectedJurisdictions[value.layer];
  if (expected && (expected.length !== value.jurisdictions.length || expected.some((item) => !value.jurisdictions.includes(item)))) {
    context.addIssue({code: "custom", path: ["jurisdictions"], message: "knowledge layer and jurisdictions disagree"});
  }
  const validReuse = value.reuseScope === "global"
    ? ["public", "house_private"].includes(value.access)
    : value.reuseScope === "organization"
      ? value.access === "organization_private"
      : value.access === "project_private";
  if (!validReuse) {
    context.addIssue({code: "custom", path: ["reuseScope"], message: "private knowledge cannot cross its authorized scope"});
  }
  if (["reviewed", "approved"].includes(value.status) && !value.reviewedAt) {
    context.addIssue({code: "custom", path: ["reviewedAt"], message: "reviewed knowledge requires review time"});
  }
});
export type DebtKnowledgeRecord = z.infer<typeof debtKnowledgeRecordSchema>;

/**
 * A locale change recompiles a presentation from the same canonical artifact and Deal State.
 * It never creates a second economic case or treats translated prose as new evidence.
 */
export const localizedArtifactProjectionSchema = z.object({
  artifactId: z.string().uuid(),
  canonicalContentFingerprint: z.string().regex(/^[0-9a-f]{64}$/),
  economicStateFingerprint: z.string().regex(/^[0-9a-f]{64}$/),
  sourceLocale: advisorLocaleSchema,
  outputLocale: advisorLocaleSchema,
  translationStatus: z.enum(["not_required", "machine_draft", "reviewed", "approved"]),
  generatedAt: z.iso.datetime(),
}).superRefine((value, context) => {
  if (value.sourceLocale === value.outputLocale && value.translationStatus !== "not_required") {
    context.addIssue({code: "custom", path: ["translationStatus"], message: "same-locale projection does not require translation"});
  }
  if (value.sourceLocale !== value.outputLocale && value.translationStatus === "not_required") {
    context.addIssue({code: "custom", path: ["translationStatus"], message: "cross-locale projection must expose translation status"});
  }
});
export type LocalizedArtifactProjection = z.infer<typeof localizedArtifactProjectionSchema>;

export const requiredDebtKnowledgePacks = [
  {
    id: "debt.universal.core",
    layer: "universal_debt_core",
    jurisdictions: [],
    supportedLocales: ["pt-BR", "en-US"],
    responsibilities: [
      "financial analysis, capacity, capital structure and risk allocation independent of jurisdiction",
      "canonical concept identifiers, calculations and evidence classes",
    ],
    requiresDatedSources: false,
  },
  {
    id: "debt.br.jurisdiction",
    layer: "br_debt",
    jurisdictions: ["BR"],
    supportedLocales: ["pt-BR", "en-US"],
    responsibilities: [
      "Brazilian instruments, providers, security mechanics, documentation and market practice",
      "Brazilian accounting, regulatory and market references with authoritative sources",
    ],
    requiresDatedSources: true,
  },
  {
    id: "debt.us.jurisdiction",
    layer: "us_debt",
    jurisdictions: ["US"],
    supportedLocales: ["pt-BR", "en-US"],
    responsibilities: [
      "US instruments, providers, security mechanics, documentation and market practice",
      "US accounting, regulatory and market references with authoritative sources",
    ],
    requiresDatedSources: true,
  },
  {
    id: "debt.br-us.bridge",
    layer: "br_us_bridge",
    jurisdictions: ["BR", "US"],
    supportedLocales: ["pt-BR", "en-US"],
    responsibilities: [
      "concept-by-concept BR/US mappings with explicit equivalence quality and caveats",
      "cross-border currency, accounting, structural, documentation and market-execution differences",
    ],
    requiresDatedSources: true,
  },
] as const satisfies readonly DebtKnowledgePackRequirement[];

packages/credit-ontology/src/reconciliat.content:
import {z} from "zod";

export const exceptionSeveritySchema = z.enum(["critical", "high", "medium", "low"]);
export type ExceptionSeverity = z.infer<typeof exceptionSeveritySchema>;

export const exceptionTypeSchema = z.enum(["arithmetic", "period", "entity", "source_conflict", "missing", "plausibility", "validation", "quality", "adjustment"]);
export type ExceptionType = z.infer<typeof exceptionTypeSchema>;

export const exceptionOwnerRoleSchema = z.enum(["company", "internal_analyst", "external_advisor"]);
export type ExceptionOwnerRole = z.infer<typeof exceptionOwnerRoleSchema>;

export type Tolerance = {kind: "absolute"; amount: string} | {kind: "relative"; ratio: string} | {kind: "none"};

export type ReconciliationRule = {
  id: string;
  titles: {pt: string; en: string};
  type: ExceptionType;
  defaultSeverity: ExceptionSeverity;
  tolerance: Tolerance;
  ownerRole: ExceptionOwnerRole;
  /** Why the rule exists — shown in the UI ("por que essa regra existe"). */
  rationale: {pt: string; en: string};
  /** Whether a critical breach blocks external outputs while open (Blueprint §14.2). */
  blocksExternalOutputsWhenCritical: boolean;
};

const rule = (id: string, pt: string, en: string, type: ExceptionType, defaultSeverity: ExceptionSeverity, tolerance: Tolerance, ownerRole: ExceptionOwnerRole, rationalePt: string, rationaleEn: string, blocks = true): ReconciliationRule => ({
  id,
  titles: {pt, en},
  type,
  defaultSeverity,
  tolerance,
  ownerRole,
  rationale: {pt: rationalePt, en: rationaleEn},
  blocksExternalOutputsWhenCritical: blocks,
});

export const reconciliationRules: readonly ReconciliationRule[] = [
  rule("R1", "Ativo = Passivo + PL por período", "Assets = liabilities + equity per period", "arithmetic", "critical", {kind: "relative", ratio: "0.005"}, "internal_analyst", "Um balanço que não fecha invalida qualquer análise de estrutura de capital.", "A balance sheet that does not balance invalidates any capital-structure analysis."),
  rule("R2", "Caixa inicial + fluxos = caixa final", "Opening cash + flows = closing cash", "arithmetic", "high", {kind: "relative", ratio: "0.005"}, "internal_analyst", "O fluxo de caixa precisa reconciliar com o balanço para que CFADS e DSCR sejam confiáveis.", "The cash-flow statement must reconcile to the balance sheet for CFADS and DSCR to be trustworthy."),
  rule("R3", "Fato material reconcilia entre fontes (auditado × gerencial × carta × deck)", "Material fact reconciles across sources", "source_conflict", "high", {kind: "relative", ratio: "0.01"}, "company", "Diferenças entre fontes escondem ajustes, períodos ou entidades distintas; um financiador vai perguntar.", "Differences between sources hide adjustments, periods, or entities; a lender will ask."),
  rule("R4", "Saldo de dívida (balanço) = mapa de dívida = contratos", "Debt balance = debt schedule = agreements", "source_conflict", "critical", {kind: "relative", ratio: "0.01"}, "company", "A dívida existente define a capacidade incremental; qualquer diferença altera a estrutura proposta.", "Existing debt defines incremental capacity; any difference changes the proposed structure."),
  rule("R5", "Despesa financeira ≈ dívida média × taxa (direcional)", "Financial expense ≈ average debt × rate (directional)", "plausibility", "medium", {kind: "relative", ratio: "0.25"}, "internal_analyst", "Despesa financeira incompatível com o estoque de dívida sugere dívida não mapeada ou taxa errada.", "Financial expense inconsistent with the debt stock suggests unmapped debt or a wrong rate."),
  rule("R6", "Contas a receber/pagar = agings", "Receivables/payables = agings", "source_conflict", "high", {kind: "relative", ratio: "0.02"}, "company", "Agings sustentam garantias de recebíveis e capital de giro.", "Agings underpin receivables collateral and working capital."),
  rule("R7", "Estoques compatíveis com métricas do setor (dias)", "Inventory consistent with sector metrics (days)", "plausibility", "medium", {kind: "none"}, "internal_analyst", "Dias de estoque fora do padrão setorial pedem explicação (obsolescência, sazonalidade, erro de escala).", "Inventory days outside sector norms require explanation (obsolescence, seasonality, scale error)."),
  rule("R8", "Períodos e moedas normalizados; sem coluna mista", "Periods and currencies normalized; no mixed columns", "period", "high", {kind: "none"}, "internal_analyst", "Séries com períodos ou moedas misturados produzem métricas sem sentido.", "Series with mixed periods or currencies produce meaningless metrics."),
  rule("R9", "Consolidado e por entidade não misturados", "Consolidated and standalone not mixed", "entity", "critical", {kind: "none"}, "internal_analyst", "Misturar controladora e consolidado distorce alavancagem e cobertura.", "Mixing parent-only and consolidated figures distorts leverage and coverage."),
  rule("R10", "Ajustes não recorrentes identificados, com fonte, aprovados separadamente", "Non-recurring adjustments identified, sourced, approved separately", "adjustment", "high", {kind: "none"}, "internal_analyst", "Add-backs sem suporte inflam o EBITDA ajustado e a capacidade.", "Unsupported add-backs inflate adjusted EBITDA and capacity."),
  rule("R11", "Montante pedido = usos; fontes = usos", "Requested amount = uses; sources = uses", "arithmetic", "high", {kind: "relative", ratio: "0.01"}, "company", "Fontes e usos que não fecham indicam pedido mal dimensionado.", "Sources and uses that do not tie indicate a mis-sized request."),
