import Decimal from "decimal.js";

/** Coexisting source assertions. Ranking orders a proposed reading; it never adopts it. */

export type FactKey = {
  fieldPath: string;
  periodStart?: string;
  periodEnd?: string;
  entityName?: string;
  entityScope?: string;
  currency?: string;
  unit?: string;
  scale?: string;
  scenario?: string;
  definitionVersionId?: string;
};

export type FactCandidate = {
  fieldPath: string;
  /** Decimal string for numbers, ISO date, text, "true"/"false", JSON array for lists. */
  normalizedValue: string;
  valueType: "text" | "number" | "date" | "boolean" | "list";
  sourceDocument: string;
  /** 1 (audited) to 7 (company statement). Reading order only. */
  evidenceRank: number;
  informationClass: string;
  confidence: number;
  anchorVerified: boolean;
  periodStart?: string;
  periodEnd?: string;
  entityName?: string;
  /** Explicit perimeter; none of these scopes takes precedence over another. */
  entityScope?: string;
  currency?: string;
  unit?: string;
  scale?: string;
  scenario?: string;
  definitionVersionId?: string;
  /** Where in the document it was found; carried through so a fact never loses its citation. */
  anchor?: unknown;
};

export type FactConflict = {
  candidate: FactCandidate;
  /** Relative difference against the accepted value; absent for non-numeric facts. */
  relativeDelta?: string;
};

export type ReconciledFact = {
  key: FactKey;
  /** Proposed reading for compatibility; not an adopted or official value. */
  value: string;
  valueType: FactCandidate["valueType"];
  /** @deprecated Proposed reference only. Contextual adoption is a separate command. */
  accepted: FactCandidate;
  /** All assertions, including corroboration with the same value. */
  observations?: FactCandidate[];
  /** Everything that said otherwise, ordered by rank then confidence. Never discarded. */
  conflicts: FactConflict[];
  /** True when at least one conflict differs beyond the tolerance the caller passed. */
  disputed: boolean;
};

// One to three digits: an {i} index, never a year such as historical_financials.2025.
const indexedPath = /^(.*)\.(\d{1,3})\.([a-z0-9_]+)$/;

export function factKeyOf(candidate: FactCandidate): string {
  // Indexed tuples (instruments, customers, windows) are rows of one document: the same index in
  // another document is another row, not the same fact read twice.
  const tupleScope = indexedPath.test(candidate.fieldPath) ? candidate.sourceDocument : "";
  return JSON.stringify([candidate.fieldPath, ...dimensionTuple(candidate), tupleScope]);
}

const isNumeric = (candidate: FactCandidate) => candidate.valueType === "number";

/**
 * Orders candidates for the same fact by how much the desk trusts them.
 *
 * Rank first, because that is a property of the document and not of the reading. Then a
 * verified anchor, because a value the verifier could confirm against the page outranks one it
 * could not, at equal rank. Then confidence, then the raw value as a tiebreak so the result is
 * deterministic — two runs over the same data room must reconcile identically, or nothing
 * downstream can be trusted.
 */
export function dimensionTuple(candidate: FactKey): Array<string | null> {
  return [candidate.entityName, candidate.entityScope, candidate.periodStart, candidate.periodEnd,
    candidate.currency, candidate.unit, candidate.scale, candidate.scenario, candidate.definitionVersionId].map((value) => value ?? null);
}

export function compareCandidates(a: FactCandidate, b: FactCandidate): number {
  if (a.evidenceRank !== b.evidenceRank) return a.evidenceRank - b.evidenceRank;
  if (a.anchorVerified !== b.anchorVerified) return a.anchorVerified ? -1 : 1;
  if (a.confidence !== b.confidence) return b.confidence - a.confidence;
  return a.normalizedValue.localeCompare(b.normalizedValue);
}

/** Relative difference between two numeric strings, as a decimal string. Null when not comparable. */
export function relativeDelta(accepted: string, other: string): string | null {
  const a = new Decimal(accepted);
  const b = new Decimal(other);
  if (!a.isFinite() || !b.isFinite()) return null;
  if (a.isZero()) return b.isZero() ? "0" : null;
  return b.minus(a).dividedBy(a).abs().toDecimalPlaces(6).toFixed();
}

export type ReconcileOptions = {
  /** A conflict beyond this relative difference marks the fact disputed. Default 1%. */
  disputeTolerance?: string;
};

export function reconcileFacts(candidates: readonly FactCandidate[], options: ReconcileOptions = {}): ReconciledFact[] {
  const tolerance = new Decimal(options.disputeTolerance ?? "0.01");
  const grouped = new Map<string, FactCandidate[]>();
  for (const candidate of candidates) {
    const key = factKeyOf(candidate);
    grouped.set(key, [...(grouped.get(key) ?? []), candidate]);
  }

  const facts: ReconciledFact[] = [];
  for (const group of grouped.values()) {
    const ordered = [...group].sort(compareCandidates);
    const accepted = ordered[0];
    if (!accepted) continue;

    const conflicts: FactConflict[] = [];
    let disputed = false;
    for (const other of ordered.slice(1)) {
      if (other.normalizedValue === accepted.normalizedValue) continue;
      const delta = isNumeric(accepted) && isNumeric(other) ? relativeDelta(accepted.normalizedValue, other.normalizedValue) : null;
      if (delta === null || new Decimal(delta).gt(tolerance)) disputed = true;
      conflicts.push(delta === null ? {candidate: other} : {candidate: other, relativeDelta: delta});
    }

    facts.push({
      key: {
        fieldPath: accepted.fieldPath,
        ...(accepted.periodStart ? {periodStart: accepted.periodStart} : {}),
        ...(accepted.entityScope ? {entityScope: accepted.entityScope} : {}),
        ...(accepted.currency ? {currency: accepted.currency} : {}),
        ...(accepted.unit ? {unit: accepted.unit} : {}),
        ...(accepted.scale ? {scale: accepted.scale} : {}),
        ...(accepted.scenario ? {scenario: accepted.scenario} : {}),
        ...(accepted.definitionVersionId ? {definitionVersionId: accepted.definitionVersionId} : {}),
        ...(accepted.periodEnd ? {periodEnd: accepted.periodEnd} : {}),
        ...(accepted.entityName ? {entityName: accepted.entityName} : {}),
      },
      value: accepted.normalizedValue,
      valueType: accepted.valueType,
      accepted,
      observations: ordered,
      conflicts,
      disputed,
    });
  }
  return facts;
}

/**
 * One number per row of one document, across the whole case.
 *
 * Every table numbers its rows from one, and so does every document: the ITR's note 15 has a
 * `debt.instruments.1`, the letter's table has a `debt.instruments.1`, and without this step
 * the two are one fact with a conflict, the reconciliation reports a contradiction the room
 * never stated, and the desk reads one instrument where there were two. Tuples are grouped by
 * document and original index, ordered by the document's evidence rank, and renumbered 1..N.
 */
export function renumberIndexedGroups(facts: readonly ReconciledFact[]): ReconciledFact[] {
  type TupleKey = string;
  const groups = new Map<string, Map<TupleKey, {rank: number; document: string; index: number}>>();
  for (const fact of facts) {
    const match = indexedPath.exec(fact.key.fieldPath);
    if (!match) continue;
    const [, group, index] = match as unknown as [string, string, string];
    const document = fact.accepted.sourceDocument;
    const tupleKey = `${document}#${index}`;
    const tuples = groups.get(group) ?? new Map();
    if (!tuples.has(tupleKey)) tuples.set(tupleKey, {rank: fact.accepted.evidenceRank, document, index: Number(index)});
    groups.set(group, tuples);
  }
  const renumbered = new Map<string, Map<TupleKey, number>>();
  for (const [group, tuples] of groups) {
    const ordered = [...tuples.entries()].sort(([, a], [, b]) => a.rank - b.rank || a.document.localeCompare(b.document) || a.index - b.index);
    renumbered.set(group, new Map(ordered.map(([key], position) => [key, position + 1])));
  }
  return facts.map((fact) => {
    const match = indexedPath.exec(fact.key.fieldPath);
    if (!match) return fact;
    const [, group, index, key] = match as unknown as [string, string, string, string];
    const next = renumbered.get(group)?.get(`${fact.accepted.sourceDocument}#${index}`);
    if (next === undefined || String(next) === index) return fact;
    return {...fact, key: {...fact.key, fieldPath: `${group}.${next}.${key}`}};
  });
}

const fold = (text: string): string => text.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, " ").trim();

/**
 * Rows from different documents that name the same contract are one instrument.
 *
 * Camil's ITR lists twelve debenture series with balances and the AGOE proposal describes the
 * same series with their rates and maturities. After renumbering they are twenty-four rows;
 * a desk reads twelve. Rows whose lender text folds to the same string are merged: the fields
 * of the higher-ranked document win on conflict, the others fill in what it lacks, and the
 * conflicts stay on the fact. Only the debt group is merged, because it is the one where a
 * name identifies a contract.
 */
/** Groups where a name identifies the row, and the field that carries the name. */
const identityGroups: ReadonlyArray<{group: string; keys: string[]}> = [
  // A bank is not a contract. Prefer contract/issuance/series; when it is absent, combine
  // lender, instrument and maturity so two facilities from the same bank are not collapsed.
  {group: "debt.instruments", keys: ["contract_id", "lender", "instrument_type", "maturity"]},
  // Nimbus measured the people case: the deck's management table and its cap table both list
  // the founders, and two tables gave the CEO twice with the same 28%.
  {group: "company.controllers", keys: ["name"]},
  {group: "company.management", keys: ["name"]},
  {group: "customers.top_customers", keys: ["name"]},
];

export function mergeInstrumentsByIdentity(facts: readonly ReconciledFact[]): ReconciledFact[] {
  return identityGroups.reduce<ReconciledFact[]>((current, entry) => mergeByIdentity(current, entry.group, entry.keys), [...facts]);
}

function mergeByIdentity(facts: readonly ReconciledFact[], group: string, identityKeys: string[]): ReconciledFact[] {
  const byTuple = new Map<number, ReconciledFact[]>();
  for (const fact of facts) {
    const match = indexedPath.exec(fact.key.fieldPath);
    if (!match || match[1] !== group) continue;
    const index = Number(match[2]);
    byTuple.set(index, [...(byTuple.get(index) ?? []), fact]);
  }
  if (byTuple.size < 2) return [...facts];
  const identity = (tuple: ReconciledFact[]): string | null => {
    if (group === "debt.instruments") {
      const contract = tuple.find((fact) => fact.key.fieldPath.endsWith(".contract_id"));
      if (contract) return `contract:${fold(contract.value)}`;
      const lender = tuple.find((fact) => fact.key.fieldPath.endsWith(".lender"));
      // An issuance/series label is itself the contractual identity across an ITR, an
      // indenture and a corporate approval. An ordinary bank name is not.
      if (lender && /(emiss|serie|series|debenture)/.test(fold(lender.value))) return `issuance:${fold(lender.value)}`;
      const parts = identityKeys.slice(1).map((key) => tuple.find((fact) => fact.key.fieldPath.endsWith(`.${key}`))?.value).filter(Boolean);
      return parts.length >= 2 ? `terms:${parts.map((value) => fold(value!)).join("|")}` : null;
    }
    const named = tuple.find((fact) => identityKeys.some((key) => fact.key.fieldPath.endsWith(`.${key}`)));
    return named ? fold(named.value) : null;
  };
  const canonical = new Map<string, number>();
  const remap = new Map<number, number>();
  for (const [index, tuple] of [...byTuple.entries()].sort(([a], [b]) => a - b)) {
    const id = identity(tuple);
    if (!id) continue;
    const existing = canonical.get(id);
    if (existing === undefined) canonical.set(id, index);
    else remap.set(index, existing);
  }
  if (remap.size === 0) return [...facts];
  const merged: ReconciledFact[] = [];
  const seen = new Map<string, ReconciledFact>();
  for (const fact of facts) {
    const match = indexedPath.exec(fact.key.fieldPath);
    if (!match || match[1] !== group) { merged.push(fact); continue; }
    const index = Number(match[2]);
    const target = remap.get(index) ?? index;
    const path = `${group}.${target}.${match[3]}`;
    const candidate = target === index ? fact : {...fact, key: {...fact.key, fieldPath: path}};
    const key = JSON.stringify([path, ...dimensionTuple(fact.key)]);
    const prior = seen.get(key);
    if (!prior) { seen.set(key, candidate); merged.push(candidate); continue; }
    // Same field from two documents: the better-ranked reading stands, the other is a conflict.
    const [winner, loser] = compareCandidates(prior.accepted, candidate.accepted) <= 0 ? [prior, candidate] : [candidate, prior];
    const conflict = loser.value === winner.value ? [] : [{candidate: loser.accepted, ...(isNumeric(loser.accepted) && isNumeric(winner.accepted) ? {relativeDelta: relativeDelta(winner.value, loser.value) ?? undefined} : {})}];
    const combined: ReconciledFact = {...winner, observations: [...(winner.observations ?? [winner.accepted]), ...(loser.observations ?? [loser.accepted])], conflicts: [...winner.conflicts, ...loser.conflicts, ...conflict].filter((entry): entry is FactConflict => Boolean(entry)), disputed: winner.disputed || loser.disputed || conflict.length > 0};
    seen.set(key, combined);
    merged[merged.indexOf(prior)] = combined;
  }
  // Compress the surviving indices to 1..N without splitting by document again: a merged
  // instrument now carries facts from two documents on purpose.
  const survivors = [...new Set(merged.map((fact) => indexedPath.exec(fact.key.fieldPath)).filter((match): match is RegExpExecArray => Boolean(match) && match![1] === group).map((match) => Number(match[2])))].sort((a, b) => a - b);
  const compress = new Map(survivors.map((index, position) => [index, position + 1]));
  return merged.map((fact) => {
    const match = indexedPath.exec(fact.key.fieldPath);
    if (!match || match[1] !== group) return fact;
    const next = compress.get(Number(match[2]));
    if (next === undefined || String(next) === match[2]) return fact;
    return {...fact, key: {...fact.key, fieldPath: `${group}.${next}.${match[3]}`}};
  });
}

/** Index for the rules and the calculations: field path (+ period) → fact. */
export function indexFacts(facts: readonly ReconciledFact[]): Map<string, ReconciledFact> {
  const buckets = new Map<string, ReconciledFact[]>();
  for (const fact of facts) {
    for (const key of [[fact.key.fieldPath, fact.key.periodEnd ?? ""].join("|"), fact.key.fieldPath]) {
      buckets.set(key, [...(buckets.get(key) ?? []), fact]);
    }
  }
  // An unqualified lookup must never choose a perimeter, currency or definition implicitly.
  return new Map([...buckets].filter(([, values]) => values.length === 1).map(([key, values]) => [key, values[0]!]));
}

export function factValue(index: Map<string, ReconciledFact>, fieldPath: string, periodEnd?: string): Decimal | null {
  const fact = index.get(periodEnd ? [fieldPath, periodEnd].join("|") : fieldPath);
  if (!fact || fact.valueType !== "number") return null;
  const value = new Decimal(fact.value);
  return value.isFinite() ? value : null;
}

/** A proposed analytical basis must be dimensionally usable before any calculation.
 * Contextual adoption is separate; unknown units/perimeters cannot be repaired by ranking. */
export function calculationBasis(facts: readonly ReconciledFact[]): {
  facts: ReconciledFact[];
  blocked: Array<{fieldPath: string; reasons: string[]}>;
} {
  const numeric = facts.filter((fact) => fact.valueType === "number");
  const perimeters = new Set(numeric.map((fact) => fact.key.entityScope).filter(Boolean));
  const entities = new Set(numeric.map((fact) => fact.key.entityName).filter(Boolean));
  const currencies = new Set(numeric.map((fact) => fact.key.currency).filter(Boolean));
  const byPath = new Map<string, number>();
  for (const fact of facts) byPath.set(fact.key.fieldPath, (byPath.get(fact.key.fieldPath) ?? 0) + 1);
  const blocked: Array<{fieldPath: string; reasons: string[]}> = [];
  const usable = facts.filter((fact) => {
    const reasons: string[] = [];
    if (fact.valueType === "number") {
      if (!fact.key.entityScope) reasons.push("perimeter_unknown");
      if (!fact.key.unit) reasons.push("unit_unknown");
      if (!fact.key.scale || !/^[0-9]+(?:\.[0-9]+)?$/.test(fact.key.scale) || new Decimal(fact.key.scale).lte(0)) reasons.push("scale_unknown");
      if (!fact.key.currency && !["ratio", "percent", "percentage", "count", "days", "months", "years"].includes(fact.key.unit ?? "")) reasons.push("currency_unknown");
      if (perimeters.size > 1 || entities.size > 1) reasons.push("context_selection_required");
      if (currencies.size > 1) reasons.push("currency_selection_required");
    }
    if ((byPath.get(fact.key.fieldPath) ?? 0) > 1) reasons.push("dimension_selection_required");
    if (fact.conflicts.length > 0) reasons.push("conflicting_observations");
    if (reasons.length > 0) { blocked.push({fieldPath: fact.key.fieldPath, reasons}); return false; }
    return true;
  });
  return {facts: usable, blocked};
}

