/** Senior-banker work product used by the conversational origination workflow. Unlike the legacy
 * meeting brief, this contract forces the synthesis to explain the operating business, financial
 * trajectory, capital structure and strategic financing choices before proposing a meeting plan. */
const originationSeniorReadoutV3Schema = z.object({
  executiveRead: z.string().min(60).max(3_600),
  companyAnalysis: z.object({
    businessOverview: z.string().min(40).max(1_800),
    businessModel: z.string().min(40).max(1_800),
    revenueAndCustomers: z.string().min(30).max(1_500),
    costAndMarginDrivers: z.string().min(30).max(1_500),
    sectorPosition: z.string().min(30).max(1_500),
    seasonality: z.string().min(20).max(1_000),
    recentDevelopments: z.array(z.string().min(12).max(700)).max(8),
    sourceUrls: z.array(z.url()).min(1).max(64),
  }),
  performanceAnalysis: z.object({
    operatingPerformance: z.string().min(40).max(1_800),
    cashFlowAndWorkingCapital: z.string().min(40).max(1_800),
    outlookAndPlans: z.string().min(30).max(1_500),
    sourceUrls: z.array(z.url()).min(1).max(64),
  }),
  /** A public-information readout still needs a forward view, but it must not disguise an
   * Offroad scenario as management guidance. Assumptions are individually sourced, explain how
   * they enter the analysis and remain editable through the conversation. */
  preliminaryForwardCase: z.object({
    status: z.enum(["directional", "not_computable"]),
    horizon: z.string().min(4).max(240),
    nature: z.string().min(30).max(1_000),
    assumptions: z.array(z.object({
      id: z.string().regex(/^[a-z][a-z0-9_]{2,80}$/),
      category: z.enum([
        "revenue", "costs_and_margin", "working_capital", "capex_and_depreciation",
        "tax", "macro_and_market", "debt_service", "sector_specific",
      ]),
      driver: z.string().min(5).max(180),
      baseCase: z.string().min(8).max(600),
      downside: z.string().min(8).max(600),
      methodology: z.string().min(15).max(800),
      rationale: z.string().min(15).max(800),
      confidence: z.enum(["high", "medium", "low"]),
      editable: z.literal(true),
      sourceUrls: z.array(z.url()).min(1).max(8),
    })).min(7).max(12),
    projectedEffects: z.array(z.object({
      category: z.enum(["revenue", "ebitda", "cash_flow", "net_debt_and_leverage", "liquidity_and_debt_service", "covenants"]),
      metric: z.string().min(3).max(160),
      baseCase: z.string().min(12).max(700),
      downside: z.string().min(12).max(700),
      debtRelevance: z.string().min(15).max(700),
      sourceUrls: z.array(z.url()).min(1).max(8),
    })).min(5).max(10),
    missingInputs: z.array(z.string().min(8).max(600)).min(1).max(12),
    limitations: z.array(z.string().min(8).max(600)).min(1).max(8),
  }),
  capitalStructure: z.object({
    overview: z.string().min(40).max(1_800),
    liquidity: z.string().min(30).max(1_500),
    debtStack: z.array(z.object({
      instrument: z.string().min(3).max(400),
      amount: z.string().min(1).max(120).nullable(),
      maturity: z.string().min(1).max(600).nullable(),
      cost: z.string().min(1).max(600).nullable(),
      // Public debt disclosures often describe indexation together with spreads,
      // step-ups, capitalization and hedging. Preserve that economic meaning
      // instead of rejecting an otherwise valid readout at an arbitrary UI length.
      indexer: z.string().min(1).max(600).nullable(),
      currency: z.string().min(1).max(600).nullable(),
      amortization: z.string().min(1).max(600).nullable(),
      guarantees: z.string().min(1).max(600).nullable(),
      covenants: z.string().min(1).max(600).nullable(),
      prepayment: z.string().min(1).max(600).nullable(),
      sourceUrls: z.array(z.url()).min(1).max(12),
    })).max(16),
    keyUnknowns: z.array(z.string().min(10).max(600)).min(1).max(12),
    // A reconciled capital structure can legitimately rely on many filings and
    // offering documents. The renderer deduplicates citations; the contract must
    // not discard traceability simply because more than eight sources are needed.
    sourceUrls: z.array(z.url()).min(1).max(64),
  }),
  strategicAgenda: z.object({
    priorities: z.array(z.string().min(12).max(700)).max(10),
    implicationsForDebt: z.string().min(30).max(1_500),
    sourceUrls: z.array(z.url()).min(1).max(64),
  }),
  strategicAlternatives: z.array(z.object({
    rank: z.number().int().min(1).max(8),
    title: z.string().min(5).max(180),
    objective: z.string().min(20).max(700),
    structure: z.string().min(20).max(1_000),
    rationale: z.string().min(40).max(1_500),
    balanceSheetImpact: z.string().min(20).max(900),
    advantages: z.array(z.string().min(8).max(500)).min(1).max(6),
    risks: z.array(z.string().min(8).max(500)).min(1).max(6),
    conditions: z.array(z.string().min(8).max(500)).min(1).max(8),
    disconfirmers: z.array(z.string().min(8).max(500)).min(1).max(6),
    sourceUrls: z.array(z.url()).min(1).max(24),
  })).min(1).max(6),
  meetingStrategy: z.object({
    narrative: z.string().min(40).max(1_500),
    recommendedAgenda: z.array(z.string().min(10).max(500)).min(2).max(8),
    decisionQuestions: z.array(z.object({
      question: z.string().min(10).max(500),
      whyItMatters: z.string().min(10).max(700),
      answerChanges: z.string().min(10).max(700),
    })).min(3).max(10),
  }),
  unknowns: z.array(z.string().min(8).max(600)).min(1).max(16),
});

