packages/credit-playbook/src/material-fi.content:
import type {ArchetypeId} from "./types";

/**
 * One economic requirement may be stated under more than one canonical path.
 *
 * Current gross debt is the clearest example: a debt schedule can state it as
 * `debt.total_gross`, while financial statements state it under a dated historical or interim
 * path. Requiring one spelling would turn a complete case into a false gap. The requirement is
 * therefore named once and discharged by any of its accepted patterns.
 */
export type MaterialFieldRequirement = {
  id: string;
  anyOf: readonly string[];
};

const requirement = (id: string, ...anyOf: string[]): MaterialFieldRequirement => ({id, anyOf});

const common: readonly MaterialFieldRequirement[] = [
  requirement("company_legal_name", "company.legal_name"),
  requirement("requested_amount", "transaction.requested_amount"),
  requirement(
    "current_gross_debt",
    "debt.total_gross",
    "interim_financials.*.gross_debt",
    "historical_financials.*.gross_debt",
  ),
];

const perArchetype: Readonly<Record<ArchetypeId, readonly MaterialFieldRequirement[]>> = {
  growth_expansion: [
    requirement("project_total_cost", "project.total_cost"),
    requirement("project_investment", "project.investments.*.amount"),
    requirement("desired_term", "transaction.desired_term_months"),
    requirement("collateral_capacity", "collateral.total_capacity"),
    requirement("minimum_dscr", "projections.minimum_dscr"),
  ],
  working_capital: [
    requirement("receivables_capacity", "collateral.receivables_capacity"),
    requirement("customer_concentration", "customers.top_customers.*.share_pct"),
  ],
  refinance: [
    requirement("debt_maturity", "debt.instruments.*.maturity"),
    requirement("debt_rate", "debt.instruments.*.rate"),
  ],
  acquisition: [
    requirement("post_transaction_leverage", "leverage.post_transaction_net_debt_ebitda"),
  ],
  equipment_finance: [
    requirement("project_total_cost", "project.total_cost"),
    requirement("asset_appraisal", "collateral.assets.*.appraisal_value"),
  ],
  venture_debt: [
    requirement("runway", "company.runway_months"),
    requirement("net_revenue_retention", "company.net_revenue_retention"),
    requirement("last_equity_round", "company.last_equity_round.amount"),
  ],
  other: [],
};

export function materialFieldRequirements(archetypeId: ArchetypeId): MaterialFieldRequirement[] {
  return [...common, ...perArchetype[archetypeId]];
}

const regexpFor = (pattern: string): RegExp => {
  const escaped = pattern.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\\\*/g, "[^.]+");
  return new RegExp(`^${escaped}$`);
};

export function fieldMatchesPattern(fieldPath: string, pattern: string): boolean {
  return regexpFor(pattern).test(fieldPath);
}

export function requirementIsSatisfied(
  requirement: MaterialFieldRequirement,
  availableFieldPaths: ReadonlySet<string>,
): boolean {
  return requirement.anyOf.some((pattern) =>
    [...availableFieldPaths].some((fieldPath) => fieldMatchesPattern(fieldPath, pattern)),
  );
}

export function fieldsForRequirement<T extends {key: {fieldPath: string}}>(
  requirement: MaterialFieldRequirement,
  facts: readonly T[],
): T[] {
  return facts.filter((fact) => requirement.anyOf.some((pattern) => fieldMatchesPattern(fact.key.fieldPath, pattern)));
}

packages/credit-playbook/src/methodology.content:
import {financialDefinitionMap} from "@offroad/credit-ontology";
import {z} from "zod";

/**
 * Historical institutional authoring schema, not execution or publication authority.
 *
 * A bank, an asset manager and a credit fund analyse the same company differently: which EBITDA
 * they accept, which adjustments they allow, which thresholds screen a deal, how many scenarios a
 * memo needs, who reviews before whom, how a page is laid out. Knowing finance is not the same as
 * knowing how this house does finance. This object holds the second thing.
 *
 * It never decides what the work is. Intent commands the workflow; the methodology modifies the
 * criteria, the checks and the presentation. And it never holds capabilities: what the
 * institution is able to do lives in `institution_capability_profiles`, with an owner and an
 * origin, and this object only points at it.
 */
const decimalString = z.string().regex(/^-?\d+(\.\d+)?$/, "a decimal written as a string");

const knownDefinitionId = z.string().min(1).refine((id) => financialDefinitionMap.has(id), {
  message: "a financial definition id from packages/credit-ontology",
});

export const definitionAdoptionSchema = z.object({
  id: knownDefinitionId,
  /** Parameters the canonical formula accepts, never a different formula. */
  parameters: z.record(z.string().max(60), z.string().max(120)).default({}),
  note: z.string().max(300).optional(),
});

export const ebitdaAdjustmentPolicySchema = z.object({
  id: z.enum([
    "non_recurring_items",
    "ifrs16_leases",
    "stock_compensation",
    "pro_forma_acquisitions",
    "run_rate_synergies",
    "fx_translation",
    "discontinued_operations",
  ]),
  allowed: z.boolean(),
  capPercentOfEbitda: z.number().min(0).max(100).nullable(),
  requiresEvidence: z.boolean(),
});

export const comparatorSchema = z.enum(["<", "<=", ">", ">="]);

export const thresholdSchema = z.object({
  metric: knownDefinitionId,
  comparator: comparatorSchema,
  value: decimalString,
  scope: z.enum(["screening", "approval", "monitoring"]),
  note: z.string().max(300).optional(),
});

export const eligibilityRuleSchema = z.object({
  key: z.string().min(1).max(80),
  comparator: comparatorSchema,
  value: decimalString,
  unit: z.string().max(20).optional(),
  note: z.string().max(300).optional(),
});

export const scenarioRequirementSchema = z.object({
  id: z.enum(["base", "downside", "stress"]),
  required: z.boolean(),
  shocks: z.array(z.object({driver: z.string().min(1).max(80), change: z.string().min(1).max(80)})).max(20),
});

export const reviewStepSchema = z.object({
  order: z.number().int().min(1),
  responsibility: z.enum(["producer", "coordinator", "reviewer", "decision_maker"]),
  label: z.string().min(1).max(120),
});

export const presentationStandardSchema = z.object({
  language: z.enum(["pt-BR", "en-US"]),
  memoSections: z.array(z.string().min(1).max(120)).min(1).max(40),
  maxPagesByOutput: z.record(z.string().max(60), z.number().int().min(1).max(200)),
  numberLocale: z.enum(["pt-BR", "en-US"]),
});

export const decisionReferenceSchema = z.object({
  reference: z.string().min(1).max(200),
  summary: z.string().min(1).max(600),
  recordedAt: z.string().datetime({offset: true}),
  recordedBy: z.string().uuid(),
});

export const organizationMethodologySchema = z.object({
  schemaVersion: z.literal("organization-methodology.v1"),
  definitions: z.array(definitionAdoptionSchema).max(40),
  ebitdaAdjustments: z.array(ebitdaAdjustmentPolicySchema).max(20),
  thresholds: z.array(thresholdSchema).max(60),
  eligibility: z.array(eligibilityRuleSchema).max(60),
  mandateReferences: z.array(z.object({fundId: z.string().uuid(), label: z.string().max(120)})).max(40),
  presentation: presentationStandardSchema,
  reviewSequence: z.array(reviewStepSchema).max(10),
  minimumScenarios: z.array(scenarioRequirementSchema).max(3),
  mandatoryMetrics: z.array(knownDefinitionId).max(40),
  /** Capabilities are not stored here; the institution profile is the only place they live. */
  capabilitiesReference: z.literal("institution_capability_profiles"),
  priorDecisions: z.array(decisionReferenceSchema).max(500),
  corrections: z.array(decisionReferenceSchema).max(500),
}).superRefine((methodology, ctx) => {
  const orders = methodology.reviewSequence.map((step) => step.order);
  if (new Set(orders).size !== orders.length) {
    ctx.addIssue({code: z.ZodIssueCode.custom, message: "review steps carry distinct orders"});
  }
  const scenarioIds = methodology.minimumScenarios.map((scenario) => scenario.id);
  if (new Set(scenarioIds).size !== scenarioIds.length) {
    ctx.addIssue({code: z.ZodIssueCode.custom, message: "a scenario id appears once"});
  }
});
export type OrganizationMethodology = z.infer<typeof organizationMethodologySchema>;

packages/credit-playbook/src/instruments.content:
import type {TransactionRoute} from "@offroad/credit-ontology";

import {routeForLegacyInstrument} from "./taxonomy";
import type {ArchetypeId} from "./types";

/**
 * The instruments a Brazilian private-credit desk actually places, as data a banker can
 * disagree with.
 *
 * An archetype says what the money is for; an instrument says what paper carries it, who may
 * issue it, what it costs to set up, how it is taxed, and what the law requires. The two are
 * different questions, and the product answered only the first. A limitada cannot issue a
 * debenture; a CRA needs agribusiness receivables as backing; a CRI needs real estate; a FIDC
 * needs a receivables base worth securitising; venture debt needs equity sponsors behind it.
 * Telling a company which papers its profile admits, and why the others are closed, is the
 * first structuring sentence a desk says.
 */

export type InstrumentId =
  | "ccb"
  | "nce"
  | "debenture_476"
  | "debenture_160"
  | "cra"
  | "cri"
  | "fidc"
  | "venture_debt"
  | "finame"
  | "leasing";

export type LegalForm = "sa" | "ltda" | "other";

export type IssuerProfile = {
  legalForm: LegalForm;
  archetypeId: ArchetypeId;
  /** Requested amount in reais, as a decimal string. */
  amount: string;
  /** Whether the company's revenue is predominantly agribusiness (producer, cooperative, agro trade). */
  agribusiness?: boolean;
  /** Whether the use of proceeds is real estate (construction, acquisition, or backed by property receivables). */
  realEstate?: boolean;
  /** Whether an equity sponsor (venture fund) is on the cap table. */
  ventureBacked?: boolean;
  /** Whether the proceeds buy identifiable equipment or vehicles. */
  equipment?: boolean;
  /** Whether the company has a receivables base large enough to securitise (as a fraction of the ask). */
  receivablesCoverage?: string;
  /** Whether the proceeds fund exports. */
  exports?: boolean;
};

export type Instrument = {
  id: InstrumentId;
  labels: {pt: string; en: string};
  description: {pt: string; en: string};
  /** Who may issue it. */
  legalForms: readonly LegalForm[];
  /** Smallest ticket that makes the set-up cost worth it, in reais. */
  minimumAmount: string;
  /** Typical tenor range in months. */
  tenorMonths: {min: number; max: number};
  /** Typical all-in cost band over CDI, in basis points, before the warrant or guarantee. */
  spreadOverCdiBps: {min: number; max: number};
  /** Structuring, registration and agent costs, as a fraction of the amount, typical. */
  setupCostPct: string;
  /** Who buys this paper. */
  buyers: readonly string[];
  /** Tax treatment the company and the investor read first. */
  tax: {pt: string; en: string};
  /** What the law and the market require before it exists. */
  requirements: {pt: string; en: string}[];
  /** The archetypes this paper usually serves. */
  archetypes: readonly ArchetypeId[];
};

const bi = (pt: string, en: string) => ({pt, en});

export const instruments: readonly Instrument[] = [
  {
    id: "ccb",
    labels: bi("Cédula de Crédito Bancário (CCB)", "Bank credit note (CCB)"),
    description: bi("Empréstimo bilateral formalizado em cédula, com banco ou fundo como credor; o papel mais rápido de fechar.", "A bilateral loan formalised as a note, with a bank or a fund as creditor; the fastest paper to close."),
    legalForms: ["sa", "ltda", "other"],
    minimumAmount: "2000000",
    tenorMonths: {min: 12, max: 60},
    spreadOverCdiBps: {min: 250, max: 700},
    setupCostPct: "0.005",
    buyers: ["bancos", "fundos de crédito via cessão", "FIDCs"],
    tax: bi("IOF de crédito sobre o principal (0,38% fixo mais 0,0082% ao dia, limitado a 365 dias); juros dedutíveis para a tomadora.", "Credit IOF on principal (0.38% flat plus 0.0082% a day, capped at 365 days); interest deductible for the borrower."),
    requirements: [bi("Garantias registradas (alienação ou cessão fiduciária) quando o perfil exige.", "Registered security (fiduciary lien or assignment) when the profile requires it."), bi("Sem registro na CVM; circulação por endosso ou cessão.", "No CVM registration; circulates by endorsement or assignment.")],
    archetypes: ["working_capital", "growth_expansion", "refinance", "equipment_finance", "other"],
  },
  {
    id: "nce",
    labels: bi("Nota de Crédito à Exportação (NCE)", "Export credit note (NCE)"),
    description: bi("Crédito bancário para financiar produção destinada à exportação, isento de IOF.", "Bank credit to fund export-bound production, IOF-exempt."),
    legalForms: ["sa", "ltda", "other"],
    minimumAmount: "5000000",
    tenorMonths: {min: 12, max: 48},
    spreadOverCdiBps: {min: 150, max: 450},
    setupCostPct: "0.004",
    buyers: ["bancos"],
    tax: bi("Isenta de IOF de crédito; exige comprovação do vínculo com exportação.", "Exempt from credit IOF; requires evidence of the export link."),
    requirements: [bi("Histórico ou contratos de exportação compatíveis com o montante.", "Export history or contracts consistent with the amount.")],
    archetypes: ["working_capital", "growth_expansion"],
  },
  {
    id: "debenture_476",
    labels: bi("Debênture com esforços restritos (CVM 160, antiga 476)", "Debenture, restricted efforts (CVM 160, formerly 476)"),
    description: bi("Título de dívida de sociedade anônima colocado junto a investidores profissionais, sem registro prévio; o papel padrão do mercado de capitais para dívida corporativa.", "Corporate bond of a sociedade anônima placed with professional investors without prior registration; the capital markets' standard corporate debt paper."),
    legalForms: ["sa"],
    minimumAmount: "30000000",
    tenorMonths: {min: 24, max: 120},
    spreadOverCdiBps: {min: 120, max: 450},
    setupCostPct: "0.012",
