  reference_date: string;
  unit: string;
  state: "complete" | "incomplete" | "blocked";
  block_reasons: string[];
  incomplete_reasons: string[];
  wall_threshold: {share: string; policyKey: string; policyVersion: string};
  walls: Array<{period: string; amount: string; share_of_gross: string; change_from_prior: {amount: string; prior_as_of: string; anchor: Anchor} | null; prior_comparability: string | null; is_wall: boolean; anchor: Anchor}>;
  peak: {period: string; amount: string; share_of_gross: string} | null;
  coverage: {
    cash_definition: string;
    cash: {value: string; anchor: Anchor};
    operating_generation: {basis: string; anchor: Anchor; periods_declared: string[]} | null;
    /** principal_only when the base states no interest per period; full_debt_service when it does. */
    coverage_basis: "principal_only" | "full_debt_service";
    /** An open-ended bucket is not assessed: its cash, sources, cover and deficits are null, never zeros. */
    by_period: Array<{period: string; principal: string; interest: string | null; interest_anchor: Anchor | null; basis: "principal_only" | "full_debt_service"; debt_service: string; opening_cash: string | null; generation: string | null; generation_declared: boolean; contracted_sources: string | null; sources: string | null; coverage: string | null; closing_cash: string | null; incremental_deficit: string | null; cumulative_deficit: string | null; rollover_dependency: string; state: "assessed" | "not_assessed"}>;
    /** The shortfall carried to the end of the assessed horizon: what rollover or new debt must provide in total. */
    cumulative_deficit: string;
    caveat: string;
  };
  /** `period` is set only for a proven source; `claimed_period` keeps what the file says. */
  /** A proven source enters the cover with the amount and the period the disbursement proves, never the claimed figure or the claimed period. */
  sources: Array<{id: string; label: string; claimed_amount: string; amount: string | null; period: string | null; claimed_period: string | null; state: "proven" | "unproven"; reason: string; evidence: {approval: {date: string; anchor: Anchor} | null; contract: {date: string; amount: string; anchor: Anchor} | null; disbursement: {date: string; amount: string; anchor: Anchor} | null}}>;
  /** Rows of the schedule that belong to no period (transaction costs); they reconcile the schedule to the gross debt and never enter the cover. */
