import {createHash} from "node:crypto";

import {buildDebtBalanceBridge, checkIdentity} from "@offroad/financial-core";
import Decimal from "decimal.js";
import {z} from "zod";

import {referenceDataRegistry} from "../reference-data";

/**
 * Executor of the method `reconcile-financial-statements` (v9, after the eighth independent review).
 * Proves that material numbers close between statements, notes and release, runs the identities
 * through financial-core, and keeps every difference above the tolerance as an open divergence
 * with its anchors. Two sources that disagree are never averaged and never silently resolved. Two
 * sources are compared only when they count the same components at the same date; otherwise the
 * pair is `not_comparable`, which is not `closes`. An explanation names the source it starts from
 * and the source it reaches, with the sign preserved. A tolerance above zero exists only under a
 * versioned policy, and policy metadata is checked even at zero. A single-source account is recorded,
 * never compared. Inside an account that is not comparable as a whole, the sources that share a
 * definition, components and date are compared among themselves, so a divergence between two
 * carrying amounts is never lost behind a nominal or a fair value. Every component tag is a known
 * tag the definition text names. Every calculation carries the anchors of its operands. A figure the
 * source publishes in another scale enters with its stated value, unit and decimals, and its rounding
 * band is recorded, so two figures that differ by less than the coarser rounding close "within the
 * published rounding", never "exactly". A sign the source publishes as an expense is declared and
 * normalized in the trace. Every line of a bridge carries its own anchor. An empty base blocks.
 */
const money = z.string().regex(/^-?\d+(\.\d+)?$/);
const nonNegative = z.string().regex(/^\d+(\.\d+)?$/);
const nonEmpty = z.string().trim().min(1);
const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);
const unitSchema = z.enum(["BRL", "BRL thousand", "BRL million", "USD", "USD thousand"]);
const anchorSchema = z.object({document: nonEmpty, page: z.number().int().positive().optional(), note: nonEmpty.optional(), table: nonEmpty.optional(), clause: nonEmpty.optional()}).strict();
type Anchor = z.infer<typeof anchorSchema>;
const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);

const toleranceSchema = z.object({value: nonNegative, policyKey: nonEmpty.optional(), policyVersion: nonEmpty.optional()}).strict();
/** A tolerance above zero must be the value the registered policy states for the family and the unit, at the policy's current version. */
function tolerancePolicyIssue(family: string, tolerance: z.infer<typeof toleranceSchema>, unit: string): string | null {
  const zero = new Decimal(tolerance.value).isZero();
  if (zero && !tolerance.policyKey && !tolerance.policyVersion) return null;
  if (!tolerance.policyKey || !tolerance.policyVersion) return zero ? `${family}: policy metadata must carry both policyKey and policyVersion, or neither` : `${family}: a tolerance above zero needs policyKey and policyVersion`;
  const policy = referenceDataRegistry.find((entry) => entry.key === tolerance.policyKey);
  if (!policy) return `${family}: policy ${tolerance.policyKey} is not in the reference-data registry`;
  if (policy.version !== tolerance.policyVersion) return `${family}: policy ${tolerance.policyKey} is at version ${policy.version}, not ${tolerance.policyVersion}`;
  if (zero) return null;
  if (policy.status === "required_missing" || policy.value === null || typeof policy.value !== "object") return `${family}: policy ${tolerance.policyKey} has no value yet; a tolerance above zero cannot rest on it`;
  const value = policy.value as {families?: Record<string, string>; familiesUnit?: string};
  const allowed = value.families?.[family];
  if (allowed === undefined) return `${family}: policy ${tolerance.policyKey} states no tolerance for this family`;
  if (value.familiesUnit !== unit) return `${family}: policy ${tolerance.policyKey} states its tolerances in ${value.familiesUnit ?? "no unit"}, not ${unit}`;
  if (!new Decimal(allowed).eq(tolerance.value)) return `${family}: policy ${tolerance.policyKey} states ${allowed}, not ${tolerance.value}`;
  return null;
}

/** Every component tag the executor accepts, with the words its definition text must contain; an unknown tag is refused. */
const COMPONENT_WORDS: Record<string, RegExp> = {
  gross_debt: /divida bruta|gross debt|emprestim|financiament|debenture/,
  cash: /caixa|disponibilidade|cash/,
  investments: /aplicac|investment/,
  derivative_liabilities: /derivativ/,
  derivative_assets: /derivativ/,
  leases: /arrendament|lease/,
  lease_liabilities: /arrendament|lease/,
  inventories: /estoque|inventor/,
  inventories_management_view: /gerencial|management/,
  advances_to_suppliers: /adiantamento|advance/,
  advances_to_producers: /adiantamento|advance/,
  dividends_declared: /dividend/,
  other_onerous_debt: /outra(s)? d[ií]vida(s)? onerosa|other (onerous|interest-bearing) debt/,
  leases_if_included: /arrendament|lease/,
  nominal: /nominal/,
  remaining_installments: /parcela|installment/,
  present_value: /valor presente|present value/,
  carrying_amount: /contabil|carrying|valor presente|present value/,
  fair_value: /valor justo|fair value/,
  interest: /juros|interest/,
  monetary_variation: /variac|variation|indexa/,
  ebitda: /ebitda/,
  quarter_annualized: /trimestre|quarter/,
  ltm: /doze meses|ultimos doze|ltm|twelve/,
};
export const knownComponents = Object.keys(COMPONENT_WORDS).sort();
const normalize = (text: string) => text.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();

const scaleUnits = z.enum(["BRL", "BRL thousand", "BRL million"]);
const SCALE: Record<z.infer<typeof scaleUnits>, string> = {"BRL": "1", "BRL thousand": "1000", "BRL million": "1000000"};

export const statementSourceSchema = z.object({
  source: nonEmpty,
  value: money,
  /** When the source publishes the figure in another scale (a release in R$ million with one decimal): the value as published, its unit and its decimals; the executor converts and records the rounding band. */
  stated: z.object({value: money, unit: scaleUnits, decimals: z.number().int().min(0).max(6)}).strict().nullable().default(null),
  /** as_published keeps the sign the source prints; absolute declares that the executor compares magnitudes (an expense printed in parentheses). */
  sign: z.enum(["as_published", "absolute"]).default("as_published"),
  /** The months the figure covers (12 for a twelve-month figure, 3 for a quarter, 0 for a balance at a date); sources covering different spans are not comparable whatever their keys. */
  periodMonths: z.number().int().min(0).max(60),
  /** When the value is recomputed from other figures, the derivation with each operand anchored; the executor re-runs it. */
  derivation: z.object({formula: z.enum(["sum", "difference", "signed_sum"]), operands: z.array(z.object({label: nonEmpty, value: money, sign: z.enum(["+", "-"]).default("+"), anchor: anchorSchema}).strict()).min(2)}).strict().nullable().default(null),
  /** What the source counts, as text, as a definition key shared by sources that count the same thing, and as component tags. */
  definition: nonEmpty,
  definitionKey: nonEmpty,
  definitionAnchor: anchorSchema,
  components: z.array(nonEmpty).min(1),
  /** The date the value is stated at; sources at different dates are not compared. */
  asOf: isoDate,
  anchor: anchorSchema,
}).strict();

export const reconciliationInputSchema = z.object({
  referenceDate: isoDate,
  unit: unitSchema,
  /** Absolute tolerance per statement family; a missing family means zero tolerance. */
  tolerance: z.record(nonEmpty, toleranceSchema).default({}),
  /** The same account stated by one or more sources. One source is recorded as single-source, never compared. */
  pairedAccounts: z.array(z.object({
    id: nonEmpty,
    label: nonEmpty,
    family: nonEmpty,
    sources: z.array(statementSourceSchema).min(1),
    /** Stated reconciliations from one source to another (adjustment lines), when the notes give them: to = from + adjustment. An account with n sources is explained only when every source is connected. */
    explanations: z.array(z.object({fromSource: nonEmpty, toSource: nonEmpty, adjustment: money, description: nonEmpty, anchor: anchorSchema}).strict()).default([]),
  }).strict()).default([]),
  /** Balance sheet identity: assets equal liabilities plus equity. Required for the state `closes`. */
  balanceSheet: z.object({assets: z.object({value: money, anchor: anchorSchema}).strict(), liabilities: z.object({value: money, anchor: anchorSchema}).strict(), equity: z.object({value: money, anchor: anchorSchema}).strict()}).strict().nullable().default(null),
  /** Debt roll-forward from the note: opening plus movements equals closing. */
  debtBridge: z.object({
    opening: z.object({value: money, anchor: anchorSchema}).strict(),
    /** Each line as the note prints it (a reduction may be printed in parentheses) and how it is read: as published or as a magnitude; the reading is traced. */
    lines: z.array(z.object({id: nonEmpty, label: nonEmpty, published: money, sign: z.enum(["as_published", "absolute"]).default("as_published"), category: z.enum(["drawdowns", "accruedInterest", "pik", "indexation", "foreignExchange", "acquisitions", "otherAdditions", "amortizations", "prepayments", "writeOffs"]), anchor: anchorSchema}).strict()).min(1),
    closing: z.object({value: money, anchor: anchorSchema}).strict(),
    anchor: anchorSchema,
  }).strict().nullable().default(null),
  /** Cash roll-forward: opening plus net change equals closing. */
  cashBridge: z.object({opening: z.object({value: money, anchor: anchorSchema}).strict(), netChange: z.object({value: money, anchor: anchorSchema}).strict(), closing: z.object({value: money, anchor: anchorSchema}).strict()}).strict().nullable().default(null),
  /** Interest expense: the note's accrued interest against the income statement's expense; the difference is recorded, never hidden. */
  /** Each side with the value as the source prints it (an expense may be negative) and how the executor is to read it: as printed or as a magnitude; the normalization is traced. */
  interestBridge: z.object({fromDebtMovement: z.object({value: money, sign: z.enum(["as_published", "absolute"]).default("as_published"), components: z.array(nonEmpty).min(1), anchor: anchorSchema}).strict(), fromIncomeStatement: z.object({value: money, sign: z.enum(["as_published", "absolute"]).default("as_published"), components: z.array(nonEmpty).min(1), anchor: anchorSchema}).strict()}).strict().nullable().default(null),
}).strict().superRefine((input, context) => {
  const REDUCTIONS = new Set(["amortizations", "prepayments", "writeOffs"]);
  (input.debtBridge?.lines ?? []).forEach((line, index) => {
    if (REDUCTIONS.has(line.category) && line.sign === "as_published" && new Decimal(line.published).isNegative()) context.addIssue({code: "custom", path: ["debtBridge", "lines", index], message: `${line.id}: a reducing line (${line.category}) published as ${line.published} would be added back by the bridge; declare its sign absolute (a magnitude in parentheses) or publish the reduction as a positive figure`});
  });
  for (const [side, entry] of Object.entries(input.interestBridge ?? {})) for (const component of entry.components) if (!COMPONENT_WORDS[component]) context.addIssue({code: "custom", path: ["interestBridge", side], message: `unknown component tag ${component} in the interest bridge`});
  for (const [family, tolerance] of Object.entries(input.tolerance)) {
    const issue = tolerancePolicyIssue(family, tolerance, input.unit);
    if (issue) context.addIssue({code: "custom", path: ["tolerance", family], message: issue});
  }
  const ids = new Set<string>();
  input.pairedAccounts.forEach((account, index) => {
    if (ids.has(account.id)) context.addIssue({code: "custom", path: ["pairedAccounts", index, "id"], message: `duplicate account ${account.id}`});
    ids.add(account.id);
    const sources = new Set<string>();
    account.sources.forEach((source, position) => {
      if (sources.has(source.source)) context.addIssue({code: "custom", path: ["pairedAccounts", index, "sources", position], message: `duplicate source ${source.source} in ${account.id}`});
      sources.add(source.source);
      // The components a source declares must be readable in its definition text; a tag the text never names is a label.
      const text = normalize(source.definition);
      for (const component of source.components) {
        const words = COMPONENT_WORDS[component];
        if (!words) { context.addIssue({code: "custom", path: ["pairedAccounts", index, "sources", position, "components"], message: `${account.id}/${source.source}: unknown component tag ${component}; the known tags are ${knownComponents.join(", ")}`}); continue; }
        if (!words.test(text)) context.addIssue({code: "custom", path: ["pairedAccounts", index, "sources", position, "components"], message: `${account.id}/${source.source}: the definition text never names the component ${component}`});
      }
      if (source.stated) {
        const converted = new Decimal(source.stated.value).times(SCALE[source.stated.unit]).div(SCALE[input.unit as z.infer<typeof scaleUnits>] ?? "1");
        if (!converted.eq(source.value)) context.addIssue({code: "custom", path: ["pairedAccounts", index, "sources", position, "stated"], message: `${account.id}/${source.source}: ${source.stated.value} ${source.stated.unit} converts to ${converted.toFixed()} ${input.unit}, not ${source.value}`});
      }
      if (source.derivation) {
        const operands = source.derivation.operands.map((operand) => new Decimal(operand.value));
        const recomputed = source.derivation.formula === "sum" ? operands.reduce((sum, value) => sum.plus(value), new Decimal(0)) : source.derivation.formula === "signed_sum" ? source.derivation.operands.reduce((sum, operand) => (operand.sign === "-" ? sum.minus(operand.value) : sum.plus(operand.value)), new Decimal(0)) : operands.slice(1).reduce((left, value) => left.minus(value), operands[0]!);
        if (!recomputed.eq(source.value)) context.addIssue({code: "custom", path: ["pairedAccounts", index, "sources", position, "derivation"], message: `${account.id}/${source.source}: the derivation gives ${recomputed.toFixed()}, not ${source.value}`});
      }
    });
    const links = new Set<string>();
    account.explanations.forEach((explanation, position) => {
      if (!sources.has(explanation.fromSource) || !sources.has(explanation.toSource)) context.addIssue({code: "custom", path: ["pairedAccounts", index, "explanations", position], message: `an explanation of ${account.id} names a source the account does not have`});
      if (explanation.fromSource === explanation.toSource) context.addIssue({code: "custom", path: ["pairedAccounts", index, "explanations", position], message: `an explanation of ${account.id} must go from one source to another`});
      const link = `${explanation.fromSource}->${explanation.toSource}`;
      if (links.has(link)) context.addIssue({code: "custom", path: ["pairedAccounts", index, "explanations", position], message: `${account.id}: two explanations link ${link}; one adjustment per pair of sources`});
      links.add(link);
    });
  });
  const lineIds = new Set<string>();
  input.debtBridge?.lines.forEach((line, index) => {
    if (lineIds.has(line.id)) context.addIssue({code: "custom", path: ["debtBridge", "lines", index], message: `duplicate bridge line ${line.id}`});
    lineIds.add(line.id);
  });
});
export type ReconciliationInput = z.input<typeof reconciliationInputSchema>;

type PairState = "closes" | "explained" | "open" | "not_comparable" | "single_source";
type Calculation = {id: string; formula: string; operands: Record<string, string>; anchors: Record<string, Anchor>; result: string; unit: string};

export type ReconciliationOutput = {
  schema_version: "method.reconcile-financial-statements.v9";
  reference_date: string;
  unit: string;
  state: "closes" | "differences_explained" | "open_divergences" | "identity_failed" | "incomplete" | "blocked";
  block_reasons: string[];
  incomplete_reasons: string[];
  reconciliations: Array<{
    id: string; label: string; family: string;
    values: Array<{source: string; value: string; stated: {value: string; unit: string; decimals: number; roundingHalfBand: string} | null; sign: string; definition: string; definitionKey: string; definitionAnchor: Anchor; components: string[]; asOf: string; anchor: Anchor}>;
    comparability: {comparable: boolean; reasons: string[]};
    spread: string | null;
    /** The coarser published rounding among the sources (half of the last published digit, in the executor's unit); a spread inside it closes within the published rounding, never exactly. */
    rounding_half_band: string | null;
    tolerance: {value: string; policyKey: string | null; policyVersion: string | null};
    state: PairState;
    closes_within: "tolerance" | "published_rounding" | null;
    explanations: Array<{fromSource: string; toSource: string; adjustment: string; expected: string; actual: string; residual: string; holds: boolean; description: string; anchor: Anchor}>;
    /** Sources connected by explanations that hold; more than one group means the account is not explained as a whole. */
    explanation_groups: string[][];
    unexplained_sources: string[];
    /** Inside an account that is not comparable as a whole: the sources that share definition, components and date, compared among themselves. */
    comparable_subsets: Array<{definitionKey: string; components: string[]; asOf: string; sources: string[]; spread: string; state: "closes" | "open"}>;
  }>;
  open_divergences: Array<{id: string; label: string; values: Array<{source: string; value: string; anchor: Anchor}>; reason: string}>;
  identities: Array<{id: string; formula: string; left: string; right: string; difference: string; holds: boolean | null; state: "holds" | "fails" | "not_comparable"; anchors: Record<string, Anchor>}>;
  uncovered_terms: Array<{id: string; state: "insufficient_evidence"; reason: string}>;
  trace: {calculations: Calculation[]; inputFingerprint: string; outputFingerprint: string};
};

const d = (value: Decimal.Value) => new Decimal(value);
const out = (value: Decimal) => value.toDecimalPlaces(8).toFixed();
const stableStringify = (value: unknown): string => JSON.stringify(value, (_key, inner: unknown) => (inner && typeof inner === "object" && !Array.isArray(inner) ? Object.fromEntries(Object.entries(inner as Record<string, unknown>).sort(([a], [b]) => compare(a, b))) : inner));
const fingerprint = (value: unknown) => createHash("sha256").update(stableStringify(value)).digest("hex");
const sortStrings = (values: readonly string[]) => [...values].sort(compare);

function canonical(input: z.infer<typeof reconciliationInputSchema>) {
  return {
    ...input,
    pairedAccounts: [...input.pairedAccounts].sort((a, b) => compare(a.id, b.id)).map((account) => ({...account, sources: [...account.sources].sort((a, b) => compare(a.source, b.source)).map((source) => ({...source, components: sortStrings(source.components)})), explanations: [...account.explanations].sort((a, b) => compare(a.fromSource, b.fromSource) || compare(a.toSource, b.toSource) || compare(a.adjustment, b.adjustment) || compare(a.description, b.description) || compare(stableStringify(a.anchor), stableStringify(b.anchor)))})),
    debtBridge: input.debtBridge ? {...input.debtBridge, lines: [...input.debtBridge.lines].sort((a, b) => compare(a.id, b.id))} : null,
    interestBridge: input.interestBridge ? {fromDebtMovement: {...input.interestBridge.fromDebtMovement, components: sortStrings(input.interestBridge.fromDebtMovement.components)}, fromIncomeStatement: {...input.interestBridge.fromIncomeStatement, components: sortStrings(input.interestBridge.fromIncomeStatement.components)}} : null,
  };
}

export function reconcileFinancialStatements(raw: ReconciliationInput): ReconciliationOutput {
  const input = canonical(reconciliationInputSchema.parse(raw));
  const calculations: Calculation[] = [];
  const record = (calculation: Omit<Calculation, "unit" | "anchors"> & {anchors?: Record<string, Anchor>}) => calculations.push({...calculation, anchors: calculation.anchors ?? {}, unit: input.unit});
  const blockReasons: string[] = [];
  const incompleteReasons: string[] = [];
  const uncovered: ReconciliationOutput["uncovered_terms"] = [];
  const toleranceOf = (family: string) => {
    const tolerance = input.tolerance[family];
    return tolerance ? {value: tolerance.value, policyKey: tolerance.policyKey ?? null, policyVersion: tolerance.policyVersion ?? null} : {value: "0", policyKey: null, policyVersion: null};
  };
  if (input.pairedAccounts.length === 0 && !input.balanceSheet && !input.debtBridge && !input.cashBridge && !input.interestBridge) blockReasons.push("nothing to reconcile: no paired account, identity or bridge in the base");

  const reconciliations = input.pairedAccounts.map((account): ReconciliationOutput["reconciliations"][number] => {
    const tolerance = toleranceOf(account.family);
    const halfBand = (source: (typeof account.sources)[number]) => (source.stated ? d(10).pow(-source.stated.decimals).div(2).times(SCALE[source.stated.unit]).div(SCALE[input.unit as z.infer<typeof scaleUnits>] ?? "1") : d(0));
    const values = account.sources.map((source) => ({source: source.source, value: out(d(source.value)), stated: source.stated ? {value: source.stated.value, unit: source.stated.unit, decimals: source.stated.decimals, roundingHalfBand: out(halfBand(source))} : null, sign: source.sign, definition: source.definition, definitionKey: source.definitionKey, definitionAnchor: source.definitionAnchor, components: source.components, asOf: source.asOf, anchor: source.anchor}));
    const roundingBand = account.sources.reduce((widest, source) => Decimal.max(widest, halfBand(source)), d(0));
    for (const source of account.sources.filter((entry) => entry.stated)) record({id: `financial.scale_conversion:${account.id}:${source.source}`, formula: "stated value * stated scale / executor scale; rounding half band = 10^-decimals / 2 * stated scale / executor scale", operands: {stated: source.stated!.value, statedUnit: source.stated!.unit, decimals: String(source.stated!.decimals), converted: source.value, roundingHalfBand: out(halfBand(source))}, anchors: {source: source.anchor}, result: source.value});
    if (account.sources.length === 1) {
      uncovered.push({id: account.id, state: "insufficient_evidence", reason: `${account.label} has a single source (${account.sources[0]!.source}); recorded, not reconciled`});
      return {id: account.id, label: account.label, family: account.family, values, comparability: {comparable: false, reasons: ["single source"]}, spread: null, rounding_half_band: null, tolerance, state: "single_source", closes_within: null, explanations: [], explanation_groups: [[account.sources[0]!.source]], unexplained_sources: [], comparable_subsets: []};
    }
    // Comparability is decided on the definition key, the components and the date, never on the name of the account.
    const reasons: string[] = [];
    if (new Set(account.sources.map((source) => source.definitionKey)).size > 1) reasons.push(`the sources follow different definitions (${account.sources.map((source) => `${source.source}: ${source.definitionKey}`).join("; ")})`);
    if (new Set(account.sources.map((source) => source.components.join("+"))).size > 1) reasons.push(`the sources count different components (${account.sources.map((source) => `${source.source}: ${source.components.join(", ")}`).join("; ")})`);
    if (new Set(account.sources.map((source) => source.asOf)).size > 1) reasons.push(`the sources are dated differently (${account.sources.map((source) => `${source.source}: ${source.asOf}`).join("; ")})`);
    if (new Set(account.sources.map((source) => source.periodMonths)).size > 1) reasons.push(`the sources cover different spans (${account.sources.map((source) => `${source.source}: ${source.periodMonths} months`).join("; ")}); a quarter and a twelve-month figure never compare, whatever their keys`);
    // The sign each source declares is applied before any comparison (a magnitude printed in parentheses compares as a magnitude), and the reading is traced.
    const read = (source: (typeof account.sources)[number]) => (source.sign === "absolute" ? d(source.value).abs() : d(source.value));
    const numbers = account.sources.map(read);
    if (account.sources.some((source) => source.sign === "absolute")) record({id: `financial.accounting_identity:${account.id}:sign`, formula: "value read as published or as a magnitude, as declared", operands: Object.fromEntries(account.sources.flatMap((source) => [[`${source.source}:published`, source.value], [`${source.source}:read`, out(read(source))], [`${source.source}:sign`, source.sign]])), anchors: Object.fromEntries(account.sources.map((source) => [source.source, source.anchor])), result: out(Decimal.max(...numbers).minus(Decimal.min(...numbers)))});
    const spreadCheck = checkIdentity({id: `${account.id}:spread`, left: Decimal.max(...numbers), right: Decimal.min(...numbers), absoluteTolerance: tolerance.value});
    const spread = d(spreadCheck.difference);
    record({id: `financial.accounting_identity:${account.id}:spread`, formula: "max(values) - min(values)", operands: Object.fromEntries(account.sources.map((source) => [source.source, source.value])), anchors: Object.fromEntries(account.sources.map((source) => [source.source, source.anchor])), result: spreadCheck.difference});
    for (const source of account.sources.filter((entry) => entry.derivation)) record({id: `financial.accounting_identity:${account.id}:${source.source}:derivation`, formula: source.derivation!.formula === "sum" ? "sum(operands)" : "first - rest", operands: Object.fromEntries(source.derivation!.operands.map((operand) => [operand.label, operand.value])), anchors: Object.fromEntries(source.derivation!.operands.map((operand) => [operand.label, operand.anchor])), result: source.value});
    // Sources that share a definition, components and date are comparable among themselves even when the account as a whole is not.
    const subsetKey = (source: (typeof account.sources)[number]) => `${source.definitionKey}|${source.components.join("+")}|${source.asOf}|${source.periodMonths}`;
    const subsets = [...new Set(account.sources.map(subsetKey))].map((key) => account.sources.filter((source) => subsetKey(source) === key)).filter((group) => group.length > 1).map((group) => {
      const values = group.map((source) => d(source.value));
      const groupBand = group.reduce((widest, source) => Decimal.max(widest, halfBand(source)), d(0));
      const check = checkIdentity({id: `${account.id}:subset:${group[0]!.definitionKey}`, left: Decimal.max(...values), right: Decimal.min(...values), absoluteTolerance: Decimal.max(d(tolerance.value), groupBand).toFixed()});
      record({id: `financial.accounting_identity:${account.id}:subset:${group[0]!.definitionKey}`, formula: "max(values) - min(values) among sources sharing definition, components and date", operands: Object.fromEntries(group.map((source) => [source.source, source.value])), anchors: Object.fromEntries(group.map((source) => [source.source, source.anchor])), result: check.difference});
      return {definitionKey: group[0]!.definitionKey, components: group[0]!.components, asOf: group[0]!.asOf, sources: group.map((source) => source.source).sort(compare), spread: check.difference, state: check.status === "pass" ? "closes" as const : "open" as const};
    }).sort((a, b) => compare(a.definitionKey, b.definitionKey));
    // Each explanation is directional; an account is explained only when every source is connected by explanations that hold.
    const valueOf = new Map(account.sources.map((source) => [source.source, read(source)]));
    const explanations = account.explanations.map((explanation) => {
      const expected = valueOf.get(explanation.fromSource)!.plus(explanation.adjustment);
      const actual = valueOf.get(explanation.toSource)!;
      const pairBand = Decimal.max(halfBand(account.sources.find((source) => source.source === explanation.fromSource)!), halfBand(account.sources.find((source) => source.source === explanation.toSource)!));
      const check = checkIdentity({id: `${account.id}:${explanation.fromSource}->${explanation.toSource}`, left: actual, right: expected, absoluteTolerance: Decimal.max(d(tolerance.value), pairBand).toFixed()});
      record({id: `financial.accounting_identity:${account.id}:explanation:${explanation.fromSource}->${explanation.toSource}`, formula: "to - (from + adjustment)", operands: {from: out(valueOf.get(explanation.fromSource)!), adjustment: explanation.adjustment, to: out(actual)}, anchors: {from: account.sources.find((source) => source.source === explanation.fromSource)!.anchor, adjustment: explanation.anchor, to: account.sources.find((source) => source.source === explanation.toSource)!.anchor}, result: check.difference});
      return {fromSource: explanation.fromSource, toSource: explanation.toSource, adjustment: explanation.adjustment, expected: out(expected), actual: out(actual), residual: check.difference, holds: check.status === "pass", description: explanation.description, anchor: explanation.anchor};
    });
    const parent = new Map(account.sources.map((source) => [source.source, source.source]));
    const find = (node: string): string => (parent.get(node) === node ? node : find(parent.get(node)!));
    for (const explanation of explanations.filter((entry) => entry.holds)) parent.set(find(explanation.fromSource), find(explanation.toSource));
    const roots = new Set(account.sources.map((source) => find(source.source)));
    // The connected groups of sources; more than one group means the account is not explained as a whole and no source is hidden.
    const groups = [...roots].map((root) => account.sources.map((source) => source.source).filter((source) => find(source) === root).sort(compare)).sort((a, b) => compare(a[0]!, b[0]!));
    const unexplained = roots.size > 1 ? account.sources.map((source) => source.source) : [];
    // An explanation exists to bridge presentations that count different things; it never bridges different dates, and without one the pair is not comparable.
    // An explanation bridges presentations, never dates and never spans: sources of different dates or different months are not comparable whatever the adjustment.
    const datesDiffer = reasons.some((reason) => reason.startsWith("the sources are dated differently") || reason.startsWith("the sources cover different spans"));
    if (datesDiffer || (reasons.length > 0 && explanations.length === 0)) {
      return {id: account.id, label: account.label, family: account.family, values, comparability: {comparable: false, reasons}, spread: out(spread), rounding_half_band: out(roundingBand), tolerance, state: "not_comparable", closes_within: null, explanations, explanation_groups: groups, unexplained_sources: account.sources.map((source) => source.source), comparable_subsets: subsets};
    }
    let state: PairState;
    let closesWithin: "tolerance" | "published_rounding" | null = null;
    // A spread that fits the published rounding closes by that rounding, whatever the policy tolerance; the tolerance answers only beyond the rounding.
    if (roundingBand.gt(0) && spread.lte(roundingBand) && reasons.length === 0) { state = "closes"; closesWithin = "published_rounding"; }
    else if (spread.lte(tolerance.value) && reasons.length === 0) { state = "closes"; closesWithin = "tolerance"; }
    else if (explanations.length > 0 && roots.size === 1) state = "explained";
    else state = "open";
    // A pair that closes as a whole has no open subset: the subsets exist to compare inside an account that does not close as a whole.
    return {id: account.id, label: account.label, family: account.family, values, comparability: {comparable: reasons.length === 0, reasons}, spread: out(spread), rounding_half_band: out(roundingBand), tolerance, state, closes_within: closesWithin, explanations, explanation_groups: groups, unexplained_sources: state === "open" ? (unexplained.length > 0 ? unexplained : account.sources.map((source) => source.source)) : [], comparable_subsets: state === "closes" ? [] : subsets};
  });

  const identities: ReconciliationOutput["identities"] = [];
  const identity = (id: string, formula: string, left: Decimal.Value, right: Decimal.Value, family: string, anchors: Record<string, Anchor>) => {
    const result = checkIdentity({id, left, right, absoluteTolerance: toleranceOf(family).value});
    record({id: `financial.accounting_identity:${id}`, formula, operands: {left: result.left, right: result.right, tolerance: result.tolerance}, anchors, result: result.difference});
    identities.push({id, formula, left: result.left, right: result.right, difference: result.difference, holds: result.status === "pass", state: result.status === "pass" ? "holds" : "fails", anchors});
  };
  const absent = (id: string, reason: string) => { incompleteReasons.push(reason); uncovered.push({id, state: "insufficient_evidence", reason}); };
  if (input.balanceSheet) identity("balance_sheet", "assets = liabilities + equity", input.balanceSheet.assets.value, d(input.balanceSheet.liabilities.value).plus(input.balanceSheet.equity.value), "balance_sheet", {assets: input.balanceSheet.assets.anchor, liabilities: input.balanceSheet.liabilities.anchor, equity: input.balanceSheet.equity.anchor});
  else absent("balance_sheet", "the balance sheet identity was not tested: assets, liabilities and equity are not in the base");
  if (input.debtBridge) {
    const byCategory: Record<string, Decimal> = {};
    const lineValue = (line: (typeof input.debtBridge.lines)[number]) => (line.sign === "absolute" ? d(line.published).abs() : d(line.published));
    for (const line of input.debtBridge.lines) byCategory[line.category] = (byCategory[line.category] ?? d(0)).plus(lineValue(line));
    const bridge = buildDebtBalanceBridge({openingBalance: input.debtBridge.opening.value, ...Object.fromEntries(Object.entries(byCategory).map(([category, value]) => [category, out(value)]))});
    record({id: "financial.debt_balance_bridge", formula: "opening + additions - reductions; each line read as published or as a magnitude, as declared", operands: {opening: input.debtBridge.opening.value, ...Object.fromEntries(input.debtBridge.lines.flatMap((line) => [[`${line.id}:published`, line.published], [`${line.id}:read`, out(lineValue(line))], [`${line.id}:sign`, line.sign]]))}, anchors: {opening: input.debtBridge.opening.anchor, ...Object.fromEntries(input.debtBridge.lines.map((line) => [line.id, line.anchor]))}, result: bridge.value});
    identity("debt_bridge", "opening + movements = closing", bridge.value, input.debtBridge.closing.value, "debt", {note: input.debtBridge.anchor, opening: input.debtBridge.opening.anchor, closing: input.debtBridge.closing.anchor, ...Object.fromEntries(input.debtBridge.lines.map((line) => [line.id, line.anchor]))});
  } else absent("debt_bridge", "the debt roll-forward was not tested: the note's movement is not in the base");
  if (input.cashBridge) identity("cash_bridge", "opening + net change = closing", d(input.cashBridge.opening.value).plus(input.cashBridge.netChange.value), input.cashBridge.closing.value, "cash", {opening: input.cashBridge.opening.anchor, netChange: input.cashBridge.netChange.anchor, closing: input.cashBridge.closing.anchor});
  else absent("cash_bridge", "the cash bridge was not tested: opening, net change and closing are not in the base");
  if (input.interestBridge) {
    const left = input.interestBridge.fromDebtMovement;
    const right = input.interestBridge.fromIncomeStatement;
    const sameComponents = sortStrings(left.components).join("+") === sortStrings(right.components).join("+");
    // The sign the source prints is kept unless the caller declares a magnitude reading; the normalization is traced, never silent.
    const leftValue = left.sign === "absolute" ? d(left.value).abs() : d(left.value);
    const rightValue = right.sign === "absolute" ? d(right.value).abs() : d(right.value);
    const bridge = checkIdentity({id: "interest_bridge", left: leftValue, right: rightValue, absoluteTolerance: toleranceOf("interest").value});
    record({id: "financial.interest_expense_bridge", formula: "accrued interest in the debt movement - interest expense in the income statement, each read as published or as a magnitude as declared", operands: {fromDebtMovementPublished: left.value, fromDebtMovementRead: out(leftValue), fromDebtMovementSign: left.sign, fromIncomeStatementPublished: right.value, fromIncomeStatementRead: out(rightValue), fromIncomeStatementSign: right.sign, tolerance: bridge.tolerance, comparable: String(sameComponents)}, anchors: {fromDebtMovement: left.anchor, fromIncomeStatement: right.anchor}, result: bridge.difference});
    const anchors = {fromDebtMovement: left.anchor, fromIncomeStatement: right.anchor};
    if (sameComponents) identities.push({id: "interest_bridge", formula: "accrued interest (note) = interest expense (income statement)", left: bridge.left, right: bridge.right, difference: bridge.difference, holds: bridge.status === "pass", state: bridge.status === "pass" ? "holds" : "fails", anchors});
    else {
      identities.push({id: "interest_bridge", formula: "accrued interest (note) = interest expense (income statement)", left: bridge.left, right: bridge.right, difference: bridge.difference, holds: null, state: "not_comparable", anchors});
      incompleteReasons.push(`the interest bridge is not comparable: the note's figure counts ${left.components.join(", ")} and the income statement's counts ${right.components.join(", ")}; the bridge is recorded, not closed`);
      uncovered.push({id: "interest_bridge", state: "insufficient_evidence", reason: `the note's figure counts ${left.components.join(", ")} and the income statement's counts ${right.components.join(", ")}; the difference of ${bridge.difference} is recorded, not bridged`});
    }
  } else absent("interest_bridge", "the interest expense bridge was not tested: the note's accrued interest or the income statement's expense is not in the base");

  const openDivergences = [
    ...reconciliations.filter((entry) => entry.state === "open" || entry.state === "not_comparable").map((entry) => ({
      id: entry.id, label: entry.label,
      values: entry.values.filter((value) => entry.unexplained_sources.includes(value.source)).map((value) => ({source: value.source, value: value.value, anchor: value.anchor})),
      reason: entry.state === "not_comparable"
        ? `the sources are not comparable: ${entry.comparability.reasons.join("; ")}; carried as a divergence, no value chosen${entry.comparable_subsets.length > 0 ? `; among themselves, ${entry.comparable_subsets.map((subset) => `${subset.sources.join(" and ")} (${subset.definitionKey}) differ by ${subset.spread} and ${subset.state === "closes" ? "close" : "stay open"}`).join("; ")}` : ""}`
        : entry.explanations.length > 0 ? `the stated adjustments leave ${entry.unexplained_sources.join(", ")} unexplained${entry.explanations.filter((explanation) => !explanation.holds).map((explanation) => ` (from ${explanation.fromSource} to ${explanation.toSource}: residual ${explanation.residual})`).join("")}` : `sources differ by ${entry.spread} with no explanation in the base; carried as a divergence, no value chosen`,
    })),
    ...reconciliations.flatMap((entry) => entry.comparable_subsets.filter((subset) => subset.state === "open").map((subset) => ({
      id: `${entry.id}:${subset.definitionKey}`, label: `${entry.label} (${subset.definitionKey})`,
      values: entry.values.filter((value) => subset.sources.includes(value.source)).map((value) => ({source: value.source, value: value.value, anchor: value.anchor})),
      reason: `${subset.sources.join(" and ")} state the same thing (${subset.definitionKey}, ${subset.components.join("+")}, ${subset.asOf}) and differ by ${subset.spread}; carried as a divergence, no value chosen`,
    }))),
  ];
  const state: ReconciliationOutput["state"] = blockReasons.length > 0 ? "blocked"
    : identities.some((entry) => entry.state === "fails") ? "identity_failed"
    : incompleteReasons.length > 0 ? "incomplete"
    : openDivergences.length > 0 ? "open_divergences"
    : reconciliations.some((entry) => entry.state === "explained") ? "differences_explained" : "closes";
  const body = {
    schema_version: "method.reconcile-financial-statements.v9" as const, reference_date: input.referenceDate, unit: input.unit, state,
    block_reasons: blockReasons, incomplete_reasons: incompleteReasons, reconciliations, open_divergences: openDivergences, identities, uncovered_terms: uncovered,
  };
  const inputFingerprint = fingerprint(input);
  return {...body, trace: {calculations, inputFingerprint, outputFingerprint: fingerprint({...body, calculations, inputFingerprint})}};
}

packages/credit-playbook/src/executors/d.content:
import {createHash} from "node:crypto";

import {aggregateDebtViews, applyRateShock, calculateCovenantHeadroom, calculateLeverage, calculateLiquidityCoverage, calculateProFormaPosition} from "@offroad/financial-core";
import Decimal from "decimal.js";
import {z} from "zod";

/**
 * Executor of the method `declare-scenarios` (v6, after the fifth independent review). When
 * management data is missing, the work goes on with declared scenarios: every parameter carries its
 * origin, its rationale and an anchor in a document of the class that origin requires; the executor
 * picks, per role and period, the best origin the register offers. A scenario that declares a lever
 * (shock, haircut, refinancing, rollover) without a registered assumption is blocked, never filled
 * with zero. CFADS is declared per period of the ledger's schedule and never split or repeated by
 * the executor; a CFADS haircut is its own assumption, never derived from the EBITDA haircut. Net
 * debt follows the contractual components; leverage carries the EBITDA's comparability; headroom
 * exists only against an applicable, resolved and comparable limit, otherwise the arithmetic
 * difference is shown as conditioned; a tier is applicable, conditional or not applicable, never a
 * bare boolean. Interest enters the service only when the ledger states it for that period, and the
 * rate shock is reported apart, never spread over periods. Every derived number carries every
 * assumption and anchor it rests on, the previous periods' included; a contracted source keeps its
 * contract and disbursement in the output; documents are bound to the corpus by their hash, checked
 * against the manifest the caller passes. An implied EBITDA is an approximation and the leverage
 * on it is shown to two decimals; the adverse scenario shocks the rate and haircuts the EBITDA, both;
 * a full rollover of future maturities is never taken from history; the EBITDA's comparability is
 * carried per instrument and the headroom follows the instrument of the covenant.
 */
const nonNegative = z.string().regex(/^\d+(\.\d+)?$/);
const nonEmpty = z.string().trim().min(1);
const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);
const key = z.string().regex(/^[a-z][a-z0-9_.-]*$/);
const moneyUnit = z.enum(["BRL", "BRL thousand", "BRL million", "USD", "USD thousand"]);
const unitSchema = z.enum(["BRL", "BRL thousand", "BRL million", "USD", "USD thousand", "ratio"]);
const anchorSchema = z.object({document: nonEmpty, page: z.number().int().positive().optional(), note: nonEmpty.optional(), clause: nonEmpty.optional()}).strict();
type Anchor = z.infer<typeof anchorSchema>;
const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
const UNIT_WORDS: Record<z.infer<typeof moneyUnit>, RegExp> = {"BRL": /\b(R\$|reais|BRL)\b(?!\s*(mil|milh))/i, "BRL thousand": /\b(mil|thousand)\b/i, "BRL million": /\b(milh[õo]es|million)\b/i, "USD": /\bUSD\b(?!\s*(mil|thousand))/i, "USD thousand": /\bUSD\b.*\b(mil|thousand)\b/i};

export const parameterOriginSchema = z.enum(["authorized_management_data", "public_announcement", "company_history", "versioned_benchmark", "user_range"]);
const originRank: Record<z.infer<typeof parameterOriginSchema>, number> = {authorized_management_data: 0, public_announcement: 1, company_history: 2, versioned_benchmark: 3, user_range: 4};
const originLabel: Record<string, string> = {authorized_management_data: "dado gerencial autorizado", public_announcement: "anúncio público", company_history: "histórico da companhia", versioned_benchmark: "benchmark versionado", user_range: "intervalo declarado pelo usuário"};
export const documentKindSchema = z.enum(["management", "announcement", "itr", "ledger", "benchmark", "user", "indenture", "contract", "disbursement_proof", "other"]);
/** The document classes each origin may cite; an announcement cannot pose as management data and a user range cannot pose as history. */
const ORIGIN_DOCUMENTS: Record<z.infer<typeof parameterOriginSchema>, Array<z.infer<typeof documentKindSchema>>> = {authorized_management_data: ["management"], public_announcement: ["announcement"], company_history: ["itr", "ledger"], versioned_benchmark: ["benchmark"], user_range: ["user"]};

export const assumptionRoleSchema = z.enum(["cfads", "cfads_haircut", "rate_shock", "ebitda_haircut", "new_debt", "refinanced_debt", "contracted_source", "rollover"]);
const RATIO_ROLES = new Set(["cfads_haircut", "rate_shock", "ebitda_haircut", "rollover"]);
const BOUNDED_ROLES = new Set(["cfads_haircut", "ebitda_haircut", "rollover"]);

export const assumptionSchema = z.object({
  key,
  role: assumptionRoleSchema,
  /** The period the assumption applies to; null for a scalar that applies everywhere. CFADS and contracted sources are always per period. */
  period: nonEmpty.nullable(),
  value: nonNegative,
  unit: unitSchema,
  origin: parameterOriginSchema,
  rationale: nonEmpty,
  asOf: isoDate,
  anchor: anchorSchema,
  confidence: z.enum(["high", "medium", "low"]),
  /** For a contracted source: the base must hold the contract and the disbursement, each in a document of its class. */
  evidence: z.object({contract: anchorSchema.nullable(), disbursement: anchorSchema.nullable()}).strict().nullable().default(null),
}).strict();

export const scenarioInputSchema = z.object({
  referenceDate: isoDate,
  unit: moneyUnit,
  /** Where the source states the unit; its note must name it, so a relabelled scale is refused. */
  unitAnchor: anchorSchema.extend({note: nonEmpty}),
  /** The corpus manifest (name and SHA-256 of every file), against which the documents below are checked; a document absent from it or with another hash is refused. */
  manifest: z.array(z.object({name: nonEmpty, sha256: z.string().regex(/^[a-f0-9]{64}$/)}).strict()).min(1),
  /** The documents of the base with their class and the SHA-256 the corpus manifest records; every anchor must name one, and an origin may cite only the classes it is allowed. */
  documents: z.array(z.object({name: nonEmpty, kind: documentKindSchema, sha256: z.string().regex(/^[a-f0-9]{64}$/)}).strict()).min(1),
  assumptions: z.array(assumptionSchema).min(1),
  position: z.object({
    perimeter: z.enum(["consolidated", "parent"]).default("consolidated"),
    /** Contractual net debt components at the reference date, each with its anchor; a release figure is not a component. */
    components: z.object({
      grossDebt: z.object({value: nonNegative, anchor: anchorSchema}).strict(),
      derivativeLiabilities: z.object({value: nonNegative, anchor: anchorSchema}).strict(),
      derivativeAssets: z.object({value: nonNegative, anchor: anchorSchema}).strict(),
      cashAndEquivalents: z.object({value: nonNegative, anchor: anchorSchema}).strict(),
      financialInvestments: z.object({value: nonNegative, anchor: anchorSchema}).strict(),
    }).strict(),
    /** The EBITDA the leverage is measured on: twelve months, its definition, how it was derived, and how comparable it is with the covenant definitions. */
    ltmEbitda: z.object({value: nonNegative, /** The twelve months the figure covers, as dates: an annualized quarter cannot claim them. */ periodStart: isoDate, periodEnd: isoDate, definitionKey: nonEmpty, basis: z.enum(["company_opened", "implied_from_reported_index", "derived_proxy"]), /** Comparability with each instrument's own EBITDA definition, from the covenant executor: the base definition and the adjustments each indenture adds. */ comparabilityByInstrument: z.array(z.object({instrument: nonEmpty, comparability: z.enum(["comparable", "conditional", "not_comparable"]), reasons: z.array(nonEmpty).default([])}).strict()).min(1), anchor: anchorSchema}).strict().nullable(),
    averageDebtBalance: z.object({value: nonNegative, basis: nonEmpty, anchor: anchorSchema}).strict(),
    baseAnnualRate: z.object({value: nonNegative, basis: nonEmpty, anchor: anchorSchema}).strict(),
  }).strict(),
  /** The covenant the scenarios are read against, from the covenant executor; null when none is resolved. */
  covenant: z.object({instrument: nonEmpty, limit: nonNegative, direction: z.enum(["maximum", "minimum"]), /** applicable when its condition is proven, conditional while the proof is missing, not_applicable when the indenture rules it out. */ tier: z.object({applicability: z.enum(["applicable", "conditional", "not_applicable"]), condition: nonEmpty}).strict(), state: z.enum(["resolved", "insufficient_evidence"]), comparability: z.enum(["comparable", "conditional", "not_comparable"]), measurement: z.object({frequency: z.enum(["annual", "semiannual", "quarterly"]), nextDate: isoDate}).strict(), anchor: anchorSchema}).strict().nullable().default(null),
  /** Debt service by period from the ledger, in the ledger's own periods; interest only when the ledger states it. */
  periods: z.array(z.object({period: nonEmpty, endsAt: isoDate, principal: z.object({value: nonNegative, anchor: anchorSchema}).strict(), interest: z.object({value: nonNegative, anchor: anchorSchema}).strict().nullable()}).strict()).min(1),
  scenarios: z.array(z.object({
    id: z.enum(["base", "adverse", "no_rollover"]).or(z.string().regex(/^[a-z][a-z0-9_-]*$/)),
    label: nonEmpty,
    rolloverAllowed: z.boolean(),
    usesRateShock: z.boolean().default(false),
    usesEbitdaHaircut: z.boolean().default(false),
    usesCfadsHaircut: z.boolean().default(false),
    usesRefinancing: z.boolean().default(false),
  }).strict()).min(1),
}).strict().superRefine((input, context) => {
  if (!UNIT_WORDS[input.unit].test(input.unitAnchor.note)) context.addIssue({code: "custom", path: ["unitAnchor"], message: `the unit anchor's note does not name the unit ${input.unit}; a relabelled scale is refused`});
  const documents = new Map(input.documents.map((document) => [document.name, document.kind]));
  const manifestNames = new Set<string>();
  input.manifest.forEach((entry, index) => { if (manifestNames.has(entry.name)) context.addIssue({code: "custom", path: ["manifest", index], message: `duplicate manifest entry ${entry.name}; a name with two hashes binds nothing`}); manifestNames.add(entry.name); });
  const manifest = new Map(input.manifest.map((entry) => [entry.name, entry.sha256]));
  const names = new Set<string>();
  input.documents.forEach((document, index) => {
    if (names.has(document.name)) context.addIssue({code: "custom", path: ["documents", index], message: `duplicate document ${document.name}`});
    names.add(document.name);
    const recorded = manifest.get(document.name);
    if (recorded === undefined) context.addIssue({code: "custom", path: ["documents", index], message: `${document.name} is not in the corpus manifest; a document outside the manifest is not evidence`});
    else if (recorded !== document.sha256) context.addIssue({code: "custom", path: ["documents", index], message: `${document.name} carries a hash the manifest does not record; the file is not the one the corpus froze`});
  });
  const checkAnchor = (anchor: Anchor, path: (string | number)[]) => { if (!documents.has(anchor.document)) context.addIssue({code: "custom", path, message: `anchor names ${anchor.document}, which is not a document of the base`}); };
  checkAnchor(input.unitAnchor, ["unitAnchor"]);
  for (const [name, component] of Object.entries(input.position.components)) checkAnchor(component.anchor, ["position", "components", name]);
  if (input.position.ltmEbitda) {
    checkAnchor(input.position.ltmEbitda.anchor, ["position", "ltmEbitda"]);
    const seenInstruments = new Set<string>();
    input.position.ltmEbitda.comparabilityByInstrument.forEach((entry, index) => { if (seenInstruments.has(entry.instrument)) context.addIssue({code: "custom", path: ["position", "ltmEbitda", "comparabilityByInstrument", index], message: `duplicate comparability reading for ${entry.instrument}`}); seenInstruments.add(entry.instrument); });
    const start = new Date(`${input.position.ltmEbitda.periodStart}T00:00:00Z`); start.setUTCMonth(start.getUTCMonth() + 12);
    if (start.toISOString().slice(0, 10) !== input.position.ltmEbitda.periodEnd) context.addIssue({code: "custom", path: ["position", "ltmEbitda"], message: `the EBITDA covers ${input.position.ltmEbitda.periodStart} to ${input.position.ltmEbitda.periodEnd}, not twelve months; an annualized shorter period is not an LTM figure`});
    if (input.position.ltmEbitda.periodEnd > input.referenceDate) context.addIssue({code: "custom", path: ["position", "ltmEbitda"], message: "the EBITDA period ends after the reference date"});
  }
  checkAnchor(input.position.averageDebtBalance.anchor, ["position", "averageDebtBalance"]);
  checkAnchor(input.position.baseAnnualRate.anchor, ["position", "baseAnnualRate"]);
  if (input.covenant) { checkAnchor(input.covenant.anchor, ["covenant"]); if (input.covenant.measurement.nextDate <= input.referenceDate) context.addIssue({code: "custom", path: ["covenant", "measurement"], message: "the next measurement date must follow the reference date"}); }
  const periodIds = new Set<string>();
  const sorted = [...input.periods].sort((a, b) => compare(a.endsAt, b.endsAt) || compare(a.period, b.period));
  sorted.forEach((period, index) => {
    if (periodIds.has(period.period)) context.addIssue({code: "custom", path: ["periods", index], message: `duplicate period ${period.period}`});
    periodIds.add(period.period);
    if (period.endsAt <= input.referenceDate) context.addIssue({code: "custom", path: ["periods", index], message: `period ${period.period} ends on or before the reference date`});
    checkAnchor(period.principal.anchor, ["periods", index, "principal"]);
    if (period.interest) checkAnchor(period.interest.anchor, ["periods", index, "interest"]);
  });
  const keys = new Set<string>();
  input.assumptions.forEach((assumption, index) => {
    if (keys.has(assumption.key)) context.addIssue({code: "custom", path: ["assumptions", index, "key"], message: `duplicate assumption ${assumption.key}`});
    keys.add(assumption.key);
    checkAnchor(assumption.anchor, ["assumptions", index, "anchor"]);
    const kind = documents.get(assumption.anchor.document);
    if (kind && !ORIGIN_DOCUMENTS[assumption.origin].includes(kind)) context.addIssue({code: "custom", path: ["assumptions", index, "origin"], message: `${assumption.key}: the origin ${assumption.origin} cannot rest on a ${kind} document; it needs ${ORIGIN_DOCUMENTS[assumption.origin].join(" or ")}`});
    if (assumption.role === "contracted_source") {
      if (!assumption.evidence || !assumption.evidence.contract || !assumption.evidence.disbursement) context.addIssue({code: "custom", path: ["assumptions", index, "evidence"], message: `${assumption.key}: a contracted source needs its contract and its disbursement in the base; an approval is not a source`});
      else {
        if (documents.get(assumption.evidence.contract.document) !== "contract") context.addIssue({code: "custom", path: ["assumptions", index, "evidence", "contract"], message: `${assumption.key}: the contract must be a contract document of the base`});
        if (documents.get(assumption.evidence.disbursement.document) !== "disbursement_proof") context.addIssue({code: "custom", path: ["assumptions", index, "evidence", "disbursement"], message: `${assumption.key}: the disbursement must be a disbursement proof of the base`});
        if (assumption.evidence.contract.document === assumption.evidence.disbursement.document) context.addIssue({code: "custom", path: ["assumptions", index, "evidence"], message: `${assumption.key}: contract and disbursement proof must be two documents`});
      }
      if (assumption.period === null) context.addIssue({code: "custom", path: ["assumptions", index, "period"], message: `${assumption.key}: a contracted source belongs to one period and is used once`});
    }
    if (assumption.role === "cfads" && assumption.period === null) context.addIssue({code: "custom", path: ["assumptions", index, "period"], message: `${assumption.key}: CFADS is declared per period of the schedule, never split or repeated by the executor`});
    if (RATIO_ROLES.has(assumption.role) && assumption.unit !== "ratio") context.addIssue({code: "custom", path: ["assumptions", index, "unit"], message: `${assumption.key}: a ${assumption.role} is a ratio`});
    if (BOUNDED_ROLES.has(assumption.role) && new Decimal(assumption.value).gt(1)) context.addIssue({code: "custom", path: ["assumptions", index, "value"], message: `${assumption.key}: a ${assumption.role} lies between 0 and 1`});
    if ((assumption.role === "rate_shock" || assumption.role === "ebitda_haircut" || assumption.role === "cfads_haircut") && new Decimal(assumption.value).isZero()) context.addIssue({code: "custom", path: ["assumptions", index, "value"], message: `${assumption.key}: a ${assumption.role} of zero is not a stress; register a positive value or leave the lever out`});
    if (!RATIO_ROLES.has(assumption.role) && assumption.unit !== input.unit) context.addIssue({code: "custom", path: ["assumptions", index, "unit"], message: `${assumption.key}: a monetary assumption must be in ${input.unit}`});
    if (assumption.period !== null && !periodIds.has(assumption.period)) context.addIssue({code: "custom", path: ["assumptions", index, "period"], message: `${assumption.key} names a period that is not projected`});
    if (assumption.role === "rollover" && assumption.origin === "company_history") context.addIssue({code: "custom", path: ["assumptions", index, "origin"], message: `${assumption.key}: past rollovers in the cash flow statement are history, not a policy for future maturities; a rollover share must be declared as management data or as a user range`});
  });
  const ids = new Set<string>();
  input.scenarios.forEach((scenario, index) => {
    if (ids.has(scenario.id)) context.addIssue({code: "custom", path: ["scenarios", index], message: `duplicate scenario ${scenario.id}`});
    ids.add(scenario.id);
    if (scenario.id === "adverse" && (!scenario.usesRateShock || !scenario.usesEbitdaHaircut)) context.addIssue({code: "custom", path: ["scenarios", index], message: "the adverse scenario of the minimum set shocks the rate and haircuts the EBITDA, both; an adverse scenario with less is a label"});
    if (scenario.id === "no_rollover" && scenario.rolloverAllowed) context.addIssue({code: "custom", path: ["scenarios", index], message: "the no-rollover scenario cannot allow rollover"});
  });
  for (const required of ["base", "adverse", "no_rollover"]) if (!ids.has(required)) context.addIssue({code: "custom", path: ["scenarios"], message: `the minimum set needs a ${required} scenario`});
});
export type ScenarioInput = z.input<typeof scenarioInputSchema>;

type Origin = {origin: string; key: string; anchor: Anchor; evidence?: {contract: Anchor; disbursement: Anchor}};
type Calculation = {id: string; scenario: string; formula: string; operands: Record<string, string>; result: string; unit: string; origins: Origin[]};
type Assumption = z.infer<typeof assumptionSchema>;

export type ScenarioOutput = {
  schema_version: "method.declare-scenarios.v6";
  reference_date: string;
  unit: string;
  state: "declared" | "partial" | "blocked";
  block_reasons: string[];
  assumption_register: Array<{key: string; role: string; period: string | null; value: string; unit: string; origin: string; origin_rank: number; rationale: string; as_of: string; anchor: Anchor; evidence: {contract: Anchor; disbursement: Anchor} | null; confidence: string; selected: boolean}>;
  scenarios: Array<{
    id: string; label: string;
    state: "declared" | "partial" | "blocked";
    block_reasons: string[];
    parameters: Array<{role: string; period: string | null; key: string; value: string; origin: string; rationale: string; anchor: Anchor; evidence: {contract: Anchor; disbursement: Anchor} | null}>;
    results: {
      pro_forma: {gross_debt: string; deductible_cash: string; contractual_net_debt: string; leverage: {value: string; precision: "exact" | "approximate_two_decimals"; precision_note: string | null; ebitda_definition: string; ebitda_basis: string; comparability_by_instrument: Array<{instrument: string; comparability: string; reasons: string[]}>} | null; origins: Origin[]};
      headroom: {absolute: string; within_limit: boolean; limit: string; instrument: string; note: string} | null;
      headroom_note: string;
      interest: {base: string; stressed: string; delta: string; origins: Origin[]} | null;
      liquidity: {basis: "principal_only" | "full_debt_service" | "mixed"; rows: Array<{period: string; basis: "principal_only" | "full_debt_service"; principal: string; interest: string | null; cfads_declared: string; cfads_used: string; cfads_haircut: string | null; contracted_sources: string; rolled_principal: string; coverage: string | null; closing_cash: string; deficit: string; origins: Origin[]}>} | null;
    };
    caveat: string;
    uncovered_terms: Array<{id: string; state: "insufficient_evidence"; reason: string}>;
  }>;
  trace: {calculations: Calculation[]; inputFingerprint: string; outputFingerprint: string};
};

const d = (value: Decimal.Value) => new Decimal(value);
const out = (value: Decimal) => value.toDecimalPlaces(8).toFixed();
const stableStringify = (value: unknown): string => JSON.stringify(value, (_key, inner: unknown) => (inner && typeof inner === "object" && !Array.isArray(inner) ? Object.fromEntries(Object.entries(inner as Record<string, unknown>).sort(([a], [b]) => compare(a, b))) : inner));
const fingerprint = (value: unknown) => createHash("sha256").update(stableStringify(value)).digest("hex");

function canonical(input: z.infer<typeof scenarioInputSchema>) {
  return {
    ...input,
    documents: [...input.documents].sort((a, b) => compare(a.name, b.name)),
    assumptions: [...input.assumptions].sort((a, b) => compare(a.key, b.key)),
    scenarios: [...input.scenarios].sort((a, b) => compare(a.id, b.id)),
    periods: [...input.periods].sort((a, b) => compare(a.endsAt, b.endsAt) || compare(a.period, b.period)),
    manifest: [...input.manifest].sort((a, b) => compare(a.name, b.name)),
    position: {...input.position, ltmEbitda: input.position.ltmEbitda ? {...input.position.ltmEbitda, comparabilityByInstrument: [...input.position.ltmEbitda.comparabilityByInstrument].sort((a, b) => compare(a.instrument, b.instrument)).map((entry) => ({...entry, reasons: [...entry.reasons].sort(compare)}))} : null},
  };
}

export function declareScenarios(raw: ScenarioInput): ScenarioOutput {
  const input = canonical(scenarioInputSchema.parse(raw));
  const calculations: Calculation[] = [];
  const selectedKeys = new Set<string>();
  const originOf = (assumption: Assumption): Origin => ({origin: originLabel[assumption.origin] ?? assumption.origin, key: assumption.key, anchor: assumption.anchor, ...(assumption.evidence?.contract && assumption.evidence.disbursement ? {evidence: {contract: assumption.evidence.contract, disbursement: assumption.evidence.disbursement}} : {})});
  const baseOrigins: Origin[] = [
    {origin: "base pública", key: "position.grossDebt", anchor: input.position.components.grossDebt.anchor},
    {origin: "base pública", key: "position.cashAndEquivalents", anchor: input.position.components.cashAndEquivalents.anchor},
    {origin: "base pública", key: "position.financialInvestments", anchor: input.position.components.financialInvestments.anchor},
    {origin: "base pública", key: "position.derivativeLiabilities", anchor: input.position.components.derivativeLiabilities.anchor},
    {origin: "base pública", key: "position.derivativeAssets", anchor: input.position.components.derivativeAssets.anchor},
  ];
  /** The best origin the register offers for a role and period: lowest rank, then highest confidence, then key. */
  const pick = (role: Assumption["role"], period: string | null): Assumption | null => {
    const candidates = input.assumptions.filter((assumption) => assumption.role === role && (assumption.period === period || (period !== null && assumption.period === null && role !== "cfads")));
    const confidenceRank = {high: 0, medium: 1, low: 2};
    return [...candidates].sort((a, b) => originRank[a.origin] - originRank[b.origin] || confidenceRank[a.confidence] - confidenceRank[b.confidence] || compare(a.key, b.key))[0] ?? null;
  };
  const components = input.position.components;
  const deductibleCash = d(components.cashAndEquivalents.value).plus(components.financialInvestments.value);
  const views = aggregateDebtViews({rows: [{id: "gross_debt", principal: components.grossDebt.value, covenantIncluded: true}, {id: "derivative_liabilities", principal: components.derivativeLiabilities.value, covenantIncluded: true}], cash: deductibleCash.plus(components.derivativeAssets.value)});
  calculations.push({id: "financial.debt_views:contractual", scenario: "all", formula: "grossDebt + derivativeLiabilities - cashAndEquivalents - financialInvestments - derivativeAssets", operands: {grossDebt: components.grossDebt.value, derivativeLiabilities: components.derivativeLiabilities.value, cashAndEquivalents: components.cashAndEquivalents.value, financialInvestments: components.financialInvestments.value, derivativeAssets: components.derivativeAssets.value}, result: views.netFinancialDebt, unit: input.unit, origins: baseOrigins});

  const scenarios = input.scenarios.map((scenario): ScenarioOutput["scenarios"][number] => {
    const parameters: ScenarioOutput["scenarios"][number]["parameters"] = [];
    const uncovered: ScenarioOutput["scenarios"][number]["uncovered_terms"] = [];
    const blocks: string[] = [];
    const use = (role: Assumption["role"], period: string | null): Assumption | null => {
      const assumption = pick(role, period);
      if (assumption) { selectedKeys.add(assumption.key); parameters.push({role, period, key: assumption.key, value: out(d(assumption.value)), origin: assumption.origin, rationale: assumption.rationale, anchor: assumption.anchor, evidence: null}); }
      return assumption;
    };
    const originsOf = (...items: Array<Assumption | null>) => items.filter((item): item is Assumption => item !== null).map(originOf).sort((a, b) => compare(a.key, b.key));
    const rollover = scenario.rolloverAllowed ? use("rollover", null) : null;
    if (scenario.rolloverAllowed && !rollover) blocks.push("the scenario assumes rollover of maturing principal but no rollover assumption is registered with an origin; rollover is not assumed by default");
    const shock = scenario.usesRateShock ? use("rate_shock", null) : null;
    if (scenario.usesRateShock && !shock) blocks.push("the scenario declares a rate shock but none is registered; a shock of zero is not a shock");
    const haircut = scenario.usesEbitdaHaircut ? use("ebitda_haircut", null) : null;
    if (scenario.usesEbitdaHaircut && !haircut) blocks.push("the scenario declares an EBITDA haircut but none is registered; the haircut is not filled with zero");
    const cfadsHaircut = scenario.usesCfadsHaircut ? use("cfads_haircut", null) : null;
    if (scenario.usesCfadsHaircut && !cfadsHaircut) blocks.push("the scenario declares a CFADS haircut but none is registered; the EBITDA haircut is never applied to CFADS in its place");
    const newDebt = scenario.usesRefinancing ? use("new_debt", null) : null;
    const refinanced = scenario.usesRefinancing ? use("refinanced_debt", null) : null;
    if (scenario.usesRefinancing && (!newDebt || !refinanced)) blocks.push("a refinancing is new debt replacing old debt; both amounts must be registered, and a subtraction alone is not a refinancing");
    const caveatFor = (state: string) => {
      const used = parameters.map((parameter) => `${originLabel[parameter.origin] ?? parameter.origin} (${parameter.key}: ${parameter.rationale})`);
      return `Cenário ${scenario.label} (${state}), declarado a partir de ${used.join("; ") || "nenhum parâmetro próprio"}; não é guidance da companhia e não afirma o que a companhia fará; cada número acima carrega as premissas e âncoras de que depende.`;
    };
    const headroomNote = (leverage: string | null): string => {
      if (!input.covenant) return "no covenant limit received; no headroom";
      if (!leverage) return "no leverage measured; no headroom";
      const reasons: string[] = [];
      if (input.covenant.state !== "resolved") reasons.push(`the limit of ${input.covenant.instrument} is ${input.covenant.state}`);
      if (input.covenant.tier.applicability === "conditional") reasons.push(`the ${input.covenant.limit}x tier is conditional (${input.covenant.tier.condition})`);
      if (input.covenant.tier.applicability === "not_applicable") reasons.push(`the ${input.covenant.limit}x tier is not applicable (${input.covenant.tier.condition})`);
      if (input.covenant.comparability !== "comparable") reasons.push(`the covenant comparison is ${input.covenant.comparability}`);
      const forInstrument = input.position.ltmEbitda?.comparabilityByInstrument.find((entry) => entry.instrument === input.covenant!.instrument);
      if (input.position.ltmEbitda && !forInstrument) reasons.push(`the EBITDA carries no comparability reading for ${input.covenant.instrument}`);
      if (forInstrument && forInstrument.comparability !== "comparable") reasons.push(`the EBITDA is ${forInstrument.comparability} with the definition of ${input.covenant.instrument}${forInstrument.reasons.length > 0 ? ` (${forInstrument.reasons.join("; ")})` : ""}`);
      if (reasons.length === 0) return `headroom measured against the ${input.covenant.limit}x tier of ${input.covenant.instrument}, as a scenario reading before the measurement of ${input.covenant.measurement.nextDate}`;
      const arithmetic = input.covenant.direction === "maximum" ? d(input.covenant.limit).minus(leverage) : d(leverage).minus(input.covenant.limit);
      return `no headroom: ${reasons.join("; ")}. The arithmetic difference against ${input.covenant.limit}x is ${out(arithmetic)}x and is conditioned, not a headroom`;
    };
    if (blocks.length > 0) {
      for (const block of blocks) uncovered.push({id: `lever:${scenario.id}`, state: "insufficient_evidence", reason: block});
      return {id: scenario.id, label: scenario.label, state: "blocked", block_reasons: blocks, parameters, results: {pro_forma: {gross_debt: components.grossDebt.value, deductible_cash: out(deductibleCash), contractual_net_debt: views.netFinancialDebt, leverage: null, origins: baseOrigins}, headroom: null, headroom_note: "scenario blocked; nothing measured", interest: null, liquidity: null}, caveat: caveatFor("blocked"), uncovered_terms: uncovered};
    }

    // Pro forma through financial-core, on the contractual net debt.
    const ebitda = input.position.ltmEbitda;
    const ebitdaBase = ebitda ? d(ebitda.value).times(d(1).minus(haircut ? haircut.value : 0)) : null;
    const proForma = calculateProFormaPosition({grossDebt: components.grossDebt.value, unrestrictedCash: deductibleCash.toFixed(), newDebt: newDebt ? newDebt.value : "0", refinancedDebt: refinanced ? refinanced.value : "0", feesPaidFromCash: "0", cashContribution: "0"});
    const contractualNetDebt = d(proForma.grossDebt).plus(components.derivativeLiabilities.value).minus(components.derivativeAssets.value).minus(proForma.unrestrictedCash);
    // An EBITDA implied from a two-decimal reported index carries that precision: the leverage on it is shown to two decimals, as an approximation.
    const exactLeverage = ebitdaBase && ebitdaBase.gt(0) ? calculateLeverage(out(contractualNetDebt), out(ebitdaBase)).value : null;
    const approximate = ebitda?.basis === "implied_from_reported_index";
    const leverageValue = exactLeverage === null ? null : approximate ? d(exactLeverage).toDecimalPlaces(2).toFixed() : exactLeverage;
    const proFormaOrigins = [...baseOrigins, ...(ebitda ? [{origin: "base pública", key: "position.ltmEbitda", anchor: ebitda.anchor}] : []), ...originsOf(newDebt, refinanced, haircut)];
    calculations.push({id: "operation.pro_forma_position", scenario: scenario.id, formula: "grossDebt + newDebt - refinancedDebt ; contractual net debt with derivatives less deductible cash ; leverage = net debt / (EBITDA * (1 - ebitdaHaircut))", operands: {grossDebt: components.grossDebt.value, newDebt: newDebt ? newDebt.value : "0", refinancedDebt: refinanced ? refinanced.value : "0", ebitda: ebitdaBase ? out(ebitdaBase) : "insufficient_evidence", ebitdaHaircut: haircut ? haircut.value : "0"}, result: out(contractualNetDebt), unit: input.unit, origins: proFormaOrigins});
    if (!ebitda) uncovered.push({id: "leverage", state: "insufficient_evidence", reason: "no EBITDA with a definition in the base; leverage is not measured"});
    else if (ebitdaBase && ebitdaBase.lte(0)) uncovered.push({id: "leverage", state: "insufficient_evidence", reason: "the EBITDA after the haircut is zero or negative; leverage is not measured"});

    let headroom: ScenarioOutput["scenarios"][number]["results"]["headroom"] = null;
    const note = headroomNote(leverageValue);
    if (input.covenant && leverageValue && note.startsWith("headroom measured")) {
      const result = calculateCovenantHeadroom({actual: leverageValue, limit: input.covenant.limit, direction: input.covenant.direction});
      calculations.push({id: "structure.covenant_headroom", scenario: scenario.id, formula: input.covenant.direction === "maximum" ? "limit - leverage" : "leverage - limit", operands: {limit: input.covenant.limit, leverage: leverageValue}, result: result.absolute, unit: "x", origins: [...proFormaOrigins, {origin: "base pública", key: "covenant", anchor: input.covenant.anchor}]});
      headroom = {absolute: result.absolute, within_limit: result.passes, limit: input.covenant.limit, instrument: input.covenant.instrument, note};
    }

    let interest: ScenarioOutput["scenarios"][number]["results"]["interest"] = null;
    if (shock) {
      const shocked = applyRateShock({averageBalance: input.position.averageDebtBalance.value, baseRate: input.position.baseAnnualRate.value, shock: shock.value});
      const origins = [{origin: "base pública", key: "position.averageDebtBalance", anchor: input.position.averageDebtBalance.anchor}, {origin: "base pública", key: "position.baseAnnualRate", anchor: input.position.baseAnnualRate.anchor}, ...originsOf(shock)];
      calculations.push({id: "financial.rate_shock", scenario: scenario.id, formula: "averageBalance * (baseRate + shock) - averageBalance * baseRate", operands: {averageBalance: input.position.averageDebtBalance.value, baseRate: input.position.baseAnnualRate.value, shock: shock.value}, result: shocked.delta, unit: input.unit, origins});
      interest = {base: shocked.baseInterest, stressed: shocked.stressedInterest, delta: shocked.delta, origins};
    }

    // Liquidity: CFADS per period from the register (its own haircut, never the EBITDA's), contracted sources once in their period, rollover only under a registered assumption.
    const periodInputs = input.periods.map((period) => {
      const cfads = use("cfads", period.period);
      if (!cfads) uncovered.push({id: `cfads:${period.period}`, state: "insufficient_evidence", reason: `no CFADS registered for ${period.period}; the cover of that period is not measured and no figure is repeated from another period`});
      const sources = input.assumptions.filter((assumption) => assumption.role === "contracted_source" && assumption.period === period.period);
      for (const source of sources) { selectedKeys.add(source.key); parameters.push({role: "contracted_source", period: period.period, key: source.key, value: out(d(source.value)), origin: source.origin, rationale: source.rationale, anchor: source.anchor, evidence: source.evidence?.contract && source.evidence.disbursement ? {contract: source.evidence.contract, disbursement: source.evidence.disbursement} : null}); }
      const contracted = sources.reduce((sum, source) => sum.plus(source.value), d(0));
      const rolled = scenario.rolloverAllowed && rollover ? d(period.principal.value).times(rollover.value) : d(0);
      const used = cfads ? d(cfads.value).times(d(1).minus(cfadsHaircut ? cfadsHaircut.value : 0)) : null;
      const origins: Origin[] = [{origin: "base pública", key: `periods.${period.period}.principal`, anchor: period.principal.anchor}, ...(period.interest ? [{origin: "base pública", key: `periods.${period.period}.interest`, anchor: period.interest.anchor}] : []), ...originsOf(cfads, cfadsHaircut, ...sources, scenario.rolloverAllowed ? rollover : null)];
      return {period, cfads, used, contracted, rolled, origins};
    });
    // Each period's numbers rest on everything before them: the opening cash of the first, then every earlier period's inputs.
    const cashOrigins: Origin[] = [{origin: "base pública", key: "position.cashAndEquivalents", anchor: components.cashAndEquivalents.anchor}, {origin: "base pública", key: "position.financialInvestments", anchor: components.financialInvestments.anchor}];
    const cumulativeOrigins = periodInputs.map((_entry, index) => [...cashOrigins, ...periodInputs.slice(0, index + 1).flatMap((previous) => previous.origins)].filter((origin, position, all) => all.findIndex((other) => other.key === origin.key) === position));
    const measurable = periodInputs.every((entry) => entry.cfads !== null);
    let liquidity: ScenarioOutput["scenarios"][number]["results"]["liquidity"] = null;
    if (measurable) {
      // The shock delta is reported apart (above) and never spread over the periods: only the interest the ledger states enters the service.
      const rows = calculateLiquidityCoverage(periodInputs.map((entry, index) => ({period: entry.period.period, openingCash: index === 0 ? deductibleCash : d(0), cfads: entry.used!, contractedSources: entry.contracted.plus(entry.rolled), principal: entry.period.principal.value, interest: entry.period.interest ? entry.period.interest.value : 0})));
      rows.forEach((row, index) => {
        const entry = periodInputs[index]!;
        calculations.push({id: `financial.liquidity_coverage:${row.period}`, scenario: scenario.id, formula: `(openingCash + cfadsUsed + contractedSources + rolledPrincipal) / (principal${entry.period.interest ? " + interest" : ""})`, operands: {openingCash: row.openingCash, cfadsUsed: out(entry.used!), contractedSources: out(entry.contracted), rolledPrincipal: out(entry.rolled), debtService: row.debtService}, result: row.coverage ?? "n/a", unit: "x", origins: cumulativeOrigins[index]!});
      });
      const bases = periodInputs.map((entry) => (entry.period.interest ? "full_debt_service" as const : "principal_only" as const));
      liquidity = {basis: bases.every((basis) => basis === "full_debt_service") ? "full_debt_service" : bases.every((basis) => basis === "principal_only") ? "principal_only" : "mixed", rows: rows.map((row, index) => { const entry = periodInputs[index]!; return {period: row.period, basis: bases[index]!, principal: out(d(entry.period.principal.value)), interest: entry.period.interest ? out(d(entry.period.interest.value)) : null, cfads_declared: out(d(entry.cfads!.value)), cfads_used: out(entry.used!), cfads_haircut: cfadsHaircut ? cfadsHaircut.value : null, contracted_sources: out(entry.contracted), rolled_principal: out(entry.rolled), coverage: row.coverage, closing_cash: row.closingCash, deficit: row.deficit, origins: cumulativeOrigins[index]!}; })};
    }
    for (const period of input.periods) if (!period.interest) uncovered.push({id: `interest:${period.period}`, state: "insufficient_evidence", reason: `the ledger states no interest for ${period.period}; that period's cover is principal-only and the shock delta is reported apart, never spread over periods`});
    const state: "declared" | "partial" = uncovered.length > 0 ? "partial" : "declared";
    return {
      id: scenario.id, label: scenario.label, state, block_reasons: [], parameters,
      results: {
        pro_forma: {gross_debt: proForma.grossDebt, deductible_cash: proForma.unrestrictedCash, contractual_net_debt: out(contractualNetDebt), leverage: leverageValue && ebitda ? {value: leverageValue, precision: approximate ? "approximate_two_decimals" : "exact", precision_note: approximate ? `the EBITDA is implied from a reported index of two decimals; the leverage is about ${leverageValue}x, not a figure to eight decimals` : null, ebitda_definition: ebitda.definitionKey, ebitda_basis: ebitda.basis, comparability_by_instrument: ebitda.comparabilityByInstrument} : null, origins: proFormaOrigins},
        headroom, headroom_note: note, interest, liquidity,
      },
      caveat: caveatFor(state), uncovered_terms: uncovered,
    };
  });
  const register = input.assumptions.map((assumption) => ({key: assumption.key, role: assumption.role, period: assumption.period, value: out(d(assumption.value)), unit: assumption.unit, origin: assumption.origin, origin_rank: originRank[assumption.origin], rationale: assumption.rationale, as_of: assumption.asOf, anchor: assumption.anchor, evidence: assumption.evidence?.contract && assumption.evidence.disbursement ? {contract: assumption.evidence.contract, disbursement: assumption.evidence.disbursement} : null, confidence: assumption.confidence, selected: selectedKeys.has(assumption.key)}));
  const minimum = scenarios.filter((scenario) => ["base", "adverse", "no_rollover"].includes(scenario.id));
  const blockReasons = minimum.filter((scenario) => scenario.state === "blocked").map((scenario) => `${scenario.id}: ${scenario.block_reasons.join("; ")}`);
  const state: ScenarioOutput["state"] = blockReasons.length > 0 ? "blocked" : scenarios.some((scenario) => scenario.state === "partial") ? "partial" : "declared";
  const body = {schema_version: "method.declare-scenarios.v6" as const, reference_date: input.referenceDate, unit: input.unit, state, block_reasons: blockReasons, assumption_register: register, scenarios};
  const inputFingerprint = fingerprint(input);
  return {...body, trace: {calculations, inputFingerprint, outputFingerprint: fingerprint({...body, calculations, inputFingerprint})}};
}

