import {createHash} from "node:crypto";

import {macaulayDurationBusinessDays, presentValueByBusinessDays} from "@offroad/financial-core";
import Decimal from "decimal.js";
import {z} from "zod";

/**
 * Executor of the method `estimate-exit-cost-by-series` (v8, after the sixth independent review).
 * For each series an alternative wants to retire on a date: which mechanisms its indenture offers on
 * that date, each with its own formula, scope and quote day, and what each costs with what the base
 * holds. The base of any price is the nominal at the exit date (updated where indexed, with the
 * derivation the source allows), the remuneration accrued to that date and the charges the indenture
 * states, each dated at the exit and anchored; a 31/05 balance is not a nominal at 04/09, and a
 * missing component is insufficient evidence, never zero. Mechanisms are never merged: the DI
 * premium is [(1 + p)^(DU/252) - 1] over the amount retired, truncated at eight decimals; an
 * extraordinary amortization retires a fraction the indenture caps and never competes as a full
 * exit; a make-whole redemption discounts the remaining flows at the quote of the contractual day
 * (the prior or the second prior business day, as the series says, and that distance is checked
 * against the calendar), adds the charges the indenture adds, and applies the floor the series says
 * (the updated value, or none); the duration that selects the reference security is discounted at
 * the series' own remuneration; a negotiated offer is open since issuance with a premium to be set;
 * an acquisition depends on the seller and may be partial. Every anchor names a document of the
 * base's registry and every mechanism cites the series' indenture with its clause; a series without
 * an indenture is not priced. Business days are the weekdays less the holidays the calendar lists,
 * for the DI premium as for the quote distance. A negotiated offer retires what adheres, all or
 * part. The reference security of a make-whole must be the nearest in duration among the
 * candidates the base lists (by business days for an NTN-B, by calendar days for a Pre x DI vertex),
 * or the route is insufficient evidence; a tie between candidates is recorded. The DI premium is
 * computed per debenture on the unit price and truncated, then multiplied by the quantity, when
 * the base gives the quantity; otherwise on the aggregate, declared as an approximation. Discount
 * factors of a make-whole are rounded at nine decimals, as the indentures write. A negotiated offer
 * prices what adhered: with the premium known and the adhesion unknown, nothing is retired yet.
 * Mechanisms the indenture offers and the input does not represent are named as gaps.
 */
const nonNegative = z.string().regex(/^\d+(\.\d+)?$/);
const nonEmpty = z.string().trim().min(1);
/** A calendar date that exists: the regex alone would let 2026-99-99 through. */
const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/).refine((value) => { const [year, month, day] = value.split("-").map(Number) as [number, number, number]; const date = new Date(Date.UTC(year, month - 1, day)); return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day; }, {message: "not a calendar date"});
const unitSchema = z.enum(["BRL", "BRL thousand", "BRL million", "USD", "USD thousand"]);
const anchorSchema = z.object({document: nonEmpty, clause: nonEmpty.optional(), page: z.number().int().positive().optional(), note: nonEmpty.optional()}).strict();
type Anchor = z.infer<typeof anchorSchema>;
const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);

/** A dated amount with its anchor; the base of every price is built from these, never from a default. */
const datedAmountSchema = z.object({value: nonNegative, asOf: isoDate, anchor: anchorSchema}).strict();
const quoteSchema = z.object({
  rate: nonNegative,
  quoteDate: isoDate,
  /** Business days between the quote date and the exit date: the weekdays between them less the holidays the calendar lists. */
  businessDaysBeforeExit: z.number().int().positive(),
  /** Holidays between the quote date and the exit date, from the calendar the base cites (zero must be stated too). */
  holidaysBetween: z.object({count: z.number().int().nonnegative(), anchor: anchorSchema}).strict(),
  security: nonEmpty,
  /** The reference security's own duration (business days for an NTN-B, calendar days for a Pre x DI vertex), and the candidates the source lists with theirs: the chosen security must be the nearest to the series' duration on the same count. */
  securityDurationBusinessDays: z.number().int().positive().nullable().default(null),
  securityCalendarDays: z.number().int().positive().nullable().default(null),
  candidates: z.array(z.object({security: nonEmpty, durationBusinessDays: z.number().int().positive().nullable().default(null), calendarDays: z.number().int().positive().nullable().default(null)}).strict()).min(1),
  anchor: anchorSchema,
}).strict();
/** Business days to maturity: the weekdays between the exit and the maturity less the holidays the calendar lists (zero must be stated too). */
const businessDaysSchema = z.object({count: z.number().int().nonnegative(), maturity: isoDate, holidays: z.object({count: z.number().int().nonnegative(), anchor: anchorSchema}).strict(), anchor: anchorSchema}).strict();
const referenceRateSchema = z.enum(["NTN-B (ANBIMA indicative, nearest duration)", "B3 Pre x DI curve (nearest vertex to remaining duration)"]);
const makeWholeFields = {
  availableFrom: isoDate,
  referenceRate: referenceRateSchema,
  /** The floor the series writes: the updated value (max of A and B) or none (present value only). */
  floor: z.enum(["max_with_base", "present_value_only"]),
  /** The contractual quote day the series writes. */
  quoteDay: z.enum(["prior_business_day", "second_prior_business_day"]),
  /** The quote of that day, when the base holds it. */
  quote: quoteSchema.nullable(),
  anchor: anchorSchema,
};

export const exitMechanismSchema = z.discriminatedUnion("mechanism", [
  z.object({
    mechanism: z.literal("extraordinary_amortization_di"),
    /** Premium per year as a decimal (0.004 for 0,40%), applied as [(1 + p)^(DU/252) - 1] over the amount retired. */
    premiumPerYear: nonNegative,
    availableFrom: isoDate,
    /** The share of the nominal the indenture lets an amortization retire (0.98 for 98%), and the share this alternative retires. */
    maxFraction: nonNegative,
    fraction: nonNegative,
    businessDays: businessDaysSchema,
    anchor: anchorSchema,
  }).strict(),
  z.object({mechanism: z.literal("total_redemption_di"), premiumPerYear: nonNegative, availableFrom: isoDate, businessDays: businessDaysSchema, anchor: anchorSchema}).strict(),
  z.object({mechanism: z.literal("extraordinary_amortization_ipca"), maxFraction: nonNegative, fraction: nonNegative, ...makeWholeFields}).strict(),
  z.object({mechanism: z.literal("total_redemption_ipca"), ...makeWholeFields}).strict(),
  z.object({mechanism: z.literal("extraordinary_amortization_pre"), maxFraction: nonNegative, fraction: nonNegative, ...makeWholeFields}).strict(),
  z.object({mechanism: z.literal("total_redemption_pre"), ...makeWholeFields}).strict(),
  z.object({
    mechanism: z.literal("negotiated_offer"),
    /** Open since issuance in the 13th, 14th and 15th; the premium is what the notice states (a rate, an amount per debenture or a total) and the holders decide; what adheres is retired, all or part. */
    availableFrom: isoDate,
    premium: z.discriminatedUnion("kind", [
      z.object({kind: z.literal("rate"), rate: nonNegative, anchor: anchorSchema}).strict(),
      z.object({kind: z.literal("amount_per_unit"), value: nonNegative, anchor: anchorSchema}).strict(),
      z.object({kind: z.literal("total"), value: nonNegative, anchor: anchorSchema}).strict(),
    ]).nullable(),
    requiresFullAdherence: z.boolean(),
    /** The share of the series that adhered, when a notice and its result are in the base; null before that; never above one. */
    adhesion: z.object({fraction: nonNegative, anchor: anchorSchema}).strict().nullable().default(null),
    anchor: anchorSchema,
  }).strict(),
  z.object({mechanism: z.literal("acquisition"), availableFrom: isoDate.nullable(), anchor: anchorSchema}).strict(),
]);
const MAKE_WHOLE = new Set(["extraordinary_amortization_ipca", "total_redemption_ipca", "extraordinary_amortization_pre", "total_redemption_pre"]);
const PARTIAL = new Set(["extraordinary_amortization_di", "extraordinary_amortization_ipca", "extraordinary_amortization_pre"]);

export const exitCostInputSchema = z.object({
  exitDate: isoDate,
  unit: unitSchema,
  /** The documents of the base; every anchor must name one of them, and a mechanism must cite an indenture. */
  documents: z.array(z.object({name: nonEmpty, kind: z.enum(["indenture", "itr", "ledger", "quote", "calendar", "notice", "market_data", "other"])}).strict()).min(1),
  series: z.array(z.object({
    id: nonEmpty,
    label: nonEmpty,
    /** The indenture that governs the series; without one in the base the series is not priced. */
    indenture: z.object({document: nonEmpty, clause: nonEmpty.optional()}).strict().nullable(),
    /** Nominal at the exit date (updated where indexed), with the derivation the source allows; null when the base does not hold it. */
    nominalAtExit: z.object({value: nonNegative, asOf: isoDate, derivation: z.enum(["unit_value_x_quantity_updated", "unit_value_x_quantity", "ledger_balance_at_exit_date", "trustee_report_at_exit_date"]), anchor: anchorSchema}).strict().nullable(),
    /** Remuneration accrued to the exit date; null when the base does not hold it (never zero by default). */
    accruedAtExit: datedAmountSchema.nullable(),
    /** Charges due at the exit date as the indenture states them, an explicit zero included; null when the base is silent. */
    chargesAtExit: datedAmountSchema.nullable(),
    /** Remaining flows after the exit date for the make-whole prices, each with its business and calendar days from the exit date; null when the base has no schedule. */
    remainingFlows: z.array(z.object({id: nonEmpty, date: isoDate, amount: nonNegative, businessDaysFromExit: z.number().int().positive(), calendarDaysFromExit: z.number().int().positive(), anchor: anchorSchema}).strict()).nullable(),
    /** Debentures outstanding, so the DI premium is computed per unit and truncated as the indenture writes; null when the base does not state it. */
    quantity: z.number().int().positive().nullable(),
    /** The mechanisms the indenture offers this series, as the base lists them; any of them absent from `mechanisms` is a gap the executor names. */
    indentureMechanisms: z.array(nonEmpty).default([]),
    /** The series' own remuneration as an annual rate (the real spread for an IPCA series, the fixed rate for a pre series), which the indenture uses to discount the duration that selects the reference security. */
    remunerationRate: z.object({value: nonNegative, anchor: anchorSchema}).strict().nullable(),
    mechanisms: z.array(exitMechanismSchema),
    anchor: anchorSchema,
  }).strict()),
}).strict().superRefine((input, context) => {
  const documents = new Map(input.documents.map((document) => [document.name, document.kind]));
  const names = new Set<string>();
  input.documents.forEach((document, index) => { if (names.has(document.name)) context.addIssue({code: "custom", path: ["documents", index], message: `duplicate document ${document.name}`}); names.add(document.name); });
  const checkAnchor = (anchor: Anchor, path: (string | number)[]) => { if (!documents.has(anchor.document)) context.addIssue({code: "custom", path, message: `anchor names ${anchor.document}, which is not a document of the base`}); };
  const ids = new Set<string>();
  input.series.forEach((series, index) => {
    if (ids.has(series.id)) context.addIssue({code: "custom", path: ["series", index], message: `duplicate series ${series.id}`});
    ids.add(series.id);
    checkAnchor(series.anchor, ["series", index, "anchor"]);
    if (series.indenture && documents.get(series.indenture.document) !== "indenture") context.addIssue({code: "custom", path: ["series", index, "indenture"], message: `${series.id}: ${series.indenture.document} is not registered as an indenture`});
    for (const [name, amount] of [["nominalAtExit", series.nominalAtExit], ["accruedAtExit", series.accruedAtExit], ["chargesAtExit", series.chargesAtExit]] as const) {
      if (!amount) continue;
      checkAnchor(amount.anchor, ["series", index, name, "anchor"]);
      if (amount.asOf !== input.exitDate) context.addIssue({code: "custom", path: ["series", index, name], message: `${series.id}: ${name} dated ${amount.asOf} is not the base at the exit date ${input.exitDate}`});
    }
    const flowIds = new Set<string>();
    (series.remainingFlows ?? []).forEach((flow, position) => {
      checkAnchor(flow.anchor, ["series", index, "remainingFlows", position, "anchor"]);
      if (flowIds.has(flow.id)) context.addIssue({code: "custom", path: ["series", index, "remainingFlows", position], message: `${series.id}: duplicate flow ${flow.id}`});
      flowIds.add(flow.id);
      if (flow.date <= input.exitDate) context.addIssue({code: "custom", path: ["series", index, "remainingFlows", position], message: `${series.id}: flow ${flow.id} on ${flow.date} is not after the exit date`});
      if (flow.businessDaysFromExit > weekdaysBetween(input.exitDate, flow.date)) context.addIssue({code: "custom", path: ["series", index, "remainingFlows", position], message: `${series.id}: flow ${flow.id} claims ${flow.businessDaysFromExit} business days in ${weekdaysBetween(input.exitDate, flow.date)} weekdays`});
      const calendarDays = Math.round((Date.parse(`${flow.date}T00:00:00Z`) - Date.parse(`${input.exitDate}T00:00:00Z`)) / 86_400_000);
      if (flow.calendarDaysFromExit !== calendarDays) context.addIssue({code: "custom", path: ["series", index, "remainingFlows", position], message: `${series.id}: flow ${flow.id} is ${calendarDays} calendar days after the exit, not ${flow.calendarDaysFromExit}`});
    });
    const kinds = new Set<string>();
    series.mechanisms.forEach((mechanism, position) => {
      const path = ["series", index, "mechanisms", position];
      if (kinds.has(mechanism.mechanism)) context.addIssue({code: "custom", path, message: `${series.id}: mechanism ${mechanism.mechanism} listed twice`});
      kinds.add(mechanism.mechanism);
      checkAnchor(mechanism.anchor, [...path, "anchor"]);
      if (documents.get(mechanism.anchor.document) !== "indenture") context.addIssue({code: "custom", path: [...path, "anchor"], message: `${series.id}: mechanism ${mechanism.mechanism} must cite an indenture, not ${mechanism.anchor.document}`});
      if (series.indenture && mechanism.anchor.document !== series.indenture.document) context.addIssue({code: "custom", path: [...path, "anchor"], message: `${series.id}: mechanism ${mechanism.mechanism} cites ${mechanism.anchor.document}, not the series' indenture ${series.indenture.document}`});
      if (!mechanism.anchor.clause) context.addIssue({code: "custom", path: [...path, "anchor"], message: `${series.id}: mechanism ${mechanism.mechanism} must cite the clause of the indenture that writes it`});
      if ("businessDays" in mechanism) {
        checkAnchor(mechanism.businessDays.anchor, [...path, "businessDays", "anchor"]);
        checkAnchor(mechanism.businessDays.holidays.anchor, [...path, "businessDays", "holidays"]);
        if (documents.get(mechanism.businessDays.anchor.document) !== "calendar" || documents.get(mechanism.businessDays.holidays.anchor.document) !== "calendar") context.addIssue({code: "custom", path: [...path, "businessDays"], message: `${series.id}: business days and holidays must cite a calendar of the base`});
        if (mechanism.businessDays.maturity <= input.exitDate) context.addIssue({code: "custom", path: [...path, "businessDays"], message: `${series.id}: maturity ${mechanism.businessDays.maturity} is not after the exit date`});
        if (mechanism.businessDays.count === 0) context.addIssue({code: "custom", path: [...path, "businessDays"], message: `${series.id}: a maturity after the exit date has at least one business day; a count of zero prices a premium of zero`});
        const weekdays = weekdaysBetween(input.exitDate, mechanism.businessDays.maturity);
        const expected = weekdays - mechanism.businessDays.holidays.count;
        if (mechanism.businessDays.count !== expected) context.addIssue({code: "custom", path: [...path, "businessDays"], message: `${series.id}: ${weekdays} weekdays less ${mechanism.businessDays.holidays.count} holidays give ${expected} business days to ${mechanism.businessDays.maturity}, not ${mechanism.businessDays.count}`});
      }
      if ("referenceRate" in mechanism) {
        const isPre = mechanism.mechanism.endsWith("_pre");
        if (isPre && !mechanism.referenceRate.startsWith("B3 Pre")) context.addIssue({code: "custom", path, message: `${series.id}: a pre-fixed mechanism discounts at the Pre x DI curve, not at ${mechanism.referenceRate}`});
        if (!isPre && !mechanism.referenceRate.startsWith("NTN-B")) context.addIssue({code: "custom", path, message: `${series.id}: an IPCA mechanism discounts at the NTN-B, not at ${mechanism.referenceRate}`});
      }
      if ("adhesion" in mechanism && mechanism.adhesion && new Decimal(mechanism.adhesion.fraction).gt(1)) context.addIssue({code: "custom", path: [...path, "adhesion"], message: `${series.id}: an adhesion above 100% is impossible`});
      if ("fraction" in mechanism) {
        if (new Decimal(mechanism.maxFraction).gte(1) || new Decimal(mechanism.maxFraction).lte(0)) context.addIssue({code: "custom", path, message: `${series.id}: an extraordinary amortization retires a fraction the indenture caps below 100%; maxFraction must be in (0, 1)`});
        if (new Decimal(mechanism.fraction).gt(mechanism.maxFraction) || new Decimal(mechanism.fraction).lte(0)) context.addIssue({code: "custom", path, message: `${series.id}: the fraction ${mechanism.fraction} exceeds the ${mechanism.maxFraction} the indenture allows, or is not positive`});
      }
      if ("quote" in mechanism && mechanism.quote) {
        checkAnchor(mechanism.quote.anchor, [...path, "quote", "anchor"]);
        if (mechanism.quote.quoteDate >= input.exitDate) context.addIssue({code: "custom", path: [...path, "quote"], message: `${series.id}: the quote must precede the exit date`});
        checkAnchor(mechanism.quote.holidaysBetween.anchor, [...path, "quote", "holidaysBetween"]);
        if (documents.get(mechanism.quote.holidaysBetween.anchor.document) !== "calendar") context.addIssue({code: "custom", path: [...path, "quote", "holidaysBetween"], message: `${series.id}: the holidays between the quote and the exit must cite a calendar of the base`});
        const expected = weekdaysBetween(mechanism.quote.quoteDate, input.exitDate) - mechanism.quote.holidaysBetween.count;
        if (mechanism.quote.businessDaysBeforeExit !== expected) context.addIssue({code: "custom", path: [...path, "quote"], message: `${series.id}: the quote of ${mechanism.quote.quoteDate} is ${expected} business days before ${input.exitDate} by the calendar (${weekdaysBetween(mechanism.quote.quoteDate, input.exitDate)} weekdays less ${mechanism.quote.holidaysBetween.count} holidays), not ${mechanism.quote.businessDaysBeforeExit}`});
        if (documents.get(mechanism.quote.anchor.document) !== "quote" && documents.get(mechanism.quote.anchor.document) !== "market_data") context.addIssue({code: "custom", path: [...path, "quote", "anchor"], message: `${series.id}: a quote must cite a quote or market data document of the base`});
        const isPreQuote = mechanism.mechanism.endsWith("_pre");
        if (isPreQuote) {
          if (mechanism.quote.securityCalendarDays === null) context.addIssue({code: "custom", path: [...path, "quote"], message: `${series.id}: a Pre x DI vertex is chosen by calendar days; the quote must state the vertex's calendar days`});
          if (mechanism.quote.candidates.some((candidate) => candidate.calendarDays === null)) context.addIssue({code: "custom", path: [...path, "quote", "candidates"], message: `${series.id}: every Pre x DI candidate must state its calendar days`});
          if (!mechanism.quote.candidates.some((candidate) => candidate.security === mechanism.quote!.security && candidate.calendarDays === mechanism.quote!.securityCalendarDays)) context.addIssue({code: "custom", path: [...path, "quote", "candidates"], message: `${series.id}: the chosen vertex ${mechanism.quote.security} is not among the candidates with its calendar days`});
        } else {
          if (mechanism.quote.securityDurationBusinessDays === null) context.addIssue({code: "custom", path: [...path, "quote"], message: `${series.id}: an NTN-B is chosen by duration in business days; the quote must state the security's duration`});
          if (mechanism.quote.candidates.some((candidate) => candidate.durationBusinessDays === null)) context.addIssue({code: "custom", path: [...path, "quote", "candidates"], message: `${series.id}: every NTN-B candidate must state its duration in business days`});
          if (!mechanism.quote.candidates.some((candidate) => candidate.security === mechanism.quote!.security && candidate.durationBusinessDays === mechanism.quote!.securityDurationBusinessDays)) context.addIssue({code: "custom", path: [...path, "quote", "candidates"], message: `${series.id}: the chosen security ${mechanism.quote.security} is not among the candidates with its duration`});
        }
        const securities = new Set<string>();
        mechanism.quote.candidates.forEach((candidate, slot) => { if (securities.has(candidate.security)) context.addIssue({code: "custom", path: [...path, "quote", "candidates", slot], message: `${series.id}: candidate ${candidate.security} listed twice`}); securities.add(candidate.security); });
      }
      if ("premium" in mechanism && mechanism.premium) checkAnchor(mechanism.premium.anchor, [...path, "premium", "anchor"]);
    });
  });
});
export type ExitCostInput = z.input<typeof exitCostInputSchema>;

/** Weekdays from `from` inclusive to `to` exclusive, as the indentures count business days (exit date included, maturity excluded); the ceiling of any business-day count. */
export function weekdaysBetween(from: string, to: string): number {
  const start = new Date(`${from}T00:00:00Z`);
  const end = new Date(`${to}T00:00:00Z`);
  let count = 0;
  for (let day = start; day < end; day = new Date(day.getTime() + 86_400_000)) {
    const weekday = day.getUTCDay();
    if (weekday !== 0 && weekday !== 6) count += 1;
  }
  return count;
}

type Calculation = {id: string; formula: string; operands: Record<string, string>; result: string; unit: string};
type RouteState = "estimated" | "base_priced_premium_open" | "premium_known_adhesion_open" | "price_at_counterparty" | "insufficient_evidence" | "not_permitted";
type Route = {
  mechanism: string; scope: "full" | "partial" | "partial_or_full"; fraction: string | null; permitted_on_date: boolean; available_from: string | null; state: RouteState;
  amount_retired: string | null; premium: string | null; total_payable: string | null; reason: string | null; anchor: Anchor;
  /** per_unit: the premium was computed on the unit price and truncated, then multiplied by the quantity; aggregate_approximation: no quantity in the base. */
  premium_basis: "per_unit" | "aggregate_approximation" | null;
  quote: {rate: string; quoteDate: string; businessDaysBeforeExit: number; security: string; securityDurationBusinessDays: number | null; securityCalendarDays: number | null; nearestCandidate: string; nearestTies: string[]; anchor: Anchor} | null;
  /** The present value of the remaining flows at the quote, the duration at the series' own remuneration (which selects the security), and the flows counted. */
  present_value: {value: string; duration_business_days_at_remuneration: string; duration_calendar_days_at_remuneration: string; remuneration_rate: string; flows: number; charges_added: string} | null;
};

export type ExitCostOutput = {
  schema_version: "method.estimate-exit-cost-by-series.v8";
  exit_date: string;
  unit: string;
  state: "complete" | "partial" | "empty";
  exit_costs: Array<{
    series_id: string;
    label: string;
    indenture: {document: string; clause: string | null} | null;
    base: {nominal: string | null; nominal_derivation: string | null; accrued: string | null; charges: string | null; payable: string | null; anchors: {nominal: Anchor | null; accrued: Anchor | null; charges: Anchor | null}; state: "priced" | "insufficient_evidence"; reason: string | null};
    routes: Route[];
    cheapest_full_exit: {mechanism: string; total_payable: string} | null;
    anchor: Anchor;
  }>;
  uncovered_terms: Array<{id: string; state: "insufficient_evidence"; reason: string}>;
  totals: {estimated_premium: string; estimated_payable: string; series_estimated: number; series_open: number};
  trace: {calculations: Calculation[]; inputFingerprint: string; outputFingerprint: string};
};

const d = (value: Decimal.Value) => new Decimal(value);
const out = (value: Decimal) => value.toDecimalPlaces(8).toFixed();
const truncate8 = (value: Decimal) => value.toDecimalPlaces(8, Decimal.ROUND_DOWN).toFixed();
const stableStringify = (value: unknown): string => JSON.stringify(value, (_key, inner: unknown) => (inner && typeof inner === "object" && !Array.isArray(inner) ? Object.fromEntries(Object.entries(inner as Record<string, unknown>).sort(([a], [b]) => compare(a, b))) : inner));
const fingerprint = (value: unknown) => createHash("sha256").update(stableStringify(value)).digest("hex");

function canonical(input: z.infer<typeof exitCostInputSchema>) {
  return {
    ...input,
    documents: [...input.documents].sort((a, b) => compare(a.name, b.name)),
    series: [...input.series].sort((a, b) => compare(a.id, b.id)).map((series) => ({...series, indentureMechanisms: [...series.indentureMechanisms].sort(compare), remainingFlows: series.remainingFlows ? [...series.remainingFlows].sort((a, b) => compare(a.date, b.date) || compare(a.id, b.id)) : null, mechanisms: [...series.mechanisms].sort((a, b) => compare(a.mechanism, b.mechanism)).map((mechanism) => ("quote" in mechanism && mechanism.quote ? {...mechanism, quote: {...mechanism.quote, candidates: [...mechanism.quote.candidates].sort((a, b) => compare(a.security, b.security))}} : mechanism))})),
  };
}

export function estimateExitCostBySeries(raw: ExitCostInput): ExitCostOutput {
  const input = canonical(exitCostInputSchema.parse(raw));
  const calculations: Calculation[] = [];
  const record = (calculation: Omit<Calculation, "unit">, unit: string = input.unit) => calculations.push({...calculation, unit});
  const uncovered: ExitCostOutput["uncovered_terms"] = [];

  const exitCosts = input.series.map((series): ExitCostOutput["exit_costs"][number] => {
    const anchors = {nominal: series.nominalAtExit?.anchor ?? null, accrued: series.accruedAtExit?.anchor ?? null, charges: series.chargesAtExit?.anchor ?? null};
    const indenture = series.indenture ? {document: series.indenture.document, clause: series.indenture.clause ?? null} : null;
    const missing = ([["nominal", series.nominalAtExit], ["accrued remuneration", series.accruedAtExit], ["charges", series.chargesAtExit]] as const).filter(([, amount]) => amount === null).map(([name]) => name);
    let base: ExitCostOutput["exit_costs"][number]["base"];
    if (!indenture) {
      const reason = `no indenture of ${series.label} is in the base; without the instrument that writes the mechanisms nothing is priced`;
      uncovered.push({id: `indenture:${series.id}`, state: "insufficient_evidence", reason});
      base = {nominal: null, nominal_derivation: null, accrued: null, charges: null, payable: null, anchors, state: "insufficient_evidence", reason};
    } else if (missing.length > 0) {
      const reason = `the base does not hold the ${missing.join(", ")} of ${series.label} at ${input.exitDate}; a price needs the nominal at the exit date, the remuneration accrued to it and the charges the indenture states (an explicit zero included), none of them assumed`;
      uncovered.push({id: `base:${series.id}`, state: "insufficient_evidence", reason});
      base = {nominal: series.nominalAtExit ? out(d(series.nominalAtExit.value)) : null, nominal_derivation: series.nominalAtExit?.derivation ?? null, accrued: series.accruedAtExit ? out(d(series.accruedAtExit.value)) : null, charges: series.chargesAtExit ? out(d(series.chargesAtExit.value)) : null, payable: null, anchors, state: "insufficient_evidence", reason};
    } else {
      const payable = d(series.nominalAtExit!.value).plus(series.accruedAtExit!.value).plus(series.chargesAtExit!.value);
      record({id: `financial.exit_base:${series.id}`, formula: "nominalAtExit + accruedAtExit + chargesAtExit", operands: {nominalAtExit: series.nominalAtExit!.value, nominalDerivation: series.nominalAtExit!.derivation, accruedAtExit: series.accruedAtExit!.value, chargesAtExit: series.chargesAtExit!.value}, result: out(payable)});
      base = {nominal: out(d(series.nominalAtExit!.value)), nominal_derivation: series.nominalAtExit!.derivation, accrued: out(d(series.accruedAtExit!.value)), charges: out(d(series.chargesAtExit!.value)), payable: out(payable), anchors, state: "priced", reason: null};
    }
    const basePayable = base.payable ? d(base.payable) : null;
    for (const offered of series.indentureMechanisms) if (!series.mechanisms.some((mechanism) => mechanism.mechanism === offered)) uncovered.push({id: `mechanism:${series.id}:${offered}`, state: "insufficient_evidence", reason: `the indenture of ${series.label} offers ${offered} and the input does not represent it; the exit routes of the series are incomplete`});

    const routes = series.mechanisms.map((mechanism): Route => {
      const availableFrom = mechanism.availableFrom ?? null;
      const permitted = availableFrom === null ? true : input.exitDate >= availableFrom;
      const partial = PARTIAL.has(mechanism.mechanism);
      const fraction = "fraction" in mechanism ? mechanism.fraction : null;
      const scope = mechanism.mechanism === "acquisition" || mechanism.mechanism === "negotiated_offer" ? "partial_or_full" as const : partial ? "partial" as const : "full" as const;
      const common = {mechanism: mechanism.mechanism, scope, fraction, permitted_on_date: permitted, available_from: availableFrom, anchor: mechanism.anchor, quote: null as Route["quote"], present_value: null, amount_retired: null, premium: null, total_payable: null, premium_basis: null as Route["premium_basis"]};
      if (!indenture) return {...common, state: "insufficient_evidence", reason: base.reason};
      if (!permitted) return {...common, state: "not_permitted", reason: `this mechanism is only available from ${availableFrom}`};
      if (mechanism.mechanism === "acquisition") return {...common, state: "price_at_counterparty", reason: "facultative acquisition of the debentures a seller accepts, all or part of the series; the price is whatever the seller accepts, and the base holds no offer"};
      if (!basePayable) return {...common, state: "insufficient_evidence", reason: base.reason};
      const retired = fraction ? basePayable.times(fraction) : basePayable;
      if (mechanism.mechanism === "extraordinary_amortization_di" || mechanism.mechanism === "total_redemption_di") {
        const factor = d(mechanism.premiumPerYear).plus(1).pow(d(mechanism.businessDays.count).div(252)).minus(1);
        let premium: Decimal;
        let basis: Route["premium_basis"];
        if (series.quantity !== null) {
          // The indenture writes P over the unit price and truncates at eight decimals; the series premium is that unit premium times the debentures retired.
          const unitBase = retired.div(series.quantity);
          const unitPremium = d(truncate8(unitBase.times(factor)));
          premium = unitPremium.times(series.quantity);
          basis = "per_unit";
          record({id: `structure.exit_premium:${series.id}:${mechanism.mechanism}`, formula: "P = [(1 + premiumPerYear)^(businessDays/252) - 1] * unitPrice, truncated at eight decimals; premium = P * quantity", operands: {premiumPerYear: mechanism.premiumPerYear, businessDays: String(mechanism.businessDays.count), maturity: mechanism.businessDays.maturity, basePayable: out(basePayable), fraction: fraction ?? "1", amountRetired: out(retired), quantity: String(series.quantity), unitPrice: out(unitBase), unitPremium: out(unitPremium)}, result: out(premium)});
        } else {
          premium = d(truncate8(retired.times(factor)));
          basis = "aggregate_approximation";
          record({id: `structure.exit_premium:${series.id}:${mechanism.mechanism}`, formula: "[(1 + premiumPerYear)^(businessDays/252) - 1] * amountRetired, truncated once on the aggregate (approximation: the base gives no quantity for the per-unit truncation)", operands: {premiumPerYear: mechanism.premiumPerYear, businessDays: String(mechanism.businessDays.count), maturity: mechanism.businessDays.maturity, basePayable: out(basePayable), fraction: fraction ?? "1", amountRetired: out(retired)}, result: out(premium)});
        }
        return {...common, state: "estimated", premium_basis: basis, amount_retired: out(retired), premium: out(premium), total_payable: out(retired.plus(premium)), reason: `${partial ? `retires ${fraction} of the series; not a full exit` : "full exit"}${basis === "aggregate_approximation" ? "; premium truncated on the aggregate, not per debenture (no quantity in the base)" : ""}`};
      }
      if (MAKE_WHOLE.has(mechanism.mechanism) && "quoteDay" in mechanism) {
        const requiredOffset = mechanism.quoteDay === "prior_business_day" ? 1 : 2;
        const which = mechanism.quoteDay === "prior_business_day" ? "the business day immediately before the exit date" : "the second business day before the exit date";
        if (!mechanism.quote) return {...common, state: "insufficient_evidence", reason: `needs the ${mechanism.referenceRate} quote of ${which}; the base holds none`};
        if (mechanism.quote.businessDaysBeforeExit !== requiredOffset) return {...common, state: "insufficient_evidence", reason: `the quote in the base is ${mechanism.quote.businessDaysBeforeExit} business days before the exit; the series requires ${which}`};
        if (!series.remainingFlows || series.remainingFlows.length === 0) return {...common, state: "insufficient_evidence", reason: `needs the remaining flows of ${series.label} after ${input.exitDate} to discount at the quote; the base holds no schedule`};
        if (!series.remunerationRate) return {...common, state: "insufficient_evidence", reason: `needs the remuneration rate of ${series.label}: the indenture discounts the duration that selects the reference security at the series' own remuneration, and the base does not state it`};
        const flows = series.remainingFlows.map((flow) => ({id: flow.id, amount: flow.amount, businessDays: flow.businessDaysFromExit}));
        // The indentures round each discount factor (FVPk, FVPd) at nine decimals before discounting.
        const present = presentValueByBusinessDays(flows, mechanism.quote.rate, {factorDecimals: 9});
        // The duration that selects the security uses the same nine-decimal factors the indenture writes for FVPd.
        const duration = macaulayDurationBusinessDays(flows, series.remunerationRate.value, {factorDecimals: 9});
        calculations.push({...present.trace, id: `${present.trace.id}:${series.id}:${mechanism.mechanism}`, unit: input.unit});
        calculations.push({...duration.trace, id: `${duration.trace.id}:${series.id}:${mechanism.mechanism}`, formula: `${duration.trace.formula}, discounted at the series' remuneration`, unit: "business days"});
        // The same weights over calendar days give the duration a Pre x DI vertex is chosen by.
        const weighted = presentValueByBusinessDays(flows, series.remunerationRate.value, {factorDecimals: 9});
        const calendarDuration = weighted.discounted.reduce((sum, flow) => sum.plus(d(flow.presentValue).times(series.remainingFlows!.find((entry) => entry.id === flow.id)!.calendarDaysFromExit)), d(0)).div(weighted.value);
        record({id: `financial.duration_calendar_days:${series.id}:${mechanism.mechanism}`, formula: "sum(calendarDays * presentValue at remuneration) / sum(presentValue at remuneration)", operands: {remunerationRate: series.remunerationRate.value, flows: String(flows.length)}, result: out(calendarDuration)}, "calendar days");
        // The reference security must be the candidate nearest to the series' duration on the count the indenture uses; ties are recorded, never broken by name in silence.
        const isPre = mechanism.mechanism.endsWith("_pre");
        const distance = (candidate: {durationBusinessDays: number | null; calendarDays: number | null}) => (isPre ? d(candidate.calendarDays!).minus(calendarDuration).abs() : d(candidate.durationBusinessDays!).minus(duration.value).abs());
        const ranked = [...mechanism.quote.candidates].sort((a, b) => distance(a).comparedTo(distance(b)) || compare(a.security, b.security));
        const nearest = ranked[0]!;
        const ties = ranked.filter((candidate) => candidate.security !== nearest.security && distance(candidate).eq(distance(nearest))).map((candidate) => candidate.security);
        const quoteOut = {rate: mechanism.quote.rate, quoteDate: mechanism.quote.quoteDate, businessDaysBeforeExit: mechanism.quote.businessDaysBeforeExit, security: mechanism.quote.security, securityDurationBusinessDays: mechanism.quote.securityDurationBusinessDays, securityCalendarDays: mechanism.quote.securityCalendarDays, nearestCandidate: nearest.security, nearestTies: ties, anchor: mechanism.quote.anchor};
        record({id: `structure.reference_security:${series.id}:${mechanism.mechanism}`, formula: isPre ? "candidate with the smallest |calendarDays - series duration in calendar days|" : "candidate with the smallest |durationBusinessDays - series duration at remuneration|", operands: {seriesDuration: isPre ? out(calendarDuration) : duration.value, chosen: mechanism.quote.security, nearest: nearest.security, ties: ties.join(", ") || "none"}, result: nearest.security}, isPre ? "calendar days" : "business days");
        const chosenIsNearest = nearest.security === mechanism.quote.security || ties.includes(mechanism.quote.security);
        if (!chosenIsNearest) return {...common, quote: quoteOut, state: "insufficient_evidence", reason: `the quoted security ${mechanism.quote.security} is not the nearest to the series' duration (${isPre ? `${out(calendarDuration)} calendar days` : `${duration.value} business days`}); ${nearest.security} is; no price at a security the indenture does not select`};
        common.quote = quoteOut;
        // The indenture compares the updated value with the present value of the remaining flows, then adds the charges due; the fraction scales both.
        const chargesRetired = d(series.chargesAtExit!.value).times(fraction ?? 1);
        const principalAndAccrued = d(series.nominalAtExit!.value).plus(series.accruedAtExit!.value).times(fraction ?? 1);
        const presentValue = d(present.value).times(fraction ?? 1);
        const payable = (mechanism.floor === "max_with_base" ? Decimal.max(principalAndAccrued, presentValue) : presentValue).plus(chargesRetired);
        record({id: `structure.exit_make_whole:${series.id}:${mechanism.mechanism}`, formula: mechanism.floor === "max_with_base" ? "max((nominal + accrued) * fraction, presentValueAtQuote * fraction) + charges * fraction" : "presentValueAtQuote * fraction + charges * fraction", operands: {nominalPlusAccrued: out(principalAndAccrued), presentValueAtQuote: present.value, charges: out(chargesRetired), fraction: fraction ?? "1", quoteRate: mechanism.quote.rate, quoteDate: mechanism.quote.quoteDate, quoteDay: mechanism.quoteDay, security: mechanism.quote.security, referenceRate: mechanism.referenceRate, durationAtRemuneration: duration.value, remunerationRate: series.remunerationRate.value}, result: out(payable)});
        return {...common, state: "estimated", amount_retired: out(retired), premium: out(payable.minus(retired)), total_payable: out(payable), present_value: {value: out(presentValue), duration_business_days_at_remuneration: duration.value, duration_calendar_days_at_remuneration: out(calendarDuration), remuneration_rate: series.remunerationRate.value, flows: flows.length, charges_added: out(chargesRetired)}, reason: `${partial ? `retires ${fraction} of the series; not a full exit` : "full exit"}${ties.length > 0 ? `; ${nearest.security} ties with ${ties.join(", ")} on duration, recorded` : ""}`};
      }
      if (mechanism.mechanism === "negotiated_offer") {
        if (mechanism.premium === null) return {...common, state: "base_priced_premium_open", amount_retired: null, reason: `the indenture prices the base (${out(basePayable)}); the premium is what the offer notice states${mechanism.requiresFullAdherence ? " and the redemption needs the adherence of every holder" : " and the holders decide"}; no notice exists in the base, and what is retired depends on the adhesion`};
        if (mechanism.requiresFullAdherence && mechanism.adhesion && d(mechanism.adhesion.fraction).lt(1)) return {...common, state: "not_permitted", reason: `the offer needs the adherence of every holder and ${mechanism.adhesion.fraction} adhered; no redemption`};
        const premiumOnWhole = mechanism.premium.kind === "rate" ? basePayable.times(mechanism.premium.rate) : mechanism.premium.kind === "amount_per_unit" ? (series.quantity !== null ? d(mechanism.premium.value).times(series.quantity) : null) : d(mechanism.premium.value);
        if (premiumOnWhole === null) return {...common, state: "insufficient_evidence", reason: "the notice states a premium per debenture and the base gives no quantity; the series premium cannot be computed"};
        if (mechanism.adhesion === null) return {...common, state: "premium_known_adhesion_open", amount_retired: null, premium: out(premiumOnWhole), reason: `the notice prices the premium (${out(premiumOnWhole)} on the whole series) but no adhesion result is in the base; what is retired, and what is paid, wait for the adhesion`};
        const adhesion = d(mechanism.adhesion.fraction);
        const retiredByOffer = basePayable.times(adhesion);
        const premium = premiumOnWhole.times(adhesion);
        record({id: `structure.exit_premium:${series.id}:negotiated_offer`, formula: `premium on the whole series (${mechanism.premium.kind}) * adhesion; base * adhesion`, operands: {basePayable: out(basePayable), adhesion: adhesion.toFixed(), premiumKind: mechanism.premium.kind, premiumOnWhole: out(premiumOnWhole)}, result: out(premium)});
        return {...common, fraction: adhesion.toFixed(), state: "estimated", amount_retired: out(retiredByOffer), premium: out(premium), total_payable: out(retiredByOffer.plus(premium)), reason: `${mechanism.requiresFullAdherence ? "requires adherence of every holder" : "holders decide in assembly"}; ${adhesion.toFixed()} of the series adhered`};
      }
      throw new Error(`unknown mechanism ${(mechanism as {mechanism: string}).mechanism}`);
    });
    const fullExits = routes.filter((route) => route.state === "estimated" && route.scope === "full" && route.mechanism !== "negotiated_offer" && route.total_payable !== null).sort((a, b) => d(a.total_payable!).comparedTo(d(b.total_payable!)) || compare(a.mechanism, b.mechanism));
    return {series_id: series.id, label: series.label, indenture, base, routes, cheapest_full_exit: fullExits[0] ? {mechanism: fullExits[0].mechanism, total_payable: fullExits[0].total_payable!} : null, anchor: series.anchor};
  });

  const estimated = exitCosts.filter((entry) => entry.cheapest_full_exit !== null);
  const totals = {
    estimated_premium: out(estimated.reduce((sum, entry) => sum.plus(d(entry.cheapest_full_exit!.total_payable).minus(entry.base.payable!)), d(0))),
    estimated_payable: out(estimated.reduce((sum, entry) => sum.plus(entry.cheapest_full_exit!.total_payable), d(0))),
    series_estimated: estimated.length,
    series_open: exitCosts.length - estimated.length,
  };
  if (input.series.length === 0) record({id: "structure.exit_cost:none", formula: "no series to retire", operands: {}, result: "0"});
  const state: ExitCostOutput["state"] = input.series.length === 0 ? "empty" : totals.series_open > 0 ? "partial" : "complete";
  const body = {schema_version: "method.estimate-exit-cost-by-series.v8" as const, exit_date: input.exitDate, unit: input.unit, state, exit_costs: exitCosts, uncovered_terms: uncovered, totals};
  const inputFingerprint = fingerprint(input);
  return {...body, trace: {calculations, inputFingerprint, outputFingerprint: fingerprint({...body, calculations, inputFingerprint})}};
}

packages/financial-core/src/contractual-.content:
import {createHash} from "node:crypto";

import {accrualFactorAtPrecision, diPercentAccrualByConvention} from "./credit-math";
import Decimal from "decimal.js";
import {z} from "zod";

/**
 * Executor of the method `build-interest-and-indexation-schedule` (v6, after the fifth independent
 * review). Projects each series period by period with the factors its indenture writes: an annual
 * rate accrues exponentially over business days of a 252-day year; a DI series compounds the DI
 * factor with the spread factor; a "p% of DI" series compounds p times the daily DI; an IPCA series
 * updates its nominal at each anniversary by the monthly index of the lagged month and accrues the
 * spread on the updated nominal. A coupon is paid on its date: the accrual is split at the payment,
 * what accrued before is paid, what accrues after is carried. The opening principal is a nominal
 * (unit value times quantity, updated where the base holds the update); a ledger balance that
 * includes accrued interest and costs is not a principal and names a gap. The accrued remuneration
 * at the reference date comes from the base or the first coupon is declared incomplete. Rounding
 * follows what each indenture writes, layer by layer (DI factor, spread factor, their product, the
 * daily accumulation, the amount). The IPCA update between anniversaries is pro rata by business
 * days (dup/dut) when the base gives the counts, and declared as not projected otherwise. When the
 * base does not say whether the IPCA update is capitalized or paid, both treatments are projected as
 * scenarios. Nothing missing becomes zero: an absent amortization schedule leaves the principal
 * projection insufficient in every aggregate, and the projected total is compared to the ledger's
 * control so omitted series are named; that coverage compares a nominal with a carrying amount and
 * says so. The unit is anchored to the source that states it; coupon, amortization and IPCA
 * anniversary positions inside a period must advance, and each event applies at its own date:
 * an anniversary updates the nominal from its date, an amortization reduces the interest base
 * from its date, a coupon pays what accrued to its date. A series without an amortization
 * schedule has no closing balance, never an unchanged one. Every factor is computed by financial-core at the precision the
 * indenture writes. When the IPCA treatment is unknown the two scenarios are shown side by side and
 * neither enters the aggregate. Anniversary dates come from the base when it lists them
 * (business-day adjusted); otherwise calendar-day anniversaries are declared as an approximation.
 */
const nonNegative = z.string().regex(/^\d+(\.\d+)?$/);
const rate = z.string().regex(/^-?\d+(\.\d+)?$/);
const nonEmpty = z.string().trim().min(1);
const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);
const isoMonth = z.string().regex(/^\d{4}-\d{2}$/);
const unitSchema = z.enum(["BRL", "BRL thousand", "BRL million", "USD", "USD thousand"]);
const anchorSchema = z.object({document: nonEmpty, page: z.number().int().positive().optional(), note: nonEmpty.optional(), clause: nonEmpty.optional()}).strict();
type Anchor = z.infer<typeof anchorSchema>;
const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);

export const projectionPeriodSchema = z.object({
  id: nonEmpty,
  start: isoDate,
  end: isoDate,
  /** Business days of the period, from the calendar the base cites (holidays included). */
  businessDays: z.number().int().nonnegative(),
  /** The calendar the count comes from. */
  anchor: anchorSchema,
}).strict();

export const curveSchema = z.object({
  id: nonEmpty,
  kind: z.enum(["CDI", "IPCA"]),
  /** Annual effective rate per period as a decimal, or the daily rate the source publishes (annualized by the executor as (1 + daily)^252 - 1). One of the two. */
  annualRateByPeriod: z.record(nonEmpty, rate).nullable().default(null),
  dailyRateByPeriod: z.record(nonEmpty, rate).nullable().default(null),
  /** IPCA only: monthly variation by calendar month (YYYY-MM) as a decimal, for the anniversary updates. */
  monthlyRateByMonth: z.record(isoMonth, rate).nullable().default(null),
  /** IPCA only: the index numbers (NI) by calendar month, as IBGE publishes them; the monthly variation is NI(m) / NI(m-1) - 1 cut to eight decimals, as the indentures write, and the month used before the anniversary day is the previous one. */
  indexNumberByMonth: z.record(isoMonth, z.string().regex(/^\d+(\.\d+)?$/)).nullable().default(null),
  source: z.object({title: nonEmpty, url: z.string().optional(), asOf: isoDate, anchor: anchorSchema}).strict(),
}).strict();

export const seriesRemunerationSchema = z.discriminatedUnion("type", [
  z.object({type: z.literal("spread_over_index"), spreadPerYear: rate}).strict(),
  z.object({type: z.literal("percent_of_index"), percentOfIndex: nonNegative}).strict(),
  z.object({type: z.literal("fixed"), ratePerYear: rate}).strict(),
]);

/** Rounding the indenture writes, layer by layer: the index factor, the spread factor, their product (Fator Juros), the daily accumulation and the amount. */
const layerSchema = z.object({decimals: z.number().int().min(2).max(16), mode: z.enum(["round", "truncate"])}).strict();
export const roundingSchema = z.object({
  indexFactor: layerSchema,
  spreadFactor: layerSchema,
  interestFactor: layerSchema,
  dailyAccumulation: layerSchema,
  amount: layerSchema,
  anchor: anchorSchema,
}).strict();

export const seriesInputSchema = z.object({
  id: nonEmpty,
  label: nonEmpty,
  /** The nominal at the reference date and where it comes from; a ledger balance including accrued interest is not a nominal. */
  openingPrincipal: z.object({value: nonNegative, basis: z.enum(["unit_value_x_quantity", "unit_value_x_quantity_updated", "trustee_report_nominal", "ledger_balance_including_accrued"]), anchor: anchorSchema}).strict(),
  /** Remuneration accrued at the reference date since the last payment; null when the base does not hold it. */
  openingAccrued: z.object({value: nonNegative, anchor: anchorSchema}).strict().nullable(),
  indexer: z.enum(["CDI", "IPCA", "fixed", "unknown"]),
  remuneration: seriesRemunerationSchema.nullable(),
  /** Coupon payment dates with the business days from the start of the period that holds them, from the calendar the base cites; positions inside a period must advance. */
  couponDates: z.array(z.object({date: isoDate, businessDaysFromPeriodStart: z.number().int().nonnegative()}).strict()).nullable(),
  /** Scheduled principal payments with their business-day position inside the period that holds them; null when the base has no amortization schedule for the series. */
  amortization: z.array(z.object({date: isoDate, amount: nonNegative, businessDaysFromPeriodStart: z.number().int().nonnegative()}).strict()).nullable(),
  /** IPCA only: how the update is treated (capitalized or paid); null when the indenture is not in the base, in which case both are projected. */
  indexationTreatment: z.enum(["capitalized_principal", "cash_paid"]).nullable(),
  /** IPCA only: the anniversary day and the lag in months the indenture writes for the index number; the anniversary dates the base lists with their business-day position inside their period, so updates interleave with coupons and amortizations; and, per period, dup/dut for the pro rata at the period end. */
  indexation: z.object({anniversaryDay: z.number().int().min(1).max(31), lagMonths: z.number().int().min(0).max(3), /** The anniversary dates the base lists (the business day before the calendar anniversary) with their position; null when not in the base, in which case calendar days are used, applied at the period start, and declared. */ anniversaryDates: z.array(z.object({date: isoDate, businessDaysFromPeriodStart: z.number().int().nonnegative()}).strict()).nullable(), proRataByPeriod: z.record(nonEmpty, z.object({dup: z.number().int().nonnegative(), dut: z.number().int().positive()}).strict()).nullable(), anchor: anchorSchema}).strict().nullable(),
  rounding: roundingSchema.nullable(),
  curveId: nonEmpty.nullable(),
  anchors: z.object({balance: anchorSchema, terms: anchorSchema.nullable(), payments: anchorSchema.nullable(), amortization: anchorSchema.nullable()}).strict(),
}).strict();

const UNIT_WORDS: Record<z.infer<typeof unitSchema>, RegExp> = {"BRL": /\b(R\$|reais|BRL)\b(?!\s*(mil|milh))/i, "BRL thousand": /\b(mil|thousand)\b/i, "BRL million": /\b(milh[õo]es|million)\b/i, "USD": /\bUSD\b(?!\s*(mil|thousand))/i, "USD thousand": /\bUSD\b.*\b(mil|thousand)\b/i};

export const interestScheduleInputSchema = z.object({
  referenceDate: isoDate,
  unit: unitSchema,
  /** Where the source states the unit; its note must name it, so a relabelled scale is refused. */
  unitAnchor: anchorSchema.extend({note: nonEmpty}),
  periods: z.array(projectionPeriodSchema).min(1),
  curves: z.array(curveSchema).default([]),
  series: z.array(seriesInputSchema).min(1),
  /** The ledger's control: the series it holds and its gross debt (a carrying amount), so omitted series are named; the coverage of a nominal over a carrying amount is reported as such, never as a nominal share. */
  ledgerControl: z.object({seriesIds: z.array(nonEmpty), grossDebt: nonNegative, grossDebtBasis: z.enum(["carrying_amount", "nominal"]), anchor: anchorSchema}).strict().nullable().default(null),
  /** The finance expense of the last closed period, to bridge against; null when not in the base. */
