    prerequisites:["Structure Truth Set","rating e instrumento identificados","pricing policy vigente"],dependencies:[],decisionRules:["Nenhum valor hardcoded substitui observação governada.","Amostra insuficiente produz abstenção.","A Offroad comunica referência indicativa e não compromete preço nem capital."],redFlags:["Comp vencido","Fonte repetida como amostra independente","Garantia incomparável","Faixa estreita demais","Custo sem fonte"],stopConditions:["Amostra ou independência abaixo da política","Choque de regime","Referência vencida","Largura fora da régua"],exceptions:["Emitir sem referência confiável e a causa exata quando o gate falhar."],templates:[],examples:{positive:[`${spec.id} fecha com amostra, fonte e validade.`],negative:[`${spec.id} usa o último deal ou opinião de mesa como curva.`]},runtime:{orchestration:"deterministic_pipeline",peerHandoffs:false,maxModelCalls:0,modelPurpose:[],allowedTools:["pricing_truth","market_reference","financial_core","procedure_coverage"]},
  });
}

